# ======================================================================== PATH HELPERS

def _file_version(path):
    try:
        st = os.stat(path)
    except OSError:
        return None
    return st.st_mtime_ns, st.st_size


def _cache_per_file_version(maxsize):
    """lru_cache for a function of one file path that re-reads the file when it changes (for files this script writes during the run:
    the addon's .vmat / .vmdl / .dmx). The cache key is (path, modification time, size)."""
    def deco(fn):
        cached = lru_cache(maxsize=maxsize)(lambda path, _ver: fn(path))

        @functools.wraps(fn)
        def w(path):
            return cached(path, _file_version(path))
        w.cache_clear = cached.cache_clear
        return w
    return deco


def _cross3(a, b):
    """np.cross(a, b). Two float64 3-vectors (nearly every call: ~400k per map) take a plain-float path, ~12x faster than np.cross's
    per-call setup and bit-identical to it; anything else (arrays of vectors, other dtypes, lists) goes to np.cross"""
    import numpy as np
    if (type(a) is np.ndarray and type(b) is np.ndarray and a.shape == (3,) and b.shape == (3,)
            and a.dtype == np.float64 and b.dtype == np.float64):
        a0, a1, a2 = a.tolist()
        b0, b1, b2 = b.tolist()
        return np.array((a1 * b2 - a2 * b1, a2 * b0 - a0 * b2, a0 * b1 - a1 * b0))
    return np.cross(a, b)


# file_exists / listdir_cached: for the READ-ONLY folders only (Source1 roots, the CS2 install); the addon folder changes during the run
@lru_cache(maxsize=None)
def file_exists(path: str) -> bool:
    return os.path.isfile(path)

@lru_cache(maxsize=None)
def listdir_cached(path: str) -> tuple:
    try:
        return tuple(os.listdir(path))
    except Exception:
        return tuple()

@lru_cache(maxsize=500_000)
def rel_norm(p: str) -> str:
    return str(p).strip().replace("\\", "/").lstrip("/")

@lru_cache(maxsize=500_000)
def normalize_candidate(p: str) -> str:
    p = rel_norm(p)
    if not p:
        return ""
    low = p.lower()
    if any(low.startswith(tok) for tok in ROOT_TOKENS):
        return low
    _name, ext = os.path.splitext(p)
    if ext.lower() in MATERIALISH_BARE_EXTS:
        return f"materials/{p}"
    return p

@lru_cache(maxsize=500_000)
def normalize_dep_must_be_rooted(p: str) -> str:
    p = rel_norm(str(p)).strip().strip('"').strip("'")
    if not p:
        return ""
    low = p.lower().lstrip("/")
    if any(low.startswith(tok) for tok in ROOT_TOKENS):
        return normalize_candidate(low)
    return ""

@lru_cache(maxsize=500_000)
def top_root(p: str) -> str:
    p = normalize_candidate(p)
    if not p or "/" not in p:
        return ""
    return p.split("/", 1)[0].lower()

@lru_cache(maxsize=500_000)
def passes_root_filter(p: str) -> bool:
    r = top_root(p)
    return bool(r) and (r in ALLOWED_ROOTS)

def strip_materials_prefix(ref: str) -> str:
    ref = rel_norm(str(ref).strip('"'))
    return ref[len("materials/"):] if ref.lower().startswith("materials/") else ref

_S2_NAME_KEY_RE = re.compile(r"[^a-z0-9/.]")


def _s2_name_key(name: str) -> str:
    """a file name with every character but letters, digits, '/' and '.' as '_', lower case. Valve's importer renames some assets this way:
    'silkroad/egypt/wall (10)' -> 'wall__10_' (mg_mario_party: names with brackets), so the map and models ask for a name no Source1
    file has"""
    return _S2_NAME_KEY_RE.sub("_", name.lower())


def find_ci(root: Path, rel: str):
    """Case-insensitive lookup of rel below root. Returns Path or None. A part with no such name falls back to the one entry whose name
    matches it with Valve's importer renaming undone (_s2_name_key: 'wall__10_.vmt' finds 'wall (10).vmt'); none or several: None."""
    cur = root
    for part in rel_norm(rel).split("/"):
        if not part:
            continue
        cand = cur / part
        if cand.exists():
            cur = cand
            continue
        names = listdir_cached(str(cur))
        match = next((n for n in names if n.lower() == part.lower()), None)
        if match is None:
            key = _s2_name_key(part)
            alike = [n for n in names if _s2_name_key(n) == key]
            match = alike[0] if len(alike) == 1 else None
        if match is None:
            return None
        cur = cur / match
    return cur

@lru_cache(maxsize=500_000)
def find_in_source1(rel: str):
    """Search SOURCE1_ROOTS in order for rel (e.g. 'materials/x/y.vmt'). -> (abs path, root) or (None, None)."""
    rel = rel_norm(rel)
    variants = [rel]
    if "_" in rel:
        variants.append(rel.replace("_", " "))
    for root in SOURCE1_ROOTS:
        r = Path(root)
        for v in variants:
            p = find_ci(r, v)
            if p is not None and p.is_file():
                return str(p), root
    return None, None

def resolve_vtf(ref: str):
    rel = strip_materials_prefix(ref)
    if rel.lower().endswith(".vtf"):
        rel = rel[:-4]
    p, _ = find_in_source1("materials/" + rel + ".vtf")
    return Path(p) if p else None

_EXT_END_RE = re.compile(r'\.[a-z0-9_]{1,8}$', re.IGNORECASE)

def split_glued_paths(s: str):
    s = normalize_candidate(s)
    hits = []
    for tok in ROOT_TOKENS:
        start = 0
        while True:
            i = s.find(tok, start)
            if i == -1:
                break
            hits.append(i)
            start = i + 1
    hits = sorted(set(hits))
    # only a root token preceded by a file extension starts a NEW (glued) path
    hits = [i for i in hits if i == 0 or _EXT_END_RE.search(s[:i])]
    if len(hits) <= 1:
        return [s]
    out = []
    for idx, pos in enumerate(hits):
        end = hits[idx + 1] if idx + 1 < len(hits) else len(s)
        chunk = normalize_candidate(s[pos:end].strip("/"))
        if "/" in chunk and "." in chunk.rsplit("/", 1)[-1]:
            out.append(chunk)
    return out or [s]

VALID_PATH_CHARS_RE = re.compile(r'^[a-zA-Z0-9_\-./&()+{ ]+$')     # '{': a stray '{' in a material name (MATERIAL_BRACE_FIX)

@lru_cache(maxsize=500_000)
def is_valid_asset_path(path: str) -> bool:
    path = normalize_candidate(path)
    if not path or "/" not in path or ".." in path.split("/"):
        return False
    folder, filename = path.rsplit("/", 1)
    if not folder or not filename or "." not in filename:
        return False
    if os.path.splitext(filename)[1].lower() not in VALID_EXTENSIONS:
        return False
    if filename.startswith(".") and "." not in filename[1:]:
        return False
    return bool(VALID_PATH_CHARS_RE.match(path))

def derive_export_dir(vmap_path_or_dir: Path) -> Path:
    p = vmap_path_or_dir
    if p.is_file():
        return p.parent.parent
    if p.is_dir():
        if p.name.lower() == "maps":
            return p.parent
        cur = p
        for _ in range(8):
            if cur.name.lower() == "maps":
                return cur.parent
            cur = cur.parent
    return p

SKYBOX_SPLIT = True           # a CS:GO 3D skybox (sky_camera in a box of sky brushes, found in the .vmf) is moved out of the main map into maps/<map>_skybox.vmap (Map Type 3D Skybox, contents centred on the origin, with a copy of the main map's light_environment), and the main map gets a skybox_reference to it. Only when the main map has no skybox_reference yet and that file does not exist. Runs after the prefab collapse; both maps backed up / logged in <prefix>_skybox_split.txt
