# Modules for reading/writing binary .vmap files, bundled from skink52's CS2 port tools (github.com/skink52/cs2portdocs).
# Changed here only for speed (same results): vmapedit.next_node_id scans just the elements added since its last call; visfit.merge_boxes
# computes box volumes per row in one call. probes.run also takes wall_classes (LIGHTING_PROBE_WALL_CLASSES).
_BUNDLED_VMAP_MODULES = {'dmx': '"""Read/write Source 2 binary DMX (encoding binary 9) - the .vmap format.\n\ndoc = dmx.load(path) -> Doc with .header, .prefix (list of attr lists), .elements\nElement = dict(type=bytes, name=bytes, guid=bytes(16), attrs=list[[name, type, value]])\nElement references are ints (index into doc.elements), -1 = null.\n"""\nimport struct\n\nT_ELEM, T_INT, T_FLOAT, T_BOOL, T_STR, T_BIN, T_TIME, T_COLOR, T_V2, T_V3, T_V4, T_QANG, T_QUAT, T_MAT, T_U64, T_U8 = range(1, 17)\nARR = 32\n_fix = {T_INT: (\'<i\', 4), T_FLOAT: (\'<f\', 4), T_BOOL: (\'<?\', 1), T_TIME: (\'<i\', 4), T_COLOR: (\'<4B\', 4), T_V2: (\'<2f\', 8),\n        T_V3: (\'<3f\', 12), T_V4: (\'<4f\', 16), T_QANG: (\'<3f\', 12), T_QUAT: (\'<4f\', 16), T_MAT: (\'<16f\', 64), T_U64: (\'<Q\', 8), T_U8: (\'<B\', 1)}\n\nclass R:\n    def __init__(s, d, p=0): s.d = d; s.p = p\n    def i(s): v = struct.unpack_from(\'<i\', s.d, s.p)[0]; s.p += 4; return v\n    def b(s): v = s.d[s.p]; s.p += 1; return v\n    def cstr(s): e = s.d.index(b\'\\0\', s.p); v = s.d[s.p:e]; s.p = e + 1; return v\n    def raw(s, n): v = s.d[s.p:s.p + n]; s.p += n; return v\n    def fmt(s, f, n):\n        v = struct.unpack_from(f, s.d, s.p); s.p += n\n        return v[0] if len(v) == 1 else list(v)\n\nclass Doc:\n    def __init__(s): s.header = b\'\'; s.prefix = []; s.elements = []\n\ndef _read_val(r, t, strtab, inline_str):\n    if t == T_ELEM:\n        v = r.i()\n        if v == -2: return (\'guid\', r.cstr())\n        return v\n    if t == T_STR: return r.cstr() if inline_str else strtab[r.i()]\n    if t == T_BIN: n = r.i(); return r.raw(n)\n    f, n = _fix[t]; return r.fmt(f, n)\n\n_ARRF = {t: (f[1:-1] or \'1\', f[-1], n) for t, (f, n) in _fix.items()}   # type -> (values per item, struct letter, item size)\n\ndef _read_attr(r, strtab, inline_str):\n    t = r.b()\n    if t > ARR:\n        n = r.i(); bt = t - ARR\n        if bt == T_STR:  # string arrays are always inline\n            return t, [r.cstr() for _ in range(n)]\n        if bt in _ARRF:  # fixed-size items: one unpack for the whole array\n            k, c, sz = _ARRF[bt]; k = int(k)\n            v = struct.unpack_from(\'<%d%s\' % (n * k, c), r.d, r.p); r.p += n * sz\n            return t, list(v) if k == 1 else [list(v[j:j + k]) for j in range(0, n * k, k)]\n        return t, [_read_val(r, bt, strtab, inline_str) for _ in range(n)]\n    return t, _read_val(r, t, strtab, inline_str)\n\ndef loads(d):\n    doc = Doc(); e = d.index(b\'\\n\\x00\'); doc.header = d[:e + 1]\n    r = R(d, e + 2)\n    for _ in range(r.i()):\n        attrs = []\n        for _ in range(r.i()):\n            name = r.cstr(); t, v = _read_attr(r, None, True); attrs.append([name, t, v])\n        doc.prefix.append(attrs)\n    strtab = [r.cstr() for _ in range(r.i())]\n    n = r.i()\n    for _ in range(n):\n        doc.elements.append({\'type\': strtab[r.i()], \'name\': strtab[r.i()], \'guid\': r.raw(16), \'attrs\': []})\n    for el in doc.elements:\n        for _ in range(r.i()):\n            name = strtab[r.i()]; t, v = _read_attr(r, strtab, False); el[\'attrs\'].append([name, t, v])\n    if r.p != len(d): raise ValueError(\'trailing data %d/%d\' % (r.p, len(d)))\n    return doc\n\ndef load(path): return loads(open(path, \'rb\').read())\n\ndef _w_val(out, t, v, sidx, inline):\n    if t == T_ELEM:\n        if isinstance(v, tuple): out += struct.pack(\'<i\', -2) + v[1] + b\'\\0\'\n        else: out += struct.pack(\'<i\', v)\n    elif t == T_STR: out += (v + b\'\\0\') if inline else struct.pack(\'<i\', sidx[v])\n    elif t == T_BIN: out += struct.pack(\'<i\', len(v)) + v\n    else:\n        f, n = _fix[t]; out += struct.pack(f, *(v if isinstance(v, (list, tuple)) else [v]))\n\ndef _w_attr(out, t, v, sidx, inline):\n    out.append(t)\n    if t > ARR:\n        out += struct.pack(\'<i\', len(v)); bt = t - ARR\n        if bt in _ARRF and v:  # fixed-size items: one pack for the whole array (same bytes as item by item)\n            k, c, _sz = _ARRF[bt]; k = int(k)\n            try:\n                flat = v if k == 1 else [y for x in v for y in x]\n                if len(flat) == len(v) * k:\n                    out += struct.pack(\'<%d%s\' % (len(flat), c), *flat)\n                    return\n            except (struct.error, TypeError):\n                pass\n        for x in v:\n            if bt == T_STR: out += x + b\'\\0\'\n            else: _w_val(out, bt, x, sidx, inline)\n    else: _w_val(out, t, v, sidx, inline)\n\ndef dumps(doc):\n    strs = []; sidx = {}\n    def add(s):\n        if s not in sidx: sidx[s] = len(strs); strs.append(s)\n    for el in doc.elements:\n        add(el[\'type\']); add(el[\'name\'])\n        for name, t, v in el[\'attrs\']:\n            add(name)\n            if t == T_STR: add(v)\n    out = bytearray(doc.header + b\'\\0\')\n    out += struct.pack(\'<i\', len(doc.prefix))\n    for attrs in doc.prefix:\n        out += struct.pack(\'<i\', len(attrs))\n        for name, t, v in attrs: out += name + b\'\\0\'; _w_attr(out, t, v, None, True)\n    out += struct.pack(\'<i\', len(strs))\n    for s in strs: out += s + b\'\\0\'\n    out += struct.pack(\'<i\', len(doc.elements))\n    for el in doc.elements: out += struct.pack(\'<ii\', sidx[el[\'type\']], sidx[el[\'name\']]) + el[\'guid\']\n    for el in doc.elements:\n        out += struct.pack(\'<i\', len(el[\'attrs\']))\n        for name, t, v in el[\'attrs\']: out += struct.pack(\'<i\', sidx[name]); _w_attr(out, t, v, sidx, False)\n    return bytes(out)\n\n# ---- helpers ----\ndef get(el, name, default=None):\n    for a in el[\'attrs\']:\n        if a[0] == name: return a[2]\n    return default\ndef geta(el, name):\n    for a in el[\'attrs\']:\n        if a[0] == name: return a\n    return None\ndef set_(el, name, t, v):\n    a = geta(el, name)\n    if a: a[1] = t; a[2] = v\n    else: el[\'attrs\'].append([name, t, v])\ndef delete(el, name): el[\'attrs\'] = [a for a in el[\'attrs\'] if a[0] != name]\n', 'kv2': '"""Parse DMX keyvalues2 text (what Valve\'s importer writes for the main .vmap) into a dmx.Doc,\nso it can be edited and saved as binary 9 like Hammer does."""\nimport re, uuid\nimport dmx\n\nTYPES = {\'element\': 1, \'int\': 2, \'float\': 3, \'bool\': 4, \'string\': 5, \'binary\': 6, \'time\': 7, \'color\': 8, \'vector2\': 9,\n         \'vector3\': 10, \'vector4\': 11, \'qangle\': 12, \'quaternion\': 13, \'matrix\': 14, \'uint64\': 15, \'uint8\': 16}\n_tok = re.compile(r\'"((?:[^"\\\\]|\\\\.)*)"|([{}\\[\\],])|//[^\\n]*|(\\S+)\')\n\ndef _unesc(s): return s.replace(\'\\\\"\', \'"\').replace(\'\\\\n\', \'\\n\').replace(\'\\\\t\', \'\\t\').replace(\'\\\\\\\\\', \'\\\\\')\n\ndef _scalar(t, s):\n    if t == 2: return int(s)\n    if t == 3: return float(s)\n    if t == 4: return s.strip() not in (\'0\', \'false\', \'\')\n    if t == 5: return _unesc(s).encode(\'utf-8\')\n    if t == 6: return bytes.fromhex(\'\'.join(s.split()))\n    if t == 7: return int(round(float(s) * 10000))\n    if t == 8: return [int(x) for x in s.split()]\n    if t in (9, 10, 11, 12, 13, 14): return [float(x) for x in s.split()]\n    if t == 15: return int(s, 16) if s.lower().startswith(\'0x\') else int(s)\n    if t == 16: return int(s)\n    raise ValueError(t)\n\ndef loads(text):\n    if isinstance(text, bytes): text = text.decode(\'utf-8\')\n    nl = text.index(\'\\n\')\n    toks = [(m.group(1) is not None, m.group(1) if m.group(1) is not None else (m.group(2) or m.group(3))) for m in _tok.finditer(text, nl + 1)\n            if m.group(1) is not None or m.group(2) or m.group(3)]\n    pos = [0]\n    def nxt(): t = toks[pos[0]]; pos[0] += 1; return t\n    def peek(): return toks[pos[0]] if pos[0] < len(toks) else (False, None)\n    elements = []; by_id = {}; refs = []   # refs: (element index, attr index, list index or None, guid)\n    def parse_element(etype):\n        q, b = nxt(); assert b == \'{\', b\n        idx = len(elements); el = {\'type\': etype.encode(), \'name\': b\'\', \'guid\': b\'\', \'attrs\': []}; elements.append(el)\n        while True:\n            q, name = nxt()\n            if not q and name == \'}\': break\n            q2, typ = nxt()\n            if typ == \'elementid\':\n                _, v = nxt(); g = uuid.UUID(v).bytes; el[\'guid\'] = g; by_id[g] = idx; continue\n            if typ.endswith(\'_array\'):\n                bt = TYPES[typ[:-6]]; nxt()  # [\n                vals = []\n                while True:\n                    qv, v = nxt()\n                    if not qv and v == \']\': break\n                    if not qv and v == \',\': continue\n                    if bt == 1:\n                        if v == \'element\':\n                            _, g = nxt()\n                            if g: refs.append((idx, len(el[\'attrs\']), len(vals), uuid.UUID(g).bytes)); vals.append(-1)\n                            else: vals.append(-1)\n                        else: vals.append(parse_element(v))\n                    else: vals.append(_scalar(bt, v))\n                el[\'attrs\'].append([name.encode(), bt + 32, vals]); continue\n            if typ in TYPES:\n                t = TYPES[typ]; _, v = nxt()\n                if t == 1:\n                    if v: refs.append((idx, len(el[\'attrs\']), None, uuid.UUID(v).bytes))\n                    el[\'attrs\'].append([name.encode(), 1, -1]); continue\n                if name == \'name\' and t == 5: el[\'name\'] = _unesc(v).encode(\'utf-8\'); continue\n                el[\'attrs\'].append([name.encode(), t, _scalar(t, v)]); continue\n            # inline element: "attr" "ElementType" { ... }\n            el[\'attrs\'].append([name.encode(), 1, parse_element(typ)])\n        return idx\n    tops = []\n    while pos[0] < len(toks):\n        q, etype = nxt(); tops.append(parse_element(etype))\n    for ei, ai, li, g in refs:\n        j = by_id.get(g, -1)\n        if li is None: elements[ei][\'attrs\'][ai][2] = j\n        else: elements[ei][\'attrs\'][ai][2][li] = j\n    # binary layout: root element first, $prefix_element$ second\n    root = next(i for i in tops if elements[i][\'type\'] == b\'CMapRootElement\')\n    pre = [i for i in tops if elements[i][\'type\'] == b\'$prefix_element$\']\n    order = [root] + pre + [i for i in range(len(elements)) if i != root and i not in pre]\n    remap = {o: n for n, o in enumerate(order)}\n    doc = dmx.Doc(); doc.header = b\'<!-- dmx encoding binary 9 format vmap 40 -->\\n\'\n    for o in order:\n        e = elements[o]; attrs = []\n        for n, t, v in e[\'attrs\']:\n            if t == 1: v = remap[v] if v >= 0 else -1\n            elif t == 33: v = [remap[x] if x >= 0 else -1 for x in v]\n            attrs.append([n, t, v])\n        doc.elements.append({**e, \'attrs\': attrs})\n    doc.prefix = [[list(a) for a in doc.elements[1][\'attrs\']]] if pre else []\n    return doc\n', 'vmapedit': '"""Edit Hammer 5 .vmap files (binary DMX) without Hammer."""\nimport os, random, math\nimport dmx\nfrom dmx import T_ELEM, T_INT, T_FLOAT, T_BOOL, T_STR, T_V3, T_QANG, T_U64, ARR\n\ndef guid(): return bytes(random.getrandbits(8) for _ in range(16))\n\nclass Map:\n    def __init__(s, path=None, data=None):\n        s.path = path\n        raw = data if data is not None else open(path, \'rb\').read()\n        if b\'encoding keyvalues2\' in raw[:80]:\n            import kv2; s.doc = kv2.loads(raw)\n        else:\n            s.doc = dmx.loads(raw)\n        s.E = s.doc.elements\n        s.root = next(i for i, e in enumerate(s.E) if e[\'type\'] == b\'CMapRootElement\')\n        s.world = dmx.get(s.E[s.root], b\'world\')\n\n    # ---------- basic element access ----------\n    def g(s, i, k, d=None): return dmx.get(s.E[i], k, d)\n    def type(s, i): return s.E[i][\'type\']\n    def children(s, i): return s.g(i, b\'children\') or []\n    def walk(s, i=None, parent=None):\n        """yield (node, parent) for every node under i (default world), depth first"""\n        i = s.world if i is None else i\n        stack = [(i, iter(s.children(i)))]\n        while stack:\n            p, it = stack[-1]\n            for c in it:\n                yield c, p\n                stack.append((c, iter(s.children(c))))\n                break\n            else:\n                stack.pop()\n    def entities(s):\n        return [n for n, _ in s.walk() if s.type(n) == b\'CMapEntity\']\n    def parent_of(s):\n        return {n: p for n, p in s.walk()}\n\n    # ---------- entity properties ----------\n    def props(s, i): return s.E[s.g(i, b\'entity_properties\')]\n    def P(s, i, k, d=None):\n        v = dmx.get(s.props(i), k.encode() if isinstance(k, str) else k)\n        return d if v is None else v.decode(\'utf-8\', \'replace\')\n    def setp(s, i, k, v):\n        k = k.encode() if isinstance(k, str) else k\n        v = v.encode() if isinstance(v, str) else v\n        dmx.set_(s.props(i), k, T_STR, v)\n    def delp(s, i, k): dmx.delete(s.props(i), k.encode() if isinstance(k, str) else k)\n    def cls(s, i): return s.P(i, \'classname\', \'\')\n    def name(s, i): return s.P(i, \'targetname\', \'\')\n    def origin(s, i): return list(s.g(i, b\'origin\', [0, 0, 0]))\n    def by_class(s, *c): return [e for e in s.entities() if s.cls(e) in c]\n\n    # ---------- connections ----------\n    def conns(s, i): return [s.E[c] for c in s.g(i, b\'connectionsData\') or []]\n    def conn_tuple(s, c):\n        return (dmx.get(c, b\'outputName\').decode(), dmx.get(c, b\'targetName\').decode(), dmx.get(c, b\'inputName\').decode(),\n                dmx.get(c, b\'overrideParam\').decode(), round(dmx.get(c, b\'delay\'), 3), dmx.get(c, b\'timesToFire\'))\n    def add_conn(s, i, out, target, inp, param=\'\', delay=0.0, times=-1):\n        c = s.new_el(b\'DmeConnectionData\', [\n            [b\'outputName\', T_STR, out.encode()], [b\'targetType\', T_INT, 7], [b\'targetName\', T_STR, target.encode()],\n            [b\'inputName\', T_STR, inp.encode()], [b\'overrideParam\', T_STR, param.encode()],\n            [b\'delay\', T_FLOAT, float(delay)], [b\'timesToFire\', T_INT, int(times)]])\n        dmx.geta(s.E[i], b\'connectionsData\')[2].append(c)\n        return c\n    def all_conns(s):\n        for e in s.entities():\n            for c in s.conns(e): yield e, c\n\n    # ---------- creation ----------\n    def new_el(s, typ, attrs, name=b\'\'):\n        s.E.append({\'type\': typ, \'name\': name, \'guid\': guid(), \'attrs\': attrs}); return len(s.E) - 1\n    def next_node_id(s):\n        """1 + the highest nodeID in the map. Remembers the highest found so far and scans only elements added since\n        (nodeIDs are only written when an element is created), not the whole map on every new entity"""\n        seen, m = getattr(s, \'_nid\', (0, 0))\n        if seen > len(s.E): seen, m = 0, 0           # element list replaced (prune): scan it all again\n        for e in s.E[seen:]:\n            v = dmx.get(e, b\'nodeID\')\n            if isinstance(v, int) and v > m: m = v\n        s._nid = (len(s.E), m)\n        return m + 1\n    def new_entity(s, classname, origin, props, angles=(0, 0, 0), parent=None):\n        pin = s.new_el(b\'DmElement\', [[b\'referenceName\', T_STR, b\'\'], [b\'targetReferenceID\', T_U64, 0], [b\'offsetOrigin\', T_V3, [0.0, 0.0, 0.0]],\n                                     [b\'offsetAngles\', T_QANG, [0.0, 0.0, 0.0]], [b\'pinAngles\', T_BOOL, True], [b\'twoWay\', T_BOOL, False]])\n        plug = s.new_el(b\'DmePlugList\', [[b\'names\', 37, []], [b\'dataTypes\', 34, []], [b\'plugTypes\', 34, []], [b\'descriptions\', 37, []]])\n        pr = [[b\'classname\', T_STR, classname.encode()]] + [[k.encode(), T_STR, str(v).encode()] for k, v in props.items()]\n        pe = s.new_el(b\'EditGameClassProps\', pr)\n        e = s.new_el(b\'CMapEntity\', [\n            [b\'nodeID\', T_INT, s.next_node_id()], [b\'referenceID\', T_U64, random.getrandbits(63)], [b\'children\', ARR + T_ELEM, []],\n            [b\'variableTargetKeys\', ARR + T_STR, []], [b\'variableNames\', ARR + T_STR, []], [b\'relayPlugData\', T_ELEM, plug],\n            [b\'connectionsData\', ARR + T_ELEM, []], [b\'entity_properties\', T_ELEM, pe], [b\'hitNormal\', T_V3, [0.0, 0.0, 1.0]],\n            [b\'isProceduralEntity\', T_BOOL, False], [b\'origin\', T_V3, [float(x) for x in origin]], [b\'angles\', T_QANG, [float(x) for x in angles]],\n            [b\'scales\', T_V3, [1.0, 1.0, 1.0]], [b\'transformLocked\', T_BOOL, False], [b\'transformPin\', T_ELEM, pin],\n            [b\'force_hidden\', T_BOOL, False], [b\'editorOnly\', T_BOOL, False], [b\'customVisGroup\', T_STR, b\'\'],\n            [b\'randomSeed\', T_INT, random.randint(1, 2**31 - 1)]])\n        dmx.geta(s.E[parent if parent is not None else s.world], b\'children\')[2].append(e)\n        return e\n    def remove_node(s, i):\n        for n, p in list(s.walk()):\n            if n == i:\n                a = dmx.geta(s.E[p], b\'children\'); a[2] = [x for x in a[2] if x != i]; return True\n        return False\n\n    # ---------- copying between maps ----------\n    def import_subtree(s, other, i, memo, node_id):\n        """deep-copy element i (and everything it references) from Map `other` into this map"""\n        if i in memo: return memo[i]\n        src = other.E[i]\n        if src[\'type\'] in (b\'CMapRootElement\', b\'CMapWorld\'):\n            raise ValueError(\'refusing to copy root/world\')\n        j = len(s.E); memo[i] = j\n        s.E.append({\'type\': src[\'type\'], \'name\': src[\'name\'], \'guid\': guid(), \'attrs\': []})\n        attrs = []\n        for name, t, v in src[\'attrs\']:\n            if t == T_ELEM and isinstance(v, int) and v >= 0: v = s.import_subtree(other, v, memo, node_id)\n            elif t == ARR + T_ELEM: v = [s.import_subtree(other, x, memo, node_id) if isinstance(x, int) and x >= 0 else x for x in v]\n            elif name == b\'nodeID\' and t == T_INT: v = node_id[0]; node_id[0] += 1\n            elif isinstance(v, list): v = list(v)\n            attrs.append([name, t, v])\n        s.E[j][\'attrs\'] = attrs\n        return j\n\n    # ---------- bounds ----------\n    def mesh_points(s, mesh_node):\n        """world-space vertex positions of a CMapMesh (mesh nodes keep local verts + node origin)"""\n        md = s.g(mesh_node, b\'meshData\')\n        if md is None: return []\n        vdata = s.g(md, b\'vertexData\')\n        o = s.g(mesh_node, b\'origin\', [0, 0, 0]); ang = s.g(mesh_node, b\'angles\', [0, 0, 0]); sc = s.g(mesh_node, b\'scales\', [1, 1, 1])\n        pts = []\n        for st in s.g(vdata, b\'streams\') or []:\n            if s.E[st][\'name\'].startswith(b\'position\'):\n                for p in s.g(st, b\'data\'):\n                    pts.append(xform([p[0] * sc[0], p[1] * sc[1], p[2] * sc[2]], o, ang))\n        return pts\n    def bounds(s, node):\n        pts = []\n        stack = [node]\n        while stack:\n            n = stack.pop()\n            if s.type(n) == b\'CMapMesh\': pts += s.mesh_points(n)\n            stack += s.children(n)\n        if not pts: return None\n        return [min(p[k] for p in pts) for k in range(3)], [max(p[k] for p in pts) for k in range(3)]\n\n    # ---------- save ----------\n    def prune(s):\n        """drop elements no longer reachable from the root / prefix; returns how many were removed"""\n        keep = set(); stack = [s.root]\n        stack += [i for i, e in enumerate(s.E) if e[\'type\'] == b\'$prefix_element$\']\n        while stack:\n            i = stack.pop()\n            if i in keep: continue\n            keep.add(i)\n            for _, t, v in s.E[i][\'attrs\']:\n                if t == T_ELEM and isinstance(v, int) and v >= 0: stack.append(v)\n                elif t == ARR + T_ELEM: stack += [x for x in v if isinstance(x, int) and x >= 0]\n        order = [i for i in range(len(s.E)) if i in keep]\n        remap = {o: n for n, o in enumerate(order)}\n        newE = []\n        for i in order:\n            e = s.E[i]; attrs = []\n            for name, t, v in e[\'attrs\']:\n                if t == T_ELEM and isinstance(v, int) and v >= 0: v = remap[v]\n                elif t == ARR + T_ELEM: v = [remap[x] if isinstance(x, int) and x >= 0 else x for x in v]\n                attrs.append([name, t, v])\n            newE.append({**e, \'attrs\': attrs})\n        removed = len(s.E) - len(newE)\n        s.doc.elements = s.E = newE; s.root = remap[s.root]; s.world = remap[s.world]\n        s._nid = (0, 0)\n        return removed\n    def dumps(s):\n        out = dmx.dumps(s.doc); dmx.loads(out); return out\n    def save(s, path):\n        out = s.dumps(); os.makedirs(os.path.dirname(path), exist_ok=True); open(path, \'wb\').write(out); return len(out)\n\n# ---------- math ----------\ndef rot_matrix(ang):\n    p, y, r = [math.radians(a) for a in ang]\n    sp, cp, sy, cy, sr, cr = math.sin(p), math.cos(p), math.sin(y), math.cos(y), math.sin(r), math.cos(r)\n    # Source QAngle (pitch, yaw, roll) -> forward/left/up columns\n    return [[cp * cy, sr * sp * cy - cr * sy, cr * sp * cy + sr * sy],\n            [cp * sy, sr * sp * sy + cr * cy, cr * sp * sy - sr * cy],\n            [-sp, sr * cp, cr * cp]]\ndef xform(p, o, ang):\n    if not any(ang): return [p[0] + o[0], p[1] + o[1], p[2] + o[2]]\n    m = rot_matrix(ang)\n    return [m[r][0] * p[0] + m[r][1] * p[1] + m[r][2] * p[2] + o[r] for r in range(3)]\ndef angle_fwd(ang):\n    m = rot_matrix(ang); return [m[0][0], m[1][0], m[2][0]]\n'}
# The lighting passes (stationary lights, light probes, vis hints, large-face splitting), bundled from rebuild_lighting.py /
# skink52's cs2portdocs tools. They need numpy + scipy and are only loaded by the lighting rebuild and the radar.
_BUNDLED_VMAP_MODULES['lighting'] = '"""Stationary (dynamic) light pass.\n\nCS:GO lights import as Static (directlight 1, baked only), so weapons / players render black. This picks a minimal set of lights\nper sealed compartment and switches them to directlight 3 (Stationary: dynamic direct light, baked shadows; max 4 may overlap), with ranges trimmed so no point in the map is\ninside more than MAX_OVERLAP stationary lights. Compartments come from voxelising the world geometry and flood-filling\nthe empty space; compartments that see sky (moondome / skybox) count as lit by light_environment when the map has one.\n"""\nimport collections\nimport numpy as np\nimport dmx\n\nTOOL_PASS = (\'materials/tools/toolstrigger\', \'materials/tools/toolsclip\', \'materials/tools/toolsplayerclip\', \'materials/tools/toolsnpcclip\',\n             \'materials/tools/toolsinvisible\', \'materials/tools/toolsinvisibleladder\', \'materials/tools/toolsareaportal\', \'materials/tools/toolsoccluder\',\n             \'materials/tools/toolshint\', \'materials/tools/toolsskip\', \'materials/tools/toolsfog\', \'materials/tools/toolslight\', \'materials/tools/toolsblocklight\',\n             \'materials/tools/toolsblock_los\', \'materials/tools/toolsbuyzone\', \'materials/tools/toolsbombsite\')\nMAX_OVERLAP = 4\nLIGHT_CLASSES = (\'light_omni2\', \'light_spot\', \'light_barn\', \'light_rect\', \'light_capsule\', \'light_omni\', \'light_ortho\')\n\n_POLY_CACHE = None      # {(id(map), node): polygons} while share_polys(True): the probe, stationary-light and vis passes read the same meshes\n_VOX_CACHE = None       # while share_polys(True): the last grid voxelise() made (polygons, voxel size, origin, shape, grid)\n_LAB_CACHE = None       # while share_polys(True): (grid, labels, count) a pass labelled with share=True, for the next label_empty of the same grid\n\ndef share_polys(on):\n    """while on, mesh_polys returns each mesh\'s polygons from one extraction (only while no pass changes mesh geometry), world_polys\n    the same list every time, and voxelise the grid it already made for that list on the same grid"""\n    global _POLY_CACHE, _VOX_CACHE, _LAB_CACHE\n    _POLY_CACHE = {} if on else None\n    _VOX_CACHE = None\n    _LAB_CACHE = None\n\ndef mesh_polys(m, node):\n    """[(material, [p0, p1, ...])] for a CMapMesh, world space"""\n    if _POLY_CACHE is None:\n        return _mesh_polys(m, node)\n    k = (id(m), node)\n    r = _POLY_CACHE.get(k)\n    if r is None:\n        r = _POLY_CACHE[k] = _mesh_polys(m, node)\n    return r\n\ndef _mesh_polys(m, node):\n    """[(material, [p0, p1, ...])] for a CMapMesh, world space"""\n    md = m.g(node, b\'meshData\')\n    if md is None: return []\n    E = m.E\n    get = lambda k: dmx.get(E[md], k)\n    vdi, evi, eni, fei, fdi = get(b\'vertexDataIndices\'), get(b\'edgeVertexIndices\'), get(b\'edgeNextIndices\'), get(b\'faceEdgeIndices\'), get(b\'faceDataIndices\')\n    mats = [x.decode().lower() for x in get(b\'materials\') or []]\n    pos = None; matidx = None\n    for st in dmx.get(E[get(b\'vertexData\')], b\'streams\'):\n        if E[st][\'name\'].startswith(b\'position\'): pos = dmx.get(E[st], b\'data\')\n    for st in dmx.get(E[get(b\'faceData\')], b\'streams\'):\n        if E[st][\'name\'].startswith(b\'materialindex\'): matidx = dmx.get(E[st], b\'data\')\n    if pos is None or not fei: return []\n    o = m.g(node, b\'origin\', [0, 0, 0])\n    out = []\n    for f, e0 in enumerate(fei):\n        loop = []; e = e0\n        for _ in range(64):\n            v = evi[e]; p = pos[vdi[v]]; loop.append((p[0] + o[0], p[1] + o[1], p[2] + o[2]))\n            e = eni[e]\n            if e == e0: break\n        mi = matidx[fdi[f]] if matidx else 0\n        out.append((mats[mi] if mi < len(mats) else \'\', loop))\n    return out\n\ndef world_polys(m):\n    """polygons of world geometry (meshes not inside entities)"""\n    if _POLY_CACHE is not None and (\'world\', id(m)) in _POLY_CACHE:\n        return _POLY_CACHE[(\'world\', id(m))]\n    polys = []\n    def walk(n):\n        for c in m.children(n):\n            t = m.type(c)\n            if t == b\'CMapMesh\': polys.extend(mesh_polys(m, c))\n            elif t == b\'CMapGroup\': walk(c)\n    walk(m.world)\n    if _POLY_CACHE is not None: _POLY_CACHE[(\'world\', id(m))] = polys\n    return polys\n\n\n_BARY = {}\ndef _bary(n):\n    """the barycentric sample grid every triangle with n steps uses (as the per-triangle meshgrid / linspace did)"""\n    r = _BARY.get(n)\n    if r is None:\n        u, w = np.meshgrid(np.linspace(0, 1, n), np.linspace(0, 1, n))\n        k = (u + w) <= 1\n        r = _BARY[n] = (u[k][:, None], w[k][:, None])\n    return r\n\ndef tri_batches(items, step, max_pts=1000000):\n    """items: (polygon points (k, 3) float64, tag). The points sampled over every fan triangle of every polygon, in batches of\n    triangles with the same sample count and tag: yields (points (m, 3), tag). Same points, far fewer numpy calls."""\n    groups = {}\n    for P, tag in items:\n        if len(P) < 3:\n            continue\n        a = P[0]\n        e1, e2, e3 = P[1:-1] - a, P[2:] - a, P[2:] - P[1:-1]\n        ns = (np.sqrt(np.maximum(np.maximum((e1 * e1).sum(1), (e2 * e2).sum(1)), (e3 * e3).sum(1))) / step).astype(int) + 2\n        for n in set(ns.tolist()):\n            sel = ns == n\n            g = groups.setdefault((n, tag), ([], [], []))\n            g[0].append(np.broadcast_to(a, (int(sel.sum()), 3))); g[1].append(e1[sel]); g[2].append(e2[sel])\n    for (n, tag), (A, E1, E2) in groups.items():\n        A, E1, E2 = np.concatenate(A), np.concatenate(E1), np.concatenate(E2)\n        uk, wk = _bary(n)\n        per = max(1, max_pts // len(uk))\n        for j in range(0, len(A), per):\n            q = A[j:j + per, None, :] + uk[None, :, :] * E1[j:j + per, None, :] + wk[None, :, :] * E2[j:j + per, None, :]\n            yield q.reshape(-1, 3), tag\n\ndef voxelise(polys, vs, extent=None):\n    pts_all = np.array([p for _, l in (extent if extent is not None else polys) for p in l], np.float64)\n    lo = pts_all.min(0) - 2 * vs; hi = pts_all.max(0) + 2 * vs\n    shape = tuple(int(x) for x in np.ceil((hi - lo) / vs))\n    global _VOX_CACHE\n    if _POLY_CACHE is not None and _VOX_CACHE is not None:\n        c_polys, c_vs, c_lo, c_shape, c_solid = _VOX_CACHE\n        if c_polys is polys and c_vs == vs and c_shape == shape and np.array_equal(c_lo, lo):\n            return c_solid.copy(), lo       # the same polygons on the same grid (the probe pass\'s, asked for again by the stationary lights)\n    solid = np.zeros(shape, np.uint8)   # 1 wall, 2 sky\n    voxelise_into(solid, lo, polys, vs)\n    if _POLY_CACHE is not None:\n        _VOX_CACHE = (polys, vs, lo.copy(), shape, solid.copy())\n    return solid, lo\n\ndef voxelise_into(solid, lo, polys, vs):\n    """rasterise more polygons into an existing voxelise() grid (each voxel keeps the highest kind: 1 wall, 2 sky)"""\n    top = np.array(solid.shape) - 1\n    items = ((np.array(loop, np.float64), 2 if (\'moondome\' in mat or \'toolsskybox\' in mat) else 1) for mat, loop in polys if not mat.startswith(TOOL_PASS))\n    for q, kind in tri_batches(items, vs * 0.4):\n        idx = np.clip(np.floor((q - lo) / vs).astype(int), 0, top)\n        cur = solid[idx[:, 0], idx[:, 1], idx[:, 2]]\n        solid[idx[:, 0], idx[:, 1], idx[:, 2]] = np.maximum(cur, kind)     # one kind per batch: duplicates write the same value\n\ndef label_boxes(lab):\n    """bounding slices of every label (scipy find_objects), for label_cells"""\n    from scipy import ndimage\n    return ndimage.find_objects(lab)\n\ndef label_cells(lab, r, boxes):\n    """np.argwhere(lab == r), searched only inside label r\'s bounding box (same cells, same order)"""\n    sl = boxes[r - 1] if 0 < r <= len(boxes) else None\n    if sl is None:\n        return np.zeros((0, lab.ndim), np.intp)\n    return np.argwhere(lab[sl] == r) + np.array([s.start for s in sl], np.intp)\n\ndef label_empty(solid, share=False):\n    """labels of the empty space (scipy ndimage.label of solid == 0) -> (labels, count). share=True (while share_polys(True)): the result\n    is kept for the next label_empty of an identical grid, which gets it instead of labelling again (the probe pass\'s grid, labelled\n    once more by the stationary lights). Neither caller writes into the labels."""\n    global _LAB_CACHE\n    if _LAB_CACHE is not None:\n        c_solid, c_lab, c_n = _LAB_CACHE\n        _LAB_CACHE = None                     # handed out once: not held through the passes after it\n        if c_solid.shape == solid.shape and np.array_equal(c_solid, solid):\n            return c_lab, c_n\n    from scipy import ndimage\n    lab, n = ndimage.label(solid == 0)\n    if share and _POLY_CACHE is not None:\n        # the grid to compare the next one with: voxelise()\'s own kept copy when it is this grid (no second copy held), else a copy\n        v = _VOX_CACHE[4] if _VOX_CACHE is not None else None\n        _LAB_CACHE = (v if v is not None and v.shape == solid.shape and np.array_equal(v, solid) else solid.copy(), lab, n)\n    return lab, n\n\ndef label_mask(lab, regions, n):\n    """np.isin(lab, regions) for labels 0..n, through a lookup table (same result, faster on a big grid)"""\n    tbl = np.zeros(int(n) + 1, bool)\n    r = [int(x) for x in regions if 0 <= int(x) <= n]\n    if r:\n        tbl[r] = True\n    return tbl[lab]\n\ndef run(m, c, vs=32.0):\n    lights = m.by_class(*LIGHT_CLASSES)\n    if not lights: return\n    polys = world_polys(m)\n    if not polys: return\n    solid, lo = voxelise(polys, vs)\n    lab, n = label_empty(solid)\n    shape = np.array(solid.shape)\n    exterior = set(np.unique(np.concatenate([lab[0].ravel(), lab[-1].ravel(), lab[:, 0].ravel(), lab[:, -1].ravel(), lab[:, :, 0].ravel(), lab[:, :, -1].ravel()])))\n    from scipy import ndimage\n    sky = ndimage.binary_dilation(solid == 2)\n    sky_labels = set(np.unique(lab[sky & (lab > 0)]))\n    has_env = bool(m.by_class(\'light_environment\'))\n    def vox(p): return tuple(np.clip(np.floor((np.array(p) - lo) / vs).astype(int), 0, shape - 1))\n    def region_of(p):\n        i = vox(p)\n        if lab[i]: return lab[i]\n        # light sits in a wall voxel: nearest empty voxel within 2 cells\n        best = None\n        for d in [(dx, dy, dz) for dx in (-2, -1, 0, 1, 2) for dy in (-2, -1, 0, 1, 2) for dz in (-2, -1, 0, 1, 2)]:\n            j = tuple(np.clip(np.array(i) + d, 0, shape - 1))\n            if lab[j] and (best is None or sum(x * x for x in d) < best[0]): best = (sum(x * x for x in d), lab[j])\n        return best[1] if best else 0\n    by_region = collections.defaultdict(list)\n    for e in lights:\n        by_region[region_of(m.origin(e))].append(e)\n    # region voxel centres (subsampled) for coverage / overlap checks\n    sizes = np.bincount(lab.ravel(), minlength=n + 1)          # voxels per label (was ndimage.sum of a ones grid: same counts)\n    boxes = label_boxes(lab)\n    centres = {}\n    for r in by_region:\n        if r == 0 or r in exterior: continue\n        idx = label_cells(lab, r, boxes)\n        if len(idx) > 4000: idx = idx[np.random.RandomState(r).choice(len(idx), 4000, replace=False)]\n        centres[r] = lo + (idx + 0.5) * vs\n    chosen = []            # (entity, pos, range)\n    all_samples = np.concatenate(list(centres.values())) if centres else np.zeros((0, 3))\n    overlap = np.zeros(len(all_samples), np.int32)\n    offs = {}; k = 0\n    for r, pts in centres.items(): offs[r] = (k, k + len(pts)); k += len(pts)\n    already = [e for e in lights if m.P(e, \'directlight\') in (\'2\', \'3\')]\n    for e in already:\n        p = np.array(m.origin(e)); rg = float(m.P(e, \'range\', \'512\') or 512)\n        overlap += (np.linalg.norm(all_samples - p, axis=1) < rg)\n    # rooms players can reach (spawns / teleport targets) with no light at all get a new stationary light first\n    play = collections.Counter(region_of(m.origin(e)) for e in m.by_class(\'info_player_terrorist\', \'info_player_counterterrorist\', \'info_teleport_destination\'))\n    unlit = [r for r in play if r and r not in exterior and r not in by_region and sizes[r] >= 8]\n    tmpl = next(iter(m.by_class(\'light_omni2\')), None)\n    added = 0\n    for r in unlit:\n        idx = label_cells(lab, r, boxes)\n        want = np.array([idx[:, 0].mean(), idx[:, 1].mean(), idx[:, 2].max() - 1])\n        v = idx[np.argmin(((idx - want) ** 2).sum(1))]\n        p = lo + (v + 0.5) * vs\n        rg = float(np.linalg.norm((idx - v) * vs, axis=1).max()) + 64\n        while rg > 128 and (overlap[np.linalg.norm(all_samples - p, axis=1) < rg] >= MAX_OVERLAP).any(): rg *= 0.85\n        props = {a[0].decode(): a[2].decode() for a in m.props(tmpl)[\'attrs\'] if a[0] not in (b\'classname\', b\'targetname\')} if tmpl else {}\n        props.update({\'directlight\': \'3\', \'range\': \'%.0f\' % rg, \'enabled\': \'1\', \'color\': \'255 255 255\'})\n        m.new_entity(\'light_omni2\', p, props); added += 1\n        overlap += (np.linalg.norm(all_samples - p, axis=1) < rg)\n    if added: c.log.append(\'added %d stationary light_omni2 to sealed rooms with spawns / teleport destinations that had no light at all\' % added)\n    report = {}; skipped_sky = 0\n    MIN_VOX = 64                                          # smaller pockets (lamp housings, vents) don\'t count as rooms\n    regions = [r for r in by_region if r and r not in exterior and r in centres and sizes[r] >= MIN_VOX]\n    if has_env: skipped_sky = sum(1 for r in regions if r in sky_labels); regions = [r for r in regions if r not in sky_labels]\n    regions = [r for r in regions if not any(e in already for e in by_region[r])]\n    covered = {r: np.zeros(len(centres[r]), bool) for r in regions}\n    def fit(p, rg):\n        while rg >= 128:\n            if not (overlap[np.linalg.norm(all_samples - p, axis=1) < rg] >= MAX_OVERLAP).any(): return rg\n            rg *= 0.85\n        return None\n    def take(r, e, p, rg):\n        nonlocal overlap\n        chosen.append((e, p, rg)); overlap += (np.linalg.norm(all_samples - p, axis=1) < rg)\n        covered[r] |= np.linalg.norm(centres[r] - p, axis=1) < rg\n    # pass 1: every room gets one light, smallest rooms first so the big ones can\'t crowd them out\n    for r in sorted(regions, key=lambda r: sizes[r]):\n        pts = centres[r]; best = None\n        for e in by_region[r]:\n            p = np.array(m.origin(e)); rg0 = float(m.P(e, \'range\', \'512\') or 512)\n            d = np.linalg.norm(pts - p, axis=1)\n            rg = fit(p, max(min(rg0, float(np.percentile(d, 95)) + 64), 192.0))\n            if rg is None: continue\n            gain = int((d < rg).sum())\n            if best is None or gain > best[0]: best = (gain, e, p, rg)\n        if best: take(r, best[1], best[2], best[3])\n        report[r] = 1 if best else 0\n    # pass 2: top up rooms that are still mostly uncovered\n    for r in sorted(regions, key=lambda r: covered[r].mean()):\n        pts = centres[r]\n        while report[r] and report[r] < 6 and covered[r].mean() < 0.85:\n            best = None\n            for e in by_region[r]:\n                if any(e is x[0] for x in chosen): continue\n                p = np.array(m.origin(e)); rg0 = float(m.P(e, \'range\', \'512\') or 512)\n                d = np.linalg.norm(pts - p, axis=1); left = d[~covered[r]]\n                if not len(left): continue\n                rg = fit(p, max(min(rg0, float(np.percentile(left, 90)) + 64), 192.0))\n                if rg is None: continue\n                gain = int(((d < rg) & ~covered[r]).sum())\n                if best is None or gain > best[0]: best = (gain, e, p, rg)\n            if best is None or best[0] < 0.08 * len(pts): break\n            take(r, best[1], best[2], best[3]); report[r] += 1\n    report = [(r, len(by_region[r]), report[r], round(float(covered[r].mean()), 2)) for r in regions]\n    for e, p, rg in chosen:\n        m.setp(e, \'directlight\', \'3\')\n        old = float(m.P(e, \'range\', \'0\') or 0)\n        if rg < old - 1: m.setp(e, \'range\', \'%.0f\' % rg)\n    none = [x for x in report if x[2] == 0]\n    if none: c.todo.append(\'%d compartments could not get a stationary light without going over %d overlapping - check them\' % (len(none), MAX_OVERLAP))\n    c.log.append(\'stationary lights: %d of %d lights switched Static -> Stationary (directlight 3) across %d sealed compartments, ranges trimmed so no spot is inside more than %d%s\'\n                 % (len(chosen), len(lights), len(report), MAX_OVERLAP, \'; %d compartments open to sky left to light_environment\' % skipped_sky if skipped_sky else \'\'))\n    weak = [x for x in report if x[3] < 0.6]\n    if weak: c.todo.append(\'%d compartments only partly covered by stationary light (overlap cap) - check weapons are lit there\' % len(weak))\n    return report\n'
_BUNDLED_VMAP_MODULES['visfit'] = '"""Vis compile time: hint boxes fitted to the play space, and sky shells out of vis where nothing needs them.\n\nThe CS2 vis compile (VIS3) spends most of its time clustering, sampling line of sight and merging clusters down to the 4,096 cap.\nHow many clusters it starts with depends on the visibility_hint that governs each part of the map (where hints overlap, the\nhighest resolution wins). So hints should only be fine where players can actually stand.\n\n1. Playable air: empty space at VS-unit voxels (world meshes that block players, incl. clips, detail and sky shells) connected\n   to a spawn or teleport destination, plus sealed compartments that hold gameplay entities (buttons, doors, triggers, trains,\n   weapons). The open void around the map never counts.\n2. Walkable band: playable air up to BAND units above something to stand on (world or entity meshes). Air inside a big active\n   trigger_hurt / trigger_teleport (HAZ_MIN) is not playable: players never stay there (deep kill water, death pits).\n3. Hints, on a 256-unit grid so they line up with the Lowest regions, Low and Lower never overlapping:\n     Low    (hintType 3, 64-unit grid)                         cells holding walkable band\n     Lower  (hintType 8, 64-unit grid, fewer initial clusters)  other playable air next to geometry (high ceilings, shafts)\n     Lowest (hintType 9, 256-unit grid)                         one box over the whole map: void, sealed-off rooms, open sky\n   Open sky far above an outdoor area gets no box of its own, so it falls to Lowest. all_lower=True makes the Low cells Lower too\n   (for maps whose vis merge stalls, e.g. mg_egypt_course). Boxes are merged while at least 75% (then 60%, 50%) of a box is its\n   own cells, aiming for at most 100 boxes.\n4. Sky shells (meshes whose faces are all sky, moondome / toolsskybox, apart from toolsnodraw faces vis ignores) get Exclude\n   from Vis. sky_shells=\'all\' (default): every one. A sky shell never hides anything that exists (nothing is outside the sky)\n   and CS2 maps need not be sealed, so it only adds vis surface, and vis time follows vis surface (piratewars: 108k regions\n   with its sea\'s shell in vis, 46k without; built and looked right). sky_shells=\'sealed\': only shells not needed to close\n   playable air (the earlier, cautious rule), tested on vis-relevant geometry only.\n5. Optional extra_visex_box (world box): every world mesh entirely inside it is excluded from vis too (an unreachable\n   ex-3D-skybox, for example).\nExisting visibility_hint entities are replaced.\n"""\nimport collections\nimport numpy as np\nfrom scipy import ndimage\nimport dmx\nfrom lighting import mesh_polys, tri_batches, label_mask\n\nPLAY = (\'info_player_counterterrorist\', \'info_player_terrorist\', \'info_player_start\', \'info_teleport_destination\')\nACTIVE = (\'func_button\', \'func_rot_button\', \'func_door\', \'func_door_rotating\', \'func_movelinear\', \'trigger_multiple\', \'trigger_once\',\n          \'trigger_teleport\', \'game_player_equip\', \'point_teleport\', \'func_tracktrain\', \'func_rotating\', \'func_physbox\')\nPHYS_PASS = (\'materials/tools/toolstrigger\', \'materials/tools/toolshint\', \'materials/tools/toolsskip\', \'materials/tools/toolsfog\',\n             \'materials/tools/toolslight\', \'materials/tools/toolsblocklight\', \'materials/tools/toolsblock_los\', \'materials/tools/toolsbuyzone\',\n             \'materials/tools/toolsbombsite\', \'materials/tools/toolsareaportal\', \'materials/tools/toolsoccluder\', \'materials/tools/toolsvisblocker\')\nCELL = 256.0\nBAND = 160.0\nAUTO_LOW_CELLS = 2000   # all_lower=\'auto\': more 256-unit cells of walkable band than this -> all Lower (piratewars 732 builds fine; mg_hellz 2861 stalled in Merge vis clusters)\nHAZ_MIN = 0.5e9   # trigger volumes at least this big (cubic units) that hurt or teleport count as not playable (deep kill water, death pits)\nCODE = {\'Low\': \'3\', \'Lower\': \'8\', \'Lowest\': \'9\'}\n\ndef is_sky(x):\n    return \'moondome\' in x or x.startswith(\'materials/tools/toolsskybox\')   # toolsskybox, toolsskybox_occluder (SKY_OCCLUDER)\n\ndef is_shell(mats):\n    # sky shells: every face sky (moondome / toolsskybox), or sky plus faces vis ignores anyway (toolsnodraw), e.g. a sky wall rebuilt as a box\n    return bool(mats) and any(is_sky(x) for x in mats) and all(is_sky(x) or x == \'materials/tools/toolsnodraw.vmat\' for x in mats)\n\ndef vis_relevant(mat):\n    if \'moondome\' in mat: return True\n    if mat.startswith(\'materials/tools/\'):\n        return mat.startswith((\'materials/tools/toolsskybox\', \'materials/tools/toolssolidblocklight\', \'materials/tools/toolsvisblocker\'))\n    return True\n\ndef meshes(m):\n    par = {n: p for n, p in m.walk()}\n    def in_ent(n):\n        p = par.get(n)\n        while p is not None:\n            if m.type(p) == b\'CMapEntity\': return p\n            p = par.get(p)\n        return None\n    out = []\n    for n, _ in m.walk():\n        if m.type(n) != b\'CMapMesh\': continue\n        pl = mesh_polys(m, n); mats = {x for x, _ in pl}\n        a = dmx.geta(m.E[n], b\'visexclude\')\n        out.append(dict(n=n, ent=in_ent(n), polys=pl, mats=mats, shell=is_shell(mats), visex=bool(a and a[2])))\n    return out\n\ndef raster(polys, lo, shape, vs, grid):\n    def items():\n        for L in polys:\n            L = np.asarray(L, np.float64)\n            if (np.floor((L.max(0) - lo) / vs) < 0).any() or (np.floor((L.min(0) - lo) / vs) >= shape).any(): continue\n            yield L, 0\n    for q, _ in tri_batches(items(), vs * 0.4):\n        idx = np.floor((q - lo) / vs).astype(int)\n        idx = idx[((idx >= 0) & (idx < shape)).all(1)]\n        grid[idx[:, 0], idx[:, 1], idx[:, 2]] = True\n\ndef _border(lab):\n    return set(np.unique(np.concatenate([lab[0].ravel(), lab[-1].ravel(), lab[:, 0].ravel(), lab[:, -1].ravel(),\n                                         lab[:, :, 0].ravel(), lab[:, :, -1].ravel()]))) - {0}\n\ndef boxes_from_cells(cells):\n    left = set(cells); out = []\n    while left:\n        i, j, k = min(left)\n        x1 = i\n        while (x1 + 1, j, k) in left: x1 += 1\n        y1 = j\n        while all((x, y1 + 1, k) in left for x in range(i, x1 + 1)): y1 += 1\n        z1 = k\n        while all((x, y, z1 + 1) in left for x in range(i, x1 + 1) for y in range(j, y1 + 1)): z1 += 1\n        for x in range(i, x1 + 1):\n            for y in range(j, y1 + 1):\n                for z in range(k, z1 + 1): left.discard((x, y, z))\n        out.append(((i, j, k), (x1 + 1, y1 + 1, z1 + 1)))\n    return out\n\ndef merge_boxes(boxes, own, other, fill=0.75):\n    """join boxes whose union is mostly own cells and holds none of the other hint type\'s cells (boxes stay disjoint)"""\n    boxes = [(tuple(a), tuple(b)) for a, b in boxes]\n    if len(boxes) < 2: return boxes\n    allc = np.array(list(own | other))\n    o = allc.min(0); sz = allc.max(0) - o + 1\n    def cum(cs):\n        g = np.zeros(sz + 1, np.int32)\n        for c in cs: g[tuple(np.array(c) - o + 1)] = 1\n        return g.cumsum(0).cumsum(1).cumsum(2)\n    O, T = cum(own), cum(other)\n    def cnt(S, a, b):        # a, b: (k, 3) arrays of box corners -> cell counts of all k boxes\n        a = np.asarray(a) - o; b = np.asarray(b) - o\n        x0, y0, z0 = a[:, 0], a[:, 1], a[:, 2]; x1, y1, z1 = b[:, 0], b[:, 1], b[:, 2]\n        return (S[x1, y1, z1] - S[x0, y1, z1] - S[x1, y0, z1] - S[x1, y1, z0] + S[x0, y0, z1] + S[x0, y1, z0] + S[x1, y0, z0] - S[x0, y0, z0]).astype(np.int64)\n    while len(boxes) > 1:\n        A = np.array([bx[0] for bx in boxes]); B = np.array([bx[1] for bx in boxes])\n        best = None\n        for i in range(len(boxes)):\n            ua = np.minimum(A[i], A[i + 1:]); ub = np.maximum(B[i], B[i + 1:])\n            vols = np.prod(ub - ua, axis=1)          # every candidate\'s volume in one call\n            if not len(vols): continue\n            ns, ts = cnt(O, ua, ub), cnt(T, ua, ub)   # every candidate\'s cell counts in one call\n            for a, b, v, n, tn in zip(ua, ub, vols, ns, ts):\n                v = int(v)\n                if v > 4096: continue\n                n = int(n)\n                if n / v < fill or (best and n / v <= best[0]) or tn: continue\n                ins = np.all((A >= a) & (B <= b), 1); ovl = np.all((A < b) & (B > a), 1)\n                if (ovl & ~ins).any(): continue\n                best = (n / v, tuple(a), tuple(b), ins)\n        if not best: break\n        _, a, b, ins = best\n        boxes = [bx for k, bx in enumerate(boxes) if not ins[k]] + [(a, b)]\n    return boxes\n\ndef plan(m, all_lower=False, extra_visex_box=None, vs=None, margin=256.0, sky_shells=\'all\'):\n    ms = meshes(m)\n    world = [x for x in ms if x[\'ent\'] is None]\n    allp = np.array([p for x in world for _, l in x[\'polys\'] for p in l])\n    lo = allp.min(0) - margin; hi = allp.max(0) + margin\n    if vs is None:     # keep the grids within the cloud workspace\'s memory\n        vs = next((v for v in (16.0, 24.0, 32.0, 48.0, 64.0, 96.0, 128.0) if np.prod(np.ceil((hi - lo) / v)) < 1.2e8), 128.0)   # mg_divine is 31k x 32k x 15k units: 48 was not enough\n    shape = np.array([int(v) for v in np.ceil((hi - lo) / vs)])\n    phys = np.zeros(shape, bool); visg = np.zeros(shape, bool); ent = np.zeros(shape, bool); sh = np.zeros(shape, np.int32)\n    raster([l for x in world for mt, l in x[\'polys\'] if not mt.startswith(PHYS_PASS)], lo, shape, vs, phys)\n    raster([l for x in world if not x[\'visex\'] and not x[\'shell\'] for mt, l in x[\'polys\'] if vis_relevant(mt)], lo, shape, vs, visg)\n    raster([l for x in ms if x[\'ent\'] is not None for mt, l in x[\'polys\'] if not mt.startswith(PHYS_PASS)], lo, shape, vs, ent)\n    shells = [x for x in world if x[\'shell\']]\n    for si, x in enumerate(shells, 1):\n        g = np.zeros(shape, bool); raster([l for _, l in x[\'polys\']], lo, shape, vs, g); sh[g] = si\n    lab, n_lab = ndimage.label(~(phys | (sh > 0)))\n    def comp_at(p, r=3):\n        i = np.floor((np.array(p, float) - lo) / vs).astype(int)\n        for rr in range(r + 1):\n            v = lab[tuple(slice(max(0, i[k] - rr), i[k] + rr + 1) for k in range(3))]; v = v[v > 0]\n            if v.size: return int(np.bincount(v).argmax())\n        return 0\n    seeds = {comp_at(np.array(m.origin(e), float) + [0, 0, 36]) for e in m.by_class(*PLAY)} - {0}\n    act = {comp_at(m.origin(e), 2) for e in m.entities() if m.cls(e) in ACTIVE or m.cls(e).startswith(\'weapon_\')} - {0}\n    border = _border(lab)\n    comps = (seeds | act) - border\n    P = label_mask(lab, comps, n_lab)\n    del lab\n    # air filled by a big active trigger_hurt (damage > 0) / trigger_teleport: players never stay there (piratewars\' deep water hurts\n    # 10/s from just under the surface to the sea floor), so no fine hint over it; it falls to Lowest\n    haz = np.zeros(shape, bool); hazv = 0.0\n    for e in m.by_class(\'trigger_hurt\', \'trigger_teleport\'):\n        if (m.P(e, \'StartDisabled\', \'0\') or \'0\').strip() == \'1\': continue\n        if m.cls(e) == \'trigger_hurt\':\n            try:\n                if float(m.P(e, \'damage\', \'0\') or 0) <= 0: continue\n            except ValueError:\n                continue\n        bb = m.bounds(e)\n        if not bb: continue\n        vol = float(np.prod(np.array(bb[1]) - np.array(bb[0])))\n        if vol < HAZ_MIN: continue\n        a = np.clip(np.floor((np.array(bb[0]) - lo) / vs).astype(int), 0, shape); b = np.clip(np.ceil((np.array(bb[1]) - lo) / vs).astype(int), 0, shape)\n        haz[a[0]:b[0], a[1]:b[1], a[2]:b[2]] = True\n    hazv = float((P & haz).sum()) * vs ** 3 / 1e9\n    P &= ~haz\n    del haz\n    solid = phys | (sh > 0) | ent\n    band = np.zeros(shape, bool)\n    for k in range(1, int(BAND / vs) + 1):\n        band[:, :, k:] |= solid[:, :, :-k]\n    band &= P\n    del solid\n    def cells_of(mask):\n        idx = np.argwhere(mask)\n        cells = np.floor((lo + (idx + 0.5) * vs) / CELL).astype(int)\n        if not len(cells): return set()\n        mn = cells.min(0)                        # each cell once: marked in a grid of cells (np.unique(axis=0) sorted every voxel\'s triple)\n        occ = np.zeros(tuple(cells.max(0) - mn + 1), bool)\n        occ[cells[:, 0] - mn[0], cells[:, 1] - mn[1], cells[:, 2] - mn[2]] = True\n        return set(map(tuple, (np.argwhere(occ) + mn).tolist()))\n    pc, bc = cells_of(P), cells_of(band)\n    geo = cells_of((phys & (sh == 0)) | visg | ent)\n    low = set(bc); lower = (pc - low) & geo\n    auto = None\n    if all_lower == \'auto\':          # big maps: the Low cells alone give VIS3 more clusters than its merge step gets through\n        auto = len(low); all_lower = auto > AUTO_LOW_CELLS\n    if all_lower: lower |= low; low = set()\n    for fill in (0.75, 0.6, 0.5):\n        hints = [(\'Low\', a, b) for a, b in merge_boxes(boxes_from_cells(low), low, lower, fill)] + \\\n                [(\'Lower\', a, b) for a, b in merge_boxes(boxes_from_cells(lower), lower, low, fill)]\n        if len(hints) <= 100: break\n    hints = [(t, np.array(a) * CELL, np.array(b) * CELL) for t, a, b in hints]\n    hints.append((\'Lowest\', np.floor(allp.min(0) / 256) * 256 - 256, np.ceil(allp.max(0) / 256) * 256 + 256))\n    # sky shells: keep the ones bordering playable air that is open once all sky shells are gone\n    vl, _ = ndimage.label(~visg)\n    leaky = P & np.isin(vl, list(_border(vl)))\n    del vl\n    near_leak = ndimage.binary_dilation(leaky, iterations=2)\n    keep_ids = set(np.unique(sh[near_leak & (sh > 0)])) - {0} if sky_shells == \'sealed\' else set()\n    exclude = [x for si, x in enumerate(shells, 1) if si not in keep_ids and not x[\'visex\']]\n    extra = []\n    if extra_visex_box is not None:\n        a, b = np.array(extra_visex_box[0], float), np.array(extra_visex_box[1], float)\n        for x in world:\n            if x[\'visex\'] or x[\'shell\']: continue\n            bb = m.bounds(x[\'n\'])\n            if bb and (np.array(bb[0]) >= a).all() and (np.array(bb[1]) <= b).all(): extra.append(x)\n    stats = dict(vs=vs, hazard=hazv, play=P.sum() * vs ** 3 / 1e9, band=band.sum() * vs ** 3 / 1e9, shells=len(shells), kept=len(shells) - len(exclude),\n                 hints=dict(collections.Counter(h[0] for h in hints)))\n    return dict(hints=hints, exclude=exclude, extra=extra, stats=stats, auto=auto, all_lower=bool(all_lower))\n\ndef apply(m, pl):\n    for e in m.by_class(\'visibility_hint\'): m.remove_node(e)\n    for t, mn, mx in pl[\'hints\']:\n        o = (mn + mx) / 2\n        m.new_entity(\'visibility_hint\', o, {\'box_mins\': \' \'.join(\'%g\' % v for v in mn - o), \'box_maxs\': \' \'.join(\'%g\' % v for v in mx - o),\n                                            \'hintType\': CODE[t]})\n    for x in pl[\'exclude\'] + pl[\'extra\']:\n        a = dmx.geta(m.E[x[\'n\']], b\'visexclude\')\n        if a: a[2] = True\n        else: dmx.set_(m.E[x[\'n\']], b\'visexclude\', dmx.T_BOOL, True)\n\ndef run(m, c, all_lower=False, extra_visex_box=None, sky_shells=\'all\'):\n    old = collections.Counter({\'3\': \'Low\', \'8\': \'Lower\', \'9\': \'Lowest\', \'2\': \'Medium\', \'0\': \'High\', \'1\': \'Normal\', \'10\': \'Reduced\'}\n                              .get(m.P(e, \'hintType\', \'\'), \'?\') for e in m.by_class(\'visibility_hint\'))\n    pl = plan(m, all_lower, extra_visex_box, sky_shells=sky_shells)\n    apply(m, pl)\n    s = pl[\'stats\']; h = s[\'hints\']\n    c.log.append(\'visfit (%g-unit voxels): %.1f billion cubic units of playable air, %.1f of it walkable band (%.1f inside big hurt / teleport triggers left out); hints %d Low, %d Lower, %d Lowest%s\'\n                 % (s[\'vs\'], s[\'play\'], s[\'band\'], s[\'hazard\'], h.get(\'Low\', 0), h.get(\'Lower\', 0), h.get(\'Lowest\', 0),\n                    (\' (replacing \' + \', \'.join(\'%d %s\' % (v, k) for k, v in old.items()) + \')\') if old else \'\'))\n    if pl.get(\'auto\') is not None:\n        c.log.append(\'visfit: %d cells of walkable band (256 units) -> %s (all_lower auto, limit %d)\'\n                     % (pl[\'auto\'], \'all Lower: a vis compile this big stalls in Merge vis clusters with Low\' if pl[\'all_lower\'] else \'Low kept\', AUTO_LOW_CELLS))\n    if s[\'shells\']:\n        c.log.append(\'visfit: %d of %d sky shell meshes set to Exclude from Vis%s\'\n                     % (len(pl[\'exclude\']), s[\'shells\'], (\', %d kept because they close playable air\' % s[\'kept\']) if sky_shells == \'sealed\'\n                        else (\' (the others already were)\' if len(pl[\'exclude\']) < s[\'shells\'] else \'\')))\n    if pl[\'extra\']: c.log.append(\'visfit: %d meshes inside %s set to Exclude from Vis\' % (len(pl[\'extra\']), extra_visex_box))\n    c.todo.append(\'vis: if anything pops in or out of view where players stand, change the nearest Lower hint to Low (or Low to Medium)\')\n    return pl\n'
_BUNDLED_VMAP_MODULES['probes'] = '"""Light probe pass: env_combined_light_probe_volume fitted to each playable compartment.\n\nPlayers, weapons and props get their indirect light from light probe volumes; without them they render dark.\nUnlike daylight.py (one slab per 2048 units along the map\'s longest axis), this fits volumes to the actual\nempty space of each compartment a player can reach, split into tiles of at most TILE units so no single\nvolume covers a huge empty bounding box.\n\nPlayable compartments: empty-space regions (world geometry voxelised and flood-filled, as in lighting.py)\nholding a spawn or teleport destination. The open void outside the map never counts.\nExisting probe volumes are left alone unless replace=True.\n"""\nimport numpy as np\nfrom lighting import world_polys, mesh_polys, voxelise, voxelise_into, label_empty, label_boxes, label_cells, label_mask\n\nSEEDS = (\'info_player_counterterrorist\', \'info_player_terrorist\', \'info_player_start\', \'info_teleport_destination\')\nPROBE_CLASSES = (\'env_combined_light_probe_volume\', \'env_light_probe_volume\')\nTILE = 2048.0      # max volume edge length\nFOREIGN_MAX = 0.05      # most of another compartment\'s voxels a volume\'s box may hold, against its own\nMIN_SPLIT = 256.0       # boxes this small across are not cut further\nPAD = 48.0         # extra space around the compartment so probes cover the walls\nMIN_VOX = 8        # ignore tiny pockets\n\nPROPS = dict(StartDisabled=0, cubemaptexture=\'\', bakenearz=\'2.0\', bakefarz=\'4096.0\', lightgroup=\'\', moveable=0,\n             lightprobetexture=\'\', voxel_size=\'48.0\', flood_fill=1, voxelize=1, light_probe_volume_from_cubemap=0,\n             storage=-1, indoor_outdoor_level=0, edge_fade_dists=\'0 32 0\', clientSideEntity=1)\n\n\ndef run(m, c, vs=32.0, replace=False, wall_classes=(), water_merge=0.0, share_labels=False):\n    """wall_classes: brush entities (e.g. func_breakable) that count as walls: compartments are split at them (a room reached only\n    through one still gets its volume) and a volume side that meets one stops at its face instead of padding into it.\n    water_merge: the TILE layer holding a func_water\'s surface is not split sideways (one volume across it) while it is at most this\n    wide. Each volume bakes its own cubemap and probes, and water shows every tile edge as a step in its reflection and fog\n    lighting (piratewars: a 3 x 3 grid of 2048-unit squares on the sea). 0 = off.\n    share_labels: the stationary light pass runs next on the same grid: its labels are kept for it (only with no wall entities, when\n    they are the labels of exactly that grid; with walls they would be held while the walls are labelled in, for nothing)."""\n    existing = m.by_class(*PROBE_CLASSES)\n    if existing and not replace:\n        c.log.append(\'probes: map already has %d light probe volumes - left alone (run the probes_replace pass to refit them)\' % len(existing))\n        return\n    polys = world_polys(m)\n    if not polys:\n        c.todo.append(\'probes: no world geometry found - no probe volumes added\')\n        return\n    walls = [e for e in m.entities() if m.cls(e) in wall_classes]\n    wpolys = [p for e in walls for ch in m.children(e) if m.type(ch) == b\'CMapMesh\' for p in mesh_polys(m, ch)]\n    wboxes = [b for b in (m.bounds(e) for e in walls) if b]\n    solid, lo = voxelise(polys, vs, extent=polys + wpolys)   # same grid as below, walls left out\n    with_walls = solid.copy() if wpolys else None\n    lab, n_lab = label_empty(solid, share=share_labels and not wpolys)\n    shape = np.array(lab.shape)\n\n    def border_of(lab):\n        return set(np.unique(np.concatenate([lab[0].ravel(), lab[-1].ravel(), lab[:, 0].ravel(), lab[:, -1].ravel(),\n                                             lab[:, :, 0].ravel(), lab[:, :, -1].ravel()]))) - {0}\n    border = border_of(lab)\n\n    def region_at(p, r=2):\n        i = np.clip(np.floor((np.asarray(p, float) - lo) / vs).astype(int), 0, shape - 1)\n        for rr in range(r + 1):\n            v = lab[tuple(slice(max(0, i[k] - rr), i[k] + rr + 1) for k in range(3))]\n            v = v[v > 0]\n            if v.size: return int(np.bincount(v).argmax())\n        return 0\n\n    regions, leaked = set(), 0\n    for e in m.by_class(*SEEDS):\n        r = region_at(np.array(m.origin(e), float) + [0, 0, 36])\n        if r in border: leaked += 1\n        elif r: regions.add(r)\n    if leaked:\n        c.todo.append(\'probes: %d spawns / teleport destinations sit in space connected to the outside of the map (a leak?) - no probes there\' % leaked)\n    if not regions:\n        c.todo.append(\'probes: no sealed playable compartments found - no probe volumes added\')\n        return\n    if wpolys:                                       # split the playable space again with the walls in\n        playable = label_mask(lab, regions, n_lab)\n        del lab\n        voxelise_into(with_walls, lo, wpolys, vs)        # the same grid with the walls added (was a second full voxelise)\n        solid = with_walls\n        lab, _ = label_empty(solid)\n        border = border_of(lab)\n        regions = set(int(x) for x in np.unique(lab[playable & (lab > 0)])) - border\n        del playable\n\n    for e in existing: m.remove_node(e)\n    n_vol = n_snap = n_merged = n_inside = n_split = 0\n    reg_arr = np.array(sorted(regions))\n    made = []\n    waters = [tuple(np.array(x, float) for x in b) for b in (m.bounds(e) for e in m.by_class(\'func_water\')) if b]\n    boxes = label_boxes(lab)\n    for r in sorted(regions):\n        idx = label_cells(lab, r, boxes)\n        if len(idx) < MIN_VOX: continue\n        P = lo + (idx + 0.5) * vs\n        tile = np.floor((P - P.min(0)) / TILE).astype(int)\n        if water_merge > 0 and waters:\n            span = P.max(0) - P.min(0)\n            layers = set()\n            for wb0, wb1 in waters:\n                if (wb1[:2] < P.min(0)[:2]).any() or (wb0[:2] > P.max(0)[:2]).any():\n                    continue\n                if P.min(0)[2] <= wb1[2] <= P.max(0)[2]:\n                    layers.add(int(np.floor((wb1[2] - P.min(0)[2]) / TILE)))\n            if layers and max(span[0], span[1]) <= water_merge:\n                lay = np.isin(tile[:, 2], list(layers))\n                tile[lay, 0] = 0\n                tile[lay, 1] = 0\n                n_merged += len(layers)\n        # the bounds of each tile\'s voxels, tiles in np.unique(tile, axis=0)\'s order: the voxels sorted by tile once (it was that np.unique,\n        # then a scan of the whole region for every tile)\n        tdim = tile.max(0) + 1\n        tkey = (tile[:, 0] * tdim[1] + tile[:, 1]) * tdim[2] + tile[:, 2]\n        tord = np.argsort(tkey, kind=\'stable\')\n        tkey = tkey[tord]\n        tstart = np.flatnonzero(np.concatenate(([True], tkey[1:] != tkey[:-1])))\n        Ps = P[tord]\n        tends = list(tstart[1:]) + [len(Ps)]\n        del tord, tkey\n        # a tile\'s box can reach into another compartment (another level beside or under it, round a corner): that space would take\n        # this volume\'s light and cubemap. A box holding more than FOREIGN_MAX of another compartment\'s voxels (against its own) is cut in\n        # two across its longest side at its voxels\' median, again until it doesn\'t or is MIN_SPLIT across (mg_hellz: the layer kept whole\n        # for its water spread 4576 units over two other levels)\n        pieces, stack = [], [Ps[s0:s1] for s0, s1 in zip(tstart, tends)]\n        while stack:\n            Q = stack.pop()\n            a0 = np.clip(np.floor((Q.min(0) - vs / 2 - PAD - lo) / vs).astype(int), 0, None)\n            a1 = np.minimum(np.ceil((Q.max(0) + vs / 2 + PAD - lo) / vs).astype(int), lab.shape)\n            sub = lab[a0[0]:a1[0], a0[1]:a1[1], a0[2]:a1[2]]\n            foreign = int((np.isin(sub, reg_arr) & (sub != r)).sum())\n            ext = Q.max(0) - Q.min(0)\n            k = int(np.argmax(ext))\n            if foreign > FOREIGN_MAX * len(Q) and ext[k] >= MIN_SPLIT:\n                cut = np.median(Q[:, k])\n                lo_ = Q[:, k] <= cut\n                if lo_.all() or not lo_.any():\n                    lo_ = Q[:, k] < cut\n                if lo_.any() and not lo_.all():\n                    stack += [Q[lo_], Q[~lo_]]\n                    n_split += 1\n                    continue\n            pieces.append((Q.min(0), Q.max(0)))\n        del Ps\n        for tmin_, tmax_ in pieces:\n            vmn, vmx = tmin_ - vs / 2, tmax_ + vs / 2\n            # a pocket inside a wall entity\'s own bounds (between the nested rings of mg_mario_party\'s breakable island, inside a\n            # breakable crate): only reachable once it breaks, when the volume around it covers it. A volume of its own there bakes its\n            # own dark cubemap, and on a water surface every such volume\'s edge shows in the reflection\n            if any((vmn >= np.asarray(b0, float) - 1).all() and (vmx <= np.asarray(b1, float) + 1).all() for b0, b1 in wboxes):\n                n_inside += 1\n                continue\n            mn, mx = vmn - PAD, vmx + PAD\n            for k in range(3):                       # a side meeting a wall entity stops at the wall\'s face\n                o1, o2 = [a for a in range(3) if a != k]\n                for b0, b1 in wboxes:\n                    ov = (max(0.0, min(mx[o1], b1[o1]) - max(mn[o1], b0[o1])) * max(0.0, min(mx[o2], b1[o2]) - max(mn[o2], b0[o2])))\n                    if ov <= 0: continue\n                    if vmx[k] - vs <= b0[k] < mx[k]:\n                        mx[k] = max(b0[k], vmx[k] - vs); n_snap += 1\n                    if mn[k] < b1[k] <= vmn[k] + vs:\n                        mn[k] = min(b1[k], vmn[k] + vs); n_snap += 1\n            o = (mn + mx) / 2\n            props = dict(PROPS, box_mins=\'%f %f %f\' % tuple(mn - o), box_maxs=\'%f %f %f\' % tuple(mx - o))\n            m.new_entity(\'env_combined_light_probe_volume\', o, props)\n            made.append((mn.copy(), mx.copy()))\n            n_vol += 1\n    # a water surface still crossed by more than one volume (several tiles, or a tile and a room\'s volume) shows each volume\'s edge as a\n    # step in its reflection and fog lighting: it gets a thin volume of its own around the surface, at a higher priority, so the whole\n    # surface takes its lighting and cubemap from one volume\n    n_wv = 0\n    if water_merge > 0:\n        for wb0, wb1 in waters:\n            top = wb1[2]\n            cross = [(a, b) for a, b in made if a[2] <= top <= b[2] and a[0] < wb1[0] and wb0[0] < b[0] and a[1] < wb1[1] and wb0[1] < b[1]]\n            if len(cross) < 2 or any(a[0] <= wb0[0] and a[1] <= wb0[1] and wb1[0] <= b[0] and wb1[1] <= b[1] for a, b in cross):\n                continue                         # one volume already holds the whole surface (smaller ones inside hulls etc. do no harm)\n            mn = np.array([wb0[0] - PAD, wb0[1] - PAD, top - min(max(wb1[2] - wb0[2], 16.0), 256.0)])\n            mx = np.array([wb1[0] + PAD, wb1[1] + PAD, top + 16.0])\n            o = (mn + mx) / 2\n            props = dict(PROPS, box_mins=\'%f %f %f\' % tuple(mn - o), box_maxs=\'%f %f %f\' % tuple(mx - o), indoor_outdoor_level=1)\n            m.new_entity(\'env_combined_light_probe_volume\', o, props)\n            n_vol += 1\n            n_wv += 1\n    c.log.append(\'probes: %s%d env_combined_light_probe_volume fitted to %d playable compartments (tiles up to %g units)%s\'\n                 % (\'replaced %d existing volumes with \' % len(existing) if existing else \'\', n_vol, len(regions), TILE,\n                    \'; %s count as walls: %d volume side(s) stop at their faces\' % (\'/\'.join(wall_classes), n_snap) if wall_classes else \'\')\n                 + (\'; %d pocket(s) inside a wall entity left to the volume around it\' % n_inside if n_inside else \'\')\n                 + (\'; %d box(es) cut where they reached into another compartment\' % n_split if n_split else \'\')\n                 + (\'; %d layer(s) holding a water surface kept as one volume across (no tile edges on the water)\' % n_merged if n_merged else \'\')\n                 + (\'; %d water surface(s) crossed by several volumes got one of their own (priority High)\' % n_wv if n_wv else \'\'))\n    c.todo.append(\'probes: after a full bake, check players / weapons are lit evenly; if a room looks off, check its probe volume covers it\')\n'
_BUNDLED_VMAP_MODULES['splitfaces'] = '"""Split very large lit faces of a .vmap into tiles (development copy; pasted into rebuild_lighting.py).\n\nWhy: in CS2 a face is one lightmap chart, and a mesh (CMapMesh) gets one probe / cubemap for the whole mesh. A huge floor\ntherefore bakes blotchy and reflects the wrong place.  This cuts faces over `limit` square units on a world-aligned grid\n(`cell` units) and, optionally, gives every grid cell its own copy of the mesh.\n\nAll geometry is rebuilt from polygons: vertices are welded by position, every undirected edge gets two half-edges (the twin of\na boundary edge has face -1), and the corner data (texcoord / normal / tangent / vertex paint) is interpolated along cut edges.\nMeshes with subdivision data (importer displacements) and non-convex faces are left alone.\n"""\nimport numpy as np\n\nEPS = 0.01          # a point this close to a cut plane counts as on it\nWELD = 3            # vertex welding, decimals\n\n\n# ----------------------------------------------------------------------------------------------------------- reading\ndef _streams(m, node, part):\n    """-> {stream name: (element index, data list)} for meshData.<part>"""\n    md = m.g(node, b\'meshData\')\n    pd = m.g(md, part)\n    return {m.E[st][\'name\'].decode(): (st, m.g(st, b\'data\')) for st in (m.g(pd, b\'streams\') or [])}\n\n\ndef mesh_has_subdivision(m, node):\n    sd = m.g(m.g(node, b\'meshData\'), b\'subdivisionData\')\n    return bool(sd is not None and m.g(sd, b\'streams\'))\n\n\ndef mesh_read(m, node):\n    """-> (polys, materials).  poly = {\'attrs\': {faceData stream: value}, \'corners\': [{\'pos\': ndarray(3), \'fvd\': {stream: ndarray}}]}"""\n    md = m.g(node, b\'meshData\')\n    dest, nxt = m.g(md, b\'edgeVertexIndices\'), m.g(md, b\'edgeNextIndices\')\n    fe, fd = m.g(md, b\'faceEdgeIndices\'), m.g(md, b\'faceDataIndices\')\n    evd, vdi = m.g(md, b\'edgeVertexDataIndices\'), m.g(md, b\'vertexDataIndices\')\n    pos = _streams(m, node, b\'vertexData\')[\'position:0\'][1]\n    fvd = {k: v[1] for k, v in _streams(m, node, b\'faceVertexData\').items()}\n    fdat = {k: v[1] for k, v in _streams(m, node, b\'faceData\').items()}\n    polys = []\n    for f, h0 in enumerate(fe):\n        corners, h = [], h0\n        for _ in range(len(dest) + 1):\n            corners.append({\'pos\': np.array(pos[vdi[dest[h]]], float), \'vid\': dest[h],\n                            \'fvd\': {k: np.array(v[evd[h]], float) for k, v in fvd.items()}})\n            h = nxt[h]\n            if h == h0:\n                break\n        polys.append({\'attrs\': {k: v[fd[f]] for k, v in fdat.items()}, \'corners\': corners})\n    return polys, [x.decode(\'utf-8\', \'replace\') if isinstance(x, (bytes, bytearray)) else x for x in m.g(md, b\'materials\')]\n\n\n# ------------------------------------------------------------------------------------------------------------ geometry\ndef poly_area(corners):\n    # (plain floats: the same products and sums as np.cross per corner gave, without its per-call cost)\n    P = np.array([c[\'pos\'] for c in corners], float).tolist()\n    x0, y0, z0 = P[0] if P else (0.0, 0.0, 0.0)\n    n0 = n1 = n2 = 0.0\n    for i in range(1, len(P) - 1):\n        a, b = P[i], P[i + 1]\n        ax, ay, az = a[0] - x0, a[1] - y0, a[2] - z0\n        bx, by, bz = b[0] - x0, b[1] - y0, b[2] - z0\n        n0 += ay * bz - az * by\n        n1 += az * bx - ax * bz\n        n2 += ax * by - ay * bx\n    return float(np.linalg.norm(np.array([n0, n1, n2])) / 2)\n\n\ndef is_convex(corners, tol=1e-6):\n    P = np.array([c[\'pos\'] for c in corners])\n    n = np.zeros(3)\n    for i in range(1, len(P) - 1):\n        n += np.cross(P[i] - P[0], P[i + 1] - P[0])\n    ln = np.linalg.norm(n)\n    if ln < 1e-9:\n        return False\n    n /= ln\n    for i in range(len(P)):\n        c = np.dot(np.cross(P[(i + 1) % len(P)] - P[i], P[(i + 2) % len(P)] - P[(i + 1) % len(P)]), n)\n        if c < -tol * max(1.0, ln):\n            return False\n    return True\n\n\ndef _lerp(a, b, t):\n    out = {\'pos\': a[\'pos\'] + (b[\'pos\'] - a[\'pos\']) * t, \'fvd\': {}}\n    for k in a[\'fvd\']:\n        v = a[\'fvd\'][k] + (b[\'fvd\'][k] - a[\'fvd\'][k]) * t\n        if k.startswith(\'normal\'):\n            ln = np.linalg.norm(v)\n            if ln > 1e-9:\n                v = v / ln\n        out[\'fvd\'][k] = v\n    return out\n\n\ndef _edge_key(p, q):\n    a, b = tuple(np.round(p, WELD)), tuple(np.round(q, WELD))\n    return (a, b) if a <= b else (b, a)\n\n\ndef clip_poly(corners, axis, c):\n    """Cut a convex polygon with the plane  pos[axis] = c  -> (below, above) corner lists (either may be empty)."""\n    lo, hi = [], []\n    n = len(corners)\n    for i in range(n):\n        a, b = corners[i], corners[(i + 1) % n]\n        sa, sb = a[\'pos\'][axis] - c, b[\'pos\'][axis] - c\n        sa0, sb0 = abs(sa) < EPS, abs(sb) < EPS\n        if sa0:\n            lo.append(a)\n            hi.append(a)\n        elif sa < 0:\n            lo.append(a)\n        else:\n            hi.append(a)\n        if not sa0 and not sb0 and (sa < 0) != (sb < 0):\n            if tuple(np.round(a[\'pos\'], WELD)) <= tuple(np.round(b[\'pos\'], WELD)):\n                p = _lerp(a, b, sa / (sa - sb))\n            else:                                   # always interpolate from the same end, so both faces sharing the edge agree\n                p = _lerp(b, a, sb / (sb - sa))\n            p[\'pos\'][axis] = c                      # exactly on the plane, so both sides weld\n            lo.append(p)\n            hi.append(p)\n    return lo, hi\n\n\ndef _usable(corners):\n    return len(corners) >= 3 and poly_area(corners) > 1e-4\n\n\n# ----------------------------------------------------------------------------------------------------------- cutting\ndef cut_polys(polys, limit, cell, candidate, min_piece=None):\n    """Cut every candidate poly with area >= limit on the grid.  -> (new polys, cut count, skipped [(reason, area)])"""\n    min_piece = cell / 64.0 if min_piece is None else min_piece\n    plan, skipped = {}, []\n    for i, p in enumerate(polys):\n        if not candidate(p):\n            continue\n        area = poly_area(p[\'corners\'])\n        if area <= limit * 1.0001:                  # a tile of exactly cell x cell is fine\n            continue\n        if not is_convex(p[\'corners\']):\n            skipped.append((\'not convex\', area))\n            continue\n        P = np.array([c[\'pos\'] for c in p[\'corners\']])\n        planes = []\n        for axis in range(3):\n            lo, hi = P[:, axis].min(), P[:, axis].max()\n            if hi - lo <= cell:\n                continue\n            k = int(np.ceil((lo + EPS) / cell))\n            while k * cell < hi - EPS:\n                c = k * cell\n                if c - lo >= min_piece and hi - c >= min_piece:\n                    planes.append((axis, float(c)))\n                k += 1\n        if planes:\n            plan[i] = planes\n    # points where the planes cross the edges of cut faces: the neighbours across those edges need the same points\n    edge_pts = {}\n    for i, planes in plan.items():\n        cs = polys[i][\'corners\']\n        for j in range(len(cs)):\n            a, b = cs[j], cs[(j + 1) % len(cs)]\n            for axis, c in planes:\n                sa, sb = a[\'pos\'][axis] - c, b[\'pos\'][axis] - c\n                if abs(sa) >= EPS and abs(sb) >= EPS and (sa < 0) != (sb < 0):\n                    if tuple(np.round(a[\'pos\'], WELD)) <= tuple(np.round(b[\'pos\'], WELD)):\n                        p = a[\'pos\'] + (b[\'pos\'] - a[\'pos\']) * (sa / (sa - sb))\n                    else:\n                        p = b[\'pos\'] + (a[\'pos\'] - b[\'pos\']) * (sb / (sb - sa))\n                    p[axis] = c\n                    edge_pts.setdefault(_edge_key(a[\'pos\'], b[\'pos\']), {})[tuple(np.round(p, WELD))] = p\n    out, cut = [], 0\n    for i, p in enumerate(polys):\n        cs = p[\'corners\']\n        if edge_pts:\n            ncs = []\n            for j in range(len(cs)):\n                a, b = cs[j], cs[(j + 1) % len(cs)]\n                pts = edge_pts.get(_edge_key(a[\'pos\'], b[\'pos\']))\n                if pts:\n                    L = np.linalg.norm(b[\'pos\'] - a[\'pos\'])\n                    ts = sorted(((float(np.dot(q - a[\'pos\'], b[\'pos\'] - a[\'pos\']) / (L * L)), q) for q in pts.values()), key=lambda x: x[0])\n                    mids = [_lerp(a, b, t) for t, _ in ts]\n                    for mid, (_, q) in zip(mids, ts):\n                        mid[\'pos\'] = q.copy()\n                    ncs.extend(mids)\n                ncs.append(b)                       # corner j+1 (so the list starts at corner 1; rotated back below)\n            cs = ncs[-1:] + ncs[:-1]                # restore the original starting corner\n        if i in plan:\n            pieces = [cs]\n            for axis, c in plan[i]:\n                nxt = []\n                for pc in pieces:\n                    lo, hi = clip_poly(pc, axis, c)\n                    nxt += [x for x in (lo, hi) if _usable(x)]\n                pieces = nxt\n            for pc in pieces:\n                out.append({\'attrs\': p[\'attrs\'], \'corners\': pc, \'cut\': True})\n            cut += 1\n        else:\n            out.append({\'attrs\': p[\'attrs\'], \'corners\': cs})\n    return out, cut, skipped\n\n\n# ----------------------------------------------------------------------------------------------------------- writing\ndef mesh_write(m, node, polys, by_id=False):\n    """Rebuild the half-edge arrays and data streams of `node` from polygons.  Returns an error string or None (mesh untouched on error).\n    by_id=True: corners read from one mesh (mesh_read\'s \'vid\') keep their own vertices instead of being welded by position, so a subset of\n    a mesh whose separate brushes share positions (Valve\'s importer merges touching brushes into one mesh) can be written back."""\n    import dmx\n    md = m.g(node, b\'meshData\')\n    verts, vidx = [], {}\n\n    def vid(p, c=None):\n        k = (\'id\', c[\'vid\']) if (by_id and c is not None and \'vid\' in c) else tuple(np.round(p, WELD))\n        if k not in vidx:\n            vidx[k] = len(verts)\n            verts.append(p)\n        return vidx[k]\n\n    faces = []\n    for p in polys:\n        pairs = []\n        for c in p[\'corners\']:\n            k = vid(c[\'pos\'], c)\n            if pairs and pairs[-1][0] == k:\n                continue                            # two corners welded together: drop the repeat\n            pairs.append((k, c))\n        if len(pairs) > 1 and pairs[0][0] == pairs[-1][0]:\n            pairs.pop()\n        ids = [k for k, _ in pairs]\n        if len(ids) < 3 or len(set(ids)) != len(ids):\n            return \'degenerate or pinched face after welding\'\n        faces.append(({\'attrs\': p[\'attrs\'], \'corners\': [c for _, c in pairs]}, ids))\n    half = {}                                       # directed (origin, destination) -> half-edge index\n    dest, face_of, corner_of, edge_of, opp, nxt, fedge = [], [], [], [], [], [], []\n    for f, (p, ids) in enumerate(faces):\n        n = len(ids)\n        hs = []\n        for j in range(n):\n            u, v = ids[j - 1], ids[j]               # the half-edge into corner j runs from the previous corner to this one\n            h = half.get((u, v))\n            if h is None:                           # new edge: face side 2k, boundary twin 2k+1\n                k = len(dest) // 2\n                h = 2 * k\n                dest += [v, u]\n                face_of += [-1, -1]\n                corner_of += [None, None]\n                edge_of += [k, k]\n                opp += [h + 1, h]\n                nxt += [-1, -1]\n                half[(u, v)] = h\n                half[(v, u)] = h + 1\n            elif face_of[h] != -1:\n                return \'non-manifold edge (two faces use the same direction)\'\n            face_of[h] = f\n            corner_of[h] = (f, j)\n            hs.append(h)\n        for j in range(n):\n            nxt[hs[j]] = hs[(j + 1) % n]\n        fedge.append(hs[0])\n    H = len(dest)\n    # boundary loops: next boundary half-edge starts where this one ends\n    out_b = {}\n    for h in range(H):\n        if face_of[h] == -1:\n            origin = dest[opp[h]]\n            out_b.setdefault(origin, []).append(h)\n    for h in range(H):\n        if face_of[h] == -1:\n            lst = out_b.get(dest[h], [])\n            nxt[h] = lst.pop(0) if lst else opp[h]\n    nv = len(verts)\n    vedge = [-1] * nv\n    for h in range(H):\n        o = dest[opp[h]]\n        if vedge[o] == -1 or (face_of[h] != -1 and face_of[vedge[o]] == -1):\n            vedge[o] = h\n    if -1 in vedge:\n        return \'unused vertex\'\n    nf = len(faces)\n    # ---- write\n    def setv(el, name, val):\n        a = dmx.geta(m.E[el], name)\n        a[2] = val\n\n    setv(md, b\'vertexEdgeIndices\', vedge)\n    setv(md, b\'vertexDataIndices\', list(range(nv)))\n    setv(md, b\'edgeVertexIndices\', dest)\n    setv(md, b\'edgeOppositeIndices\', opp)\n    setv(md, b\'edgeNextIndices\', nxt)\n    setv(md, b\'edgeFaceIndices\', face_of)\n    setv(md, b\'edgeDataIndices\', edge_of)\n    setv(md, b\'edgeVertexDataIndices\', list(range(H)))\n    setv(md, b\'faceEdgeIndices\', fedge)\n    setv(md, b\'faceDataIndices\', list(range(nf)))\n    ne = H // 2\n\n    def resize(part, size, fill):\n        pd = m.g(md, part)\n        setv(pd, b\'size\', size)\n        for st in m.g(pd, b\'streams\') or []:\n            name = m.E[st][\'name\'].decode()\n            setv(st, b\'data\', fill(name))\n\n    resize(b\'vertexData\', nv, lambda name: [list(map(float, v)) for v in verts])\n    zero = {}\n    for k, (st, data) in _streams(m, node, b\'faceVertexData\').items():\n        zero[k] = [0.0] * len(data[0]) if data else [0.0]\n\n    def fvd_fill(name):\n        arr = [list(zero[name]) for _ in range(H)]\n        for h in range(H):\n            if corner_of[h] is not None:\n                f, j = corner_of[h]\n                arr[h] = [float(x) for x in faces[f][0][\'corners\'][j][\'fvd\'][name]]\n        return arr\n\n    # (zero template is taken from the old data before it is overwritten)\n    resize(b\'faceVertexData\', H, fvd_fill)\n    resize(b\'edgeData\', ne, lambda name: [0] * ne)\n    resize(b\'faceData\', nf, lambda name: [faces[f][0][\'attrs\'][name] for f in range(nf)])\n    sd = m.g(md, b\'subdivisionData\')\n    if sd is not None:\n        setv(sd, b\'subdivisionLevels\', [0] * H)\n    fix_bowtie_links(m, node)\n    return None\n\n\ndef fix_bowtie_links(m, node):\n    """Where separate fans of faces meet at one corner, the open edges through it must be linked fan to fan: each fan\'s incoming open\n    edge -> the NEXT fan\'s outgoing open edge (what Valve\'s importer writes). Linked back to its own fan\'s outgoing edge, the mesh crashes\n    Hammer on load (hammer.dll null write; mg_divine, mg_hellz). Only edgeNextIndices of those open edges change. -> links changed, -1 if odd"""\n    from dmx import geta\n    md = m.g(node, b\'meshData\')\n    if md is None:\n        return 0\n    dest, opp, face = m.g(md, b\'edgeVertexIndices\'), m.g(md, b\'edgeOppositeIndices\'), m.g(md, b\'edgeFaceIndices\')\n    na = geta(m.E[md], b\'edgeNextIndices\')\n    if not dest or na is None:\n        return 0\n    nxt = na[2]\n    H = len(dest)\n    inc = {}\n    for h in range(H):\n        if face[h] == -1:\n            inc.setdefault(dest[h], []).append(h)\n    if all(len(v) < 2 for v in inc.values()):\n        return 0\n    prev = [0] * H\n    for h in range(H):\n        prev[nxt[h]] = h\n    changed = 0\n    for v, hs in inc.items():\n        if len(hs) < 2:\n            continue\n        pairs = []\n        for h in hs:\n            x, own = opp[h], None\n            for _ in range(H):\n                if face[x] == -1:\n                    own = x\n                    break\n                x = opp[prev[x]]\n            if own is None:\n                return -1\n            pairs.append((h, own))\n        for i, (h, own) in enumerate(pairs):\n            want = pairs[(i + 1) % len(pairs)][1]\n            if nxt[h] != want:\n                nxt[h] = want\n                changed += 1\n    return changed\n\n\n# ----------------------------------------------------------------------------------------------------------- checking\ndef mesh_check(m, node):\n    """Structural check of the half-edge arrays.  -> list of problems (empty = fine)"""\n    md = m.g(node, b\'meshData\')\n    g = lambda k: m.g(md, k)\n    dest, opp, nxt, face = g(b\'edgeVertexIndices\'), g(b\'edgeOppositeIndices\'), g(b\'edgeNextIndices\'), g(b\'edgeFaceIndices\')\n    fe, vedge = g(b\'faceEdgeIndices\'), g(b\'vertexEdgeIndices\')\n    evd, edi = g(b\'edgeVertexDataIndices\'), g(b\'edgeDataIndices\')\n    bad = []\n    H = len(dest)\n    if not (len(opp) == len(nxt) == len(face) == len(evd) == len(edi) == H):\n        return [\'array lengths differ\']\n    if sorted(evd) != list(range(len(evd))):\n        bad.append(\'edgeVertexDataIndices is not a permutation\')\n    for h in range(H):\n        if opp[opp[h]] != h:\n            bad.append(\'opposite of opposite of %d\' % h)\n        if dest[opp[h]] == dest[h]:\n            bad.append(\'half-edge %d is a loop\' % h)\n        if dest[opp[nxt[h]]] != dest[h]:\n            bad.append(\'next of %d does not start where it ends\' % h)\n        if face[h] != -1 and face[nxt[h]] != face[h]:\n            bad.append(\'next of %d leaves the face\' % h)\n    for f, h0 in enumerate(fe):\n        h, seen = h0, 0\n        while True:\n            if face[h] != f:\n                bad.append(\'face %d loop has a foreign half-edge\' % f)\n                break\n            h = nxt[h]\n            seen += 1\n            if h == h0 or seen > H:\n                break\n        if seen > H:\n            bad.append(\'face %d loop does not close\' % f)\n    for v, h in enumerate(vedge):\n        if dest[opp[h]] != v:\n            bad.append(\'vertexEdge of %d does not start at it\' % v)\n    dm = m.g(m.g(node, b\'meshData\'), b\'vertexData\')\n    for st in m.g(dm, b\'streams\'):\n        if len(m.g(st, b\'data\')) != m.g(dm, b\'size\'):\n            bad.append(\'vertexData stream length\')\n    return bad[:10]\n\n\n# ----------------------------------------------------------------------------------------------------------- whole-map pass\ndef _identity_xform(m, node):\n    o = m.g(node, b\'origin\', [0, 0, 0]); a = m.g(node, b\'angles\', [0, 0, 0]); sc = m.g(node, b\'scales\', [1, 1, 1])\n    ok = all(abs(x) < 1e-4 for x in a) and all(abs(x - 1) < 1e-4 for x in sc)\n    return ok, np.array(o, dtype=float)\n\n\ndef split_large(m, limit, cell, mode, skip_mat, log):\n    """Cut every lit face over `limit` sq units on a world grid of `cell`.  mode \'faces\' keeps one mesh; \'meshes\' also moves the\n    pieces into one mesh per grid cell (a cubemap / probe is assigned per mesh).  -> dict of counts + list of skipped notes"""\n    res = dict(meshes=0, faces=0, pieces=0, new_meshes=0, skipped=[])\n    owner = {}\n\n    def walk(n, label, cls):\n        for c in m.children(n):\n            t = m.type(c)\n            if t == b\'CMapMesh\':\n                owner[c] = (n, label, cls)\n            elif t == b\'CMapEntity\':\n                walk(c, \'%s %s\' % (m.cls(c), m.name(c) or \'-\'), m.cls(c))\n            else:\n                walk(c, label, cls)\n    walk(m.world, \'world\', \'world\')\n    first_ent = {}      # (class, label) -> the first entity with them (found once: it was a scan of every entity for every mesh, most of this pass)\n    for e in m.entities():\n        c_ = m.cls(e)\n        first_ent.setdefault((c_, \'%s %s\' % (c_, m.name(e) or \'-\')), e)\n    for node, (parent, label, cls) in list(owner.items()):\n        if m.g(node, b\'meshData\') is None:\n            continue\n        if cls.startswith(\'func_water\') or cls.startswith(\'trigger_\'):\n            continue\n        ent0 = first_ent.get((cls, label)) if cls != \'world\' else None\n        if ent0 is not None and m.P(ent0, \'lightmapstatic\', \'1\') == \'0\':\n            continue\n        try:\n            polys, mats = mesh_read(m, node)\n        except Exception:\n            continue\n        cand = lambda p: not any(x in mats[p[\'attrs\'][\'materialindex:0\']] for x in skip_mat)\n        big = [p for p in polys if cand(p) and poly_area(p[\'corners\']) > limit * 1.0001]\n        if not big:\n            continue\n        if mesh_has_subdivision(m, node):\n            res[\'skipped\'].append(\'%s (mesh %d): %d large face(s) in a displacement / subdivision mesh, not touched\' % (label, node, len(big)))\n            continue\n        ok, org = _identity_xform(m, node)\n        if not ok:\n            res[\'skipped\'].append(\'%s (mesh %d): %d large face(s), mesh is rotated or scaled, not touched\' % (label, node, len(big)))\n            continue\n        for p in polys:\n            p[\'corners\'] = [{\'pos\': c[\'pos\'] + org, \'fvd\': c[\'fvd\']} for c in p[\'corners\']]\n        newp, cut, sk = cut_polys(polys, limit, cell, cand)\n        for kind, area in sk:\n            res[\'skipped\'].append(\'%s (mesh %d): face of %d sq units %s, not cut\' % (label, node, area, kind))\n        if not cut:\n            continue\n        for p in newp:                              # corner dicts can be shared between pieces, so copy rather than shift in place\n            p[\'corners\'] = [{\'pos\': c[\'pos\'] - org, \'fvd\': c[\'fvd\']} for c in p[\'corners\']]\n        groups = {}\n        rest = []\n        if mode == \'meshes\':\n            for p in newp:\n                if p.get(\'cut\'):\n                    ctr = np.mean([c[\'pos\'] for c in p[\'corners\']], axis=0) + org\n                    groups.setdefault(tuple(int(x) for x in np.floor(ctr / cell)), []).append(p)\n                else:\n                    rest.append(p)\n        else:\n            rest = newp\n        if len(groups) <= 1 and not rest:\n            groups = {}\n            rest = newp\n        if len(groups) > 0 and rest:\n            pass\n        # write the original mesh first; if it has nothing left, it takes the first group\n        keys = sorted(groups)\n        first = rest if rest else groups[keys.pop(0)] if groups else newp\n        err = mesh_write(m, node, first)\n        if err:\n            res[\'skipped\'].append(\'%s (mesh %d): %s, not touched\' % (label, node, err))\n            continue\n        made = []\n        failed = False\n        for k in keys:\n            nid = [m.next_node_id()]\n            new = m.import_subtree(m, node, {}, nid)\n            e = mesh_write(m, new, groups[k])\n            if e:\n                failed = True\n                res[\'skipped\'].append(\'%s (mesh %d): tile %s: %s\' % (label, node, k, e))\n                break\n            made.append(new)\n        if failed:                                  # put every piece back in the original mesh\n            mesh_write(m, node, newp)\n            continue\n        if made:\n            from dmx import geta\n            arr = geta(m.E[parent], b\'children\')\n            arr[2].extend(made)\n        res[\'meshes\'] += 1\n        res[\'faces\'] += cut\n        res[\'pieces\'] += sum(1 for p in newp if p.get(\'cut\'))\n        res[\'new_meshes\'] += len(made)\n        log.append(\'%s (mesh %d): cut %d large face(s) into %d pieces%s\' % (label, node, cut, sum(1 for p in newp if p.get(\'cut\')), \', %d new mesh(es)\' % len(made) if made else \'\'))\n    return res\n'

