_EQ_DATA_RE = re.compile(r"/\*EQ_DATA_BEGIN\*/(.*?)/\*EQ_DATA_END\*/", re.S)
_EQ_ROLE_RE = re.compile(r"/\*EQ_ROLE\*/.*?/\*EQ_ROLE_END\*/", re.S)

def player_equip_script_text(template: str, data: dict, role: str, previous: str = "") -> str:
    """player_equip.js with the maps' equips and named weapons filled in ({map: {e, wn}}) and its role ("equip" / "spawn"); maps of an
    earlier run that are not in this one keep theirs."""
    import json
    merged = {}
    mm = _EQ_DATA_RE.search(previous or "")
    if mm:
        try:
            merged = json.loads(mm.group(1)) or {}
        except ValueError:
            merged = {}
    merged.update(data)
    if not _EQ_DATA_RE.search(template) or not _EQ_ROLE_RE.search(template):
        raise ValueError("player_equip.js has no /*EQ_DATA_BEGIN*/ or /*EQ_ROLE*/ block (an old copy?)")
    blob = json.dumps(merged, separators=(",", ":"), sort_keys=True)
    t = _EQ_DATA_RE.sub(lambda _m: "/*EQ_DATA_BEGIN*/" + blob + "/*EQ_DATA_END*/", template, count=1)
    return _EQ_ROLE_RE.sub(lambda _m: '/*EQ_ROLE*/"' + role + '"/*EQ_ROLE_END*/', t, count=1)
