def fix_obsolete_entities(vmap_paths):
    """OBSOLETE_ENTITIES: CS:GO entities CS2 dropped. player_weaponstrip -> a blank game_player_equip (WEAPONSTRIP_SPAWNFLAGS, Use Only) with
    the same name and place, and the outputs that fired Strip / StripWeaponsAndSuit at it fire TriggerForActivatedPlayer; game_ui: logged
    (no CS2 entity does what it did: rebuild with cs_script / triggers by hand); func_tracktrain without 'No User Control' (1): logged, as it
    is nearly always a mistake, and left; monster_generic -> prop_dynamic (MONSTER_GENERIC_FIX: see the setting). Rerun-safe. -> log lines"""
    dmx = _bundled_vmapedit()[1]
    out = []
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        rows, changed = [], 0
        at = lambda e: " ".join(str(round(x)) for x in m.origin(e))      # noqa: E731
        strips = {}
        for e in m.by_class("player_weaponstrip"):
            nm = m.name(e)
            pe = m.props(e)
            keep = {"targetname", "parentname"}
            pe["attrs"][:] = [a for a in pe["attrs"] if (a[0].decode("utf-8", "replace") if isinstance(a[0], bytes) else a[0]).lower() in keep]
            m.setp(e, "classname", "game_player_equip")
            m.setp(e, "spawnflags", WEAPONSTRIP_SPAWNFLAGS)
            if nm:
                strips[nm.lower()] = nm
            changed += 1
            rows.append(f"REPLACED\tplayer_weaponstrip {nm or '(unnamed)'} at {at(e)}\tnow a blank game_player_equip, spawnflags {WEAPONSTRIP_SPAWNFLAGS} (Use Only + Strip First)")
        if strips:
            for src, cc in m.all_conns():
                o, t, i, _p, _d, _n = m.conn_tuple(cc)
                if t.lower() in strips and i.lower() in ("strip", "stripweaponsandsuit", "use"):
                    dmx.set_(cc, b"inputName", dmx.T_STR, b"TriggerForActivatedPlayer")
                    changed += 1
                    rows.append(f"INPUT\t{m.cls(src)} {m.name(src) or '(unnamed)'}\t{o} -> {t}.{i} now TriggerForActivatedPlayer (strips the player that set it off)")
        for e in m.by_class("game_ui"):
            ins = [f"{m.cls(s_)} {m.name(s_) or '(unnamed)'} {m.conn_tuple(c_)[0]} -> {m.conn_tuple(c_)[2]}" for s_, c_ in m.all_conns()
                   if m.name(e) and m.conn_tuple(c_)[1].lower() == m.name(e).lower()]
            outs = sorted({m.conn_tuple(c_)[0] for c_ in m.conns(e)})
            rows.append(f"GAME_UI\tgame_ui {m.name(e) or '(unnamed)'} at {at(e)}\tno CS2 version: fix by hand (cs_script: player buttons). "
                        f"Its outputs: {', '.join(outs) or 'none'}; fired by: {'; '.join(ins[:4]) or 'nothing'}{' ...' if len(ins) > 4 else ''}")
        for e in m.by_class("env_screenoverlay"):
            ovs = sorted({v for k in [f"OverlayName{i}" for i in range(1, 11)] for v in [(m.P(e, k, "") or "").strip()] if v})
            rows.append(f"OBSOLETE\tenv_screenoverlay {m.name(e) or '(unnamed)'} at {at(e)}\tnot in CS2 (overlay: {', '.join(ovs) or 'none set'}); "
                        + ("redone as Panorama panels shown by screen_overlay.js (SCREEN_OVERLAYS, screen_overlays log)" if SCREEN_OVERLAYS and MAP_SCRIPTS else
                           "a picture can be redone as a custom_hud_layout (Panorama) shown from cs_script (SCREEN_OVERLAYS). Left as is"))
        for cls_ in ("point_camera", "func_monitor", "info_camera_link"):
            for e in m.by_class(cls_):
                rows.append(f"OBSOLETE\t{cls_} {m.name(e) or '(unnamed)'} at {at(e)}\tcamera / monitor entity CS2 does not have (its screens used the _rt_Camera "
                            "render target, also gone). Left as is")
        if MONSTER_GENERIC_FIX:
            for e in m.by_class("monster_generic"):
                nm = m.name(e)
                mdl = (m.P(e, "model", "") or "").replace("\\", "/")
                idle = mdl_activity_sequence(os.path.splitext(mdl)[0] + ".mdl", "ACT_IDLE")
                try:
                    sf, sleep = int(float(m.P(e, "spawnflags", "0") or 0)), int(float(m.P(e, "sleepstate", "0") or 0))
                except ValueError:
                    sf, sleep = 0, 0
                woken = bool(nm) and any(m.conn_tuple(c_)[1].lower() == nm.lower() and m.conn_tuple(c_)[2].lower() == "wake" for _s, c_ in m.all_conns())
                hide = sleep in (1, 2, 3) and not woken and not MONSTER_GENERIC_SHOW_SLEEPING
                m.setp(e, "classname", "prop_dynamic")
                m.setp(e, "solid", "0" if sf & 65536 else "2")
                m.setp(e, "spawnflags", "0")
                for k_ in ("sleepstate", "physdamagescale"):
                    m.delp(e, k_)
                if idle:
                    for k_ in ("StartingAnim", "IdleAnim"):
                        m.setp(e, k_, idle)
                    for k_ in ("StartingAnimationLoopMode", "IdleAnimationLoopMode"):
                        m.setp(e, k_, "ANIM_LOOP_MODE_USE_SEQUENCE_SETTINGS")
                if hide:
                    m.setp(e, "StartDisabled", "1")
                changed += 1
                rows.append(f"REPLACED\tmonster_generic {nm or '(unnamed)'} at {at(e)}\tnow a prop_dynamic ({mdl})"
                            + (f" playing its idle sequence {idle}" if idle else "; no ACT_IDLE sequence found for the model, so it stands in its reference pose")
                            + (f"; it starts DISABLED (not drawn): sleepstate {sleep} put the NPC to sleep, a sleeping NPC is not drawn and no output wakes "
                               f"it. MONSTER_GENERIC_SHOW_SLEEPING = True shows it" if hide else "")
                            + ("; an output sends it Wake (prop_dynamic has no such input): send it Enable" if woken and sleep else ""))
        if MDL_SKIP_PREFIXES and not MDL_INCLUDE_TRIM:
            for e in m.entities():
                mdl = (m.P(e, "model", "") or "").replace("\\", "/").lower()
                if m.cls(e).startswith("prop_") and mdl.startswith(tuple(x.lower() for x in MDL_SKIP_PREFIXES)) \
                        and not (derive_export_dir(Path(vp)) / mdl).is_file():     # one imported on an earlier run stays
                    rows.append(f"PLAYER_MODEL\t{m.cls(e)} {m.name(e) or '(unnamed)'} at {at(e)}\t{mdl}: a player model, not imported (MDL_SKIP_PREFIXES); "
                                "swap it for a stock CS2 character model")
        for e in m.by_class("func_tracktrain"):
            try:
                sf = int(m.P(e, "spawnflags", "0") or 0)
            except ValueError:
                sf = 0
            if not sf & 1:
                rows.append(f"TRACKTRAIN\tfunc_tracktrain {m.name(e) or '(unnamed)'} at {at(e)}\t'No User Control' (spawnflag 1) is off: players can drive it "
                            "with +use. Usually a mistake; not changed")
        if not changed:
            _keep_map(m, vp)
            if rows:
                out += [f"# {vn}"] + rows
            continue
        try:
            bak = _save_map(m, vp, "obsolete_entities")
        except OSError as ex:
            out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
            continue
        print(f"  [OBSOLETE] {vn}: {sum(1 for r in rows if r.startswith('REPLACED'))} player_weaponstrip / monster_generic replaced; original saved as {os.path.basename(bak)}")
        out += [f"# {vn}"] + rows
    kinds = collections.Counter(r.split("\t")[0] for r in out if not r.startswith("#"))
    n_mg = sum(1 for r in out if r.startswith("REPLACED\tmonster_generic "))
    out.insert(0, f"# obsolete entities: {kinds.get('REPLACED', 0) - n_mg} player_weaponstrip replaced, {n_mg} monster_generic made prop_dynamic, {kinds.get('GAME_UI', 0)} game_ui to redo by hand, "
                  f"{kinds.get('OBSOLETE', 0)} screen overlay / camera entities CS2 lacks, {kinds.get('PLAYER_MODEL', 0)} props with a skipped player model, "
                  f"{kinds.get('TRACKTRAIN', 0)} func_tracktrain without 'No User Control'")
    return out


def check_player_equips(vmap_paths):
    """game_player_equip, CS:GO -> CS2 (from skink52's cs2-gotchas). Reports; with EQUIP_FIX_INPUTS also renames "Use" inputs on equips to
    TriggerForActivatedPlayer and spells their target exactly like the equip. Rerun-safe (fixed outputs are already right). -> log lines"""
    dmx = _bundled_vmapedit()[1]
    out, nfix, nwarn = [], 0, 0
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        eqs = [e for e in m.by_class("game_player_equip")      # EQUIP_SCRIPT's stand-ins and equips are the script's now
               if not (m.P(e, "eq_k", "") or "").strip() and (m.P(e, "csgo_class", "") or "").lower() != "equip_stub"]
        if not eqs:
            _keep_map(m, vp)
            continue
        by_name = {}
        for e in eqs:
            if m.name(e):
                by_name.setdefault(m.name(e).lower(), e)
        fired = collections.defaultdict(list)        # equip -> [(source class, source name, output, input, times)]
        fixes = []
        for src, cc in m.all_conns():
            o, t, i, _p, _d, n = m.conn_tuple(cc)
            e = by_name.get(t.lower())
            if e is None:
                continue
            fired[e].append((m.cls(src), m.name(src), o, i, n))
            if not EQUIP_FIX_INPUTS:
                continue
            what = []
            if i.lower() == "use":
                dmx.set_(cc, b"inputName", dmx.T_STR, b"TriggerForActivatedPlayer")
                what.append("Use -> TriggerForActivatedPlayer")
            if t != m.name(e):
                dmx.set_(cc, b"targetName", dmx.T_STR, m.name(e).encode())
                what.append(f"target {t} -> {m.name(e)}")
            if what:
                fixes.append(f"FIXED\t{m.cls(src)} {m.name(src) or '(unnamed)'}\t{o} -> {m.name(e)}\t" + ", ".join(what))
        rows = []
        for e in eqs:
            who = f"game_player_equip {m.name(e) or '(unnamed)'} at {' '.join(str(round(x)) for x in m.origin(e))}"
            pe = m.props(e)
            if EQUIP_FIX_KEYS:
                done_ = []
                for k in _EQUIP_SLOTS:                       # CS:GO names in the slots -> CS2 names
                    v = (m.P(e, k, "") or "").strip()
                    if v.lower() in _CSGO_WEAPON_RENAMES:
                        m.setp(e, k, _CSGO_WEAPON_RENAMES[v.lower()])
                        done_.append(f"{k} {v} -> {_CSGO_WEAPON_RENAMES[v.lower()]}")
                free = [k for k in _EQUIP_SLOTS if not (m.P(e, k, "") or "").strip()]
                keep_attrs, moved_ = [], []
                for a in pe["attrs"]:
                    nm = a[0].decode("utf-8", "replace") if isinstance(a[0], bytes) else str(a[0])
                    low = nm.lower()
                    if not low.startswith("weapon_"):
                        keep_attrs.append(a)
                        continue
                    val = a[2].decode("utf-8", "replace").strip() if isinstance(a[2], bytes) else str(a[2])
                    try:
                        cnt_ = int(float(val or "0"))
                    except ValueError:
                        cnt_ = 1
                    cs2 = _CSGO_WEAPON_RENAMES.get(low, low)
                    if cs2 not in _CS2_WEAPONS and not cs2.startswith("weapon_knife"):
                        rows.append(f"UNKNOWN_WEAPON\t{who}\tkey {nm}: CS2 has no such weapon and no stand-in is known; left as it was")
                        keep_attrs.append(a)
                        continue
                    if cnt_ <= 0:
                        done_.append(f"key {nm} {val} removed (it gave none)")
                        continue
                    if not free:
                        rows.append(f"NO_SLOT\t{who}\tkey {nm}: all 22 weapon slots are used; left as it was")
                        keep_attrs.append(a)
                        continue
                    k = free.pop(0)
                    moved_.append((k, cs2))
                    done_.append(f"{nm} {val} -> {k} {cs2}" + (f" (it gave {cnt_}: CS2 gives one per slot)" if cnt_ > 1 else ""))
                if moved_ or len(keep_attrs) != len(pe["attrs"]):
                    pe["attrs"][:] = keep_attrs
                    for k, v in moved_:
                        m.setp(e, k, v)
                if done_:
                    fixes.append(f"FIXED\t{who}\tweapon keys: " + "; ".join(done_))
            try:
                sf = int(m.P(e, "spawnflags", "0") or 0)
            except ValueError:
                sf = 0
            slots = [(k, (m.P(e, k, "") or "").strip()) for k in _EQUIP_SLOTS]
            gives = [v.lower() for _k, v in slots if v]
            legacy = [a[0].decode("utf-8", "replace") for a in pe["attrs"] if re.match(rb"(?i)^(weapon_|item_|ammo_)", a[0])]
            items = [v for v in gives if v.startswith("item_")]
            if items:
                rows.append(f"CRASH\t{who}\t{', '.join(items)} in a weapon slot: the CS2 server crashes while loading the map. Keep only weapon_* in the "
                            "slots and give armour another way (cs_script GiveNamedItem)")
            for v in gives:
                if v.startswith("item_"):
                    continue
                if v in _CSGO_WEAPON_RENAMES:
                    rows.append(f"OLD_WEAPON\t{who}\t{v} is the CS:GO name: use {_CSGO_WEAPON_RENAMES[v]}")
                elif v not in _CS2_WEAPONS and not v.startswith("weapon_knife"):
                    rows.append(f"UNKNOWN_WEAPON\t{who}\t{v} is not a CS2 weapon class name")
            if legacy and not EQUIP_SCRIPT:            # (EQUIP_SCRIPT reads these keys from the .vmf: item_kevlar / item_assaultsuit become armour)
                rows.append(f"LEGACY_KEYS\t{who}\tkeys {', '.join(legacy)} (CS:GO's 'weapon_x 1' form) do nothing in CS2: put the names in weapon0..weapon21")
            if EQUIP_SPAWN_STRIP and not sf & 1 and not sf & 2:
                sf |= 2
                m.setp(e, "spawnflags", str(sf))
                fixes.append(f"FIXED\t{who}\tno 'Use Only': CS:GO replaced the spawn loadout with it ({', '.join(gives) or 'nothing: a full strip'}); "
                             "'Strip First' (2) added so CS2 strips at spawn too")
            if not gives and not (sf & 2):
                rows.append(f"EMPTY\t{who}\tgives nothing and does not strip: does nothing")
            src = fired.get(e, [])
            if not sf & 1:
                rows.append(f"SPAWN_EQUIP\t{who}\tno 'Use Only': runs at spawn ({'strip, then ' if sf & 2 else ''}{', '.join(gives) or 'nothing'}). "
                            f"Stripping at spawn / round restart is confirmed in CS2 with 'Strip First'; check in game that {', '.join(gives) if gives else 'players spawn with nothing'}"
                            f"{' arrive' if gives else ''}")
            elif not src:
                rows.append(f"NEVER_FIRED\t{who}\t'Use Only' but no output targets it{'' if m.name(e) else ' (it has no name)'}: it never gives anything")
            for c, nm, o, i, _n in src:
                if c in ("logic_auto", "logic_timer") and i.lower() in ("use", "triggerforactivatedplayer"):
                    rows.append(f"NO_PLAYER\t{who}\t{c} {nm or '(unnamed)'} {o} -> {i}: there is no player activator there, so nobody gets anything (use TriggerForAllPlayers)")
            if not EQUIP_FIX_INPUTS and any(i.lower() == "use" for _c, _nm, _o, i, _n in src):
                rows.append(f"USE_INPUT\t{who}\tfired with 'Use': CS2's equip input is TriggerForActivatedPlayer (EQUIP_FIX_INPUTS changes it)")
            rep = collections.Counter(f"{c} {o}" for c, _nm, o, i, n in src if n < 0 and i.lower() in ("use", "triggerforactivatedplayer")
                                      and c in ("trigger_multiple", "trigger_hurt") and o.lower() in ("onstarttouch", "ontrigger", "onstarttouchall", "ontouching"))
            if rep and any(v for v in gives if not v.startswith("weapon_knife")):
                rows.append(f"STACKING\t{who}\tfired every time by {', '.join(f'{k} x{v}' for k, v in rep.items())}: CS:GO never gave a second copy of a gun the "
                            "player already had, CS2 does, so going back in stacks them (fine if the player loses them in between, e.g. strip or death)")
        nwarn += sum(1 for r in rows if r.split("\t")[0] in ("CRASH", "OLD_WEAPON", "UNKNOWN_WEAPON", "LEGACY_KEYS", "SPAWN_EQUIP", "NEVER_FIRED", "NO_PLAYER", "USE_INPUT"))
        if fixes:
            try:
                bak = _save_map(m, vp, "equips")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); the outputs were not changed. Close Hammer and rerun.")
                fixes = []
            else:
                print(f"  [EQUIPS] {vn}: {len(fixes)} output(s) on game_player_equips fixed; original saved as {os.path.basename(bak)}")
                nfix += len(fixes)
        else:
            _keep_map(m, vp)
        order = {"CRASH": 0, "OLD_WEAPON": 1, "UNKNOWN_WEAPON": 2, "LEGACY_KEYS": 3, "NO_PLAYER": 4, "SPAWN_EQUIP": 5, "NEVER_FIRED": 6, "USE_INPUT": 7, "EMPTY": 8, "STACKING": 9}
        out += [f"# {vn}: {len(eqs)} game_player_equip(s)"] + sorted(rows, key=lambda r: order.get(r.split("\t")[0], 99)) + fixes
    out.insert(0, f"# game_player_equip: {nwarn} thing(s) to check, {nfix} output(s) fixed. CRASH / OLD_WEAPON / LEGACY_KEYS / NO_PLAYER need changing; "
                  "SPAWN_EQUIP and STACKING are behaviour that changed from CS:GO; EMPTY / NEVER_FIRED are probably leftovers")
    return out


_CAST_SHADOWS = {"enabled": 0, "no shadows": 1, "only realtime": 2, "only baked": 3}
_RENDER_MODES = {"normal": "kRenderNormal", "texture": "kRenderTransAlpha"}     # CS2 RenderMode_t: 0 normal, 1 kRenderTransAlpha (Source1's "texture"), 2 none


def fix_brush_render(vmap_paths, backup_dir):
    """Brush-entity render settings (BRUSH_*) on BRUSH_RENDER_CLASSES, and every brush entity's meshes given the entity's Cast Shadows value.
    Every run by default; BRUSH_RENDER_ONCE remembers entities by reference ID (<map>.vmap.brush_render_done.txt) so hand edits are kept. -> log lines"""
    dmx = _bundled_vmapedit()[1]
    cast = _CAST_SHADOWS[BRUSH_CAST_SHADOWS.lower()] if BRUSH_CAST_SHADOWS else None
    mode = (_RENDER_MODES.get(BRUSH_RENDER_MODE.lower(), BRUSH_RENDER_MODE) if BRUSH_RENDER_MODE else None)
    out, n_set, n_sync = [], 0, 0
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        state = Path(backup_dir) / (vn + ".brush_render_done.txt")
        done = _state_read(state)
        new_done, rows = set(), []
        for e in m.entities():
            meshes = [c for c in m.children(e) if m.type(c) == b"CMapMesh"]
            rid = str(m.g(e, b"referenceID", ""))
            if not meshes or not rid or (BRUSH_RENDER_ONCE and rid in done):
                continue
            cls, who = m.cls(e), f"{m.cls(e)} {m.name(e) or '(unnamed)'} @ {' '.join('%g' % round(x) for x in m.origin(e))}"
            ch = []
            if cls in BRUSH_RENDER_CLASSES:
                if cast is not None and m.P(e, "disableshadows") != str(cast):
                    m.setp(e, "disableshadows", str(cast)); ch.append(f"Cast Shadows {BRUSH_CAST_SHADOWS}")
                if mode and m.P(e, "rendermode") != mode:
                    m.setp(e, "rendermode", mode); ch.append(f"Render Mode {BRUSH_RENDER_MODE}")
                if BRUSH_DISABLE_RECEIVING_SHADOWS is not None and m.P(e, "disablereceiveshadows") != str(int(BRUSH_DISABLE_RECEIVING_SHADOWS)):
                    m.setp(e, "disablereceiveshadows", str(int(BRUSH_DISABLE_RECEIVING_SHADOWS))); ch.append("Disable Receiving Shadows %s" % ("on" if BRUSH_DISABLE_RECEIVING_SHADOWS else "off"))
                if BRUSH_DISABLE_MESH_MERGING is not None:
                    k = [c for c in meshes if bool(m.g(c, b"disablemerging", False)) != BRUSH_DISABLE_MESH_MERGING]
                    for c in k:
                        dmx.set_(m.E[c], b"disablemerging", dmx.T_BOOL, bool(BRUSH_DISABLE_MESH_MERGING))
                    if k:
                        ch.append(f"Disable Mesh Merging {'on' if BRUSH_DISABLE_MESH_MERGING else 'off'} ({len(k)} mesh(es))")
                n_set += bool(ch)
            want = m.P(e, "disableshadows")
            if BRUSH_SYNC_MESH_SHADOWS and want is not None and want.strip().isdigit():
                k = [c for c in meshes if m.g(c, b"disableShadows", None) is not None and m.g(c, b"disableShadows") != int(want)]
                for c in k:
                    dmx.set_(m.E[c], b"disableShadows", dmx.T_INT, int(want))
                if k:
                    ch.append(f"{len(k)} mesh(es) Cast Shadows set to the entity's ({want})")
                    n_sync += 1
            if cls in BRUSH_RENDER_CLASSES or ch:
                new_done.add(rid)
            if ch:
                rows.append(f"SET\t{who}\t" + "; ".join(ch))
        if not rows:
            _keep_map(m, vp)
        else:
            try:
                bak = _save_map(m, vp, "brushrender")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            print(f"  [BRUSHES] {vn}: {len(rows)} brush entit(ies) changed; original saved as {os.path.basename(bak)}")
        if BRUSH_RENDER_ONCE and new_done - done:
            try:
                state.parent.mkdir(parents=True, exist_ok=True)
                state.write_text("# brush entities already given the BRUSH_* settings (Hammer reference IDs). Delete a line to have it redone.\n"
                                 + "\n".join(sorted(done | new_done)) + "\n", encoding="utf-8")
            except OSError:
                pass
        out += [f"# {vn}"] + rows
    out.insert(0, f"# brush entity render settings: {n_set} entit(ies) of {', '.join(BRUSH_RENDER_CLASSES)} set; {n_sync} entit(ies) had meshes whose Cast Shadows "
                  "differed from the entity's (synced)." + (" Each entity is only processed once (BRUSH_RENDER_ONCE)." if BRUSH_RENDER_ONCE else " Applied every run."))
    return out


def add_water_volumes(vmap_paths, export_dir: Path, backup_dir, vmf_path=None):
    """Source1 water -> CS2 (CS2 only treats water as water - swimming, splashes, sounds - inside a func_water):
      - world meshes using a Source1 "Water" material (the importer sometimes leaves water as plain world geometry: a nodraw shell
        plus the surface cut into 512 tiles) are grouped by touching bounds and each group is moved into a new func_water.
        A group with no depth (surface only) is left alone and listed: it needs a box built in Hammer.
      - func_water_analog (Source1 moving water; no such entity in CS2) -> func_water, movement keys dropped.
      - a flat func_water gets its depth back from the .vmf (nodraw box) and the Source1 water materials are converted (WATER_CONVERT):
        a CS2 water material of their own at the same path; a 3D skybox map's water gets a <name>_skybox copy. Swapped for another only
        where WATER_MATERIAL_MAP lists them; one that cannot be converted is flagged MISSING.
    Rerun-safe: water already in a func_water is never touched again.
    Underwater LIGHTS are not added here: the lighting rebuild (run after this pass) lights every func_water.
    The vmap is backed up to BACKUP_DIR first. -> list of log lines"""
    dmx = _bundled_vmapedit()[1]
    out, todo = [], []
    import numpy as np
    tot = {"new_func_water": 0, "analog_converted": 0, "surface_only": 0, "water_sides": 0}
    water_mats = {}
    swaps = {}                   # (old material, new material, why) -> meshes
    converted = {}               # Source1 water material -> (CS2 vmat written, why)  (WATER_CONVERT)
    sky_scale = None             # the 3D skybox map's sky_camera scale, when one of the maps is a 3D skybox map
    sky_water = False            # ... and whether that 3D skybox has water for the main map's water to fade into
    for _vp in vmap_paths:
        if _is_skybox_map(_vp):
            try:
                _sm = _open_map(_vp)
                _c = _sm.by_class("sky_camera")
                sky_scale = float(_sm.P(_c[0], "scale", "16") or 16) if _c else 16.0
                sky_water = sky_water or any(_water_material(x.decode("utf-8", "replace"))[0] for n_, _q in _sm.walk() if _sm.type(n_) == b"CMapMesh"
                                             for x in (_sm.g(_sm.g(n_, b"meshData"), b"materials") or []))
                _keep_map(_sm, _vp)
            except Exception:
                pass
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        par = m.parent_of()
        rows, changed = [], False

        def owner(n):
            p = par.get(n)
            while p is not None and p != m.world:
                if m.type(p) == b"CMapEntity":
                    return p
                p = par.get(p)
            return None

        def mesh_mats(n):                        # materials the mesh's faces actually use
            md = m.g(n, b"meshData")
            if md is None:
                return []
            mats_ = [x.decode("utf-8", "replace") for x in (m.g(md, b"materials") or [])]
            mi = next((m.g(st, b"data") for st in m.g(m.g(md, b"faceData"), b"streams") or [] if m.E[st]["name"].startswith(b"materialindex")), None)
            return [mats_[i] for i in sorted(set(mi))if 0 <= i < len(mats_)] if mi else mats_

        vmf_water = []                           # (lo, hi) of the .vmf's world water brushes: the depth a flat imported surface had
        vmf_water_mm = []                        # (lo, hi, {water materials as vmat paths}) of the same brushes
        vmf_water_mats = set()
        if vmf_path and Path(vmf_path).is_file():
            for s_ in _vmf_world_solids(vmf_path):
                wm = {"materials/" + rel_norm(x["mat"]).lower() + ".vmat" for x in s_["sides"] if "water" in x["mat"].lower() and not x["mat"].lower().startswith("tools/")}
                wm = {x for x in wm if _water_material(x)[0]}
                if wm:
                    vmf_water_mm.append((s_["lo"], s_["hi"], wm))
                    vmf_water_mats |= wm
            vmf_water = [(s_["lo"], s_["hi"]) for s_ in _vmf_world_solids(vmf_path) if any("water" in x["mat"] for x in s_["sides"])
                         and not any(x["mat"].startswith("tools/") and "nodraw" not in x["mat"] for x in s_["sides"])]

        def vmf_depth(lo, hi):                   # bottom of the .vmf water brushes under a flat surface (lo, hi), or None
            zs = [wl[2] for wl, wh in vmf_water if abs(wh[2] - hi[2]) < 1.0 and wl[0] < hi[0] and lo[0] < wh[0] and wl[1] < hi[1] and lo[1] < wh[1]]
            return min(zs) if zs and min(zs) < hi[2] - 2 else None

        box_cache_w = {}

        def give_depth(ent, lo, hi):             # a flat func_water gets a nodraw box down to the .vmf water's bottom, so it can be swum in
            bot = vmf_depth(lo, hi)
            if bot is None:
                return False
            # one box per .vmf water brush under the surface, its own size: one box over the surface's bounds would also cover the
            # ground between pools that are not rectangles together (an L of water brushes)
            under = [(wl, wh) for wl, wh in vmf_water if abs(wh[2] - hi[2]) < 1.0 and wl[0] < hi[0] - 1 and lo[0] < wh[0] - 1
                     and wl[1] < hi[1] - 1 and lo[1] < wh[1] - 1 and wl[2] < hi[2] - 2]
            for wl, wh in under or [([lo[0], lo[1], bot], hi)]:
                box = _water_box_mesh(m, dmx, [wl[0], wl[1], wl[2]], [wh[0], wh[1], hi[2]], box_cache_w)
                if box is None:
                    return False
                dmx.set_(m.E[m.g(box, b"meshData")], b"materials", dmx.ARR + dmx.T_STR, [b"materials/tools/toolsnodraw.vmat"])
                dmx.geta(m.E[ent], b"children")[2].append(box)
            rows.append(f"DEPTH\t{m.name(ent) or '(unnamed)'}\t{_fmt_box(lo, hi)}\tflat water surface (the importer dropped the water brush's sides): "
                        f"nodraw box added down to z {bot:g} from the .vmf, so players can swim in it")
            return True

        # ---- func_water_analog -> func_water (moving water: carried by a func_movelinear that takes its name and inputs)
        analog_kv = {}
        if vmf_path and Path(vmf_path).is_file():
            for node in _vmf_tree(str(vmf_path))[2]:
                if node[0] == "entity" and node[1].get("classname", "").lower() == "func_water_analog" and node[1].get("targetname"):
                    analog_kv[node[1]["targetname"].lower()] = node[1]
        for e in m.by_class("func_water_analog"):
            if m.name(e) and m.name(e).lower() not in analog_kv:
                analog_kv[m.name(e).lower()] = {k: m.P(e, k, "") for k in ("movedir", "movedistance", "speed", "startposition")}
            m.setp(e, "classname", "func_water")
            for k in ("WaveHeight", "startposition", "speed", "movedistance", "movedir"):
                m.delp(e, k)
            rows.append(f"ANALOG\t{m.name(e) or '(unnamed)'}\t{_fmt_box(*(m.bounds(e) or ([0] * 3, [0] * 3)))}\tfunc_water_analog -> func_water")
            tot["analog_converted"] += 1
            changed = True
        if WATER_ANALOG_MOVER:
            byname = {}
            for e in m.entities():
                if m.name(e):
                    byname.setdefault(m.name(e).lower(), []).append(e)
            for low, akv in analog_kv.items():
                ws = [x for x in byname.get(low, []) if m.cls(x) == "func_water"]
                if not ws or any(m.cls(x) == "func_movelinear" for x in byname.get(low, [])):
                    continue                     # not in this map, or carried already
                dist, spd = _num(akv.get("movedistance", "0")), _num(akv.get("speed", "0"))
                if dist <= 0 or spd <= 0:
                    continue
                w = ws[0]
                nm = m.name(w)
                bb = m.bounds(w) or (m.origin(w), m.origin(w))
                c_ = [(bb[0][k] + bb[1][k]) / 2 for k in range(3)]
                box = _water_box_mesh(m, dmx, [c_[0] - 1, c_[1] - 1, bb[1][2] - 2], [c_[0] + 1, c_[1] + 1, bb[1][2]], box_cache_w)
                if box is None:
                    rows.append(f"ANALOG_STATIC\t{nm}\tno box mesh in the map to build the mover from: the water does not move")
                    continue
                mv = m.new_entity("func_movelinear", m.origin(w), {
                    "targetname": nm, "movedir": akv.get("movedir", "-90 0 0") or "-90 0 0", "movedistance": f"{dist:g}",
                    "speed": f"{spd:g}", "startposition": akv.get("startposition", "0") or "0", "spawnflags": "8",
                    "rendermode": "kRenderNormal" if WATER_ANALOG_CARRY == "mesh" else "kRenderNone", "csgo_water_analog": "1"})
                if WATER_ANALOG_CARRY == "mesh":
                    wm = [c for c in m.children(w) if m.type(c) == b"CMapMesh"]
                    if wm:
                        a_ = dmx.geta(m.E[w], b"children")
                        a_[2] = [c for c in a_[2] if c not in wm]
                        dmx.geta(m.E[mv], b"children")[2].extend(wm)
                        m.remove_node(w)
                        rows.append(f"ANALOG_MOVER\t{nm}\tfunc_movelinear {nm} (movedir {akv.get('movedir')}, {dist:g} units at {spd:g}/s) now holds the water's "
                                    f"{len(wm)} mesh(es): Open / Close / SetPosition move the water itself. It is no longer a func_water (not swimmable)")
                        changed = True
                        continue
                dmx.geta(m.E[mv], b"children")[2].append(box)
                m.setp(w, "targetname", nm + "__water")
                m.setp(w, "parentname", nm)
                rows.append(f"ANALOG_MOVER\t{nm}\tfunc_movelinear {nm} (movedir {akv.get('movedir')}, {dist:g} units at {spd:g}/s) now carries "
                            f"the water ({nm}__water, parented): Open / Close / SetPosition reach the mover. Check in game that CS2 moves the swim volume with it")
                changed = True

        # ---- func_water holding sky / wall faces (an earlier run moved a whole mixed world mesh; Valve's importer merges the world brushes
        # around the water into the func_water's mesh): those faces go back to the world. Nodraw stays only on the .vmf's water brushes: the
        # importer's mesh also held the world's nodraw faces across the whole map (ba_jail_os_gulag_d: 3982 of them, 6887 x 6441 units, all
        # linked through shared vertices), and CS2 made all of it water
        _wgrid = [None]                          # the world's visible faces before anything comes back from a func_water

        def unz(c_):                             # what comes back must not lie on the world's own faces (z-fighting)
            r_ = _cut_doubled_faces(m, c_, _wgrid[0])
            if r_ is None:
                rows.append(f"ZFIGHT\t{_fmt_box(*(m.bounds(c_) or ([0] * 3, [0] * 3)))}\tcould not check it for faces lying on the world's (mesh not rebuilt)")
            elif r_[0] or r_[1]:
                rows.append(f"ZFIGHT\t{_fmt_box(*(m.bounds(c_) or ([0] * 3, [0] * 3)))}\t{r_[0]} face(s) deleted and {r_[1]} cut where they lay on the "
                            f"world's own faces (the importer compiled the func_water's brushes apart from the world's: both kept the overlap)")

        def on_water_brush(P_):                  # every corner on / in one of the .vmf's water brushes
            return any(all(lo[k] - 1 <= q[k] <= hi[k] + 1 for q in P_ for k in range(3)) for lo, hi, _w in vmf_water_mm)
        for e in m.by_class("func_water"):
            for c in [c for c in m.children(e) if m.type(c) == b"CMapMesh"]:
                mm_ = mesh_mats(c)
                if all(_water_material(x)[0] for x in mm_):
                    continue
                if not any(_water_material(x)[0] for x in mm_):
                    # no water in it: the water's nodraw depth box stays; another mesh (the world nodraw an earlier run's pool split left
                    # in the func_water, an overlay quad laid on a wall or on the water that was in it) goes back to the world
                    fw_ = _mesh_faces_world(m, c)
                    if not vmf_water_mm or not fw_ or all(on_water_brush(P) and "/tools/" in _mt.lower() for _f, P, _k, _mt in fw_):
                        continue
                    a = dmx.geta(m.E[e], b"children")
                    a[2] = [x for x in a[2] if x != c]
                    if _wgrid[0] is None:
                        _wgrid[0] = _world_face_grid(m)
                    dmx.geta(m.E[m.world], b"children")[2].append(c)
                    par[c] = m.world
                    rows.append(f"UNMIXED\t{m.name(e) or '(unnamed)'}\t{_fmt_box(*(m.bounds(c) or ([0] * 3, [0] * 3)))}\ta mesh with no water "
                                f"({', '.join(sorted({os.path.basename(x) for x in mm_}))}) moved out of the func_water back into the world")
                    unz(c)
                    changed = True
                    if not any(m.type(x) == b"CMapMesh" for x in m.children(e)) and not m.name(e) and not m.conns(e):
                        m.remove_node(e)                 # nothing of it was water: the func_water goes
                        rows.append(f"REMOVED\tfunc_water at {' '.join('%g' % round(v) for v in m.origin(e))}\tno water left in it")
                        break
                    continue
                if vmf_water_mm:                 # nodraw faces on the .vmf's water brushes (their sides) stay with the water
                    keep_ = {f for f, P, _k, mt in _mesh_faces_world(m, c) if "toolsnodraw" in mt.lower() and on_water_brush(P)}
                    dn = _split_water_faces(m, c, keep_idx=keep_)
                else:
                    dn = _split_water_faces(m, c, keep=lambda mt: "toolsnodraw" in mt.lower())
                if dn is None or dn is c:
                    continue
                # dn holds the water (+ nodraw) faces, c the rest: swap so the entity keeps the water
                a = dmx.geta(m.E[e], b"children")
                a[2] = [dn if x == c else x for x in a[2]]
                if _wgrid[0] is None:
                    _wgrid[0] = _world_face_grid(m)
                dmx.geta(m.E[m.world], b"children")[2].append(c)
                par[c], par[dn] = m.world, e
                rows.append(f"UNMIXED\t{m.name(e) or '(unnamed)'}\t{_fmt_box(*(m.bounds(c) or ([0] * 3, [0] * 3)))}\tnon-water faces "
                            f"({', '.join(sorted({os.path.basename(x) for x in mesh_mats(c) if not _water_material(x)[0]}))}) moved out of the func_water back into the world")
                unz(c)
                changed = True

        # ---- a func_water holding several separate water brushes (Valve's importer merged a level's pools):
        # unnamed ones become a func_water per brush, so the water volume is each pool and not everything between them
        for e in list(m.by_class("func_water")):
            if m.name(e) or m.conns(e):
                continue
            meshes = [c for c in m.children(e) if m.type(c) == b"CMapMesh"]
            pieces = []
            for c in meshes:
                pieces += _split_mesh_parts(m, c)
            if len(pieces) <= len(meshes) and len(meshes) <= 1:
                continue

            # pieces whose boxes really overlap stay together (a surface and its depth box). Union-find, so a piece overlapping two groups
            # joins them (a single pass left surface tiles listed before their depth box as func_waters of their own)
            bxs_ = [m.bounds(q) for q in pieces]
            up_ = list(range(len(pieces)))

            def root_(i):
                while up_[i] != i:
                    up_[i] = up_[up_[i]]
                    i = up_[i]
                return i
            for i_ in range(len(pieces)):
                for j_ in range(i_):
                    if bxs_[i_] and bxs_[j_] and _pool_overlap(bxs_[i_], bxs_[j_]):
                        up_[root_(i_)] = root_(j_)
            grp_ = {}
            for i_, q in enumerate(pieces):
                grp_.setdefault(root_(i_), []).append(q)
            groups_ = list(grp_.values())        # in order of each group's first piece, as before
            if len(groups_) < 2:
                if len(pieces) != len(meshes):     # meshes were split into pieces: put them all back (was `or old`: unbound, crashed)
                    dmx.geta(m.E[e], b"children")[2][:] = [x for x in m.children(e) if x not in meshes] + pieces
                    changed = True
                continue
            props = {a[0].decode(): a[2].decode("utf-8", "replace") for a in m.props(e)["attrs"] if a[1] == dmx.T_STR and a[0] != b"classname"}
            a = dmx.geta(m.E[e], b"children")
            a[2] = [x for x in a[2] if x not in meshes] + groups_[0]
            for g_ in groups_[1:]:
                lo = [min(m.bounds(x)[0][k] for x in g_) for k in range(3)]
                hi = [max(m.bounds(x)[1][k] for x in g_) for k in range(3)]
                ne = m.new_entity("func_water", [(lo[k] + hi[k]) / 2 for k in range(3)], props)
                dmx.geta(m.E[ne], b"children")[2].extend(g_)
            rows.append(f"POOLS\t{_fmt_box(*(m.bounds(e) or ([0] * 3, [0] * 3)))}\tone func_water held {len(groups_)} separate water brushes: "
                        f"a func_water each now (one over them all made everything between them water)")
            tot["new_func_water"] += len(groups_) - 1
            changed = True
            par = m.parent_of()

        # ---- the same pool twice: Valve's importer makes a func_water of each .vmf water brush and also leaves the brush's compiled water
        # surface in the func_water it merged the world into (ba_jail_os_gulag_d: 3 pools, two water surfaces on top of each other). The
        # func_water that is a whole .vmf water brush (else the one with the fewest faces) is kept; the other one's water faces inside it
        # are deleted, and when it has no water left, its meshes go back to the world and it is removed
        _bundled_install("splitfaces")
        sf_ = sys.modules["splitfaces"]
        fws = []
        for e in m.by_class("func_water"):
            if m.name(e) or m.conns(e):
                continue
            ms = [c for c in m.children(e) if m.type(c) == b"CMapMesh"]
            fw = [(c, _mesh_faces_world(m, c)) for c in ms]
            if any(_water_material(mt)[0] for _c, fs in fw for _f, _P, _k, mt in fs):
                fws.append((e, sum(len(fs) for _c, fs in fw), m.bounds(e)))

        def whole_brush(b_):
            return bool(b_) and any(all(abs(b_[0][k] - lo[k]) <= 1 and abs(b_[1][k] - hi[k]) <= 1 for k in range(3)) for lo, hi, _w in vmf_water_mm)
        fws.sort(key=lambda x: (not whole_brush(x[2]), x[1], x[0]))
        gone_ = set()
        for i, (ke, _nk, kb) in enumerate(fws):
            if ke in gone_ or not kb:
                continue
            for de, _nd, db in fws[i + 1:]:
                if de in gone_ or not db or not _pool_overlap(kb, db):
                    continue
                inside = lambda P: all(kb[0][k] - 1 <= q[k] <= kb[1][k] + 1 for q in P for k in range(3))      # noqa: E731
                n_del = 0
                for c in [c for c in m.children(de) if m.type(c) == b"CMapMesh"]:
                    fs = _mesh_faces_world(m, c)
                    drop = {f for f, P, _k, mt in fs if _water_material(mt)[0] and inside(P)}
                    if not drop or sf_.mesh_has_subdivision(m, c):
                        continue
                    polys, _mm = sf_.mesh_read(m, c)
                    rest = [q for f, q in enumerate(polys) if f not in drop]
                    if not rest:
                        a = dmx.geta(m.E[de], b"children")
                        a[2] = [x for x in a[2] if x != c]
                        n_del += len(drop)
                    elif sf_.mesh_write(m, c, rest, by_id=True) is None:
                        n_del += len(drop)
                if not n_del:
                    continue
                changed = True
                left = [c for c in m.children(de) if m.type(c) == b"CMapMesh"]
                wet_left = any(_water_material(mt)[0] for c in left for _f, _P, _k, mt in _mesh_faces_world(m, c))
                rows.append(f"DOUBLED\t{_fmt_box(*db)}\t{n_del} water face(s) of a second func_water over the same pool deleted (the importer's "
                            f"compiled surface over its func_water of the brush)" + ("" if wet_left else "; its other faces went back to the world"))
                if not wet_left:
                    a = dmx.geta(m.E[de], b"children")
                    a[2] = [x for x in a[2] if x not in left]
                    dmx.geta(m.E[m.world], b"children")[2].extend(left)
                    m.remove_node(de)
                    gone_.add(de)

        for e in list(m.by_class("func_water")):      # a func_water with no water face left in it (nodraw pieces the pool split made one of)
            if m.name(e) or m.conns(e):
                continue
            ms = [c for c in m.children(e) if m.type(c) == b"CMapMesh"]
            if not ms or any(_water_material(x)[0] for c in ms for x in mesh_mats(c)):
                continue
            b_ = m.bounds(e) or ([0] * 3, [0] * 3)
            a = dmx.geta(m.E[e], b"children")
            a[2] = [x for x in a[2] if x not in ms]
            dmx.geta(m.E[m.world], b"children")[2].extend(ms)
            rows.append(f"REMOVED\tfunc_water {_fmt_box(*b_)}\tno water face in it: its {len(ms)} mesh(es) went back to the world")
            m.remove_node(e)
            changed = True

        # ---- world water -> func_water
        par = m.parent_of()                      # (the pool split above can put pieces back into their func_water without updating it)
        world = []
        for n, _p in list(m.walk()):
            if m.type(n) != b"CMapMesh" or owner(n) is not None:
                continue
            hits = [x for x in mesh_mats(n) if _water_material(x)[0]]
            b = m.bounds(n) if hits else None
            if not b:
                continue
            for x in hits:
                water_mats.setdefault(x, _water_material(x)[1])
            if len(hits) < len(mesh_mats(n)):           # the importer merged the water with other brushes (sky, walls): split the water faces off
                wn = _split_water_faces(m, n)
                if wn is n:
                    world.append((n, b))
                    continue
                if wn is None:
                    rows.append(f"MIXED_MESH\t{_fmt_box(*b)}\ta world mesh holds water and other faces ({', '.join(os.path.basename(x) for x in mesh_mats(n))}) and could not be split: "
                                "left in the world. In Hammer select its water faces, separate them into their own mesh and tie that to a func_water")
                    continue
                rows.append(f"SPLIT\t{_fmt_box(*b)}\twater faces split off a world mesh that also held {', '.join(sorted({os.path.basename(x) for x in mesh_mats(n) if not _water_material(x)[0]}))}")
                par[wn] = _p
                dmx.geta(m.E[_p], b"children")[2].append(wn)
                n, b = wn, m.bounds(wn)
                changed = True
            parts = _split_mesh_parts(m, n)      # separate water brushes the importer merged: a func_water each (one func_water over
            for q in parts[1:]:                  # pools spread across a level makes the whole level water)
                par[q] = par.get(n, m.world)
                dmx.geta(m.E[par[q]], b"children")[2].append(q)
                changed = True
            if len(parts) > 1:
                rows.append(f"PIECES\t{_fmt_box(*b)}\tworld water mesh holding {len(parts)} separate water brushes split into {len(parts)} meshes (a func_water each)")
            for q in parts:
                world.append((q, m.bounds(q)))
            continue
        idx = list(range(len(world)))

        def find(i):
            while idx[i] != i:
                idx[i] = idx[idx[i]]
                i = idx[i]
            return i
        for i in range(len(world)):
            for j in range(i + 1, len(world)):
                if _pool_overlap(world[i][1], world[j][1]):     # only water whose footprints really overlap is one func_water
                    idx[find(i)] = find(j)
        groups = {}
        for i in range(len(world)):
            groups.setdefault(find(i), []).append(world[i])
        for g in groups.values():
            lo = [min(b[0][k] for _, b in g) for k in range(3)]
            hi = [max(b[1][k] for _, b in g) for k in range(3)]
            if hi[2] - lo[2] < 2 and vmf_depth(lo, hi) is None:
                rows.append(f"SURFACE_ONLY\t{_fmt_box(lo, hi)}\t{len(g)} mesh(es) of water surface with no depth: left as they are. Build a box under it in Hammer and tie it to a func_water to make it swimmable")
                tot["surface_only"] += 1
                continue
            ent = m.new_entity("func_water", [(lo[k] + hi[k]) / 2 for k in range(3)], {})
            for n, _b in g:
                a = dmx.geta(m.E[par[n]], b"children")
                a[2] = [x for x in a[2] if x != n]
                dmx.geta(m.E[ent], b"children")[2].append(n)
            rows.append(f"FUNC_WATER\t(new)\t{_fmt_box(lo, hi)}\t{len(g)} world mesh(es) moved into a new func_water, depth {hi[2] - lo[2]:g}")
            if hi[2] - lo[2] < 2:
                give_depth(ent, lo, hi)
            tot["new_func_water"] += 1
            changed = True

        for e in m.by_class("func_water"):       # func_water left flat by an earlier run
            b = m.bounds(e)
            if b and b[1][2] - b[0][2] < 2 and give_depth(e, b[0], b[1]):
                changed = True

        # ---- a water brush's surface is its top. CS:GO drew only that face of a water brush; CS2 makes water of every face with a water
        # material (Valve: water is defined by the material on a surface, the other faces are not needed), so a side or bottom face with
        # the water material spreads water out of the brush (ba_jail_os_gulag_d: its water brushes have water on every side, and the
        # whole map was water). Those faces of a func_water become toolsnodraw, as the importer leaves them when the .vmf has nodraw there
        for e in m.by_class("func_water"):
            n_side = 0
            for n, _p in m.walk(e):
                md = m.g(n, b"meshData") if m.type(n) == b"CMapMesh" else None
                if md is None:
                    continue
                ma = dmx.geta(m.E[md], b"materials")
                mats_ = [x.decode("utf-8", "replace") for x in (ma[2] if ma else [])]
                st = next((x for x in m.g(m.g(md, b"faceData"), b"streams") or [] if m.E[x]["name"] == b"materialindex:0"), None)
                da = dmx.geta(m.E[st], b"data") if st is not None else None
                if not mats_ or da is None or not any(_water_material(x)[0] for x in mats_):
                    continue
                fdi = m.g(md, b"faceDataIndices") or []
                faces_ = _mesh_faces_world(m, n)
                side = [fdi[f] for f, P, _k, mt in faces_ if _water_material(mt)[0] and _poly_normal_sum(np.asarray(P, float))[2]
                        <= 0.7 * float(np.linalg.norm(_poly_normal_sum(np.asarray(P, float))))]
                if not side:
                    continue
                nod = "materials/tools/toolsnodraw.vmat"
                if nod not in [x.lower() for x in mats_]:
                    ma[2] = list(ma[2]) + [nod.encode()]
                    mats_.append(nod)
                k_nod = [x.lower() for x in mats_].index(nod)
                for i in side:
                    da[2][i] = k_nod
                n_side += len(side)
            if n_side:
                b = m.bounds(e)
                rows.append(f"WATER_SIDES\t{m.name(e) or '(unnamed)'} {_fmt_box(b[0], b[1]) if b else ''}\t{n_side} side / bottom face(s) "
                            f"with the water material -> toolsnodraw (only the top is the water's surface)")
                tot["water_sides"] += n_side
                changed = True

        # ---- the water materials found
        waters = m.by_class("func_water")
        for e in waters:
            for c in m.children(e):
                if m.type(c) == b"CMapMesh":
                    for x in mesh_mats(c):
                        if _water_material(x)[0]:
                            water_mats.setdefault(x, _water_material(x)[1])
        # ---- Source1 water materials -> CS2 water materials of their own (WATER_CONVERT); the rest -> a stock CS2 water (WATER_MATERIAL)
        is_sky = _is_skybox_map(vp)
        blend = None                             # main map with a 3D skybox: its biggest water fades into the skybox water
        # (only when the 3D skybox has water: Map UV Min / Max is then the biggest water's box, and csgo_water_fancy does not draw water
        # outside it - ba_jail_os_gulag_d, no water in its skybox: every pool but the biggest would have been left out)
        if WATER_CONVERT and not is_sky and sky_scale and sky_water and m.by_class("skybox_reference"):
            sea = [w for w in waters if m.bounds(w)]
            if sea:
                bb = m.bounds(max(sea, key=lambda w: (m.bounds(w)[1][0] - m.bounds(w)[0][0]) * (m.bounds(w)[1][1] - m.bounds(w)[0][1])))
                blend = (bb[0], bb[1], sky_scale)
        if WATER_CONVERT and is_sky:            # 3D skybox map: its water uses the <name>_skybox copy (same look, no fade)
            for w in waters:
                for c in m.children(w):
                    md = m.g(c, b"meshData") if m.type(c) == b"CMapMesh" else None
                    a = dmx.geta(m.E[md], b"materials") if md is not None else None
                    if not a:
                        continue
                    new = []
                    for x in a[2]:
                        mat = x.decode("utf-8", "replace")
                        base = mat[:-len("_skybox.vmat")] + ".vmat" if mat.lower().endswith("_skybox.vmat") else mat
                        if _water_material(base)[0] and not base.lower().startswith("materials/liquids/"):
                            key = base + "|skybox"
                            if key not in converted:
                                converted[key] = make_cs2_water_vmat(base, export_dir, skybox=True, sky_scale=sky_scale or 16.0)
                            if converted[key][0] and mat != _water_skybox_name(base):
                                x = _water_skybox_name(base).encode("utf-8")
                                rows.append(f"SKYBOX_WATER_MATERIAL\t{mat} -> {_water_skybox_name(base)}\t3D skybox map: same water, no fade")
                        new.append(x)
                    if new != a[2]:
                        a[2] = new
                        changed = True
        if WATER_CONVERT and not is_sky:
            # the map's own Source1 water (a water material of the .vmf's water brushes) is converted wherever it lives, materials/liquids/
            # included (CS:GO's liquids/aztecwater, water_aztec_cheap: CS2 has no such material); another water material only outside
            # materials/liquids/ (CS2's own waters are there) and only when it is missing
            for w in waters:
                for c in m.children(w):
                    for mat in (mesh_mats(c) if m.type(c) == b"CMapMesh" else []):
                        if (_water_material(mat)[0] and mat not in converted
                                and (mat.lower() in vmf_water_mats
                                     or (not mat.lower().startswith("materials/liquids/") and _water_vmat_missing(mat, export_dir)))):
                            converted[mat] = make_cs2_water_vmat(mat, export_dir, blend=blend)
        # ---- swaps: WATER_MATERIAL_MAP; a <name>_skybox.vmat whose copy is gone (WATER_CONVERT off / failed) back to <name>.vmat
        for w in waters:
            for c in m.children(w):
                md = m.g(c, b"meshData") if m.type(c) == b"CMapMesh" else None
                a = dmx.geta(m.E[md], b"materials") if md is not None else None
                if not a:
                    continue
                new = []
                for x in a[2]:
                    mat = x.decode("utf-8", "replace")
                    if mat.lower().endswith("_skybox.vmat") and not (export_dir / mat).exists() and not converted.get(mat[:-len("_skybox.vmat")] + ".vmat|skybox", (False,))[0] and _water_material(mat[:-len("_skybox.vmat")] + ".vmat")[0]:
                        rows.append(f"SKYBOX_WATER_MATERIAL\t{mat} -> {mat[:-len('_skybox.vmat')]}.vmat\tthe recompiled 3D skybox copy is gone")
                        mat = mat[:-len("_skybox.vmat")] + ".vmat"
                        x = mat.encode("utf-8")
                    repl, why = (None, "")
                    if mat.lower() in {k.lower() for k in WATER_MATERIAL_MAP}:     # only swaps you listed
                        repl, why = _water_replacement(mat)
                    if repl and repl.lower() != mat.lower():
                        swaps[(mat, repl, why)] = swaps.get((mat, repl, why), 0) + 1
                        x = repl.encode("utf-8")
                    new.append(x)
                if new != a[2]:
                    a[2] = new
                    changed = True
        if not changed:
            _keep_map(m, vp)
        else:
            try:
                bak = _save_map(m, vp, "water")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                print(f"  [WARN] water: could not write {vp} ({ex}); close Hammer and rerun")
                continue
            print(f"  [WATER] {vn}: " + (", ".join(r.split("\t")[0] for r in rows if r.split("\t")[0] in ("FUNC_WATER", "ANALOG", "DEPTH")).lower()
                                        or "water materials") + f"; original saved as {os.path.basename(bak)}")
        out.append(f"# {vn}: {len(waters)} func_water")
        out += rows
    # ---- what each water material became
    if str(export_dir) in _WAVE_TEX_NOTE:
        wn_ = _WAVE_TEX_NOTE[str(export_dir)]
        if wn_.startswith("written"):
            out.append(f"WAVE_TEXTURES\tmaterials/water/cs2_waves_normal.tga, cs2_waves_height.tga\t{wn_}")
        else:
            out.append(f"WAVE_TEXTURES\tNOT WRITTEN\t{wn_}")
            todo.append(f"the converted water materials have no wave textures, so the water is a flat sheet: {wn_}")
    for mat, (ok_, why_) in sorted(converted.items()):
        out.append(f"CONVERTED\t{mat}\t" + (f"CS2 water material in the addon ({why_}); fog colour and murkiness from the Source1 .vmt"
                                             if ok_ else f"NOT converted: {why_}"))
    swapped = {old for old, _n, _w in swaps}
    for (old, new, why), n in sorted(swaps.items()):
        out.append(f"SWAPPED\t{old} -> {new}\t{n} water mesh(es)\t({why})")
    for mat, how in sorted(water_mats.items()):
        if (export_dir / mat).exists():
            where = "in the addon"
        elif cs2_file_exists(mat + "_c") and not cs2_vmat_is_stub(mat):
            where = "ships with CS2"
        elif mat in swapped:
            where = "not in CS2: swapped (above)"
        else:
            where = "MISSING"
            todo.append(f"{mat}: MISSING in CS2 (a Source1 water material); in Hammer, give its water a CS2 water material (or list it in WATER_MATERIAL_MAP)")
        out.append(f"MATERIAL\t{mat}\t{where}\tdetected by: {how}")
        if how.startswith("GUESSED") and where not in ("ships with CS2", "in the addon"):
            todo.append(f"{mat}: treated as water from its name only; if it is not water, add it to WATER_IGNORE_MATERIALS and restore the vmap from its .before_water backup in the backups folder")
    if any(t.startswith(tuple(water_mats)) and "MISSING" in t for t in todo):
        out.append("# CS2 water materials to choose from (materials/liquids/): " + (", ".join(_cs2_water_materials()) or "none found (CS2 install not read?)"))
    out.insert(0, "# water: " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in tot.items())
               + ". Underwater lights come from the lighting rebuild (LIGHTING_UNDERWATER).")
    if todo:
        out += ["", "# check by hand:"] + ["TODO\t" + t for t in todo]
    return out



# ======================================================================== LIGHTING (from rebuild_lighting.py)
# Valve's importer gets CS:GO lights wrong (brightness NaN -> Hammer resets it to 1000 lumens, colour turned into a 6600 K white).
# rebuild_map_lighting() deletes every light, light probe volume and visibility hint and rebuilds them from the .vmf:
#   light -> light_omni2, light_spot -> light_barn (brightness = _light x _lightHDR x _lightscaleHDR, real colour, range from _distance /
#   fade, cone from _cone / _inner_cone; switchable lights become Dynamic), light_environment kept (SUN_SCALE), dim underwater lights in each
#   func_water, then skink52's passes: light probe volumes, Static -> Stationary lights (max 4 overlapping), vis hints, large-face splitting.
# The light scale (1000 lumens per 265 intensity) comes from the importer's own output; bake and compare a few rooms to CS:GO, then tune LIGHT_SCALE.
LIGHT_CLASSES = ('light_omni2', 'light_barn', 'light_rect', 'light_capsule', 'light_omni', 'light_ortho', 'light_spot', 'light')
WATER_CLASSES = ('func_water', 'func_water_analog')
