class _RadarTex:
    """Floor colour per material: the average of its colour texture in the addon (the .tga/.png this script wrote next to the
    vmat) when RADAR_TEXTURE_COLOURS, else a guess from the material name."""

    def __init__(self, export_dir: Path):
        self.root, self.cache = export_dir, {}

    def colour(self, mat):
        key = mat.lower()
        if key not in self.cache:
            col = None
            if RADAR_TEXTURE_COLOURS:
                base = os.path.splitext(key)[0]
                for suf in ("_color", "_c", ""):
                    for ext in (".tga", ".png", ".jpg"):
                        p = self.root / (base + suf + ext)
                        if p.is_file():
                            try:
                                im = Image.open(p).convert("RGB").resize((8, 8))
                                from PIL import ImageStat
                                col = tuple(int(x) for x in ImageStat.Stat(im).mean[:3])
                            except Exception:
                                col = None
                            break
                    if col:
                        break
            if not col:
                col = next((rgb for words, rgb in RADAR_COLOURS if any(w in key for w in words)), RADAR_DEFAULT_COLOUR)
            self.cache[key] = col
        return self.cache[key]


def _poly_area_xy(P):
    """area of a polygon seen from above (as drawn on the radar)"""
    x, y = P[:, 0], P[:, 1]
    return 0.5 * abs(float((x * (y.take(range(1, len(y) + 1), mode="wrap")) - y * (x.take(range(1, len(x) + 1), mode="wrap"))).sum()))


def _radar_draw(m, export_dir: Path, size: int):
    """Draw the radar for an open vmapedit.Map (method from make_radar.py). -> (rgba image, overview values, note lines)"""
    import numpy as np
    from PIL import ImageDraw
    notes = []
    lighting = _bundled_lighting_passes(("lighting",))         # its mesh / voxel helpers; numpy only
    wp = lighting.world_polys(m)
    polys = list(wp)
    for e in m.entities():                              # doors, func_brush, breakables, water...
        if m.cls(e).startswith(RADAR_SKIP_ENTS):
            continue
        for ch in m.children(e):
            if m.type(ch) == b"CMapMesh":
                polys.extend(lighting.mesh_polys(m, ch))
    floors, walls = [], []
    for mat, loop in polys:
        if any(s in mat for s in RADAR_SKIP_MATS) or len(loop) < 3:
            continue
        P = np.array(loop)
        Q = np.roll(P, -1, axis=0)                       # Newell normal
        n = np.array([((P[:, 1] - Q[:, 1]) * (P[:, 2] + Q[:, 2])).sum(), ((P[:, 2] - Q[:, 2]) * (P[:, 0] + Q[:, 0])).sum(),
                      ((P[:, 0] - Q[:, 0]) * (P[:, 1] + Q[:, 1])).sum()])
        ln = np.linalg.norm(n)
        if ln < 1e-6:
            continue
        n /= ln
        if n[2] > 0.6:
            floors.append((mat, P))
        elif abs(n[2]) < 0.3:
            walls.append(P)
    if not floors:
        return None, None, ["no floor faces found"]
    notes.append(f"{len(floors)} floor faces, {len(walls)} wall faces")
    note = "room filter off (RADAR_ROOM_FILTER)"
    room_ok = None
    if wp and RADAR_ROOM_FILTER:
        try:
            from scipy import ndimage
        except ImportError:
            ndimage = None
            note = "room filter skipped: needs scipy (py -m pip install scipy); roofs and outside faces are drawn too"
        if ndimage is not None:
            vs = 32.0
            solid, vlo = lighting.voxelise(wp, vs)
            lab, _ = lighting.label_empty(solid)
            shape = np.array(solid.shape)

            def lab_at(p):
                i = np.floor((np.array(p) - vlo) / vs).astype(int)
                return 0 if (i < 0).any() or (i >= shape).any() else lab[tuple(i)]

            def lab_near(p):
                for dz in (0, 32, -32, 64):
                    v = lab_at([p[0], p[1], p[2] + dz])
                    if v:
                        return v
                return 0
            play = set()
            for e in m.by_class(*lighting.LIGHT_CLASSES) + m.by_class("info_player_terrorist", "info_player_counterterrorist", "info_teleport_destination", "info_deathmatch_spawn"):
                v = lab_near(m.origin(e))
                if v:
                    play.add(v)
            ext = set(np.unique(np.concatenate([lab[0].ravel(), lab[-1].ravel(), lab[:, 0].ravel(), lab[:, -1].ravel(), lab[:, :, 0].ravel(), lab[:, :, -1].ravel()])))
            skyl = set(np.unique(lab[ndimage.binary_dilation(solid == 2) & (lab > 0)]))
            play -= ext                     # a light / spawn outside the sealed map must not turn the void into a room
            note = "room filter found no rooms with lights or spawns; every upward face drawn"
            if play:
                ids = np.arange(int(lab.max()) + 1)
                okl = np.isin(ids, list(play)) | ((ids > 0) & ~np.isin(ids, list(ext)) & ~np.isin(ids, list(skyl)))

                def _room_ok(pts):
                    """(N, 3) world points -> True where the point is in a room (with lights / spawns, or sealed and not open to sky)"""
                    i = np.floor((np.asarray(pts, float) - vlo) / vs).astype(int)
                    inb = ((i >= 0) & (i < shape)).all(1)
                    res = np.zeros(len(i), bool)
                    j = i[inb]
                    res[inb] = okl[lab[j[:, 0], j[:, 1], j[:, 2]]]
                    return res

                def face_ok(P):
                    c0 = P.mean(0)
                    return bool(_room_ok(np.array([c0] + [(c0 + v) / 2 for v in P]) + [0, 0, 40]).any())
                kept = [f for f in floors if _poly_area_xy(f[1]) > RADAR_CLIP_AREA or face_ok(f[1])]
                if kept:
                    note = "kept %d of %d floor faces that open onto a room; faces over %g sq units clipped to the rooms pixel by pixel" % (len(kept), len(floors), RADAR_CLIP_AREA)
                    floors = kept
                    room_ok = _room_ok
    notes.append(note)
    land = [f for f in floors if "water" not in f[0].lower()] or floors
    allp = np.concatenate([f[1] for f in land])
    lo = np.percentile(allp, RADAR_TRIM, axis=0)
    hi = np.percentile(allp, 100 - RADAR_TRIM, axis=0)
    span = max(hi[0] - lo[0], hi[1] - lo[1]) * 1.04 + 128
    cx, cy = (lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2
    px, py = cx - span / 2, cy + span / 2
    scale = span / size
    ss = 2
    S = size * ss
    zlo, zhi = np.percentile(allp[:, 2], 2), np.percentile(allp[:, 2], 98)
    tex = _RadarTex(export_dir)

    def to_img(P):
        return [((x - px) / scale * ss, (py - y) / scale * ss) for x, y in P[:, :2]]

    img = Image.new("RGBA", (S, S), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    for mat, P in sorted(floors, key=lambda f: f[1][:, 2].mean()):
        t = float(np.clip((P[:, 2].mean() - zlo) / max(zhi - zlo, 1), 0, 1))
        r, g, b = tex.colour(mat)
        k = 0.55 + 0.5 * t
        fill = (int(min(255, r * k)), int(min(255, g * k)), int(min(255, b * k)), 110 if "glass" in mat.lower() else 255)
        if room_ok is None or _poly_area_xy(P) <= RADAR_CLIP_AREA:
            d.polygon(to_img(P), fill=fill)
            continue
        # big face (a square block of water / terrain often reaches outside the map): keep only the pixels over a room
        pts = to_img(P)
        x0, y0 = max(0, int(min(q[0] for q in pts))), max(0, int(min(q[1] for q in pts)))
        x1, y1 = min(S, int(max(q[0] for q in pts)) + 2), min(S, int(max(q[1] for q in pts)) + 2)
        if x1 <= x0 or y1 <= y0:
            continue
        mask = Image.new("L", (x1 - x0, y1 - y0), 0)
        ImageDraw.Draw(mask).polygon([(x - x0, y - y0) for x, y in pts], fill=255)
        M = np.asarray(mask) > 0
        yy, xx = np.nonzero(M)
        wx = px + (xx + x0 + 0.5) / ss * scale
        wy = py - (yy + y0 + 0.5) / ss * scale
        Q = np.roll(P, -1, axis=0)
        n = np.array([((P[:, 1] - Q[:, 1]) * (P[:, 2] + Q[:, 2])).sum(), ((P[:, 2] - Q[:, 2]) * (P[:, 0] + Q[:, 0])).sum(), ((P[:, 0] - Q[:, 0]) * (P[:, 1] + Q[:, 1])).sum()])
        c0 = P.mean(0)
        wz = c0[2] - (n[0] * (wx - c0[0]) + n[1] * (wy - c0[1])) / n[2]          # on the face's plane
        ok = room_ok(np.stack([wx, wy, wz + 40], 1))
        M[yy[~ok], xx[~ok]] = False
        img.paste(fill, (x0, y0), Image.fromarray(M.astype(np.uint8) * 255))
    edge = Image.new("RGBA", (S, S), (0, 0, 0, 0))
    de = ImageDraw.Draw(edge)
    for P in walls:
        if P[:, 2].max() - P[:, 2].min() < RADAR_MIN_WALL:
            continue
        pts = to_img(P)
        de.line(pts + [pts[0]], fill=(20, 22, 28, 255), width=max(1, ss))
    img = Image.alpha_composite(img, edge).resize((size, size), Image.LANCZOS)

    def frac(cls):
        es = m.by_class(cls)
        if not es:
            return 0.5, 0.5
        o = np.mean([m.origin(e)[:2] for e in es], axis=0)
        return float(np.clip((o[0] - px) / span, 0, 1)), float(np.clip((py - o[1]) / span, 0, 1))
    ctx, cty = frac("info_player_counterterrorist")
    tx, ty = frac("info_player_terrorist")
    notes.append("map extent x %.0f..%.0f  y %.0f..%.0f; pos_x %d pos_y %d scale %.2f" % (lo[0], hi[0], lo[1], hi[1], px, py, scale))
    return img, dict(px=px, py=py, scale=scale, ctx=ctx, cty=cty, tx=tx, ty=ty), notes


def _sha1(data: bytes) -> str:
    import hashlib
    return hashlib.sha1(data).hexdigest()


SEAM_SKIP_CLASSES = ("trigger_", "func_water", "post_processing_volume", "env_", "visibility_hint", "func_buyzone", "func_bomb_target",
                     "func_hostage_rescue", "func_clip", "func_nav")


def report_entity_seams(targets):
    """Brush-entity faces that sit in the plane of a world surface: one filling a gap in it (shares edges with the world faces around) is
    lit as a separate surface, so it rarely matches (a black square in a ceiling); one lying ON a world face z-fights. Report only.
    -> list of log lines"""
    import importlib.util
    if importlib.util.find_spec("numpy") is None:
        return ["# entity seams: skipped - needs numpy"]
    lighting = _bundled_lighting_passes(("lighting",))

    def plane(loop):
        P = loop
        n = [0.0, 0.0, 0.0]
        for i in range(len(P)):
            a, b = P[i], P[(i + 1) % len(P)]
            n[0] += (a[1] - b[1]) * (a[2] + b[2]); n[1] += (a[2] - b[2]) * (a[0] + b[0]); n[2] += (a[0] - b[0]) * (a[1] + b[1])
        ln = math.sqrt(sum(x * x for x in n))
        if ln < 1e-6:
            return None
        n = [x / ln for x in n]
        c = [sum(p[k] for p in P) / len(P) for k in range(3)]
        return n, sum(n[k] * c[k] for k in range(3)), c, ln / 2

    def flat(n, pts):                            # drop the dominant axis -> 2D
        ax = max(range(3), key=lambda k: abs(n[k]))
        keep = [k for k in range(3) if k != ax]
        return [(p[keep[0]], p[keep[1]]) for p in pts]

    def shared(e1, e2):                          # collinear overlap length of two 2D segments
        (ax, ay), (bx, by) = e1
        dx, dy = bx - ax, by - ay
        L = math.hypot(dx, dy)
        if L < 1e-6:
            return 0.0
        ux, uy = dx / L, dy / L
        ts = []
        for (px, py) in e2:
            if abs((px - ax) * uy - (py - ay) * ux) > 0.25:
                return 0.0
            ts.append((px - ax) * ux + (py - ay) * uy)
        return max(0.0, min(L, max(ts)) - max(0.0, min(ts)))

    def inside(pt, poly):
        x, y = pt
        c = False
        for i in range(len(poly)):
            (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % len(poly)]
            if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1) + x1:
                c = not c
        return c

    out, total = [], 0
    for vp in targets:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        index = {}
        for mat, loop in lighting.world_polys(m):
            if mat.startswith("materials/tools") or len(loop) < 3:
                continue
            pl = plane(loop)
            if pl:
                n, d, _c, _a = pl
                index.setdefault((round(n[0], 2), round(n[1], 2), round(n[2], 2), round(d)), []).append((mat, flat(n, loop)))
        rows = []
        for e in m.entities():
            cls = m.cls(e)
            if cls.startswith(SEAM_SKIP_CLASSES):
                continue
            for ch in m.children(e):
                if m.type(ch) != b"CMapMesh":
                    continue
                for mat, loop in lighting.mesh_polys(m, ch):
                    if mat.startswith("materials/tools") or len(loop) < 3:
                        continue
                    pl = plane(loop)
                    if not pl:
                        continue
                    n, d, c, area = pl
                    key = (round(n[0], 2), round(n[1], 2), round(n[2], 2))
                    cands = [w for dd in (-1, 0, 1) for w in index.get(key + (round(d) + dd,), [])]
                    if not cands:
                        continue
                    f2 = flat(n, loop)
                    edges = [(f2[i], f2[(i + 1) % len(f2)]) for i in range(len(f2))]
                    c2 = flat(n, [c])[0]
                    on_top = [wm for wm, w2 in cands if inside(c2, w2)]
                    touch, wmats = 0, set()
                    for ed in edges:
                        hit = False
                        for wm, w2 in cands:
                            if any(shared(ed, (w2[i], w2[(i + 1) % len(w2)])) > 1.0 for i in range(len(w2))):
                                hit = True
                                wmats.add(wm)
                        touch += hit
                    who = f"{cls} {m.name(e) or '(unnamed)'}"
                    where = " ".join("%g" % round(x) for x in c)
                    if on_top:
                        rows.append(f"OVERLAPS\t{who}\tat {where}\t{os.path.basename(mat)} lies on a world face ({os.path.basename(on_top[0])}): the two z-fight")
                    elif touch:
                        rows.append(f"FILLS_GAP\t{who}\tat {where}\t{area:.0f} sq u of {os.path.basename(mat)}, {touch} of {len(edges)} edge(s) meet the world surface "
                                    f"({', '.join(sorted(os.path.basename(x) for x in wmats))}): lit separately, may not match it")
        _keep_map(m, vp)
        total += len(rows)
        out += [f"# {vn}"] + sorted(rows)
    out.insert(0, f"# entity seams: {total} brush-entity face(s) continue or overlap a world surface in the same plane. Such a face is lit on its own "
                  "(a separate lightmap chart, or per object from probes), so it often shows as a lighter or darker patch; nothing was changed. "
                  "If the entity never moves or disappears, making the face part of the world surface (or nodraw on the entity) removes the seam.")
    return out


def make_radars(vmaps, primary, export_dir: Path, backup_dir):
    """Draw a radar for the main map(s) (primary, else the .vmaps directly in the maps folder; prefab sub-maps get none):
         <addon>\\panorama\\images\\overheadmaps\\<map>_radar_psd.png + .vtex      (content)
         <game twin of the addon>\\resource\\overviews\\<map>.txt                  (pos_x / pos_y / scale + spawn icons)
         logs\\<map>_radar_preview.png                                             (a quick look, with the spawn spots)
    Rerun-safe: what was written is remembered (backups\\<map>.radar_written.txt, a hash per file). Files still exactly as written are simply
    redrawn. A file you edited (or one from make_radar.py / elsewhere) is kept while the map is unchanged, i.e. while the new drawing is the one
    this script last wrote; once the map changes (RADAR_REDRAW_ON_CHANGE), all three are redrawn, your versions copied to
    backups\\radar_replaced\\<time> first. -> list of log lines"""
    import importlib.util
    if importlib.util.find_spec("numpy") is None:
        return ["# radar: skipped - needs numpy (and scipy for the room filter):  py -m pip install numpy scipy"]
    out = []
    targets = _main_vmaps(vmaps, primary)
    game_dir = _game_dir(export_dir)
    for vp in targets:
        name = vp.stem
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {name}: cannot read ({ex})")
            continue
        files = {
            "png": export_dir / "panorama" / "images" / "overheadmaps" / f"{name}_radar_psd.png",
            "vtex": export_dir / "panorama" / "images" / "overheadmaps" / f"{name}_radar_psd.vtex",
            "txt": (game_dir / "resource" / "overviews" / f"{name}.txt") if game_dir else Path(LOG_DIR) / "radar_game_files" / "resource" / "overviews" / f"{name}.txt",
        }
        state_path = Path(backup_dir) / f"{name}.radar_written.txt"
        known = {}
        for ln in (state_path.read_text(encoding="utf-8").splitlines() if state_path.is_file() else []):
            if "\t" in ln and not ln.startswith("#"):
                h, p = ln.split("\t", 1)
                known[p] = h
        foreign = [k for k, p in files.items() if p.is_file() and known.get(str(p)) != _sha1(p.read_bytes())]
        try:
            img, ov, notes = _radar_draw(m, export_dir, RADAR_SIZE)
            _keep_map(m, vp)                     # the radar only reads the map
        except Exception as ex:
            out.append(f"# {name}: radar not drawn ({type(ex).__name__}: {ex})")
            continue
        if img is None:
            out.append(f"# {name}: radar not drawn ({notes[0]})")
            continue
        import io
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        data = {"png": buf.getvalue(), "vtex": (RADAR_VTEX % dict(map=name, size=RADAR_SIZE)).encode("utf-8"),
                "txt": (RADAR_OVERVIEW % dict(map=name, **ov)).encode("utf-8")}
        out.append(f"# {name}: " + "; ".join(notes))
        if foreign and RADAR_REDRAW_ON_CHANGE and any(known.get(str(files[k])) != _sha1(data[k]) for k in foreign):
            # the drawing is not the one these files were last written from: the map changed since -> redraw, keeping a copy of the edited files
            keep_dir = Path(backup_dir) / "radar_replaced" / time.strftime("%Y%m%d-%H%M%S")
            for k in foreign:
                try:
                    keep_dir.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(str(files[k]), str(keep_dir / files[k].name))
                    out.append(f"REPLACED\t{files[k]}\tthe map changed since this radar was drawn: redrawn (your version copied to {keep_dir})")
                except OSError as ex:
                    out.append(f"ERROR\t{files[k]}\tcould not back it up ({ex}); kept")
                    break
            else:
                foreign = []
        for k, p in files.items():
            if p.is_file() and foreign:
                why = "edited by hand or not made by this script, and the map has not changed since this radar was drawn" if k in foreign else f"kept with the {', '.join(f.name for kk, f in files.items() if kk in foreign)} you changed (they must match)"
                out.append(f"KEPT\t{p}\t{why} (it is redrawn when the map changes, or delete the radar files to redraw now)")
                continue
            if foreign and k == "txt":
                out.append(f"NOTE\t{p}\twritten for the new drawing, but your radar image was kept: check pos_x / pos_y / scale still match it")
            same = p.is_file() and p.read_bytes() == data[k]
            err = None if same else _safe_write(p, data[k])
            if err:
                out.append(f"ERROR\t{p}\t{err}")
            else:
                known[str(p)] = _sha1(data[k])
                out.append(f"{'UNCHANGED' if same else 'WROTE'}\t{p}")
        try:
            state_path.parent.mkdir(parents=True, exist_ok=True)
            state_path.write_text("# radar files written by vmap_asset_slop_import (sha1). A file whose hash no longer matches was edited and is left alone.\n"
                                  + "\n".join(f"{h}\t{p}" for p, h in sorted(known.items())) + "\n", encoding="utf-8")
        except OSError:
            pass
        try:
            from PIL import ImageDraw
            prev = Image.new("RGBA", img.size, (24, 26, 32, 255))
            prev.alpha_composite(img)
            pd = ImageDraw.Draw(prev)
            for (fx, fy), col in (((ov["ctx"], ov["cty"]), (80, 140, 255)), ((ov["tx"], ov["ty"]), (255, 190, 60))):
                x, y = fx * RADAR_SIZE, fy * RADAR_SIZE
                pd.ellipse([x - 6, y - 6, x + 6, y + 6], outline=col + (255,), width=3)
            pp = os.path.join(LOG_DIR, f"{name}_radar_preview.png")
            prev.convert("RGB").save(pp)
            out.append(f"PREVIEW\t{pp}\t(blue = CT spawns, orange = T spawns; not compiled)")
        except Exception:
            pass
        if not game_dir:
            out.append(f"NOTE\t{files['txt']}\tthe addon is not under content\\csgo_addons, so the overview .txt was written to the logs folder: copy it to <addon game folder>\\resource\\overviews\\")
    if out:
        out.insert(0, "# radar: drawn from the map geometry (floors lowest to highest, darker lower down, tall walls outlined). Reopen the addon in Hammer / rebuild so the radar texture compiles.")
    return out


def _scan_worker(item):
    path, data = item
    return path, extract_assets_from_bytes(data)


def _scan_vmaps(vmaps):
    """[(vmap path, [asset paths])] for every vmap: the scan is CPU-bound pure Python, so with many maps it runs in worker processes
    (VMAP_SCAN_WORKERS, from VMAP_SCAN_PROCESS_MIN maps on); with a few, in this process (starting workers would cost more)"""
    items = [(str(vp), _vmap_read(vp)) for vp in vmaps]
    workers = VMAP_SCAN_WORKERS or os.cpu_count() or 1
    if len(items) >= max(2, VMAP_SCAN_PROCESS_MIN) and workers > 1:
        try:
            with ProcessPoolExecutor(max_workers=min(workers, len(items))) as ex:
                return list(ex.map(_scan_worker, items))
        except Exception as ex:          # (a broken pool, a frozen exe without multiprocessing support, ...)
            print(f"  [NOTE] asset scan: worker processes failed ({ex}); scanning in this process")
    return [_scan_worker(it) for it in items]


def _screen_overlay_refs(vmaps):
    """the OverlayName1..10 values of every env_screenoverlay, as the asset scan normalises them (they are not asset paths: relative to
    materials/, and the entity is not in CS2)"""
    out = set()
    for vp in vmaps:
        try:
            m = _open_map(vp)
        except Exception:
            continue
        for e in m.by_class("env_screenoverlay"):
            for i in range(1, 11):
                v = (m.P(e, f"OverlayName{i}", "") or "").strip()
                if v:
                    out.add(normalize_candidate(v))
        _keep_map(m, vp)
    return out


def extract_assets_from_bytes(data: bytes):
    """the asset paths referenced in a .vmap's bytes (top-level: run in worker processes by the scan in main)"""
    candidates = set()
    candidates.update(_extract_from_ascii_tokens(data))
    if not data.startswith(b"<!-- dmx encoding binary"):    # binary DMX strings are UTF-8: the UTF-16 scan of a .vmap found nothing
        candidates.update(_extract_from_utf16le_tokens(data))
    if not REQUIRE_NULL_DELIMITED:
        candidates.update(_fallback_regex_scan(data))
    results = set()
    for c in candidates:
        for piece in split_glued_paths(c):
            piece = normalize_candidate(piece)
            if piece:
                results.add(piece)
    return sorted(results)

EXT_RE = r"(?:vmat|vtex|vtex_c|tga|png|jpg|jpeg|dmx|vmdl|vmdl_c|vsnd|vpcf|wav|mp3|vmt|vtf)"
PATH_RE_TEXT = re.compile(rf'([A-Za-z0-9_\-./\\&()+{{ ]+\.{EXT_RE})', re.IGNORECASE)

@_cache_per_file_version(maxsize=200_000)
def parse_vmat_dependencies(vmat_path: str):
    deps = set()
    try:
        text = Path(vmat_path).read_text(encoding="utf-8", errors="ignore")
        deps.update(re.findall(r'"([^"]+\.(?:tga|png|jpg|jpeg|vtex|vtex_c))"', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.vmat)"', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.vmdl)"', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.dmx)"', text, flags=re.IGNORECASE))
    except Exception:
        pass
    return frozenset(d for d in (normalize_dep_must_be_rooted(x) for x in deps) if d)

def scan_addon_models_for_deps(export_dir: Path) -> set:
    deps = set()
    models_root = export_dir / "models"
    if not models_root.exists():
        return deps
    for fp in models_root.rglob("*"):
        if not fp.is_file() or fp.suffix.lower() not in (".vmdl", ".vmdl_c"):
            continue
        try:
            text = fp.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        for m in PATH_RE_TEXT.findall(text):
            rel = m.strip().strip('"').strip("'").lstrip("/").replace("\\", "/")
            if not rel.lower().endswith("meshinfo.txt"):
                nr = normalize_dep_must_be_rooted(rel)
                if nr:
                    deps.add(nr)
    return deps

# ======================================================================== MDL (Source1 model) materials

def parse_mdl_materials(mdl_path: str):
    """Return candidate 'materials/<cd>/<name>.vmat' paths referenced by a Source1 .mdl
    (studiohdr: numtextures@204, textureindex@208, numcdtextures@212, cdtextureindex@216)."""
    try:
        data = Path(mdl_path).read_bytes()
    except Exception:
        return []
    if len(data) < 220 or data[:4] != b"IDST":
        return []

    def cstr(off):
        if off < 0 or off >= len(data):
            return ""
        end = data.find(b"\0", off)
        return data[off:end].decode("ascii", errors="ignore") if end != -1 else ""

    try:
        numtex, texidx, numcd, cdidx = struct.unpack_from("<4i", data, 204)
    except struct.error:
        return []
    names, cds = [], []
    if 0 <= numtex <= 512 and texidx > 0:
        for i in range(numtex):
            base = texidx + i * 64
            if base + 4 > len(data):
                break
            rel = struct.unpack_from("<i", data, base)[0]
            names.append(cstr(base + rel))
    if 0 <= numcd <= 64 and cdidx > 0:
        for i in range(numcd):
            p = cdidx + i * 4
            if p + 4 > len(data):
                break
            cds.append(cstr(struct.unpack_from("<i", data, p)[0]))
    out = []
    for cd in cds or [""]:
        cd = rel_norm(cd).strip("/")
        for n in names:
            n = rel_norm(n)
            if n:
                out.append(normalize_candidate("materials/" + (cd + "/" if cd else "") + n + ".vmat"))
    return out

# ======================================================================== KEYVALUES / VMT

def _strip_comments_keep_quotes(text: str) -> str:
    out_lines = []
    for line in text.splitlines():
        result, in_quotes, i = [], False, 0
        while i < len(line):
            ch = line[i]
            if ch == '"':
                in_quotes = not in_quotes
            elif not in_quotes and ch == "/" and i + 1 < len(line) and line[i + 1] == "/":
                break
            result.append(ch)
            i += 1
        out_lines.append("".join(result))
    return "\n".join(out_lines)

KV_TOK_RE = re.compile(r'"[^"]*"|\[[^\]]*\]|[^\s{}"]+|{|}')

def _kv_add(d: dict, k: str, v):
    """Repeated block keys (several 'Clamp' proxies, ...) become a list of dicts."""
    if isinstance(v, dict) and k in d:
        old = d[k]
        if isinstance(old, list):
            old.append(v)
            return
        if isinstance(old, dict):
            d[k] = [old, v]
            return
    d[k] = v

def _parse_kv_block(tokens, i):
    d = {}
    n = len(tokens)
    while i < n:
        tok = tokens[i]
        if tok == "}":
            return d, i + 1
        if tok == "{":
            i += 1
            continue
        key = tok.strip('"').lower()
        if i + 1 >= n:
            break
        nxt = tokens[i + 1]
        if nxt == "{":
            sub, i = _parse_kv_block(tokens, i + 2)
            _kv_add(d, key, sub)
        elif nxt == "}":
            i += 1
        else:
            d[key] = nxt.strip('"')
            i += 2
    return d, i

def parse_kv_tree(text: str):
    tokens = KV_TOK_RE.findall(_strip_comments_keep_quotes(text))
    if not tokens:
        return "lightmappedgeneric", {}
    shader = tokens[0].strip('"').lower()
    if len(tokens) < 2 or tokens[1] != "{":
        return shader, {}
    tree, _ = _parse_kv_block(tokens, 2)
    return shader, tree

def _kv_merge(base: dict, over: dict) -> dict:
    out = dict(base)
    for k, v in over.items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = _kv_merge(out[k], v)
        else:
            out[k] = v
    return out

def _emit_kv_block(d: dict, level: int):
    pad = "\t" * level
    out = []
    for k, v in d.items():
        for item in (v if isinstance(v, list) else [v]):
            if isinstance(item, dict):
                out.append(f'{pad}"{k}"')
                out.append(f"{pad}{{")
                out.extend(_emit_kv_block(item, level + 1))
                out.append(f"{pad}}}")
            else:
                out.append(f'{pad}"{k}" "{item}"')
    return out

def _kv_tree_to_text(shader: str, tree: dict) -> str:
    return "\n".join([f'"{shader}"', "{", *_emit_kv_block(tree, 1), "}"]) + "\n"

@_cache_per_file_version(maxsize=100_000)
def read_text_safe(path_str: str) -> str:
    path = Path(path_str)
    try:
        return path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return path.read_text(errors="ignore")

def _resolve_vmt_tree(text: str, depth: int = 0):
    """Resolve patch VMTs (include + insert + replace) recursively through all Source1 roots."""
    shader, tree = parse_kv_tree(text)
    if shader != "patch" or depth > 8:
        return shader, tree, False
    inc = tree.get("include")
    if not isinstance(inc, str):
        return shader, tree, False
    rel = "materials/" + strip_materials_prefix(inc)
    if not rel.lower().endswith(".vmt"):
        rel += ".vmt"
    inc_abs, _ = find_in_source1(rel)
    if not inc_abs:
        return shader, tree, False
    base_shader, base_tree, _ = _resolve_vmt_tree(read_text_safe(inc_abs), depth + 1)
    merged = base_tree
    for name in ("insert", "replace"):
        blk = tree.get(name)
        if isinstance(blk, dict):
            merged = _kv_merge(merged, blk)
    return base_shader, merged, True

def _as_list(v):
    return v if isinstance(v, list) else ([v] if isinstance(v, dict) else [])

def _to_float(s, default=0.0):
    try:
        return float(str(s).strip())
    except Exception:
        return default

def _parse_vec3(v):
    """a .vmt vector ("[1 0.5 0]", "{255 128 0}") -> (x, y, z) as 0..1 floats, or None. {} braces hold 0..255 colour values"""
    if not isinstance(v, str):
        return None
    nums = re.findall(r"-?\d+(?:\.\d+)?(?:e-?\d+)?", v)
    if len(nums) < 3:
        return None
    x = [float(n) for n in nums[:3]]
    return tuple(c / 255.0 for c in x) if v.strip().startswith("{") else tuple(x)


def parse_envmaptint_scalar(s):
    if not s:
        return None
    s = str(s).strip().replace("[", "").replace("]", "").replace("{", "").replace("}", "")
    parts = [p for p in s.replace(",", " ").split() if p]
    try:
        return float(parts[0]) if parts else None
    except Exception:
        return None

def parse_vmt(vmt_path: Path):
    text = read_text_safe(str(vmt_path))
    shader, tree, resolved = _resolve_vmt_tree(text)
    shown_text = _kv_tree_to_text(shader, tree) if resolved else text

    flat = {k: v for k, v in tree.items() if isinstance(v, str)}
    for k, v in tree.items():           # >=dx9x blocks only fill in missing keys
        if isinstance(v, dict) and k.startswith(">=dx9"):
            for kk, vv in v.items():
                if isinstance(vv, str):
                    flat.setdefault(kk, vv)

    # "!gameconsole?$key" applies on PC; "gameconsole?$key" is console-only and ignored.
    for k, v in list(flat.items()):
        if k.startswith("!gameconsole?"):
            flat.setdefault(k[len("!gameconsole?"):], v)

    def is_true(key):
        return str(flat.get(key, "")).strip() == "1"

    def ref(key):
        return rel_norm(flat[key]) if flat.get(key) else None

    shader = shader.removeprefix("sdk_").removesuffix("_dx9").removesuffix("_hdr")
    data = {
        "shader": shader,
        "basetexture": ref("$basetexture"),
        "texture2": ref("$texture2"),
        "normalmap": ref("$normalmap") or ref("$bumpmap"),
        "surfaceprop": flat.get("$surfaceprop"),
        "translucent": is_true("$translucent"),
        "alphatest": is_true("$alphatest"),
        "additive": is_true("$additive"),
        "nocull": is_true("$nocull"),
        "ssbump": is_true("$ssbump"),
        "selfillum": is_true("$selfillum"),
        "selfillummask": ref("$selfillummask"),
        "selfillumtint": flat.get("$selfillumtint"),
        "alphatestreference": None,
        "envmapmask": ref("$envmapmask"),
        "phongmask": ref("$phongmask"),
        "envmap": flat.get("$envmap"),
        "envmaptint": flat.get("$envmaptint"),
        "normalmapalphaenvmapmask": is_true("$normalmapalphaenvmapmask"),
        "basealphaenvmapmask": is_true("$basealphaenvmapmask"),
        "detail": ref("$detail"),
        "detailscale": flat.get("$detailscale"),
        "detailblendfactor": flat.get("$detailblendfactor"),
        "detailblendmode": flat.get("$detailblendmode"),
        "fps": 15,
        "scrolls": [],
        "conveyor": None,
        "text": shown_text,
    }
    if flat.get("$alphatestreference"):
        v = _to_float(flat["$alphatestreference"], None)
        data["alphatestreference"] = v

    proxies = tree.get("proxies")
    if isinstance(proxies, dict):
        for blk in _as_list(proxies.get("texturescroll")):
            data["scrolls"].append((
                str(blk.get("texturescrollvar", "")).lower(),
                _to_float(blk.get("texturescrollrate", 0)),
                _to_float(blk.get("texturescrollangle", 0)),
            ))
        for blk in _as_list(proxies.get("conveyorscroll")):
            data["conveyor"] = str(blk.get("texturescrollvar", "")).lower()
        for blk in _as_list(proxies.get("animatedtexture")):
            if "animatedtextureframerate" in blk:
                data["fps"] = int(_to_float(blk["animatedtextureframerate"], 15))
    return data

# ======================================================================== VTF DECODING

def vtf_block_bytes(fmt):
    if fmt in (IMAGE_FORMAT_DXT1, IMAGE_FORMAT_DXT1_ONEBITALPHA):
        return 8
    if fmt in (IMAGE_FORMAT_DXT3, IMAGE_FORMAT_DXT5):
        return 16
    return 0

def vtf_bytes_per_pixel(fmt):
    if fmt in (IMAGE_FORMAT_BGRA8888, IMAGE_FORMAT_RGBA8888, IMAGE_FORMAT_ABGR8888,
               IMAGE_FORMAT_ARGB8888, IMAGE_FORMAT_BGRX8888):
        return 4
    if fmt in (IMAGE_FORMAT_RGB888, IMAGE_FORMAT_BGR888):
        return 3
    return 0

def mip_level_size(w, h, fmt):
    bb = vtf_block_bytes(fmt)
    if bb:
        return max(1, (w + 3) // 4) * max(1, (h + 3) // 4) * bb
    bpp = vtf_bytes_per_pixel(fmt)
    if not bpp:
        raise ValueError(f"Unsupported format for sizing: {fmt}")
    return w * h * bpp

def parse_vtf_header(vtf_path: Path):
    with open(vtf_path, "rb") as f:
        if f.read(4) != b"VTF\0":
            raise ValueError("Not a VTF file (missing signature).")
        ver_major, ver_minor = struct.unpack("<II", f.read(8))
        header_size = struct.unpack("<I", f.read(4))[0]
        width, height = struct.unpack("<HH", f.read(4))
        flags = struct.unpack("<I", f.read(4))[0]
        frames, start_frame = struct.unpack("<HH", f.read(4))
        f.read(4); f.read(12); f.read(4); f.read(4)
        image_format = struct.unpack("<I", f.read(4))[0]
        mip_count = struct.unpack("<B", f.read(1))[0]
        low_res_format = struct.unpack("<I", f.read(4))[0]
        low_res_w = struct.unpack("<B", f.read(1))[0]
        low_res_h = struct.unpack("<B", f.read(1))[0]
        depth = 1
        if ver_major == 7 and ver_minor >= 2:
            depth = struct.unpack("<H", f.read(2))[0]
    return {
        "ver": (ver_major, ver_minor), "header_size": header_size, "width": width, "height": height,
        "depth": max(1, depth), "flags": flags, "frames": max(1, frames), "start_frame": start_frame,
        "format": image_format, "mip_count": max(1, mip_count),
        "low_res_format": low_res_format, "low_res_w": low_res_w, "low_res_h": low_res_h,
    }

def parse_vtf_resources_if_any(vtf_path: Path, hdr):
    """VTF 7.3+: numResources @68, entries (3-byte tag, 1-byte flags, uint32 offset) from @80."""
    ver_major, ver_minor = hdr["ver"]
    if ver_major != 7 or ver_minor < 3:
        return {}
    with open(vtf_path, "rb") as f:
        blob = f.read(max(hdr["header_size"], 80))
    if len(blob) < 80:
        return {}
    num = struct.unpack_from("<I", blob, 68)[0]
    if num > 64 or 80 + num * 8 > len(blob):
        return {}
    file_size = vtf_path.stat().st_size
    out = {}
    for i in range(num):
        raw_tag, off = struct.unpack_from("<II", blob, 80 + i * 8)
        if (raw_tag >> 24) & 0x02:
            continue
        if off < file_size:
            out[raw_tag & 0x00FFFFFF] = off
    return out

def compute_image_data_offset(hdr, resources=None):
    resources = resources or {}
    if VTF_RSRC_IMAGE in resources:
        return resources[VTF_RSRC_IMAGE]
    lrf = hdr["low_res_format"]
    low = 0
    if lrf != 0xFFFFFFFF and hdr["low_res_w"] and hdr["low_res_h"]:
        try:
            low = mip_level_size(hdr["low_res_w"], hdr["low_res_h"], lrf)
        except Exception:
            low = 0
    return hdr["header_size"] + low

def compute_largest_mip_layout(vtf_path: Path, hdr):
    file_size = vtf_path.stat().st_size
    fmt, frames, depth = hdr["format"], hdr["frames"], hdr["depth"]
    start = compute_image_data_offset(hdr, parse_vtf_resources_if_any(vtf_path, hdr))
    w0, h0 = hdr["width"], hdr["height"]
    for faces in ((6 if hdr["flags"] & TEXTUREFLAGS_ENVMAP else 1), 1):
        for mips in range(hdr["mip_count"], 0, -1):
            try:
                # each mip's own size, smallest first: level L is max(1, w >> L) x max(1, h >> L). (Doubling up from the
                # smallest went wrong on non-square textures: 64 x 128 has 1x1, 1x2, 2x4 ... not 1x1, 2x2, 4x4 ..., so every
                # non-square VTF was read from the wrong offset: shifted sideways, fewer frames)
                sizes = [mip_level_size(max(1, w0 >> L), max(1, h0 >> L), fmt) for L in range(mips - 1, -1, -1)]
                base = start + sum(sizes[:-1]) * frames * faces * depth
                largest = sizes[-1]
                if base + largest <= file_size:
                    return base, largest, largest * faces * depth
            except Exception:
                continue
    w, h = w0, h0
    for _ in range(16):
        try:
            cand = mip_level_size(w, h, fmt)
        except Exception:
            break
        if start + cand <= file_size:
            return start, cand, cand
        w, h = max(1, w // 2), max(1, h // 2)
    raise ValueError("VTF image data offset/size does not fit file (corrupt or unsupported layout).")

def _rgb565(c):
    return (((c >> 11) & 0x1F) * 255 // 31, ((c >> 5) & 0x3F) * 255 // 63, (c & 0x1F) * 255 // 31)

def _color_palette(c0, c1, four_color_always):
    p0, p1 = _rgb565(c0), _rgb565(c1)
    if four_color_always or c0 > c1:
        p2 = tuple((2 * a + b) // 3 for a, b in zip(p0, p1))
        p3 = tuple((a + 2 * b) // 3 for a, b in zip(p0, p1))
        return [p0 + (255,), p1 + (255,), p2 + (255,), p3 + (255,)]
    p2 = tuple((a + b) // 2 for a, b in zip(p0, p1))
    return [p0 + (255,), p1 + (255,), p2 + (255,), (0, 0, 0, 0)]

def _dxt_np(data, w, h, kind, one_bit_alpha=False):
    """decode_dxt1 / 3 / 5 with numpy: the same bytes as the per-pixel loops below (same integer maths, a block the data ends before
    stays 0), about 100x faster. -> RGBA bytes, or None without numpy (the loops run instead)"""
    try:
        import numpy as np
    except ImportError:
        return None
    bs = 8 if kind == 1 else 16
    bw, bh = (w + 3) // 4, (h + 3) // 4
    n = bw * bh
    nb = min(n, len(data) // bs)
    a = np.frombuffer(bytes(data[:nb * bs]), np.uint8).reshape(nb, bs)
    co = bs - 8
    c = a[:, co:co + 4].astype(np.int32)
    c0, c1 = c[:, 0] | (c[:, 1] << 8), c[:, 2] | (c[:, 3] << 8)
    bits = a[:, co + 4:co + 8].astype(np.uint32)
    bits = bits[:, 0] | (bits[:, 1] << 8) | (bits[:, 2] << 16) | (bits[:, 3] << 24)

    def rgb(v):
        return np.stack([((v >> 11) & 0x1F) * 255 // 31, ((v >> 5) & 0x3F) * 255 // 63, (v & 0x1F) * 255 // 31], 1)
    p0, p1 = rgb(c0), rgb(c1)
    pal = np.zeros((nb, 4, 4), np.int32)
    pal[:, :, 3] = 255
    pal[:, 0, :3], pal[:, 1, :3] = p0, p1
    pal[:, 2, :3], pal[:, 3, :3] = (2 * p0 + p1) // 3, (p0 + 2 * p1) // 3
    if kind == 1:
        three = c0 <= c1
        pal[three, 2, :3] = ((p0 + p1) // 2)[three]
        pal[three, 3, :3] = 0
        if one_bit_alpha:
            pal[three, 3, 3] = 0
    sh = np.arange(16, dtype=np.uint32)
    rows = np.arange(nb)[:, None]
    pix = pal[rows, (bits[:, None] >> (2 * sh)) & 3]              # (nb, 16, 4)
    if kind == 3:
        av = a[:, 0:8].astype(np.uint64)
        av = sum(av[:, k] << np.uint64(8 * k) for k in range(8))
        pix[:, :, 3] = ((av[:, None] >> (4 * sh).astype(np.uint64)) & np.uint64(0xF)).astype(np.int32) * 255 // 15
    elif kind == 5:
        a0, a1 = a[:, 0].astype(np.int32), a[:, 1].astype(np.int32)
        ai = a[:, 2:8].astype(np.uint64)
        ai = sum(ai[:, k] << np.uint64(8 * k) for k in range(6))
        ap = np.zeros((nb, 8), np.int32)
        ap[:, 0], ap[:, 1] = a0, a1
        big = a0 > a1
        for i in range(1, 7):
            ap[:, i + 1] = ((7 - i) * a0 + i * a1) // 7
        for i in range(1, 5):
            ap[~big, i + 1] = (((5 - i) * a0 + i * a1) // 5)[~big]
        ap[~big, 6], ap[~big, 7] = 0, 255
        pix[:, :, 3] = ap[rows, ((ai[:, None] >> (3 * sh).astype(np.uint64)) & np.uint64(7)).astype(np.intp)]
    full = np.zeros((n, 16, 4), np.uint8)
    full[:nb] = pix
    return full.reshape(bh, bw, 4, 4, 4).transpose(0, 2, 1, 3, 4).reshape(bh * 4, bw * 4, 4)[:h, :w].tobytes()

def decode_dxt1(data, w, h, one_bit_alpha=False):
    fast = _dxt_np(data, w, h, 1, one_bit_alpha)
    if fast is not None:
        return fast
    out = bytearray(w * h * 4)
    pos = 0
    for by in range((h + 3) // 4):
        for bx in range((w + 3) // 4):
            if pos + 8 > len(data):
                return bytes(out)
            c0, c1 = struct.unpack_from("<HH", data, pos)
            bits = struct.unpack_from("<I", data, pos + 4)[0]
            pos += 8
            pal = _color_palette(c0, c1, False)
            if not one_bit_alpha:
                pal[3] = pal[3][:3] + (255,)       # Source treats plain DXT1 as opaque
            for py in range(4):
                for px in range(4):
                    x, y = bx * 4 + px, by * 4 + py
                    if x < w and y < h:
                        o = (y * w + x) * 4
                        out[o:o + 4] = bytes(pal[(bits >> (2 * (py * 4 + px))) & 3])
    return bytes(out)

def decode_dxt3(data, w, h):
    fast = _dxt_np(data, w, h, 3)
    if fast is not None:
        return fast
    out = bytearray(w * h * 4)
    pos = 0
    for by in range((h + 3) // 4):
        for bx in range((w + 3) // 4):
            if pos + 16 > len(data):
                return bytes(out)
            alpha_val = int.from_bytes(data[pos:pos + 8], "little")
            c0, c1 = struct.unpack_from("<HH", data, pos + 8)
            bits = struct.unpack_from("<I", data, pos + 12)[0]
            pos += 16
            pal = _color_palette(c0, c1, True)
            for py in range(4):
                for px in range(4):
                    x, y = bx * 4 + px, by * 4 + py
                    if x < w and y < h:
                        p = py * 4 + px
                        r, g, b, _ = pal[(bits >> (2 * p)) & 3]
                        o = (y * w + x) * 4
                        out[o:o + 4] = bytes((r, g, b, ((alpha_val >> (4 * p)) & 0xF) * 255 // 15))
    return bytes(out)

def decode_dxt5(data, w, h):
    fast = _dxt_np(data, w, h, 5)
    if fast is not None:
        return fast
    out = bytearray(w * h * 4)
    pos = 0
    for by in range((h + 3) // 4):
        for bx in range((w + 3) // 4):
            if pos + 16 > len(data):
                return bytes(out)
            a0, a1 = data[pos], data[pos + 1]
            alpha_idx = int.from_bytes(data[pos + 2:pos + 8], "little")
            c0, c1 = struct.unpack_from("<HH", data, pos + 8)
            bits = struct.unpack_from("<I", data, pos + 12)[0]
            pos += 16
            ap = [a0, a1]
            if a0 > a1:
                ap += [((7 - i) * a0 + i * a1) // 7 for i in range(1, 7)]
            else:
                ap += [((5 - i) * a0 + i * a1) // 5 for i in range(1, 5)] + [0, 255]
            pal = _color_palette(c0, c1, True)
            for py in range(4):
                for px in range(4):
                    x, y = bx * 4 + px, by * 4 + py
                    if x < w and y < h:
                        p = py * 4 + px
                        r, g, b, _ = pal[(bits >> (2 * p)) & 3]
                        o = (y * w + x) * 4
                        out[o:o + 4] = bytes((r, g, b, ap[(alpha_idx >> (3 * p)) & 7]))
    return bytes(out)

def decode_uncompressed_to_rgba(data, w, h, fmt):
    n = w * h
    if fmt == IMAGE_FORMAT_RGBA8888:
        return bytes(data[:n * 4])
    out = bytearray(n * 4)
    for i in range(n):
        if fmt == IMAGE_FORMAT_BGRA8888:
            b, g, r, a = data[i * 4:i * 4 + 4]
        elif fmt == IMAGE_FORMAT_ABGR8888:
            a, b, g, r = data[i * 4:i * 4 + 4]
        elif fmt == IMAGE_FORMAT_ARGB8888:
            a, r, g, b = data[i * 4:i * 4 + 4]
        elif fmt == IMAGE_FORMAT_BGRX8888:
            b, g, r, _x = data[i * 4:i * 4 + 4]
            a = 255
        elif fmt == IMAGE_FORMAT_BGR888:
            b, g, r = data[i * 3:i * 3 + 3]
            a = 255
        elif fmt == IMAGE_FORMAT_RGB888:
            r, g, b = data[i * 3:i * 3 + 3]
            a = 255
        else:
            raise ValueError(f"Unsupported uncompressed format: {fmt}")
        out[i * 4:i * 4 + 4] = bytes((r, g, b, a))
    return bytes(out)

def vtf_extract_frames_rgba(vtf_path: Path):
    hdr = parse_vtf_header(vtf_path)
    fmt = hdr["format"]
    if fmt not in SUPPORTED:
        raise ValueError(f"VTF format not supported by this script: {fmt}")
    base, largest, stride = compute_largest_mip_layout(vtf_path, hdr)
    w, h = hdr["width"], hdr["height"]
    file_size = vtf_path.stat().st_size
    frames = []
    with open(vtf_path, "rb") as f:
        for i in range(hdr["frames"]):
            off = base + i * stride
            if off + largest > file_size:
                break
            f.seek(off)
            chunk = f.read(largest)
            if len(chunk) != largest:
                break
            if fmt == IMAGE_FORMAT_DXT1:
                rgba = decode_dxt1(chunk, w, h, False)
            elif fmt == IMAGE_FORMAT_DXT1_ONEBITALPHA:
                rgba = decode_dxt1(chunk, w, h, True)
            elif fmt == IMAGE_FORMAT_DXT3:
                rgba = decode_dxt3(chunk, w, h)
            elif fmt == IMAGE_FORMAT_DXT5:
                rgba = decode_dxt5(chunk, w, h)
            else:
                rgba = decode_uncompressed_to_rgba(chunk, w, h, fmt)
            frames.append((w, h, rgba))
    if not frames:
        raise ValueError("Unexpected EOF reading image data.")
    return hdr, frames

@lru_cache(maxsize=16)
def vtf_extract_frames_rgba_cached(path_str: str):
    return vtf_extract_frames_rgba(Path(path_str))

# ======================================================================== IMAGES

def _next_pow2(x):
    p = 1
    while p < x:
        p <<= 1
    return p

def build_atlas(rgba_list, w, h, out_path: Path):
    count = len(rgba_list)
    cols = _next_pow2(math.ceil(math.sqrt(count)))
    rows = _next_pow2(math.ceil(count / cols))
    atlas = Image.new("RGBA", (cols * w, rows * h), (0, 0, 0, 0))
    for idx, rgba in enumerate(rgba_list):
        atlas.paste(Image.frombytes("RGBA", (w, h), rgba), ((idx % cols) * w, (idx // cols) * h))
    # cells past the last frame repeat the frames from the start (were left empty: transparent black). CS2's F_FLIPBOOK (lit shaders) has
    # no frame count and plays every cell of the grid, so an empty cell flashed blank / black once a cycle (comshieldwall: 31 frames in 32
    # cells); this way the loop only shows frame 0 twice. F_TEXTURE_ANIMATION (unlit) stops at g_nNumAnimationCells and never shows them
    for idx in range(count, cols * rows):
        atlas.paste(Image.frombytes("RGBA", (w, h), rgba_list[idx % count]), ((idx % cols) * w, (idx // cols) * h))
    out_path.parent.mkdir(parents=True, exist_ok=True)
    atlas.save(out_path)
    return rows, cols

def save_static(rgba, w, h, out_path: Path):
    out_path.parent.mkdir(parents=True, exist_ok=True)
    Image.frombytes("RGBA", (w, h), rgba).save(out_path)

def ssbump_to_normal_rgba(rgba, w, h):
    """$ssbump textures are self-shadowing bump maps: R, G, B are the light reaching the surface from the three Source1 radiosity
    basis directions, not a tangent-space normal (exported as one they average ~(122,123,116) instead of ~(128,128,255) and light
    wrongly). Rebuild an approximate normal: n = R*b0 + G*b1 + B*b2, normalised, with the Source1 basis (the same y orientation as
    Source1 normal maps, so legacy_source1_inverted_normal still applies). -> rgba bytes (alpha 255)."""
    r2, r6, r3 = math.sqrt(2.0 / 3.0), 1.0 / math.sqrt(6.0), 1.0 / math.sqrt(3.0)
    h2 = 1.0 / math.sqrt(2.0)
    try:
        import numpy as np
        a = np.frombuffer(rgba, dtype=np.uint8).reshape(h, w, 4)[:, :, :3].astype(np.float32) / 255.0
        bas = np.array([[r2, 0.0, r3], [-r6, h2, r3], [-r6, -h2, r3]], dtype=np.float32)
        n = a @ bas
        n /= np.maximum(np.linalg.norm(n, axis=2, keepdims=True), 1e-6)
        out = np.empty((h, w, 4), dtype=np.uint8)
        out[:, :, :3] = np.clip((n * 0.5 + 0.5) * 255.0 + 0.5, 0, 255).astype(np.uint8)
        out[:, :, 3] = 255
        return out.tobytes()
    except ImportError:
        pass
    out = bytearray(w * h * 4)
    for i in range(w * h):
        r, g, b = rgba[i * 4] / 255.0, rgba[i * 4 + 1] / 255.0, rgba[i * 4 + 2] / 255.0
        x, y, z = r * r2 - (g + b) * r6, (g - b) * h2, (r + g + b) * r3
        ln = math.sqrt(x * x + y * y + z * z) or 1.0
        o = i * 4
        out[o] = int((x / ln * 0.5 + 0.5) * 255.0 + 0.5)
        out[o + 1] = int((y / ln * 0.5 + 0.5) * 255.0 + 0.5)
        out[o + 2] = int((z / ln * 0.5 + 0.5) * 255.0 + 0.5)
        out[o + 3] = 255
    return bytes(out)

def save_png(rgba, w, h, out_path: Path):
    save_static(rgba, w, h, out_path)

def _extract_mask_from_rgba(rgba, w, h, channel="A", invert=True):
    img = Image.frombytes("RGBA", (w, h), rgba)
    if channel.upper() == "L":
        mask = img.convert("L")
    else:
        mask = img.getchannel({"R": 0, "G": 1, "B": 2, "A": 3}[channel.upper()])
    if invert:
        mask = mask.point(lambda v: 255 - v)
    return Image.merge("RGBA", (mask, mask, mask, Image.new("L", mask.size, 255))).tobytes()

def write_texture_settings_txt(texture_path: Path, settings: dict):
    lines = ['"settings"', '{']
    for k, v in settings.items():
        lines.append(f'\t"{k}"\t\t"{v}"')
    lines.append('}')
    texture_path.with_suffix(".txt").write_text("\n".join(lines) + "\n", encoding="utf-8")

def _tex_base(ref: str, suffix: str) -> str:
    """'Effects/Foo/bar' -> 'materials/effects/foo/bar<suffix>' (lower-case, suffix not doubled)."""
    t = strip_materials_prefix(ref).lower()
    if t.endswith(".vtf"):
        t = t[:-4]
    if _S2_RENAMED_RE.search(t):        # a name Valve's importer renames ('wall (10)' -> 'wall__10_', as it did the material): the same for its textures
        t = _s2_name_key(t)
    # '+' (CS:GO animated-texture frames: +0name) is a "fused delimiter" in resourcecompiler: files are written with '_' instead
    if t.endswith(suffix):
        return ("materials/" + t).replace("+", "_")
    return ("materials/" + t + suffix).replace("+", "_")

def _load_vtf_first_frame(ref: str):
    vtf = resolve_vtf(ref)
    if vtf is None:
        return None
    try:
        return vtf_extract_frames_rgba_cached(str(vtf))[1][0]
    except Exception:
        return None

class TextureMissing(Exception):
    pass

class RunState:
    """What the passes of one run share, in one place (main() starts every run with a fresh one): set by one pass, read by later ones
    and by the final report."""
    def __init__(self):
        self.addon_dir = None              # Path: the addon folder the converted materials / textures are written to
        self.overlay_vmats = set()         # lower-case 'materials/x.vmat' used by CMapStaticOverlay elements: written with the static overlay shader
        self.missing_textures = set()      # Source1 textures a converted material needs that were not found
        self.missing_texture_users = {}    # texture -> {vmat that needed it}
        self.stub_cs2_vmats = set()        # CS2 vmats that compile to the error shader (Valve shipped them without textures): re-ported from Source1
        self.exported_textures = {}        # export_color_texture results (each texture is exported once per run)


RUN = RunState()

def export_color_texture(export_dir: Path, ref: str, allow_anim: bool):
    """Decode a VTF into <ref>_color.tga (static) or <ref>_color.png (multi-frame atlas).
    Returns (rel_path, flipbook) where flipbook is None or (rows, cols, nframes)."""
    base = _tex_base(ref, "_color")
    key = (str(export_dir), base, allow_anim)
    if key in RUN.exported_textures:
        return RUN.exported_textures[key]
    vtf = resolve_vtf(ref)
    if vtf is None:
        raise TextureMissing(ref)
    _hdr, frames = vtf_extract_frames_rgba_cached(str(vtf))
    if allow_anim and len(frames) > 1:
        rel = base + ANIM_EXT
        w, h, _ = frames[0]
        rows, cols = build_atlas([r for (_, _, r) in frames], w, h, export_dir / rel)
        result = (rel, (rows, cols, len(frames)))
    else:
        rel = base + STATIC_EXT
        w, h, rgba = frames[0]
        save_static(rgba, w, h, export_dir / rel)
        result = (rel, None)
    RUN.exported_textures[key] = result
    return result

# ======================================================================== CS2 VPK INDEX

VPK_SIGNATURE = 0x55AA1234
VPK_READ_PREFIXES = ("soundevents/", "particles/entity/path_particle_cable")   # only these entries keep their data location (to read them
                                                                             # later): soundevents, ROPE_MATERIALS' source particle (left out
                                                                             # before 2026-11-24e: the rope pass always said "not found")

class Cs2Vpk:
    """Directory index of the CS2 *_dir.vpk files: which files exist (no extraction). Read-only."""
    def __init__(self):
        self.files = set()                 # lower-case 'dir/name.ext'
        self.dirs = {}                     # lower-case dir -> set of file names
        self.entries = {}                  # path -> (dir vpk path, archive idx, offset, length, preload bytes) for VPK_READ_PREFIXES
        self.loaded = []                   # [(vpk path, file count)]
        self.errors = []

    def add_dir_vpk(self, path: str):
        try:
            st = os.stat(path)
            # one cache for every map (it was in each map's own log folder: every new map re-read all of CS2's VPKs)
            cache = os.path.join(LOG_ROOT, ".vpkcache4_" + re.sub(r"[^A-Za-z0-9]+", "_", path)[-120:] + ".pkl")
            key = (path, st.st_size, int(st.st_mtime), VPK_READ_PREFIXES, 3)    # the read rules are part of the key: changing them rebuilds the index
            try:
                with open(cache, "rb") as f:
                    ckey, files, entries = pickle.load(f)
                if ckey == key:
                    self._merge(files, entries)
                    self.loaded.append((path, len(files)))
                    return
            except Exception:
                pass
            files, entries = self._parse(path)
            try:                               # atomic: two runs at once (two maps) share the file now
                _atomic_write(cache, pickle.dumps((key, files, entries), protocol=pickle.HIGHEST_PROTOCOL))
            except Exception:
                pass
            self._merge(files, entries)
            self.loaded.append((path, len(files)))
        except Exception as e:
            self.errors.append(f"{path}: {e}")

    def _merge(self, files, entries):
        for fp in files:
            self.files.add(fp)
            d, _, n = fp.rpartition("/")
            self.dirs.setdefault(d, set()).add(n)
        self.entries.update(entries)

    @staticmethod
    def _parse(path: str):
        files, entries = [], {}
        with open(path, "rb") as f:
            sig, ver, tree_size = struct.unpack("<III", f.read(12))
            if sig != VPK_SIGNATURE or ver not in (1, 2):
                raise ValueError(f"not a VPK v1/v2 file (signature {sig:#x}, version {ver})")
            header = 12 if ver == 1 else 28
            f.seek(header)
            tree = f.read(tree_size)
        data_start = header + tree_size
        n, find, unpack = len(tree), tree.find, struct.unpack_from
        pos = 0

        def cstr():
            nonlocal pos
            e = find(b"\0", pos)
            s = tree[pos:e].decode("utf-8", errors="replace")
            pos = e + 1
            return s

        while pos < n:
            ext = cstr()
            if not ext:
                break
            while True:
                d = cstr()
                if not d:
                    break
                while True:
                    name = cstr()
                    if not name:
                        break
                    _crc, preload, arch, offset, length, _term = unpack("<IHHIIH", tree, pos)
                    pos += 18
                    pre = tree[pos:pos + preload]
                    pos += preload
                    dd = "" if d == " " else d
                    fp = ((dd + "/") if dd else "") + ("" if name == " " else name) + ("" if ext == " " else "." + ext)
                    fp = fp.replace("\\", "/").lower()
                    files.append(fp)
                    if fp.startswith(VPK_READ_PREFIXES) or fp.endswith((".vmat_c", ".vmdl_c")) or (fp.startswith("materials/") and fp.endswith(".vtex_c")):
                        entries[fp] = (path, arch, (data_start + offset) if arch == 0x7FFF else offset, length, pre)
        return files, entries

    def has(self, rel: str) -> bool:
        return rel in self.files

    def listdir(self, rel_dir: str):
        return self.dirs.get(rel_dir.strip("/").lower(), set())

    def read(self, rel: str):
        ent = self.entries.get(rel.lower())
        if not ent:
            return None
        dir_path, arch, offset, length, pre = ent
        if length == 0:
            return pre
        fn = dir_path if arch == 0x7FFF else dir_path.replace("_dir.vpk", f"_{arch:03d}.vpk")
        try:
            with open(fn, "rb") as f:
                f.seek(offset)
                return pre + f.read(length)
        except Exception:
            return None

_CS2_VPK = None

def cs2_vpk() -> Cs2Vpk:
    global _CS2_VPK
    if _CS2_VPK is None:
        v = Cs2Vpk()
        if USE_CS2_VPK:
            for sub in CS2_VPK_FOLDERS:
                folder = os.path.join(CS2_GAME_DIR, sub)
                try:
                    names = sorted(x for x in os.listdir(folder)
                                   if x.lower().endswith("_dir.vpk") and not x.lower().startswith(CS2_VPK_SKIP_PREFIXES))
                except Exception:
                    continue
                for nm in names:
                    v.add_dir_vpk(os.path.join(folder, nm))
        _CS2_VPK = v
    return _CS2_VPK

def _cs2_roots():
    """the extracted CS2 folders that are set (CS2_VERIFY_FOLDER = None crashed; "" checked paths relative to the current folder)"""
    return [r for r in (CS2_VERIFY_FOLDER, *CS2_EXTRA_VERIFY_FOLDERS) if r]


def cs2_file_exists(rel: str) -> bool:
    """File present in the CS2 install: VPK index first, then the extracted folders."""
    rel = rel_norm(rel).lower()
    if cs2_vpk().has(rel):
        return True
    return any(file_exists(os.path.join(root, rel)) for root in _cs2_roots())


def compiled_resource_refs(data: bytes):
    """External references of a compiled Source 2 resource (its RERL block: textures of a vmat_c, materials of a vmdl_c ...), as
    lower-case paths without the _c. Falls back to scanning the bytes for resource-looking paths."""
    out = []
    try:
        _fsize, _hv, _ver, boff, bcount = struct.unpack_from("<IHHII", data, 0)
        p = 8 + boff
        for _ in range(min(bcount, 64)):
            typ = data[p:p + 4]
            off, size = struct.unpack_from("<II", data, p + 4)
            if typ == b"RERL" and size:
                start = p + 4 + off
                roff, cnt = struct.unpack_from("<II", data, start)
                q = start + roff
                for j in range(min(cnt, 100000)):
                    e = q + j * 16
                    noff = struct.unpack_from("<q", data, e + 8)[0]
                    a = e + 8 + noff
                    z = data.index(b"\0", a)
                    out.append(data[a:z].decode("utf-8", "replace").replace("\\", "/").lower())
                return out
            p += 12
    except Exception:
        out = []
    for mm in re.finditer(rb"[a-z0-9_\-./]+\.(?:vtex|vmat|vmdl)(?![a-z_])", data.lower()):
        out.append(mm.group(0).decode("ascii", "replace"))
    return sorted(set(out))


@lru_cache(maxsize=100_000)
def cs2_vmat_missing_textures(rel: str):
    """Textures a CS2 vmat_c (in the VPK) uses that are in none of the indexed VPKs: the material renders pink / black."""
    if not CS2_CHECK_ASSET_REFS:
        return ()
    data = cs2_vpk().read(rel_norm(rel).lower() + "_c")
    if not data:
        return ()
    return tuple(r for r in compiled_resource_refs(data) if r.endswith(".vtex") and not cs2_file_exists(r + "_c") and not cs2_file_exists(r))


@lru_cache(maxsize=100_000)
def cs2_vmat_is_stub(rel: str) -> bool:
    """True when CS2's compiled vmat (in the VPK) uses core/error.vfx (it was never ported properly and has no texture), or when
    textures it uses are missing from CS2 (CS2_CHECK_ASSET_REFS): referencing it in a map shows the error material / black, so it is
    ported from Source1 instead where a .vmt exists. Needs the VPK data to be readable; False otherwise."""
    data = cs2_vpk().read(rel_norm(rel).lower() + "_c")
    return bool(data) and (b"error.vfx" in data or bool(cs2_vmat_missing_textures(rel)))


@lru_cache(maxsize=100_000)
def cs2_vmdl_bad_materials(rel: str):
    """Materials a CS2 vmdl_c (in the VPK) uses that CS2 does not have (or has only as an error / texture-less stub): the model shows
    pink / black there. -> tuple of vmat paths"""
    if not CS2_CHECK_ASSET_REFS:
        return ()
    data = cs2_vpk().read(rel_norm(rel).lower() + "_c")
    if not data:
        return ()
    return tuple(r for r in compiled_resource_refs(data)
                 if r.endswith(".vmat") and (not cs2_file_exists(r + "_c") or cs2_vmat_is_stub(r)))

def cs2_listdir(rel_dir: str):
    """File names directly inside rel_dir across the VPKs and the extracted folders."""
    rel_dir = rel_norm(rel_dir).strip("/")
    names = set(cs2_vpk().listdir(rel_dir))
    for root in _cs2_roots():
        try:
            names.update(listdir_cached(os.path.join(root, rel_dir)))
        except Exception:
            pass
    return names

# ======================================================================== CS2 INSTALL LOOKUPS

def _hashed_color_vtex_name(folder_rel: str, base: str):
    base_low = base.lower()
    best_c, best = None, None
    for f in cs2_listdir(folder_rel):
        fl = f.lower()
        if not fl.startswith(base_low + "_color_tga_"):
            continue
        if fl.endswith(".vtex_c"):
            best_c = f
        elif fl.endswith(".vtex"):
            best = f
    return best_c or best

@lru_cache(maxsize=500_000)
def try_resolve_cs2_texture_for_vtf(asset_rel_vtf: str):
    """Texture already shipped in the CS2 install. -> (marker, rel path) or (None, None).
    The first value is only a truthy marker ('cs2:<rel>'); nothing is copied from the install."""
    asset_rel_vtf = normalize_candidate(asset_rel_vtf)
    base_no_ext = os.path.splitext(asset_rel_vtf)[0]
    folder_rel = os.path.dirname(base_no_ext)
    base = os.path.basename(base_no_ext)
    for rel in (base_no_ext + ".vtex_c", base_no_ext + ".vtex"):
        if cs2_file_exists(rel):
            return "cs2:" + rel, rel
    hashed = _hashed_color_vtex_name(folder_rel, base)
    if hashed:
        rel = rel_norm(os.path.join(folder_rel, hashed))
        return "cs2:" + rel, rel
    rel_color = rel_norm(os.path.join(folder_rel, base + "_color.tga"))
    if cs2_file_exists(rel_color):
        return "cs2:" + rel_color, rel_color
    return None, None

@lru_cache(maxsize=500_000)
def cs2_compiled_texture_exists(asset_rel: str) -> bool:
    """A source image (.tga/.png/...) counts as present when CS2 has its compiled .vtex_c
    (either '<name>.vtex_c' or '<name>_<ext>_<hash>.vtex_c')."""
    base_no_ext, ext = os.path.splitext(asset_rel)
    if cs2_file_exists(base_no_ext + ".vtex_c"):
        return True
    stem = os.path.basename(base_no_ext).lower()
    prefix = f"{stem}_{ext[1:].lower()}_"
    return any(f.lower().startswith(prefix) and f.lower().endswith(".vtex_c")
               for f in cs2_listdir(os.path.dirname(base_no_ext)))

# ======================================================================== VMAT WRITER

def comment_original_vmt(vmt_text: str) -> str:
    lines = vmt_text.splitlines()
    out = ["// =================== BEGIN ORIGINAL VMT (%d lines) ===================" % len(lines)]
    out.extend("// " + ln for ln in lines)
    out.append("// ==================== END ORIGINAL VMT ====================")
    return "\n".join(out)

def generate_vmat(
    vmat_path: Path, shader: str, texture_color_path: str, original_vmt_text: str,
    surfaceprop=None, alphatest=False, translucent=False, additive=False, selfillum=False,
    alphatestreference=None, texture_normal_path=None, texture_roughness_path=None,
    texture_detail_path=None, detail_scale=None, detail_blend_factor=None, detail_blend_mode=None,
    flipbook=None, specular_indirect=False, cubemap_scalar=None, roughness_scalar=None,
    texture2_path=None, tex2_scroll=None, texture_translucency_path=None, nocull=False,
    selfillum_mask_path=None, selfillum_tint=None, base_scroll=None,
):
    shader_name = SHADER_MAP.get((shader or "").lower().strip(), "csgo_vertexlitgeneric.vfx")
    if selfillum and selfillum_mask_path and shader_name == "csgo_lightmappedgeneric.vfx":
        # SELFILLUM_MASKS: CS2's self-illumination (F_SELF_ILLUM with TextureSelfIllumMask) on csgo_complex, which draws world faces too;
        # csgo_lightmappedgeneric with F_SELF_ILLUM alone drew mg_divine's lava (bob/lavabob) red and see-through
        shader_name = "csgo_complex.vfx"
        texture_detail_path = None
    # Additive: only csgo_unlitgeneric has a confirmed additive switch (F_BLEND_MODE 4); a saved
    # vertexlit vmat dropped F_ADDITIVE_BLEND (no such option) and rendered opaque/black.
    if additive and shader_name != "csgo_unlitgeneric.vfx":
        shader_name = "csgo_unlitgeneric.vfx"
        texture2_path = None
    if base_scroll and shader_name in ("csgo_lightmappedgeneric.vfx", "csgo_vertexlitgeneric.vfx", "csgo_complex.vfx"):
        # TEXTURE_SCROLL: the scroll only worked on csgo_unlitgeneric in the CS2 test (waterfall_scrolltest_unlit on mg_divine; the same
        # DynamicParams on csgo_complex and csgo_lightmappedgeneric stayed still), so a scrolling material becomes unlit (not lit by the map)
        shader_name = "csgo_unlitgeneric.vfx"
        texture_detail_path = texture_normal_path = texture_roughness_path = None
        selfillum = False
    if flipbook and ANIMATED_UNLIT and shader_name in ("csgo_lightmappedgeneric.vfx", "csgo_vertexlitgeneric.vfx", "csgo_complex.vfx"):
        # ANIMATED_UNLIT: F_FLIPBOOK on csgo_lightmappedgeneric did not play in CS2 (mario_party's animated_trim_mario stayed on one
        # frame and its Material Editor showed no animation); csgo_unlitgeneric's F_TEXTURE_ANIMATION plays (mg_divine's mclava), so an
        # animated lit material becomes unlit, as a scrolling one does (TEXTURE_SCROLL)
        shader_name = "csgo_unlitgeneric.vfx"
        texture_detail_path = texture_normal_path = texture_roughness_path = None
        selfillum = False
    is_lightmapped = shader_name == "csgo_lightmappedgeneric.vfx"
    is_unlit = shader_name == "csgo_unlitgeneric.vfx"

    L = ['"Layer0"', "{", f'    "Shader" "{shader_name}"']

    def rough_line(key):
        if texture_roughness_path:
            L.append(f'    "{key}" "{texture_roughness_path}"')
        elif roughness_scalar is not None:
            L.append(f'    "{key}" "[{roughness_scalar:.6f} {roughness_scalar:.6f} {roughness_scalar:.6f} 1.000000]"')

    if is_lightmapped:
        L.append(f'    "TextureLayer1Color" "{texture_color_path}"')
        if texture_normal_path:
            L.append(f'    "TextureLayer1Normal" "{texture_normal_path}"')
        rough_line("TextureLayer1Roughness")
        if texture_translucency_path:
            L.append(f'    "TextureLayer1Translucency" "{texture_translucency_path}"')
        L += [f'    "TextureLayer1AmbientOcclusion" "{DEFAULT_AO}"',
              '    "F_LAYERS" "0"',
              '    "g_vLayer1Tint" "[1.000000 1.000000 1.000000]"',
              '    "F_TEXTURETRANSFORMS" "0"']
        if texture_detail_path:
            L.append(f'    "TextureLayer1Detail" "{texture_detail_path}"')
            if detail_scale is not None:
                L.append(f'    "g_vLayer1DetailScale" "[{detail_scale:.6f} {detail_scale:.6f}]"')
            bf = 1.0 if detail_blend_factor is None else detail_blend_factor
            L.append(f'    "g_vLayer1DetailTintAndBlend" "[1.000000 1.000000 1.000000 {bf:.6f}]"')
            L.append('    "F_DETAILTEXTURE" "1"')
            L.append(f'    "F_DETAILBLENDMODE" "{detail_blend_mode if detail_blend_mode is not None else 0}"')
    elif is_unlit:
        L.append(f'    "TextureColor" "{texture_color_path}"')
        if texture_translucency_path:
            L.append(f'    "TextureTranslucency" "{texture_translucency_path}"')
        if texture2_path:
            L += ['    "F_TWOTEXTURE" "1"', f'    "Texture2Color" "{texture2_path}"']
    else:
        L.append(f'    "TextureColor" "{texture_color_path}"')
        if texture_normal_path:
            L.append(f'    "TextureNormal" "{texture_normal_path}"')
        rough_line("TextureRoughness")
        if texture_translucency_path:
            L.append(f'    "TextureTranslucency" "{texture_translucency_path}"')

    if not is_unlit:
        if specular_indirect:
            L.append('    "F_SPECULAR_INDIRECT" "1"')
        if cubemap_scalar is not None:
            L.append(f'    "g_flCubeMapScalar" "{cubemap_scalar:.6f}"')

    # Unlit shader: single F_BLEND_MODE dropdown (confirmed from a saved vmat: 4 = Additive;
    # vertexlit confirmed F_TRANSLUCENT and F_ALPHA_TEST (no additive option);
    # other numbers assumed from dropdown order). Lightmapped/vertexlit shaders: separate flags;
    # F_TRANSLUCENT confirmed from a saved vmat; F_ALPHA_TEST name unconfirmed.
    if is_unlit:
        if additive:
            L.append(f'    "F_BLEND_MODE" "{BLEND_MODE_ADDITIVE}"')
        elif alphatest:
            L.append(f'    "F_BLEND_MODE" "{BLEND_MODE_ALPHATEST}"')
        elif translucent:
            L.append(f'    "F_BLEND_MODE" "{BLEND_MODE_TRANSLUCENT}"')
    else:
        # additive materials never reach here: they are moved to the unlit shader (no confirmed additive flag on the lit shaders)
        if alphatest:
            L.append('    "F_ALPHA_TEST" "1"')
        elif translucent:
            L.append('    "F_TRANSLUCENT" "1"')
    if nocull:
        L.append('    "F_RENDER_BACKFACES" "1"')   # confirmed on unlit, vertexlit and lightmapped
        if not is_unlit and NOCULL_DONT_FLIP_NORMALS:
            L.append('    "F_DONT_FLIP_BACKFACE_NORMALS" "1"')   # vertexlit/lightmapped only
    if selfillum and selfillum_mask_path and not is_unlit:
        L += ['    "F_SELF_ILLUM" "1"', f'    "TextureSelfIllumMask" "{selfillum_mask_path}"',
              '    "g_flSelfIllumScale" "1.000"', f'    "g_flSelfIllumBrightness" "{SELFILLUM_BRIGHTNESS:.3f}"', '    "g_flSelfIllumAlbedoFactor" "1.000"']
        if selfillum_tint:
            L.append(f'    "g_vSelfIllumTint" "[{selfillum_tint[0]:.6f} {selfillum_tint[1]:.6f} {selfillum_tint[2]:.6f} 0.000000]"')
    elif selfillum and not (SELFILLUM_MASKS and not is_unlit):
        L.append('    "F_SELF_ILLUM" "1"')
    if alphatest and alphatestreference is not None:
        L.append(f'    "g_flAlphaTestReference" "{float(alphatestreference):.6f}"')

    if flipbook:
        rows, cols, fps, nframes = flipbook
        if is_unlit:
            tpf = (1.0 / fps) if fps and fps > 0 else 0.1
            L += ['    "F_TEXTURE_ANIMATION" "1"',
                  f'    "g_vAnimationGrid" "[{cols} {rows}]"',
                  f'    "g_nNumAnimationCells" "{nframes}"',
                  f'    "g_flAnimationTimePerFrame" "{tpf:.3f}"']
        else:
            L += ['    "F_FLIPBOOK" "1"',
                  f'    "g_vFlipbookGrid" "[{cols} {rows}]"',
                  f'    "g_flFlipbookFrameRate" "{fps}"']

    dyn = []
    if base_scroll and is_unlit and base_scroll[0] == "conveyor":
        # CONVEYOR_SCROLL: CS:GO's CConveyorMaterialProxy: U offset = curtime x -speed / 128 (V: none)
        sp_ = float(base_scroll[1])
        if CONVEYOR_SCROLL_FOLLOWS_SPEED:
            dyn.append('        "g_vTexCoordOffset" "frac( float2( ( exists( csgo_conveyor_speed ) ? csgo_conveyor_speed.x : '
                       f'{sp_:.3f} ) * -0.0078125, 0.0 ) * time() )"')
        else:
            dyn.append(f'        "g_vTexCoordOffset" "frac( float2( {-sp_ / 128.0 + 0.0:.6f}, 0.000 ) * time() )"')
    elif base_scroll and is_unlit:
        dx, dy = (round(v, 3) + 0.0 for v in base_scroll)      # (+ 0.0: no "-0.000")
        dyn.append(f'        "g_vTexCoordOffset" "frac( float2( {dx:.3f}, {dy:.3f} ) * time() )"')
    if tex2_scroll and texture2_path and is_unlit:
        dx, dy = tex2_scroll
        dyn.append(f'        "g_vTex2CoordOffset" "frac( float2( {dx:.3f}, {dy:.3f} ) * time() )"')
    if dyn:
        L += ['    "DynamicParams"', "    {"] + dyn + ["    }"]

    if surfaceprop:
        L += ['    "SystemAttributes"', "    {",
              f'        "PhysicsSurfaceProperties" "{surfaceprop}"', "    }"]
    L.append("}")

    vmat = "\n".join(L)
    if original_vmt_text:
        vmat += "\n\n" + comment_original_vmt(original_vmt_text) + "\n"
    vmat_path.parent.mkdir(parents=True, exist_ok=True)
    vmat_path.write_text(vmat, encoding="utf-8")

# ======================================================================== VMT -> VMAT

def generate_overlay_vmat(vmat_path: Path, texture_color_path: str, mask_path, original_vmt_text: str):
    """Static overlays (CMapStaticOverlay: Source1 infodecal / info_overlay) need csgo_static_overlay.vfx. Layout copied
    from a working port of the same kind of material: translucent blend (F_BLEND_MODE 1), lit, alpha as a
    TextureTranslucency mask. Without the mask the overlay is drawn as an opaque rectangle (or not at all)."""
    L = ['"Layer0"', "{", '    "Shader" "csgo_static_overlay.vfx"',
         '    "F_BLEND_MODE" "1"', '    "F_LIT" "1"',
         '    "g_vColorTint" "[1.000000 1.000000 1.000000 0.000000]"',
         f'    "TextureColor" "{texture_color_path}"']
    if mask_path:
        L += ['    "g_flOpacityScale" "1.000"', f'    "TextureTranslucency" "{mask_path}"']
    L += ['    "TextureNormal" "materials/default/default_normal.tga"',
          '    "TextureRoughness" "materials/default/default_rough.tga"',
          '    "TextureMetalness" "materials/default/default_metal.tga"', "}"]
    vmat = "\n".join(L)
    if original_vmt_text:
        vmat += "\n\n" + comment_original_vmt(original_vmt_text) + "\n"
    vmat_path.parent.mkdir(parents=True, exist_ok=True)
    vmat_path.write_text(vmat, encoding="utf-8")

def static_overlay_materials(vmap_paths) -> set:
    out = set()
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
            if b"encoding binary" not in data[:100]:
                continue
            els = read_binary_dmx(data)
        except Exception:
            continue
        for e in els:
            mv = e["attrs"].get("materials")
            if mv and isinstance(mv[2], list):
                # this script's overlay quads (<material>_quad.vmat, made from the overlay's own material by convert_entity_overlays): on a
                # map that already went through the script the overlay is a quad now, and its material must still be written with the static
                # overlay shader (the quad material is rebuilt from it; as a plain lightmapped material it has no TextureColor)
                for mat in mv[2]:
                    if isinstance(mat, str) and mat.lower().endswith("_quad.vmat"):
                        out.add(mat.replace("\\", "/").lower()[:-len("_quad.vmat")] + ".vmat")
            if e["type"] != "CMapStaticOverlay":
                continue
            md = e["attrs"].get("meshData")
            if md and isinstance(md[2], int) and 0 <= md[2] < len(els):
                mv = els[md[2]]["attrs"].get("materials")
                for mat in (mv[2] if mv else []):
                    out.add(mat.replace("\\", "/").lower())
    return out

def convert_one_vmt(export_dir: Path, vmt_abs: str, vmat_rel: str):
    vmt_path = Path(vmt_abs)
    try:
        data = parse_vmt(vmt_path)
    except Exception as e:
        return False, f"VMT parse failed: {vmt_path} :: {e}"
    if data["shader"] in UNSUPPORTED_SHADERS or (data["shader"] in ("eyes", "teeth") and not EYES_TEETH_AS_VERTEXLIT):
        return False, f"UNSUPPORTED_SHADER:{data['shader']} :: {vmt_path}"
    if not data["basetexture"] and "water" in vmat_rel.lower():
        return False, f"UNSUPPORTED_SHADER:water(by path, shader={data['shader']}) :: {vmt_path}"
    if not data["basetexture"]:
        return False, f"VMT has no $basetexture: {vmt_path}"

    vmat_out = export_dir / normalize_candidate(vmat_rel)
    is_overlay = normalize_candidate(vmat_rel).replace("\\", "/").lower() in RUN.overlay_vmats
    shader = data["shader"]
    shader_name = SHADER_MAP.get(shader, "csgo_vertexlitgeneric.vfx")
    # vertexlit has no additive option (a saved vmat dropped F_ADDITIVE_BLEND), so additive
    # materials go on the unlit shader, whose F_BLEND_MODE 4 = Additive is confirmed.
    if data["additive"] and shader_name != "csgo_unlitgeneric.vfx":
        shader = "unlitgeneric"
        shader_name = SHADER_MAP.get(shader, "csgo_unlitgeneric.vfx")
    is_unlit = shader_name == "csgo_unlitgeneric.vfx"
    env_is_cubemap = bool(data.get("envmap") and str(data["envmap"]).lower() == "env_cubemap") and not is_unlit
    cube_scalar = parse_envmaptint_scalar(data.get("envmaptint")) if env_is_cubemap else None

    additive_flag = data["additive"]
    if shader == "sprite" and SPRITE_DEFAULT_ADDITIVE and not (data["additive"] or data["translucent"] or data["alphatest"]):
        additive_flag = True
    common = dict(
        surfaceprop=data["surfaceprop"], alphatest=data["alphatest"], translucent=data["translucent"],
        additive=additive_flag, nocull=data["nocull"], selfillum=data["selfillum"], alphatestreference=data["alphatestreference"],
    )

    # ---- base colour texture
    # ANIM_ONLY_BY_PROXY: Source1 plays a multi-frame texture by time only through an AnimatedTexture proxy on $basetexture; otherwise
    # it shows $frame (0, or what another proxy sets: comshieldwall's frame follows the player's distance, which CS2 materials cannot
    # do). Played by time those textures flicker through their frames and sample the sheet's empty cells (invisible / black), so they
    # get their first frame, as Source1 shows them with no proxy
    _by_time = (not ANIM_ONLY_BY_PROXY) or bool(re.search(r'animatedtexturevar"?\s+"?\$basetexture\b', data.get("text", "") or "", flags=re.I))
    try:
        color_rel, anim = export_color_texture(export_dir, data["basetexture"], _by_time)
    except TextureMissing:
        # not in any Source1 root: maybe the texture already ships with CS2
        want = normalize_candidate("materials/" + strip_materials_prefix(data["basetexture"]) + ".vtf")
        p2, rel2 = try_resolve_cs2_texture_for_vtf(want)
        if p2:
            tex_ref = rel2[:-2] if rel2.lower().endswith(".vtex_c") else rel2   # never reference .vtex_c
            if is_overlay:
                generate_overlay_vmat(vmat_out, tex_ref, None, data["text"])
                return True, str(vmat_out)
            generate_vmat(vmat_out, shader, tex_ref, data["text"], specular_indirect=env_is_cubemap,
                          cubemap_scalar=cube_scalar, roughness_scalar=0.8 if env_is_cubemap else None, **common)
            return True, str(vmat_out)
        if data["basetexture"].replace("\\", "/").lower().lstrip("/").startswith("_rt_"):
            # a render target (_rt_Camera: the screen of a func_monitor / point_camera, e.g. dev/dev_tvmonitornonoise): CS2 has none of these
            return False, (f"OBSOLETE: render-target material ($basetexture {data['basetexture']}, a camera / monitor screen): CS2 has no such render target; "
                           + ("its references point at CS2's black material instead (RENDER_TARGET_BLACK, black_materials log)" if RENDER_TARGET_BLACK and cs2_black_material()
                              else "flagged and left as is"))
        RUN.missing_textures.add(normalize_source1_vtf_dep(data["basetexture"]))
        RUN.missing_texture_users.setdefault(normalize_source1_vtf_dep(data["basetexture"]), set()).add(vmat_rel)
        return False, f"VTF missing for basetexture: {data['basetexture']}"
    except Exception as e:
        return False, f"VTF decode failed: {data['basetexture']} :: {e}"

    if is_overlay:
        mask_rel = None
        try:
            tw, th, trgba = vtf_extract_frames_rgba_cached(str(resolve_vtf(data["basetexture"])))[1][0]
            alpha = Image.frombytes("RGBA", (tw, th), trgba).getchannel(3)
            if alpha.getextrema()[0] < 255:
                mask_rel = _tex_base(data["basetexture"], "_trans") + ".tga"
                (export_dir / mask_rel).parent.mkdir(parents=True, exist_ok=True)
                alpha.convert("RGB").save(export_dir / mask_rel)
        except Exception:
            mask_rel = None
        resized = []
        for _rel in (color_rel, mask_rel):          # static overlays can fail to draw when a texture side is not a power of two
            if not _rel:
                continue
            try:
                _p = export_dir / _rel
                _im = Image.open(_p)
                _w, _h = _im.size
                _nw, _nh = (1 << (_w - 1).bit_length()), (1 << (_h - 1).bit_length())
                if (_nw, _nh) != (_w, _h):
                    _im.load()
                    _im.resize((_nw, _nh), Image.LANCZOS).save(_p)
                    resized.append(f"{_w}x{_h}->{_nw}x{_nh}")
            except Exception:
                pass
        generate_overlay_vmat(vmat_out, color_rel, mask_rel, data["text"])
        return True, str(vmat_out) + ("" if mask_rel else " (overlay: texture has no alpha, no mask written)") \
            + (f" (overlay textures resized to a power of two: {', '.join(resized)})" if resized else "")

    flipbook = (anim[0], anim[1], data["fps"], anim[2]) if anim else None

    # ---- second texture + scroll (UnlitTwoTexture)
    tex2_rel, tex2_scroll = None, None
    if is_unlit and data["texture2"] and shader == "unlittwotexture":
        try:
            tex2_rel, _ = export_color_texture(export_dir, data["texture2"], False)
            for var, rate, angle in data["scrolls"]:
                if var == "$texture2transform":
                    a = math.radians(angle)
                    tex2_scroll = (rate * math.cos(a), rate * math.sin(a))
        except TextureMissing:
            RUN.missing_textures.add(normalize_source1_vtf_dep(data["texture2"]))
            RUN.missing_texture_users.setdefault(normalize_source1_vtf_dep(data["texture2"]), set()).add(vmat_rel)
        except Exception:
            tex2_rel = None

    # ---- base texture scroll (TEXTURE_SCROLL; generate_vmat makes the material csgo_unlitgeneric for it)
    base_scroll = None
    if _CONVEYOR_BUILD[0] is not None:       # CONVEYOR_SCROLL: this is a func_conveyor copy of the material (conveyor_scroll_materials)
        base_scroll = ("conveyor", _CONVEYOR_BUILD[0])
    elif TEXTURE_SCROLL:
        for var, rate, angle in data["scrolls"]:
            if var == "$basetexturetransform" and rate:
                a = math.radians(angle)
                base_scroll = (rate * math.cos(a), rate * math.sin(a))

    # ---- normal map
    normal_rel, normal_frame = None, None
    if data["normalmap"] and not is_unlit:
        normal_frame = _load_vtf_first_frame(data["normalmap"])
        if normal_frame is not None:
            try:
                nw, nh, nrgba = normal_frame
                normal_rel = _tex_base(data["normalmap"], "_normal") + ".tga"
                if data.get("ssbump"):
                    nrgba = ssbump_to_normal_rgba(nrgba, nw, nh)
                save_static(nrgba, nw, nh, export_dir / normal_rel)
                write_texture_settings_txt(export_dir / normal_rel, {"legacy_source1_inverted_normal": "1"})
            except Exception:
                normal_rel = None

    # ---- roughness: separate mask textures use RGB luminance, flagged alpha uses alpha
    rough_rel, roughness_scalar = None, None
    mask_frame, mask_ref, mask_channel = None, None, "L"
    if not is_unlit:
        if data["envmapmask"] or data["phongmask"]:
            mask_ref = data["envmapmask"] or data["phongmask"]
            mask_frame = _load_vtf_first_frame(mask_ref)
        elif data["normalmapalphaenvmapmask"] and normal_frame is not None:
            mask_ref, mask_frame, mask_channel = data["normalmap"], normal_frame, "A"
        elif data["basealphaenvmapmask"]:
            try:
                mask_frame = vtf_extract_frames_rgba_cached(str(resolve_vtf(data["basetexture"])))[1][0]
                mask_ref, mask_channel = data["basetexture"], "A"
            except Exception:
                mask_frame = None
    if mask_frame is not None and mask_ref:
        try:
            rw, rh, rrgba = mask_frame
            rough_rel = _tex_base(mask_ref, "_rough") + ".tga"
            save_static(_extract_mask_from_rgba(rrgba, rw, rh, mask_channel, True), rw, rh, export_dir / rough_rel)
        except Exception:
            rough_rel = None
    if env_is_cubemap and not rough_rel:
        roughness_scalar = 0.8

    # ---- detail texture
    detail_rel = detail_scale = detail_bf = detail_bm = None
    if data["detail"] and not is_unlit:
        dframe = _load_vtf_first_frame(data["detail"])
        if dframe is not None:
            try:
                dw, dh, drgba = dframe
                detail_rel = _tex_base(data["detail"], "_color") + ".tga"
                save_static(drgba, dw, dh, export_dir / detail_rel)
                detail_scale = _to_float(data["detailscale"], None) if data["detailscale"] is not None else None
                detail_bf = _to_float(data["detailblendfactor"], None) if data["detailblendfactor"] is not None else None
                v = _to_float(data["detailblendmode"], None) if data["detailblendmode"] is not None else None
                detail_bm = int(v) if v is not None else None
            except Exception:
                detail_rel = detail_scale = detail_bf = detail_bm = None

    # ---- separate translucency texture (lightmapped: TextureLayer1Translucency, others TextureTranslucency). Every shader ignores the
    #      colour texture's own alpha, so without this mask an alpha-tested / translucent material draws its background
    trans_rel = None
    if not data["additive"] and (data["translucent"] or data["alphatest"]) and not anim:     # unlit too: confirmed in game (cattails drew their background until the mask was set)
        try:
            tw, th, trgba = vtf_extract_frames_rgba_cached(str(resolve_vtf(data["basetexture"])))[1][0]
            alpha = Image.frombytes("RGBA", (tw, th), trgba).getchannel(3)
            if alpha.getextrema()[0] < 255:
                trans_rel = _tex_base(data["basetexture"], "_trans") + ".tga"
                (export_dir / trans_rel).parent.mkdir(parents=True, exist_ok=True)
                alpha.convert("RGB").save(export_dir / trans_rel)
        except Exception:
            trans_rel = None

    # ---- self-illumination mask (SELFILLUM_MASKS): $selfillummask, else the base texture's alpha (Source1's mask when the alpha is not
    #      used for see-through or the envmap mask), else all of it. A mask with nothing lit in it: no self-illumination
    si_rel, si_tint = None, None
    if SELFILLUM_MASKS and data["selfillum"] and not is_unlit:
        try:
            if data.get("selfillummask"):
                fr = _load_vtf_first_frame(data["selfillummask"])
                mask = Image.frombytes("RGBA", fr[:2], fr[2]).convert("L") if fr else None
                src = data["selfillummask"]
            else:
                fw, fh, frgba = vtf_extract_frames_rgba_cached(str(resolve_vtf(data["basetexture"])))[1][0]
                img = Image.frombytes("RGBA", (fw, fh), frgba)
                use_alpha = not (data["translucent"] or data["alphatest"] or data["basealphaenvmapmask"])
                mask = img.getchannel(3) if use_alpha else Image.new("L", (fw, fh), 255)
                src = data["basetexture"]
            if mask is not None and mask.getextrema()[1] > 8:
                si_rel = _tex_base(src, "_selfillum") + ".tga"
                (export_dir / si_rel).parent.mkdir(parents=True, exist_ok=True)
                mask.convert("RGB").save(export_dir / si_rel)
                tv = _parse_vec3(data.get("selfillumtint")) if data.get("selfillumtint") else None
                si_tint = tv if tv and any(abs(x - 1.0) > 1e-3 for x in tv) else None
        except Exception:
            si_rel = None

    generate_vmat(
        vmat_out, shader, color_rel, data["text"], texture_translucency_path=trans_rel,
        selfillum_mask_path=si_rel, selfillum_tint=si_tint,
        texture_normal_path=normal_rel, texture_roughness_path=rough_rel,
        texture_detail_path=detail_rel, detail_scale=detail_scale,
        detail_blend_factor=detail_bf, detail_blend_mode=detail_bm,
        flipbook=flipbook, specular_indirect=env_is_cubemap, cubemap_scalar=cube_scalar,
        roughness_scalar=roughness_scalar, texture2_path=tex2_rel, tex2_scroll=tex2_scroll, base_scroll=base_scroll, **common,
    )
    return True, str(vmat_out)

SE_BEGIN = "\t// ===== BEGIN events generated by vmap_convert_merged (replaced on every run) ====="
SE_END = "\t// ===== END events generated by vmap_convert_merged ====="
SE_HEADER = ('<!-- kv3 encoding:text:version{e21c7f3c-8a33-41c5-9977-a76d3a32aa0d} '
             'format:generic:version{7412167c-06e9-4698-aff2-e63eb59037e7} -->')

def _kv3_scan(text: str):
    """Brace/bracket balance of a KV3 text file, ignoring // and /* */ comments and "strings".
    -> (brace_depth_at_eof, bracket_depth_at_eof, index of the '}' that closes the root block or -1)"""
    depth = br = 0
    root_close = -1
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c == "<" and text.startswith("<!--", i):          # kv3 header line contains braces
            j = text.find("-->", i + 4)
            i = n if j < 0 else j + 3
            continue
        if c == "/" and text.startswith("//", i):
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if c == "/" and text.startswith("/*", i):
            j = text.find("*/", i + 2)
            i = n if j < 0 else j + 2
            continue
        if c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 2 if text[j] == "\\" else 1
            i = j + 1
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0 and root_close < 0:
                root_close = i
        elif c == "[":
            br += 1
        elif c == "]":
            br -= 1
        i += 1
    return depth, br, root_close

EVENT_TOKEN_RE = re.compile(rb'[A-Za-z0-9_\-]+(?:\.[A-Za-z0-9_\-]+)+')

def event_names_to_sounds(export_dir: Path, vmap_paths, sound_events: dict, loop_names: set, sound_report: list):
    """Entities already renamed to a path-derived event name ('mysounds.mh_blade_loop1') no longer contain the
    .vsnd path, so re-derive the sound from the name itself: dots -> folders, then look for
    sound/<path>.wav|mp3 in the Source1 roots. Same result as the first run, nothing stale is carried over.
    -> list of (event name, status) for the log"""
    known = {k.lower() for k in sound_events}
    index = load_soundscripts()
    seen, rows = set(), []
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
        except Exception:
            continue
        for m in EVENT_TOKEN_RE.finditer(data):
            tok = m.group(0).decode("ascii", errors="ignore")
            low = tok.lower()
            if low in seen or low in known or low in index:
                continue
            seen.add(low)
            name = tok[len(SOUNDEVENT_PREFIX):] if SOUNDEVENT_PREFIX and tok.startswith(SOUNDEVENT_PREFIX) else tok
            rest = name.replace(".", "/").lower()
            found = None
            for e in (".wav", ".mp3"):
                p, _r = find_in_source1("sound/" + rest + e)
                if p:
                    found = p
                    break
            if not found:
                continue
            dest_rel = "sounds/" + rest + os.path.splitext(found)[1].lower()
            place_sound(export_dir, found, dest_rel, sound_report)
            sound_events[tok] = "sounds/" + rest + ".vsnd"
            if is_looping_sound(found):
                loop_names.add(tok)
            rows.append((tok, f"re-derived from Source1 sound/{rest}{os.path.splitext(found)[1].lower()}"))
    return rows

def read_generated_events(export_dir: Path) -> dict:
    """Events from our own BEGIN/END block in the addon's soundevents file (previous runs).
    -> {name: ([vsnd files], volume text or None, had_base_line)}"""
    f = export_dir / "soundevents" / "soundevents_addon.vsndevts"
    try:
        txt = f.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return {}
    m = re.search(re.escape(SE_BEGIN.strip()) + r"(.*?)" + re.escape(SE_END.strip()), txt, flags=re.S)
    if not m:
        return {}
    out = {}
    for em in re.finditer(r'^[ \t]*"([^"]+)"[ \t]*=\s*\{(.*?)^[ \t]*\}', m.group(1), flags=re.S | re.M):
        body = em.group(2)
        files = re.findall(r'"(sounds/[^"]+\.vsnd)"', body)
        vol = re.search(r"volume\s*=\s*([0-9.]+)", body)
        if files:
            out[em.group(1)] = (files, vol.group(1) if vol else None, bool(re.search(r'^\s*base\s*=', body, flags=re.M)))
    return out

def sound_ranges(vmap_paths, sound_events: dict, vols: dict = None, levels: dict = None):
    """ambient_generic entities in the .vmap files -> {event name: audible radius}. radius keyvalue (default 1250);
    spawnflag 1 'Play everywhere' = SOUND_EVERYWHERE_RADIUS. An event used by several entities gets the largest."""
    by_key = {}
    for name, v in sound_events.items():
        by_key[name.lower()] = name
        for f in (v[0] if isinstance(v, tuple) else [v]):
            by_key.setdefault(f.lower(), name)
    out = {}
    for vp in vmap_paths:
        ents, _err = vmap_entities(str(vp))
        for e in ents:
            if e["cls"].lower() != "ambient_generic":
                continue
            p = {k.lower(): v for k, v in e["props"].items()}
            msg = (p.get("message") or "").strip().replace("\\", "/").lstrip(_WAVE_PREFIX_CHARS).lower()
            if not msg:
                continue
            name = by_key.get(msg)
            if not name:
                base, ext = os.path.splitext(msg)
                if ext in (".vsnd", ".wav", ".mp3"):
                    key = (base if base.startswith("sounds/") else "sounds/" + base.removeprefix("sound/")) + ".vsnd"
                    name = by_key.get(key)
            if not name:
                continue
            try:
                flags = int(float(p.get("spawnflags", "0") or 0))
            except ValueError:
                flags = 0
            if os.path.splitext(msg)[1] not in (".wav", ".mp3", ".vsnd") and levels is not None and (load_soundscripts() or True) \
                    and msg in _SS_LEVEL:
                # message is a soundscript name: Source1 ignores the entity's radius and Volume ("soundscripts ignore this
                # entity's settings"); the script's own soundlevel and volume apply
                load_soundscripts()
                if not (flags & 1):
                    levels[name] = max(levels.get(name, 0), _SS_LEVEL.get(msg, 75))
                continue
            try:
                _rv = str(p.get("radius", "")).strip()
                rad = SOUND_DEFAULT_RADIUS if _rv == "" else float(_rv)
                if rad <= 0:
                    rad = SOUND_EVERYWHERE_RADIUS      # Source1: radius 0 -> no attenuation (plays everywhere)
            except ValueError:
                rad = SOUND_DEFAULT_RADIUS
            if flags & 1:
                rad = SOUND_EVERYWHERE_RADIUS
            if rad < SOUND_EVERYWHERE_RADIUS:
                rad = max(rad * SOUND_RANGE_SCALE, SOUND_RANGE_MIN)
            out[name] = max(out.get(name, 0.0), rad)
            if vols is not None:        # Source1 ambient_generic: the "Volume (0-10)" keyvalue is stored as health; volume = health / 10 (default 10)
                try:
                    _hv = str(p.get("health", "")).strip()
                    vols[name] = max(vols.get(name, 0.0), min(max(float(_hv), 0.0), 10.0) / 10.0 if _hv != "" else 1.0)
                except ValueError:
                    vols[name] = max(vols.get(name, 0.0), 1.0)
    return out

def _source1_soundlevel(radius: float) -> int:
    """ambient_generic (Source SDK sound.cpp, ComputeSoundlevel): dB = 40 + 20*log10(radius / 36), truncated to an int."""
    return int(40 + 20 * math.log10(radius / 36.0))

def _source1_gain_level(level: int, dist: float) -> float:
    """Gain at a distance for a sound of this sound level in dB (engine: snd_refdb 60, snd_refdist 36)."""
    dist_mult = (10 ** ((60 - level) / 20.0)) / 36.0
    rel = dist * dist_mult
    gain = 1.0 if rel <= 1.0 else 1.0 / rel
    gmin = SOUND_SOURCE1_GAIN_MIN
    if gain < gmin:
        gain = max(0.0, gmin * (2.0 - rel * gmin))
    return gain

def _source1_curve_points_level(level: int):
    """(distance, gain) points for a sound level; the distance unit is the point where gain starts to fall (36 x 10^((dB-60)/20))."""
    d1 = 36.0 * 10 ** ((level - 60) / 20.0)
    mult = [0.0, 1.0, 2.0, 3.5, 5.0, 7.5, 10.0, 15.0, 20.0, 30.0, 50.0, 75.0, 100.0]
    pts = [(m * d1, _source1_gain_level(level, m * d1)) for m in mult]
    pts.append((200.0 * d1, 0.0))
    return pts

def _source1_gain(radius: float, dist: float) -> float:
    """Gain Source1 gives an ambient_generic with this radius at this distance (engine: snd_refdb 60, snd_refdist 36):
    dist_mult = 10^((60 - dB)/20) / 36; relative = dist * dist_mult; gain = 1/relative (never above 1);
    below snd_gain_min the gain drops to 0 over the same distance again."""
    dist_mult = (10 ** ((60 - _source1_soundlevel(radius)) / 20.0)) / 36.0
    rel = dist * dist_mult
    gain = 1.0 if rel <= 1.0 else 1.0 / rel
    gmin = SOUND_SOURCE1_GAIN_MIN
    if gain < gmin:
        gain = max(0.0, gmin * (2.0 - rel * gmin))
    return gain

def _source1_curve_points(radius: float):
    """(distance, gain) points following the Source1 model out to where it reaches 0 (~20 x radius)."""
    mult = [0.0, 0.1, 0.2, 0.35, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 5.0, 7.5, 10.0]
    pts = [(m * radius, _source1_gain(radius, m * radius)) for m in mult]
    pts.append((20.0 * radius, 0.0))
    return pts

def _curve_points_lines(prop: str, pts):
    out = [f'\t\t{prop} = ', '\t\t[']
    for x, y in pts:
        out += ['\t\t\t[', f'\t\t\t\t{x:.1f}, {y:.4f}, 0.0, 0.0,', '\t\t\t\t2.0, 3.0,', '\t\t\t],']
    out.append('\t\t]')
    return out

def _curve_lines(prop: str, radius: float, end_vol: float):
    return [f'\t\t{prop} = ', '\t\t[',
            '\t\t\t[', '\t\t\t\t0.0, 1.0, 0.0, 0.0,', '\t\t\t\t2.0, 3.0,', '\t\t\t],',
            '\t\t\t[', f'\t\t\t\t{radius:.1f}, {end_vol:.1f}, 0.0, 0.0,', '\t\t\t\t2.0, 3.0,', '\t\t\t],',
            '\t\t]']

def write_soundevents(export_dir: Path, events: dict, log_copy: str, loop_names=(), ranges=None, vols=None, levels=None):
    """Merge one csgo_mega soundevent per converted sound into soundevents/soundevents_addon.vsndevts
    (Valve's addon template layout: quoted names, vsnd_files_track_01). An existing file is kept; our
    block between the BEGIN/END markers is replaced on each run. Names already defined elsewhere in the
    file are skipped. The block goes just before the root block's closing brace; if the file has no
    closing brace it is added, and if the braces are otherwise unbalanced nothing is written.
    Looping needs cue markers in the .wav."""
    dest = export_dir / "soundevents" / "soundevents_addon.vsndevts"
    old = dest.read_text(encoding="utf-8-sig", errors="replace") if dest.exists() else None   # -sig: drop a BOM
    if old is not None:
        # The engine only treats the file as KeyValues3 when '<!-- kv3 ...' is the very first thing in it. A BOM, blank
        # lines before it, CRLF line endings or a different/duplicated header make it fall back to the old KeyValues
        # parser ("is not a KeyValues3 file and will be converted" + "expected '{', found '='" errors).
        old = old.replace("\r\n", "\n").replace("\r", "\n")
        old = re.sub(r"[ \t]*<!--\s*kv3[^>]*?-->[ \t]*\n?", "", old, flags=re.I)
        old = SE_HEADER + "\n" + old.lstrip()
    existing = set()
    if old is not None:
        outside = re.sub(re.escape(SE_BEGIN.strip()) + r".*?" + re.escape(SE_END.strip()), "", old, flags=re.S)
        existing = set(re.findall(r'^\s*"([^"]+)"\s*=', outside, flags=re.M))
    block, skipped = [SE_BEGIN], []
    use_base = bool(LOOP_EVENT_BASE) and LOOP_EVENT_BASE in existing   # an undefined base makes the whole file fail to compile
    if LOOP_EVENT_BASE and not use_base and loop_names:
        print(f'NOTE: "{LOOP_EVENT_BASE}" is not defined in {dest.name}; looping events keep type csgo_mega without a base. '
              f'Copy that event from Valve\'s template soundevents file into yours to use it.')
    for name, vsnd in sorted(events.items()):
        if name in existing:
            skipped.append(name)
            continue
        files, vol = (vsnd if isinstance(vsnd, tuple) else ([vsnd], None))
        try:
            _v = float(vol) if vol is not None and 0 < float(vol) <= 1 else 1.0
        except ValueError:
            _v = 1.0
        if vols and name in vols:                  # ambient_generic Volume (health / 10); several entities on one event: the loudest
            _v *= vols[name]
        vol_txt = f"{_v:.3f}" if _v != 1.0 else "1.0"
        if use_base and name in loop_names:
            block += [f'\t"{name}" =', '\t{', f'\t\tbase = "{LOOP_EVENT_BASE}"', f'\t\tvolume = {vol_txt}']
        else:
            block += [f'\t"{name}" =', '\t{', '\t\ttype = "csgo_mega"', f'\t\tvolume = {vol_txt}', '\t\tpitch = 1.0', '\t\tmixgroup = "Amb_Common"']
        if len(files) == 1:
            block.append(f'\t\tvsnd_files_track_01 = "{files[0]}"')
        else:
            block += ['\t\tvsnd_files_track_01 = ', '\t\t[']
            block += [f'\t\t\t"{f}",' for f in files]
            block.append('\t\t]')
        if SOUND_RANGE_CURVES and SOUND_SOURCE1_FALLOFF and levels and name in levels and not (ranges and name in ranges):
            block += _curve_points_lines("distance_volume_mapping_curve", _source1_curve_points_level(levels[name]))
        elif SOUND_RANGE_CURVES and ranges and name in ranges:
            if SOUND_SOURCE1_FALLOFF and ranges[name] < SOUND_EVERYWHERE_RADIUS and ranges[name] > 0:
                block += _curve_points_lines("distance_volume_mapping_curve", _source1_curve_points(ranges[name]))
            else:
                block += _curve_lines("distance_volume_mapping_curve", ranges[name], 1.0 if ranges[name] >= SOUND_EVERYWHERE_RADIUS else 0.0)
            block += _curve_lines("distance_unfiltered_stereo_mapping_curve", ranges[name], 1.0 if ranges[name] >= SOUND_EVERYWHERE_RADIUS else 0.0)
        block += ['\t}', '']
    block.append(SE_END)
    block_text = "\n".join(block) + "\n"
    Path(log_copy).write_text(block_text, encoding="utf-8")
    if old is None:
        text = SE_HEADER + "\n{\n\n" + block_text + "\n}\n"
    else:
        cleaned = re.sub(r"[ \t]*" + re.escape(SE_BEGIN.strip()) + r".*?" + re.escape(SE_END.strip()) + r"\n?",
                         "", old, flags=re.S)
        depth, br, root_close = _kv3_scan(cleaned)
        if br != 0 or depth not in (0, 1):
            print(f"WARNING: {dest} has unbalanced braces/brackets (braces {depth:+d}, brackets {br:+d}); "
                  f"left untouched. Fix it, or paste the events from {log_copy}.")
            return
        if depth == 1:       # root block never closed: append our block and the missing '}'
            print(f"NOTE: {dest} had no closing '}}' for the root block; added one.")
            text = cleaned.rstrip() + "\n\n" + block_text + "\n}\n"
        else:
            text = cleaned[:root_close].rstrip() + "\n\n" + block_text + "\n" + cleaned[root_close:]
        d2, b2, _ = _kv3_scan(text)
        if d2 != 0 or b2 != 0:
            print(f"WARNING: merged {dest.name} would be unbalanced ({d2:+d}, {b2:+d}); not written. Events are in {log_copy}")
            return
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(text.encode("utf-8"))                       # no BOM, LF endings
    if not dest.read_bytes().startswith(b"<!-- kv3 "):
        print(f"WARNING: {dest} does not start with the KV3 header; the tools will not compile it.")
    print(f"Soundevents: {len(events) - len(skipped)} written to {dest}"
          + (f" ({len(skipped)} already defined elsewhere, skipped)" if skipped else ""))

def normalize_source1_vtf_dep(ref: str) -> str:
    return normalize_candidate("materials/" + strip_materials_prefix(ref) + ".vtf")

# ----- explicit .vtex requests (kept from the old pipeline)

def write_simple_vtex(vtex_path: Path, input_image_rel: str, output_format: str = "DXT5", linear: bool = False):
    input_image_rel = input_image_rel.replace("\\", "/")
    cs = "linear" if linear else "srgb"
    dmx = (
        '<!-- dmx encoding keyvalues2_noids 1 format vtex 1 -->\n"CDmeVtex"\n{\n'
        '    "m_inputTextureArray" "element_array"\n    [\n        "CDmeInputTexture"\n        {\n'
        '            "m_name" "string" "0"\n'
        f'            "m_fileName" "string" "{input_image_rel}"\n'
        f'            "m_colorSpace" "string" "{cs}"\n            "m_typeString" "string" "2D"\n'
        '            "m_imageProcessorArray" "element_array"\n            [\n            ]\n        }\n    ]\n'
        '    "m_outputTypeString" "string" "2D"\n'
        f'    "m_outputFormat" "string" "{output_format}"\n'
        '    "m_textureOutputChannelArray" "element_array"\n    [\n        "CDmeTextureOutputChannel"\n        {\n'
        '            "m_inputTextureArray" "string_array" [ "0" ]\n'
        '            "m_srcChannels" "string" "rgba"\n            "m_dstChannels" "string" "rgba"\n'
        '            "m_mipAlgorithm" "CDmeImageProcessor"\n            {\n'
        '                "m_algorithm" "string" ""\n                "m_stringArg" "string" ""\n'
        '                "m_vFloat4Arg" "vector4" "0 0 0 0"\n            }\n'
        f'            "m_outputColorSpace" "string" "{cs}"\n'
        '        }\n    ]\n}\n'
    )
    vtex_path.parent.mkdir(parents=True, exist_ok=True)
    vtex_path.write_text(dmx, encoding="utf-8")

def convert_one_vtf_to_vtex(export_dir: Path, vtf_abs: str, vtex_rel: str):
    vtex_rel = normalize_candidate(vtex_rel)
    out_vtex_path = export_dir / vtex_rel
    stem = Path(vtex_rel).stem
    out_img_path = out_vtex_path.parent / f"{stem}{ANIM_EXT}"
    out_img_rel = normalize_candidate(str(Path(vtex_rel).parent).replace("\\", "/") + f"/{stem}{ANIM_EXT}")
    try:
        _hdr, frames = vtf_extract_frames_rgba_cached(vtf_abs)
    except Exception as e:
        return False, f"VTF decode failed: {vtf_abs} :: {e}"
    if len(frames) > 1:
        w, h, _ = frames[0]
        build_atlas([r for (_, _, r) in frames], w, h, out_img_path)
    else:
        w, h, rgba = frames[0]
        save_png(rgba, w, h, out_img_path)
    write_simple_vtex(out_vtex_path, out_img_rel)
    return True, str(out_vtex_path)

# ======================================================================== SOUND HELPERS

def wav_loop_info(path: str):
    """-> (cue_points, smpl_loops) read from a RIFF/WAVE file; (0, 0) if none or not a wav."""
    cues = loops = 0
    try:
        with open(path, "rb") as f:
            if f.read(4) != b"RIFF":
                return 0, 0
            f.read(4)
            if f.read(4) != b"WAVE":
                return 0, 0
            while True:
                hdr = f.read(8)
                if len(hdr) < 8:
                    break
                cid, size = hdr[:4], struct.unpack("<I", hdr[4:])[0]
                body = f.read(min(size, 64)) if cid in (b"cue ", b"smpl") else b""
                if cid == b"cue " and len(body) >= 4:
                    cues = struct.unpack("<I", body[:4])[0]
                elif cid == b"smpl" and len(body) >= 36:
                    loops = struct.unpack("<I", body[28:32])[0]
                f.seek(size - len(body) + (size & 1), 1)
    except Exception:
        pass
    return cues, loops

def is_looping_sound(path: str) -> bool:
    low = os.path.basename(path).lower()
    if any(h in low for h in LOOP_NAME_HINTS):
        return True
    c, l = wav_loop_info(path)
    return (c + l) > 0

def wav_format_info(path: str):
    """-> (format tag, channels, sample rate, bits) from the fmt chunk, or None if not a readable RIFF/WAVE.
    tag 1 = PCM, 2 = MS ADPCM, 3 = float, 17 = IMA ADPCM, 0xFFFE = extensible."""
    try:
        with open(path, "rb") as f:
            if f.read(4) != b"RIFF":
                return None
            f.read(4)
            if f.read(4) != b"WAVE":
                return None
            while True:
                hdr = f.read(8)
                if len(hdr) < 8:
                    return None
                cid, size = hdr[:4], struct.unpack("<I", hdr[4:])[0]
                if cid == b"fmt " and size >= 16:
                    tag, ch, rate, _br, _ba, bits = struct.unpack("<HHIIHH", f.read(16))
                    if tag == 0xFFFE and size >= 26:
                        f.read(8)
                        tag = struct.unpack("<H", f.read(2))[0]
                    return tag, ch, rate, bits
                f.seek(size + (size & 1), 1)
    except Exception:
        return None

def _wav_raw_chunks(path: str, wanted=(b"cue ", b"smpl")):
    out = []
    with open(path, "rb") as f:
        f.read(12)
        while True:
            hdr = f.read(8)
            if len(hdr) < 8:
                break
            cid, size = hdr[:4], struct.unpack("<I", hdr[4:])[0]
            body = f.read(size)
            if size & 1:
                f.read(1)
            if cid in wanted:
                out.append(hdr + body + (b"\0" if size & 1 else b""))
    return out

def _wav_pcm16_pure(src: str, info) -> bytes:
    """8/24/32-bit integer PCM and 32/64-bit float -> 16-bit PCM bytes, no third-party modules (ADPCM still needs miniaudio)."""
    import array
    tag, _ch, _rate, bits = info
    data = None
    with open(src, "rb") as f:
        f.read(12)
        while True:
            hdr = f.read(8)
            if len(hdr) < 8:
                break
            cid, size = hdr[:4], struct.unpack("<I", hdr[4:])[0]
            if cid == b"data":
                data = f.read(size)
                break
            f.seek(size + (size & 1), 1)
    if data is None:
        raise ValueError("no data chunk")
    if tag == 1 and bits == 8:
        out = array.array("h", [(b - 128) << 8 for b in data])
    elif tag == 1 and bits == 24:
        n = len(data) // 3
        out = array.array("h", [struct.unpack_from("<h", data, 3 * i + 1)[0] for i in range(n)])
    elif tag == 1 and bits == 32:
        n = len(data) // 4
        out = array.array("h", [struct.unpack_from("<h", data, 4 * i + 2)[0] for i in range(n)])
    elif tag == 3 and bits in (32, 64):
        fl = array.array("f" if bits == 32 else "d")
        fl.frombytes(data[: len(data) // (bits // 8) * (bits // 8)])
        out = array.array("h", [max(-32768, min(32767, int(round(v * 32767.0)))) for v in fl])
    else:
        raise ValueError(f"cannot convert tag {tag} / {bits}-bit without miniaudio")
    if sys.byteorder == "big":
        out.byteswap()
    return out.tobytes()

def wav_to_pcm16(src: str, dst: str, info):
    import wave
    _tag, ch, rate, _bits = info
    try:
        import miniaudio
        dec = miniaudio.decode_file(src, output_format=miniaudio.SampleFormat.SIGNED16, nchannels=ch, sample_rate=rate)
        pcm, n_ch, sr = dec.samples.tobytes(), dec.nchannels, dec.sample_rate
    except ImportError:
        pcm, n_ch, sr = _wav_pcm16_pure(src, info), ch, rate     # miniaudio not installed: 8/24/32-bit and float still convert
    Path(dst).parent.mkdir(parents=True, exist_ok=True)
    with wave.open(dst, "wb") as w:
        w.setnchannels(n_ch)
        w.setsampwidth(2)
        w.setframerate(sr)
        w.writeframes(pcm)
    extra = _wav_raw_chunks(src)
    if extra:
        with open(dst, "r+b") as f:
            f.seek(0, 2)
            for c in extra:
                f.write(c)
            end = f.tell()
            f.seek(4)
            f.write(struct.pack("<I", end - 8))

def mp3_to_wav(src: str, dst: str, add_cue: bool):
    import miniaudio, wave
    dec = miniaudio.decode_file(src, output_format=miniaudio.SampleFormat.SIGNED16)
    Path(dst).parent.mkdir(parents=True, exist_ok=True)
    with wave.open(dst, "wb") as w:
        w.setnchannels(dec.nchannels)
        w.setsampwidth(2)
        w.setframerate(dec.sample_rate)
        w.writeframes(dec.samples.tobytes())
    if add_cue:   # one cue point at sample 0, appended after the data chunk
        cue = struct.pack("<4sII", b"cue ", 4 + 24, 1) + struct.pack("<II4sIII", 1, 0, b"data", 0, 0, 0)
        with open(dst, "r+b") as f:
            f.seek(0, 2)
            f.write(cue)
            end = f.tell()
            f.seek(4)
            f.write(struct.pack("<I", end - 8))

def place_sound(export_dir: Path, found: str, dest_rel: str, report: list):
    """Copy (or convert) one Source1 sound. -> (final dest_rel, copied_new: bool)"""
    ext = os.path.splitext(found)[1].lower()
    looping = is_looping_sound(found)
    cues, loops = wav_loop_info(found) if ext == ".wav" else (0, 0)
    action = "copied"
    final_rel = dest_rel
    if ext == ".mp3" and ((looping and CONVERT_LOOP_MP3_TO_WAV) or CONVERT_ALL_MP3_TO_WAV):
        final_rel = os.path.splitext(dest_rel)[0] + ".wav"
        dst = export_dir / rel_norm(final_rel)
        if dst.exists():
            action = "converted (already present)"
        else:
            try:
                mp3_to_wav(found, str(dst), looping and ADD_LOOP_CUE_TO_CONVERTED)
                action = "mp3 -> wav" + (" + cue@0" if looping and ADD_LOOP_CUE_TO_CONVERTED else "")
            except Exception as e:
                final_rel, action = dest_rel, f"copied as mp3 (convert failed: {e}; pip install miniaudio?)"
    note = ""
    finfo = wav_format_info(found) if ext == ".wav" else None
    if finfo:
        note = f"fmt={finfo[0]} ch={finfo[1]} {finfo[2]}Hz {finfo[3]}bit; "
        if CONVERT_NONPCM_WAV and (finfo[0] != 1 or finfo[3] != 16):
            try:
                wav_to_pcm16(found, str(export_dir / rel_norm(final_rel)), finfo)
                report.append(f"{final_rel}\tsrc={os.path.basename(found)}\tloop={'yes' if looping else 'no'}\tcues={cues}\tsmpl_loops={loops}\twav -> pcm16\t{note}")
                return final_rel, True
            except Exception as e:
                note += f"pcm16 convert failed: {e}; "
    if looping and ext == ".mp3" and final_rel.endswith(".mp3"):
        note += "LOOP SOUND IS MP3: will play once"
    elif looping and ext == ".wav" and not (cues or loops):
        note += "looping by name but wav has no cue/loop points"
    report.append(f"{final_rel}\tsrc={os.path.basename(found)}\tloop={'yes' if looping else 'no'}\tcues={cues}\tsmpl_loops={loops}\t{action}\t{note}")
    if final_rel == dest_rel:
        return final_rel, copy_asset_to_export(export_dir, found, final_rel)
    return final_rel, action.startswith("mp3")

# ======================================================================== SOURCE1 SOUNDSCRIPTS

SOUNDSCRIPT_NAME_RE = re.compile(rb'[A-Za-z][A-Za-z0-9_]{0,63}(?:\.[A-Za-z0-9_]{1,63})+')
_WAVE_PREFIX_CHARS = "*#@><^)(}$!?~`"

_SS_LEVEL = {}      # lower soundscript name -> its soundlevel in dB (filled by parse_soundscript_text)
_SNDLVL_NAMES = {"SNDLVL_NONE": 0, "SNDLVL_IDLE": 60, "SNDLVL_TALKING": 60, "SNDLVL_STATIC": 66, "SNDLVL_NORM": 75, "SNDLVL_GUNFIRE": 140}

def _parse_sndlvl(txt: str):
    t = txt.strip().strip('"').upper()
    if t in _SNDLVL_NAMES:
        return _SNDLVL_NAMES[t]
    m = re.fullmatch(r"SNDLVL_(\d+)DB", t)
    if m:
        return int(m.group(1))
    try:
        return int(float(t))
    except ValueError:
        return None

def parse_soundscript_text(text: str) -> dict:
    """game_sounds*.txt -> {lower name: (Name, [wave paths], volume or None)} (all waves, incl. rndwave).
    Also records each script's soundlevel in _SS_LEVEL."""
    toks = KV_TOK_RE.findall(_strip_comments_keep_quotes(text))
    out, i, n = {}, 0, len(toks)
    while i < n:
        t = toks[i]
        if i + 1 < n and toks[i + 1] == "{" and t not in ("{", "}"):
            name = t.strip('"')
            depth, j, waves, vol = 1, i + 2, [], None
            while j < n and depth > 0:
                x = toks[j]
                if x == "{":
                    depth += 1
                elif x == "}":
                    depth -= 1
                else:
                    k = x.strip('"').lower()
                    if j + 1 < n and toks[j + 1] not in ("{", "}"):
                        if k == "wave":
                            waves.append(toks[j + 1].strip('"'))
                            j += 1
                        elif k == "volume" and vol is None:
                            vol = toks[j + 1].strip('"')
                            j += 1
                        elif k == "soundlevel" and name.lower() not in _SS_LEVEL:
                            _lv = _parse_sndlvl(toks[j + 1])
                            if _lv is not None:
                                _SS_LEVEL[name.lower()] = _lv
                            j += 1
                j += 1
            out[name.lower()] = (name, waves, vol)
            i = j
        else:
            i += 1
    return out

@lru_cache(maxsize=1)
def load_soundscapes() -> dict:
    """Every soundscape in the Source1 roots' scripts/soundscapes_*.txt / .vsc (the manifest lists them; any such file found counts, the map
    root's first, first definition wins). -> {lower name: (block dict, defining file)}"""
    index = {}
    for root in SOURCE1_ROOTS:
        sdir = find_ci(Path(root), "scripts")
        if sdir is None or not sdir.is_dir():
            continue
        try:
            files = sorted(f for f in os.listdir(sdir) if f.lower().startswith("soundscapes_") and f.lower().endswith((".txt", ".vsc"))
                           and not f.lower().startswith("soundscapes_manifest"))
        except Exception:
            continue
        for f in files:
            try:
                toks = KV_TOK_RE.findall(_strip_comments_keep_quotes(Path(sdir, f).read_text(encoding="utf-8", errors="ignore")))
                tree, _ = _parse_kv_block(toks, 0)
            except Exception:
                continue
            for k, v in tree.items():
                for blk in (v if isinstance(v, list) else [v]):
                    if isinstance(blk, dict):
                        index.setdefault(k, (blk, f"{os.path.basename(root)}/scripts/{f}"))
    return index


def convert_soundscapes(export_dir: Path, vmap_paths, sound_events: dict, loop_names: set, sound_report: list, everywhere: set):
    """CS2 has env_soundscape / env_soundscape_triggerable / trigger_soundscape but none of CS:GO's soundscape scripts, so a map's own
    soundscapes (mg_harero's music: one playlooping .mp3 each) play nothing. Each soundscape an env_soundscape* uses -> a looping soundevent
    soundscape.<name> heard everywhere (a soundscape's playlooping has no place) with its wave(s) copied, and the entity gets CS2's override
    enablesoundevent 1 + soundevent. playlooping only (nested playsoundscape followed, volumes multiplied); playrandom, a looping wave with a
    position, and a second looping wave are listed, not rebuilt (an entity plays one event). Rerun-safe. -> log lines"""
    index = load_soundscapes()
    lines = [f"# {len(index)} soundscape(s) found in the Source1 roots' scripts/soundscapes_*.txt / .vsc"]
    if not index:
        return lines + ["# none: extract the map's soundscape script (scripts/soundscapes_<map>.txt or .vsc, in the .bsp's packed files) into SOURCE1_ROOT"]

    def loops(name, vol=1.0, seen=()):
        blk = index.get(name.lower())
        if blk is None or name.lower() in seen:
            return [], [f"soundscape {name} not found" if blk is None else f"soundscape {name} includes itself"]
        blk, notes = blk[0], []
        out = []
        for key, items in blk.items():
            for it in (items if isinstance(items, list) else [items]):
                if not isinstance(it, dict):
                    continue
                try:
                    v = float(it.get("volume", "1") or 1)
                except ValueError:
                    v = 1.0
                if key == "playlooping":
                    w = (it.get("wave") or "").strip()
                    if w:
                        out.append((w, vol * v, it.get("position")))
                elif key == "playsoundscape" and it.get("name"):
                    o2, n2 = loops(it["name"], vol * v, seen + (name.lower(),))
                    out += o2
                    notes += n2
                elif key == "playrandom":
                    notes.append("playrandom (random one-shots) not rebuilt")
        return out, notes

    made = {}                    # soundscape (lower) -> event or None
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            lines.append(f"# {vn}: cannot read ({ex})")
            continue
        changed = 0
        for e in m.by_class("env_soundscape", "env_soundscape_triggerable"):
            sc = (m.P(e, "soundscape", "") or "").strip()
            if not sc:
                continue
            key = sc.lower()
            if key not in made:
                ls, notes = loops(sc)
                ev = None
                if ls:
                    w, vol, pos = ls[0]
                    rel = w.lstrip(_WAVE_PREFIX_CHARS).replace("\\", "/").lstrip("/")
                    base, ext = os.path.splitext(rel)
                    vsnd = ("sounds/" + base + ".vsnd").lower()
                    p_, _r = find_in_source1("sound/" + rel)
                    if p_:
                        place_sound(export_dir, p_, "sounds/" + base.lower() + os.path.splitext(p_)[1].lower(), sound_report)
                    if p_ or cs2_file_exists(vsnd + "_c"):
                        ev = SOUNDEVENT_PREFIX + "soundscape." + re.sub(r"[^a-z0-9_]+", "_", key)
                        sound_events[ev] = ([vsnd], min(1.0, max(0.0, vol)))
                        loop_names.add(ev)
                        everywhere.add(ev)
                        if pos is not None:
                            notes.append(f"its loop played from position {pos} in CS:GO: heard everywhere here")
                        if len(ls) > 1:
                            notes.append(f"{len(ls) - 1} more looping wave(s) not played (an entity plays one event): " + "; ".join(x[0] for x in ls[1:]))
                        lines.append(f"EVENT\t{sc}\t-> {ev}\t{rel} volume {vol:g} ({'copied' if p_ else 'CS2 file'}), looping, everywhere"
                                     + "\t" + index[key][1] + ("\t" + "; ".join(notes) if notes else ""))
                    else:
                        lines.append(f"NO_WAVE\t{sc}\t{rel} not in any Source1 root nor CS2: not converted")
                else:
                    lines.append(f"NOT_REBUILT\t{sc}\t" + ("; ".join(notes) if notes else "no playlooping wave"))
                made[key] = ev
            ev = made[key]
            if not ev:
                continue
            if (m.P(e, "enablesoundevent", "") or "") != "1" or (m.P(e, "soundevent", "") or "") != ev:
                m.setp(e, "enablesoundevent", "1")
                m.setp(e, "soundevent", ev)
                changed += 1
        if changed:
            try:
                _save_map(m, vp, "soundscapes")
            except OSError as ex:
                lines.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            lines.append(f"# {vn}: {changed} env_soundscape(s) set to play their soundevent")
        else:
            _keep_map(m, vp)
    return lines


def load_soundscripts() -> dict:
    """Index of every soundscript in the Source1 roots (map root first; first definition wins).
    -> {lower name: (Name, [waves], volume, defining file)}. Read once per set of roots (it was re-read by every caller, twice per
    soundscript ambient_generic in sound_ranges); the same dict is returned each time, so callers only read it."""
    return _load_soundscripts(tuple(str(r) for r in SOURCE1_ROOTS))


@lru_cache(maxsize=2)
def _load_soundscripts(roots) -> dict:
    index = {}
    for root in roots:
        sdir = None
        for cand in ("scripts",):
            q = find_ci(Path(root), cand)
            if q is not None and q.is_dir():
                sdir = q
        if sdir is None:
            continue
        try:
            files = sorted(f for f in os.listdir(sdir)
                           if f.lower().endswith(".txt") and (f.lower().startswith("game_sounds")
                                                              or f.lower().startswith("npc_sounds")))
        except Exception:
            continue
        for f in files:
            try:
                parsed = parse_soundscript_text(Path(sdir, f).read_text(encoding="utf-8", errors="ignore"))
            except Exception:
                continue
            for k, (nm, waves, vol) in parsed.items():
                index.setdefault(k, (nm, waves, vol, f"{os.path.basename(root)}/scripts/{f}"))
    return index

@lru_cache(maxsize=1)
def _cs2_soundevent_blob() -> bytes:
    """Lower-cased bytes of the CS2 install's soundevents (VPK entries and/or extracted files), for a
    best-effort name search; compressed files will not match."""
    parts = []
    v = cs2_vpk()
    for rel in sorted(v.entries):
        if rel.endswith((".vsndevts_c", ".vsndevts")):
            data = v.read(rel)
            if data:
                parts.append(data.lower())
    for root in _cs2_roots():
        folder = os.path.join(root, "soundevents")
        try:
            for f in os.listdir(folder):
                if f.lower().endswith((".vsndevts_c", ".vsndevts")):
                    parts.append(Path(folder, f).read_bytes().lower())
        except Exception:
            pass
    return b"\n".join(parts)

def vmap_soundscript_names(vmap_paths) -> dict:
    """Soundscript names found as plain strings in the .vmap files -> {lower name: Name as defined}."""
    index = load_soundscripts()
    found = {}
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
        except Exception:
            continue
        for m in SOUNDSCRIPT_NAME_RE.finditer(data):
            key = m.group(0).decode("ascii", errors="ignore").lower()
            if key in index:
                found[key] = index[key][0]
    return found

def convert_soundscripts(export_dir: Path, vmap_paths, sound_events: dict, loop_names: set, sound_report: list):
    """Port the CS:GO/Source1 soundscripts the map refers to: copy the waves and define a soundevent with
    the SAME name. -> report lines."""
    index = load_soundscripts()
    names = vmap_soundscript_names(vmap_paths)
    cs2_blob = _cs2_soundevent_blob()
    per_file = {}
    for _k, (_nm, _w, _v, _src) in index.items():
        per_file[_src] = per_file.get(_src, 0) + 1
    lines = [f"# {len(index)} soundscripts indexed from {len(per_file)} script file(s); "
             f"{len(names)} of them are used by the map"]
    if not index:
        lines.append("# NO scripts/game_sounds*.txt (or npc_sounds*.txt) found under any Source1 root, so nothing can be "
                     "resolved. Extract the game's scripts folder (it is inside pak01_dir.vpk) next to the sounds.")
    lines += [f"#   {src}: {c}" for src, c in sorted(per_file.items())]
    for key in sorted(names):
        nm, waves, vol, src = index[key]
        if cs2_blob and nm.lower().encode() in cs2_blob:
            lines.append(f"{nm}\talready defined in the CS2 install (best-effort check); skipped\t{src}")
            continue
        vsnds, missing, from_cs2 = [], [], []
        for w in waves:
            rel = w.lstrip(_WAVE_PREFIX_CHARS).replace("\\", "/").lstrip("/")
            if not rel:
                continue
            base, ext = os.path.splitext(rel)
            vsnd = ("sounds/" + base + ".vsnd").lower()
            if SOUND_PREFER_CS2_FILES and cs2_file_exists(vsnd + "_c"):
                vsnds.append(vsnd)
                from_cs2.append(rel)
                continue
            p, _r = find_in_source1("sound/" + rel)
            if not p and not ext:
                for e in (".wav", ".mp3"):
                    p, _r = find_in_source1("sound/" + rel + e)
                    if p:
                        break
            if not p:
                missing.append(rel)
                continue
            dest_rel = "sounds/" + base.lower() + os.path.splitext(p)[1].lower()
            place_sound(export_dir, p, dest_rel, sound_report)
            vsnds.append(vsnd)
            if is_looping_sound(p):
                loop_names.add(nm)
        vsnds = list(dict.fromkeys(vsnds))
        if vsnds:
            sound_events[nm] = (vsnds, vol)
        status = "ok" if vsnds and not missing else ("PARTIAL" if vsnds else "NO WAVES FOUND")
        lines.append(f"{nm}\t{status}\twaves={len(waves)} found={len(vsnds)}\tdefined in {src}"
                     + (f"\tUSING CS2's OWN FILE (not copied): {'; '.join(from_cs2)}" if from_cs2 else "")
                     + (f"\tMISSING: {'; '.join(missing)}" if missing else ""))
    # strings that look like soundscript names but are not defined in any script file found
    ext_skip = {"vmat", "vsnd", "vmdl", "vpcf", "vtex", "tga", "png", "jpg", "wav", "mp3", "dmx", "vmap", "vmt", "vtf", "txt", "vdata"}
    cand = set()
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
        except Exception:
            continue
        for m in SOUNDSCRIPT_NAME_RE.finditer(data):
            t = m.group(0).decode("ascii", errors="ignore")
            last = t.rsplit(".", 1)[-1]
            if t.lower() in index or last.lower() in ext_skip or not t[0].isupper() or len(last) < 4:
                continue
            cand.add(t)
    if cand:
        lines.append("# UNRESOLVED: look like soundscript names but are not defined in any script file found:")
        lines += [f"{t}\tNOT DEFINED" for t in sorted(cand)]
    return lines

def _vpcf_spawn_initializers(life: float) -> str:
    """m_Initializers block: spawn at control point 0, fixed lifetime. CS2's particle editor drops the old C_INIT_CreateWithinSphere /
    C_INIT_RandomLifeTime (a trail saved in the editor came back with no initializers and drew nothing); these are the classes the
    steam particles use, which work."""
    ind = "\t\t"
    lines = ["\tm_Initializers =", "\t[", ind + "{", ind + '\t_class = "C_INIT_CreateWithinSphereTransform"', ind + "},"]
    lines += _init_float_lines(ind, life, life, 1)
    lines.append("\t]")
    return "\n".join(lines) + "\n"


def make_sprite_particle(export_dir: Path, vpcf_rel: str):
    """particles/<dir>/<name>.vpcf has no Source1 equivalent, but Source1 sprite VMT materials/sprites/<name>.vmt does
    (the importer turns env_sprite into a particle named after the sprite). Build a simple additive sprite particle from
    that sprite's texture. Header/texture layout follows a Hammer-saved vpcf61 file; operators follow skink52's glowfix.py. -> (ok, message)"""
    stem = os.path.splitext(os.path.basename(vpcf_rel))[0]
    vmt, _root = find_in_source1(f"materials/sprites/{stem}.vmt")
    if not vmt:
        return False, f"no Source1 materials/sprites/{stem}.vmt to build a sprite particle from"
    try:
        data = parse_vmt(Path(vmt))
        if not data["basetexture"]:
            return False, f"{vmt} has no $basetexture"
        color_rel, _anim = export_color_texture(export_dir, data["basetexture"], False)
        vtex_rel = os.path.splitext(color_rel)[0] + "_particle.vtex"   # own name: the .tga already feeds the vmat
        write_simple_vtex(export_dir / vtex_rel, color_rel)
    except Exception as e:
        return False, f"sprite texture export failed: {e}"
    body = VPCF66_HEADER + (
        "{\n\t_class = \"CParticleSystemDefinition\"\n\tm_nBehaviorVersion = 12\n\tm_nMaxParticles = 16\n"
        "\tm_ConstantColor = [ 255, 255, 255, 255 ]\n"
        f"\tm_flConstantRadius = {SPRITE_PARTICLE_RADIUS}\n"
        "\tm_Renderers =\n\t[\n\t\t{\n\t\t\t_class = \"C_OP_RenderSprites\"\n"
        "\t\t\tm_nOutputBlendMode = \"PARTICLE_OUTPUT_BLEND_MODE_ADD\"\n"
        "\t\t\tm_vecTexturesInput =\n\t\t\t[\n\t\t\t\t{\n"
        f"\t\t\t\t\tm_hTexture = resource:\"{vtex_rel}\"\n" "\t\t\t\t},\n\t\t\t]\n\t\t},\n\t]\n"
        "\tm_Emitters =\n\t[\n\t\t{\n\t\t\t_class = \"C_OP_ContinuousEmitter\"\n\t\t\tm_flEmitRate = 40.0\n\t\t},\n\t]\n"
        + _vpcf_spawn_initializers(0.15) +
        "\tm_Operators =\n\t[\n\t\t{\n\t\t\t_class = \"C_OP_Decay\"\n\t\t},\n\t\t{\n\t\t\t_class = \"C_OP_PositionLock\"\n\t\t},\n"
        "\t\t{\n\t\t\t_class = \"C_OP_FadeInSimple\"\n\t\t\tm_flFadeInTime = 0.3\n\t\t},\n"
        "\t\t{\n\t\t\t_class = \"C_OP_FadeOutSimple\"\n\t\t\tm_flFadeOutTime = 0.3\n\t\t},\n\t]\n}\n")
    out = export_dir / normalize_candidate(vpcf_rel)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(body, encoding="utf-8")
    return True, f"generated from {vmt} -> {vtex_rel}"

# ---- vpcf66 value structs, copied field-for-field from what the CS2 particle editor saves ----
VPCF66_HEADER = ('<!-- kv3 encoding:text:version{e21c7f3c-8a33-41c5-9977-a76d3a32aa0d} '
                 'format:vpcf66:version{dd571be4-586e-4f41-8b2d-5bbc969e1c53} -->\n')

def _kv_f(v) -> str:
    return f"{float(v):.4f}".rstrip("0").rstrip(".") if float(v) != int(float(v)) else f"{float(v):.1f}"

def _pf_lines(ind: str, ptype: str = "PF_TYPE_LITERAL", **ov) -> list:
    """A CPerParticleFloatInput struct (editor's full field list). ov: field name -> value."""
    d = [("m_nType", f'"{ptype}"'), ("m_nMapType", '"PF_MAP_TYPE_DIRECT"'), ("m_flLiteralValue", "0.0"),
         ("m_NamedValue", '""'), ("m_nControlPoint", "0"), ("m_nScalarAttribute", "3"), ("m_nVectorAttribute", "6"),
         ("m_nVectorComponent", "0"), ("m_bReverseOrder", "false"), ("m_flRandomMin", "0.0"), ("m_flRandomMax", "1.0"),
         ("m_bHasRandomSignFlip", "false"), ("m_nRandomSeed", "-1"), ("m_nRandomMode", '"PF_RANDOM_MODE_CONSTANT"'),
         ("m_strSnapshotSubset", '""'), ("m_flLOD0", "0.0"), ("m_flLOD1", "0.0"), ("m_flLOD2", "0.0"), ("m_flLOD3", "0.0"),
         ("m_nNoiseInputVectorAttribute", "0"), ("m_flNoiseOutputMin", "0.0"), ("m_flNoiseOutputMax", "1.0"),
         ("m_flNoiseScale", "0.1"), ("m_vecNoiseOffsetRate", "[ 0.0, 0.0, 0.0 ]"), ("m_flNoiseOffset", "0.0"),
         ("m_nNoiseOctaves", "1"), ("m_nNoiseTurbulence", '"PF_NOISE_TURB_NONE"'), ("m_nNoiseType", '"PF_NOISE_TYPE_PERLIN"'),
         ("m_nNoiseModifier", '"PF_NOISE_MODIFIER_NONE"'), ("m_flNoiseTurbulenceScale", "1.0"), ("m_flNoiseTurbulenceMix", "0.5"),
         ("m_flNoiseImgPreviewScale", "1.0"), ("m_bNoiseImgPreviewLive", "true"), ("m_flNoCameraFallback", "0.0"),
         ("m_bUseBoundsCenter", "false"), ("m_nInputMode", '"PF_INPUT_MODE_CLAMPED"'), ("m_flMultFactor", "1.0"),
         ("m_flInput0", "0.0"), ("m_flInput1", "1.0"), ("m_flOutput0", "0.0"), ("m_flOutput1", "1.0"),
         ("m_flNotchedRangeMin", "0.0"), ("m_flNotchedRangeMax", "1.0"), ("m_flNotchedOutputOutside", "0.0"),
         ("m_flNotchedOutputInside", "1.0"), ("m_nRoundType", '"PF_ROUND_TYPE_NEAREST"'), ("m_nBiasType", '"PF_BIAS_TYPE_STANDARD"'),
         ("m_flBiasParameter", "0.0")]
    out = ["{"]
    for k, v in d:
        out.append(f"\t{k} = {ov.get(k, v)}")
    out += ["\tm_Curve = ", "\t{", "\t\tm_spline = [  ]", "\t\tm_tangents = [  ]",
            "\t\tm_vDomainMins = [ 0.0, 0.0 ]", "\t\tm_vDomainMaxs = [ 0.0, 0.0 ]", "\t}",
            "\tm_flCompareValue = 0.0", "}"]
    return [ind + ln for ln in out]

def _pvec_literal_lines(ind: str, vec) -> list:
    """A CPerParticleVecInput struct holding a literal vector (editor's full field list)."""
    out = ["{", "\tm_nType = \"PVEC_TYPE_LITERAL\"",
           f"\tm_vLiteralValue = [ {_kv_f(vec[0])}, {_kv_f(vec[1])}, {_kv_f(vec[2])} ]",
           "\tm_LiteralColor = [ 0, 0, 0 ]", "\tm_NamedValue = \"\"", "\tm_bFollowNamedValue = false",
           "\tm_nVectorAttribute = 6", "\tm_vVectorAttributeScale = [ 1.0, 1.0, 1.0 ]", "\tm_nControlPoint = 0",
           "\tm_nDeltaControlPoint = 0", "\tm_vCPValueScale = [ 1.0, 1.0, 1.0 ]",
           "\tm_vCPRelativePosition = [ 0.0, 0.0, 0.0 ]", "\tm_vCPRelativeDir = [ 1.0, 0.0, 0.0 ]"]
    for comp in ("m_FloatComponentX", "m_FloatComponentY", "m_FloatComponentZ", "m_FloatInterp"):
        out.append(f"\t{comp} = ")
        out += ["\t" + ln for ln in _pf_lines("")]
    out += ["\tm_flInterpInput0 = 0.0", "\tm_flInterpInput1 = 1.0", "\tm_vInterpOutput0 = [ 0.0, 0.0, 0.0 ]",
            "\tm_vInterpOutput1 = [ 1.0, 1.0, 1.0 ]", "\tm_Gradient = ", "\t{", "\t\tm_Stops = [  ]", "\t}",
            "\tm_vRandomMin = [ 0.0, 0.0, 0.0 ]", "\tm_vRandomMax = [ 0.0, 0.0, 0.0 ]", "}"]
    return [ind + ln for ln in out]

def _init_float_lines(ind: str, vmin: float, vmax: float, field: int, signflip: bool = False) -> list:
    """C_INIT_InitFloat with a uniform random value written to a particle attribute (1 life duration, 4 rotation, 5 rotation speed)."""
    out = [ind + "{", ind + '\t_class = "C_INIT_InitFloat"', ind + "\tm_InputValue = "]
    out += _pf_lines(ind + "\t", "PF_TYPE_RANDOM_UNIFORM", m_flRandomMin=_kv_f(vmin), m_flRandomMax=_kv_f(vmax),
                     m_bHasRandomSignFlip="true" if signflip else "false")
    out += [ind + f"\tm_nOutputField = {field}", ind + "},"]
    return out

def make_heatwave_normal(export_dir: Path):
    """Soft, noisy tangent-space normal map for the refraction sprite: bumps fade to a flat normal at the edge so no
    ring or outline is displaced. -> vtex path (relative)."""
    N = 128
    rng = random.Random(7)
    waves = [(rng.uniform(2.0, 5.0), rng.uniform(2.0, 5.0), rng.uniform(0, 6.283), rng.uniform(0.5, 1.0)) for _ in range(6)]
    H = [[0.0] * N for _ in range(N)]
    for y in range(N):
        for x in range(N):
            u, v = (x + .5) / N * 2 - 1, (y + .5) / N * 2 - 1
            rr = (u * u + v * v) ** .5
            env = max(0.0, 1.0 - rr)
            env = env * env * (3 - 2 * env)                       # smoothstep: 0 at the rim and flat there
            h = sum(a * math.sin(fx * u * 3.1416 + fy * v * 3.1416 + ph) for fx, fy, ph, a in waves)
            H[y][x] = h * env
    img = Image.new("RGBA", (N, N))
    px = img.load()
    k = STEAM_HEATWAVE_NORMAL_STRENGTH
    for y in range(N):
        for x in range(N):
            dx = (H[y][min(N - 1, x + 1)] - H[y][max(0, x - 1)]) * .5 * k
            dy = (H[min(N - 1, y + 1)][x] - H[max(0, y - 1)][x]) * .5 * k
            nx, ny, nz = -dx, -dy, 1.0
            ln = (nx * nx + ny * ny + nz * nz) ** .5
            u, v = (x + .5) / N * 2 - 1, (y + .5) / N * 2 - 1
            rr = min(1.0, (u * u + v * v) ** .5)
            al = int(255 * (1 - rr * rr) ** 2 + .5)               # opacity falls to 0 at the rim
            px[x, y] = (int((nx / ln * .5 + .5) * 255 + .5), int((ny / ln * .5 + .5) * 255 + .5),
                        int((nz / ln * .5 + .5) * 255 + .5), al)
    rel = "materials/particle/steam_heatwave_normal.png"
    (export_dir / rel).parent.mkdir(parents=True, exist_ok=True)
    img.save(export_dir / rel)
    vtex = "materials/particle/steam_heatwave_normal.vtex"
    write_simple_vtex(export_dir / vtex, rel, "DXT5", linear=True)
    return vtex

def _steam_renderer_extras(emissive: bool, refract: bool) -> list:
    """Extra C_OP_RenderSprites fields (tab-indented as renderer members) for lighting / fog / brightness."""
    ind = "\t\t\t"
    out = []

    def fl(name, value):
        out.append(f"{ind}{name} = ")
        out.extend(_pf_lines(ind, "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(value)))
    if not refract:
        if emissive and STEAM_SELF_ILLUM is not None:
            fl("m_flSelfIllumAmount", STEAM_SELF_ILLUM)
        if STEAM_DIFFUSE_AMOUNT is not None:
            fl("m_flDiffuseAmount", STEAM_DIFFUSE_AMOUNT)
        if STEAM_OVERBRIGHT is not None and float(STEAM_OVERBRIGHT) != 1.0:
            fl("m_flOverbrightFactor", STEAM_OVERBRIGHT)
    fog = {"disabled": "PARTICLE_FOG_DISABLED", "enabled": "PARTICLE_FOG_ENABLED"}.get(str(STEAM_FOG).strip().lower())
    if fog:
        out.append(f'{ind}m_nFogType = "{fog}"')
    return out

def _steam_speed_vecs(speed: float, spread: float):
    """(min, max) local speed vectors with the jet along STEAM_FORWARD_AXIS and +-spread on the other two axes."""
    ax = STEAM_FORWARD_AXIS.strip().lower()
    sign = -1.0 if ax.startswith("-") else 1.0
    i = "xyz".index(ax.lstrip("-")) if ax.lstrip("-") in ("x", "y", "z") else 0
    vmin, vmax = [-spread] * 3, [spread] * 3
    vmin[i] = vmax[i] = sign * speed
    return tuple(vmin), tuple(vmax)

def steam_initializers_text(speed: float, spread: float, life: float, roll: float) -> str:
    ind = "\t\t"
    vmin, vmax = _steam_speed_vecs(speed, spread)
    ax = {"x": 0, "y": 1, "z": 2}.get(str(STEAM_EMIT_AXIS).strip().lower(), 0)
    vmin, vmax = [-spread] * 3, [spread] * 3
    vmin[ax] = vmax[ax] = speed
    out = [ind + "{", ind + '\t_class = "C_INIT_CreateWithinSphereTransform"',
           ind + "\tm_LocalCoordinateSystemSpeedMin = "]
    out += _pvec_literal_lines(ind + "\t", vmin)
    out.append(ind + "\tm_LocalCoordinateSystemSpeedMax = ")
    out += _pvec_literal_lines(ind + "\t", vmax)
    out.append(ind + "},")
    out += _init_float_lines(ind, life, life, 1)
    out += _init_float_lines(ind, 0.0, 360.0, 4, True)
    out += _init_float_lines(ind, -roll, roll, 5, True)
    return "\n".join(out)


def _steam_num(kv: dict, key: str, default: float) -> float:
    for k, v in kv.items():
        if k.lower() == key.lower():
            try:
                return float(str(v).split()[0])
            except (ValueError, IndexError):
                break
    return float(default)

def _steam_str(kv: dict, key: str, default: str = "") -> str:
    return next((str(v) for k, v in kv.items() if k.lower() == key.lower()), default)

def _steam_status(msg: str) -> str:
    return msg if msg.startswith("SKIPPED") else f"FAILED: {msg}"

def _sn(v: float) -> str:
    """number for a file name: 120 -> '120', 2.5 -> '2d5'"""
    return f"{float(v):g}".replace(".", "d").replace("-", "m")

def steam_particle_name(kv: dict) -> str:
    """The particle's file name carries the Source1 values that shaped it, so the vmap's effect_name is enough to rebuild
    it on any run (no env_steam entity, hash or manifest needed):
    env_steam_s<Speed>_p<SpreadSpeed>_z<StartSize>-<EndSize>_r<Rate>_j<JetLength>_l<rollspeed>_a<renderamt>_c<r>-<g>-<b>_e<emissive>_t<type>"""
    try:
        r, g, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "rendercolor", "255 255 255").split()[:3]]
    except ValueError:
        r = g = b = 255
    emissive = int(_steam_num(kv, "spawnflags", 0)) & 1
    return ("env_steam_s{}_p{}_z{}-{}_r{}_j{}_l{}_a{}_c{}-{}-{}_e{}_t{}".format(
        _sn(_steam_num(kv, "Speed", 120)), _sn(_steam_num(kv, "SpreadSpeed", 15)),
        _sn(_steam_num(kv, "StartSize", 10)), _sn(_steam_num(kv, "EndSize", 25)),
        _sn(_steam_num(kv, "Rate", 26)), _sn(_steam_num(kv, "JetLength", 80)), _sn(_steam_num(kv, "rollspeed", 8)),
        int(_steam_num(kv, "renderamt", 255)), r, g, b, emissive, int(_steam_num(kv, "type", 0)))).lower()

_SN = r"m?\d+(?:d\d+)?"
STEAM_NAME_RE = re.compile(
    rf"^env_steam_s({_SN})_p({_SN})_z({_SN})-({_SN})_r({_SN})_j({_SN})_l({_SN})_a(\d+)_c(\d+)-(\d+)-(\d+)_e([01])_t(\d+)$")

def parse_steam_particle_name(stem: str):
    """Inverse of steam_particle_name -> env_steam keyvalues (strings), or None if the name is not one of ours."""
    m = STEAM_NAME_RE.match(stem.lower())
    if not m:
        return None
    n = lambda t: str(float(t.replace("d", ".").replace("m", "-")))   # noqa: E731
    g = m.groups()
    return {"Speed": n(g[0]), "SpreadSpeed": n(g[1]), "StartSize": n(g[2]), "EndSize": n(g[3]), "Rate": n(g[4]),
            "JetLength": n(g[5]), "rollspeed": n(g[6]), "renderamt": g[7], "rendercolor": f"{g[8]} {g[9]} {g[10]}",
            "spawnflags": g[11], "type": g[12]}

def make_steam_particle(export_dir: Path, name: str, kv: dict):
    """Source1 env_steam keyvalues -> particles/steam/<name>.vpcf, following C_SteamJet (Source SDK 2013):
      * every particle lives JetLength / Speed seconds
      * spawns at the entity origin with velocity = Speed*forward + rand(-SpreadSpeed, SpreadSpeed)*(right, up), constant
        (no gravity, no drag), roll = random 0-360 deg turning at rand(-rollspeed, rollspeed)
      * size lerps StartSize -> EndSize over the lifetime
      * alpha = sin(pi * age / lifetime) * renderamt / 255  (0 -> peak at half life -> 0); the particle fades in and out
        linearly here, which is the closest simple operator (check in the particle editor)
      * colour = rendercolor when the Emissive flag (spawnflags 1) is set; otherwise Source1 uses world lighting
        (STEAM_UNLIT_TINT here)
    -> (ok, message, entity-settings lines). Operator/field names are Source 2 particle classes written from memory of
    Hammer-saved vpcf61 files: open the result in the particle editor and check."""
    speed = _steam_num(kv, "Speed", 120)
    spread = _steam_num(kv, "SpreadSpeed", 15)
    size0 = _steam_num(kv, "StartSize", 10)
    size1 = _steam_num(kv, "EndSize", 25)
    rate = _steam_num(kv, "Rate", 26)
    jet = _steam_num(kv, "JetLength", 80)
    roll = _steam_num(kv, "rollspeed", 8)
    alpha = max(0, min(255, int(round(_steam_num(kv, "renderamt", 255) * STEAM_ALPHA_SCALE))))
    flags = int(_steam_num(kv, "spawnflags", 0))
    emissive = bool(flags & 1)
    if emissive:
        try:
            r, g, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "rendercolor", "255 255 255").split()[:3]]
        except ValueError:
            r = g = b = 255
        r, g, b = (min(255, c + a) for c, a in zip((r, g, b), STEAM_EMISSIVE_ADD))
    else:
        r, g, b = STEAM_UNLIT_TINT
    heat = int(_steam_num(kv, "type", 0)) == 1
    if heat and STEAM_HEATWAVE_MODE == "skip":
        return False, ("SKIPPED: env_steam type 1 is the heat-wave variant (a distortion with no visible steam in Source1) and "
                       "STEAM_HEATWAVE_MODE is \"skip\"; nothing built"), []
    refract = heat and STEAM_HEATWAVE_MODE == "refract"
    if refract:
        r = g = b = 255
    if speed <= 0:
        return False, "Speed is 0 (Source1 divides JetLength by Speed); nothing to build", []
    life = max(0.05, jet / speed)
    max_p = int(rate * life) + 6
    start_r = max(size0, 1.0) * STEAM_SIZE_TO_RADIUS
    end_scale = max(size1, 1.0) / max(size0, 1.0)

    refract_amt = 0.25 if STEAM_HEATWAVE_REFRACT is None else float(STEAM_HEATWAVE_REFRACT)
    refract_note = ""
    if refract and STEAM_HEATWAVE_REFRACT is None:
        # Source1 keeps the heat-wave distortion in the MATERIAL ($refractamount of sprites/heatwave.vmt, which env_steam type 1 always draws), not on the entity or the particle
        _hm = STEAM_HEATWAVE_TEXTURE[11:].strip().replace("\\", "/") if STEAM_HEATWAVE_TEXTURE.lower().startswith("source1vmt:") else "sprites/heatwave"
        _hv = None
        try:
            _hp, _hr = find_in_source1("materials/" + _hm + ".vmt")
            if _hp:
                _m = re.search(r'"?\$refractamount"?\s+"?(-?[0-9]*\.?[0-9]+)', parse_vmt(Path(_hp)).get("text", ""), flags=re.I)
                if _m:
                    _hv = float(_m.group(1))
        except Exception:
            _hv = None
        if _hv is None:
            _hv = refract_amt
            refract_note = f"; WARNING refract amount {refract_amt:g} is NOT the Source1 one: materials/{_hm}.vmt (with its $refractamount) was not found under SOURCE1_ROOTS - extract it there, or set STEAM_HEATWAVE_REFRACT"
        else:
            refract_note = f"; refract amount {_hv:g} taken from Source1 material {_hm}"
        refract_amt = _hv
    if refract:
        if STEAM_HEATWAVE_TEXTURE.lower().startswith("source1vmt:"):
            _vref = STEAM_HEATWAVE_TEXTURE[11:].strip().replace("\\", "/")
            try:
                _vp, _r = find_in_source1("materials/" + _vref + ".vmt")
                if not _vp:
                    raise FileNotFoundError(f"materials/{_vref}.vmt not found in SOURCE1_ROOTS")
                _vd = parse_vmt(Path(_vp))
                if not _vd.get("normalmap"):
                    raise ValueError("the material has no $normalmap")
                _crel, _a = export_color_texture(export_dir, _vd["normalmap"], False)
                vtex_rel = os.path.splitext(_crel)[0] + "_heatnormal.vtex"
                write_simple_vtex(export_dir / vtex_rel, _crel, "DXT5", linear=True)
                tex_note = f"refraction using the normal map of Source1 material {_vref} ({_vd['normalmap']}) -> {vtex_rel}"
            except Exception as _ex:
                vtex_rel = make_heatwave_normal(export_dir)
                tex_note = f"Source1 material {_vref} unavailable ({_ex}); fell back to the generated soft normal map ({vtex_rel})"
        elif STEAM_HEATWAVE_TEXTURE.lower().startswith("source1:"):
            _ref = STEAM_HEATWAVE_TEXTURE[8:].strip()
            try:
                _crel, _a = export_color_texture(export_dir, _ref, False)
                vtex_rel = os.path.splitext(_crel)[0] + "_refract.vtex"
                write_simple_vtex(export_dir / vtex_rel, _crel, linear=True)
                tex_note = f"refraction using Source1 texture {_ref} ({vtex_rel}); it is not a normal map, so expect a rough shimmer"
            except Exception as _ex:
                vtex_rel = make_heatwave_normal(export_dir)
                tex_note = f"Source1 texture {_ref} unavailable ({_ex}); fell back to the generated soft normal map ({vtex_rel})"
        elif STEAM_HEATWAVE_TEXTURE:
            vtex_rel = STEAM_HEATWAVE_TEXTURE
            tex_note = f"refraction using stock texture {vtex_rel}"
            if USE_CS2_VPK and cs2_vpk().loaded and not cs2_file_exists(vtex_rel + "_c"):
                tex_note += " (NOT found in the CS2 VPK index: check the path, STEAM_HEATWAVE_TEXTURE)"
        else:
            vtex_rel = make_heatwave_normal(export_dir)
            tex_note = f"refraction using a generated soft normal map ({vtex_rel})"
    else:
        tex_note = ""
        try:
            color_rel, _a = export_color_texture(export_dir, STEAM_TEXTURE_SOURCE1, False)
            tex_note = f"Source1 texture {STEAM_TEXTURE_SOURCE1}"
        except Exception:
            N = 64
            img = Image.new("RGBA", (N, N))
            px = img.load()
            for y in range(N):
                for x in range(N):
                    d = (((x + .5) / N - .5) ** 2 + ((y + .5) / N - .5) ** 2) ** .5 * 2
                    a = int(max(0.0, 1 - d) ** 1.6 * 255 + .5)
                    px[x, y] = (255, 255, 255, a)
            color_rel = "materials/particle/steam_soft_color.png"
            (export_dir / color_rel).parent.mkdir(parents=True, exist_ok=True)
            img.save(export_dir / color_rel)
            tex_note = "generated soft puff (Source1 texture not found)"
        vtex_rel = os.path.splitext(color_rel)[0] + "_particle.vtex"
        write_simple_vtex(export_dir / vtex_rel, color_rel)

    if refract:
        renderer = "\n".join(
            ["\t\t{", '\t\t\t_class = "C_OP_RenderSprites"'] + _steam_renderer_extras(emissive, True)
            + ["\t\t\tm_bRefract = true", "\t\t\tm_flRefractAmount = "]
            + _pf_lines("\t\t\t", "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(refract_amt))
            + ["\t\t\tm_nRefractBlurRadius = 1", '\t\t\tm_nRefractBlurType = "BLURFILTER_BOX"',
               "\t\t\tm_vecTexturesInput =", "\t\t\t[", "\t\t\t\t{", f'\t\t\t\t\tm_hTexture = resource:"{vtex_rel}"',
               "\t\t\t\t},", "\t\t\t]", "\t\t},"])
    else:
        renderer = "\n".join(
            ["\t\t{", '\t\t\t_class = "C_OP_RenderSprites"'] + _steam_renderer_extras(emissive, False)
            + ["\t\t\tm_vecTexturesInput =", "\t\t\t[", "\t\t\t\t{",
               f'\t\t\t\t\tm_hTexture = resource:"{vtex_rel}"', "\t\t\t\t},", "\t\t\t]", "\t\t},"])

    body = VPCF66_HEADER + f"""{{
	_class = "CParticleSystemDefinition"
	m_nBehaviorVersion = 12
	m_nMaxParticles = {max_p}
	m_ConstantColor = [ {r}, {g}, {b}, {alpha} ]
	m_flConstantRadius = {start_r:.2f}
	m_Renderers =
	[
{renderer}
	]
	m_Emitters =
	[
		{{
			_class = "C_OP_ContinuousEmitter"
			m_flEmitRate = {rate:.2f}
		}},
	]
	m_Initializers =
	[
{steam_initializers_text(speed, spread, life, STEAM_HEATWAVE_SPIN if refract else roll)}
	]
	m_Operators =
	[
		{{
			_class = "C_OP_BasicMovement"
		}},
		{{
			_class = "C_OP_SpinUpdate"
		}},
		{{
			_class = "C_OP_InterpolateRadius"
			m_flStartTime = 0.0
			m_flEndTime = 1.0
			m_flStartScale = 1.0
			m_flEndScale = {end_scale:.4f}
		}},
		{{
			_class = "C_OP_FadeAndKill"
			m_flStartFadeInTime = 0.0
			m_flEndFadeInTime = 0.5
			m_flStartFadeOutTime = 0.5
			m_flEndFadeOutTime = 1.0
			m_flStartAlpha = 0.0
			m_flEndAlpha = 0.0
		}},
		{{
			_class = "C_OP_Decay"
		}},
	]
}}
"""
    out = export_dir / "particles" / "steam" / f"{name}.vpcf"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(body, encoding="utf-8")
    lines = [f"{name}\teffect_name=particles/steam/{name}.vpcf\t"
             f"lifetime={life:.3f}s speed={speed:g} spread={spread:g} rate={rate:g}/s max_particles={max_p} "
             f"size {size0:g}->{size1:g} (radius {start_r:.1f} x{end_scale:.2f}) roll=+-{roll:g} "
             f"colour {r} {g} {b} ({'emissive' if emissive else 'lit in Source1; STEAM_UNLIT_TINT here'}) alpha<={alpha}\t"
             f"texture: {tex_note}{refract_note if refract else ''}"]
    if heat:
        lines.append(f"{name}\tNOTE: env_steam type 1 is the heat-wave (distortion) variant; built as "
                     + ("a refracting sprite (no visible steam)" if refract else "visible soft sprites, not a distortion"))
    return True, "ok", lines

# env_smokestack keyvalues and their defaults (Source1 FGD); the client's own defaults differ, but Hammer writes every key
_SMOKESTACK_DEFAULTS = {"BaseSpread": 20, "SpreadSpeed": 15, "Speed": 30, "StartSize": 20, "EndSize": 30, "Rate": 20, "JetLength": 180,
                        "WindAngle": 0, "WindSpeed": 0, "twist": 0, "roll": 0, "renderamt": 255}

def smokestack_particle_name(kv: dict) -> str:
    """The file name carries the values that shaped the particle, like env_steam's:
    smokestack_b<BaseSpread>_p<SpreadSpeed>_s<Speed>_z<StartSize>-<EndSize>_r<Rate>_j<JetLength>_w<WindAngle>-<WindSpeed>_t<twist>_l<roll>
    _a<renderamt>_c<r>-<g>-<b>_m<material>"""
    d = _SMOKESTACK_DEFAULTS
    try:
        r, g, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "rendercolor", "255 255 255").split()[:3]]
    except ValueError:
        r = g = b = 255
    mat = _steam_str(kv, "SmokeMaterial", "particle/SmokeStack.vmt").replace("\\", "/").lower()
    mat = re.sub(r"[^a-z0-9]+", "-", os.path.splitext(os.path.basename(mat))[0]).strip("-") or "smoke"
    v = lambda k: _sn(_steam_num(kv, k, d[k]))   # noqa: E731
    return (f"smokestack_b{v('BaseSpread')}_p{v('SpreadSpeed')}_s{v('Speed')}_z{v('StartSize')}-{v('EndSize')}_r{v('Rate')}_j{v('JetLength')}"
            f"_w{v('WindAngle')}-{v('WindSpeed')}_t{v('twist')}_l{v('roll')}_a{int(_steam_num(kv, 'renderamt', 255))}_c{r}-{g}-{b}_m{mat}").lower()

def make_smokestack_particle(export_dir: Path, name: str, kv: dict):
    """Source1 env_smokestack keyvalues -> particles/smokestack/<name>.vpcf, following C_SmokeStack (Source SDK 2013 c_smokestack.cpp):
      * every particle lives JetLength / Speed seconds; Rate per second
      * it starts on a ring of radius BaseSpread around the entity, in the entity's own horizontal plane, moving Speed along the
        entity's up axis plus rand(-SpreadSpeed, SpreadSpeed) along each of its other two axes
      * wind (WindSpeed towards the world yaw WindAngle) accelerates it the whole time; twist turns the smoke around the entity's
        vertical axis at twist degrees a second; roll = random 0-360 deg turning at rand(-roll, roll)
      * size lerps StartSize -> EndSize; alpha rises and falls over the lifetime (a raised cosine, faded in and out here) x renderamt
      * colour = rendercolor (Source1 lit it with env_particlelight entities; CS2 lights particles from the map)
      * texture = SmokeMaterial's $basetexture (particle/SmokeStack by default); a soft puff when it isn't found
    -> (ok, message, report lines). Operator fields from Hammer-saved vpcf66 files and the steam particles; the ring (distance bias)
    and the twist operator are new here: check them in the particle editor."""
    d = _SMOKESTACK_DEFAULTS
    num = lambda k: _steam_num(kv, k, d[k])   # noqa: E731
    base, spread, speed = num("BaseSpread"), num("SpreadSpeed"), num("Speed")
    size0, size1, rate, jet = num("StartSize"), num("EndSize"), num("Rate"), num("JetLength")
    wang, wspd, twist, roll = num("WindAngle"), num("WindSpeed"), num("twist"), num("roll")
    alpha = max(0, min(255, int(round(num("renderamt")))))
    try:
        r, g, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "rendercolor", "255 255 255").split()[:3]]
    except ValueError:
        r = g = b = 255
    if speed <= 0:
        return False, "Speed is 0 (Source1 divides JetLength by Speed); nothing to build", []
    if rate <= 0:
        return False, "Rate is 0: Source1 drew nothing; nothing to build", []
    life = max(0.05, jet / speed)
    max_p = int(rate * life) + 6
    start_r = max(size0, 0.5) * STEAM_SIZE_TO_RADIUS
    end_scale = max(size1, 0.0) / max(size0, 0.5)
    wx, wy = math.cos(math.radians(wang)) * wspd, math.sin(math.radians(wang)) * wspd
    # texture: the material's $basetexture, else the soft puff the steam particles fall back to
    mat = _steam_str(kv, "SmokeMaterial", "particle/SmokeStack.vmt").replace("\\", "/").lower()
    mat = mat[:-4] if mat.endswith(".vmt") else mat
    tex_note = ""
    try:
        vmt, _r = find_in_source1(f"materials/{mat}.vmt")
        if not vmt:
            raise FileNotFoundError(f"materials/{mat}.vmt not under SOURCE1_ROOTS")
        data = parse_vmt(Path(vmt))
        if not data.get("basetexture"):
            raise ValueError(f"{vmt} has no $basetexture")
        color_rel, _anim = export_color_texture(export_dir, data["basetexture"], False)
        tex_note = f"texture from Source1 material {mat} ({data['basetexture']})"
    except Exception as ex:
        N = 64
        img = Image.new("RGBA", (N, N))
        px = img.load()
        for y in range(N):
            for x in range(N):
                dd = (((x + .5) / N - .5) ** 2 + ((y + .5) / N - .5) ** 2) ** .5 * 2
                px[x, y] = (255, 255, 255, int(max(0.0, 1 - dd) ** 1.6 * 255 + .5))
        color_rel = "materials/particle/steam_soft_color.png"
        (export_dir / color_rel).parent.mkdir(parents=True, exist_ok=True)
        img.save(export_dir / color_rel)
        tex_note = f"generated soft puff ({ex})"
    vtex_rel = os.path.splitext(color_rel)[0] + "_particle.vtex"
    write_simple_vtex(export_dir / vtex_rel, color_rel)
    renderer = "\n".join(["\t\t{", '\t\t\t_class = "C_OP_RenderSprites"'] + _steam_renderer_extras(False, False)
                         + ["\t\t\tm_vecTexturesInput =", "\t\t\t[", "\t\t\t\t{", f'\t\t\t\t\tm_hTexture = resource:"{vtex_rel}"',
                            "\t\t\t\t},", "\t\t\t]", "\t\t},"])
    ind = "\t\t"
    init = [ind + "{", ind + '\t_class = "C_INIT_CreateWithinSphereTransform"']
    if base > 0:   # a ring of radius BaseSpread in the entity's own horizontal plane
        init += [ind + "\tm_fRadiusMin = "] + _pf_lines(ind + "\t", "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(base))
        init += [ind + "\tm_fRadiusMax = "] + _pf_lines(ind + "\t", "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(base))
        init += [ind + "\tm_vecDistanceBias = [ 1.0, 1.0, 0.0 ]", ind + "\tm_bLocalCoords = true"]
    init += [ind + "\tm_LocalCoordinateSystemSpeedMin = "] + _pvec_literal_lines(ind + "\t", (-spread, -spread, speed))
    init += [ind + "\tm_LocalCoordinateSystemSpeedMax = "] + _pvec_literal_lines(ind + "\t", (spread, spread, speed))
    init += [ind + "},"]
    init += _init_float_lines(ind, life, life, 1)
    init += _init_float_lines(ind, 0.0, 360.0, 4, True)
    if roll:
        init += _init_float_lines(ind, -abs(roll), abs(roll), 5, True)
    ops = [ind + "{", ind + '\t_class = "C_OP_BasicMovement"']
    if wx or wy:
        ops.append(ind + f"\tm_Gravity = [ {wx:.3f}, {wy:.3f}, 0.0 ]")
    ops += [ind + "},", ind + "{", ind + '\t_class = "C_OP_SpinUpdate"', ind + "},"]
    if twist:   # Source1 turned every particle around the entity's vertical axis (twist degrees a second)
        ops += [ind + "{", ind + '\t_class = "C_OP_MovementRotateParticleAroundAxis"', ind + "\tm_vecRotAxis = [ 0.0, 0.0, 1.0 ]",
                ind + "\tm_flRotRate = "] + _pf_lines(ind + "\t", "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(twist)) + [
                ind + "\tm_nCP = 0", ind + "\tm_bLocalSpace = false", ind + "},"]
    ops += [ind + "{", ind + '\t_class = "C_OP_InterpolateRadius"', ind + "\tm_flStartTime = 0.0", ind + "\tm_flEndTime = 1.0",
            ind + "\tm_flStartScale = 1.0", ind + f"\tm_flEndScale = {end_scale:.4f}", ind + "},",
            ind + "{", ind + '\t_class = "C_OP_FadeAndKill"', ind + "\tm_flStartFadeInTime = 0.0", ind + "\tm_flEndFadeInTime = 0.5",
            ind + "\tm_flStartFadeOutTime = 0.5", ind + "\tm_flEndFadeOutTime = 1.0", ind + "\tm_flStartAlpha = 0.0", ind + "\tm_flEndAlpha = 0.0", ind + "},",
            ind + "{", ind + '\t_class = "C_OP_Decay"', ind + "},"]
    body = VPCF66_HEADER + "\n".join([
        "{", '\t_class = "CParticleSystemDefinition"', "\tm_nBehaviorVersion = 12", f"\tm_nMaxParticles = {max_p}",
        f"\tm_ConstantColor = [ {r}, {g}, {b}, {alpha} ]", f"\tm_flConstantRadius = {start_r:.2f}",
        "\tm_Renderers =", "\t[", renderer, "\t]",
        "\tm_Emitters =", "\t[", "\t\t{", '\t\t\t_class = "C_OP_ContinuousEmitter"', f"\t\t\tm_flEmitRate = {rate:.2f}", "\t\t},", "\t]",
        "\tm_Initializers =", "\t["] + init + ["\t]", "\tm_Operators =", "\t["] + ops + ["\t]", "}"]) + "\n"
    out = export_dir / "particles" / "smokestack" / f"{name}.vpcf"
    out.parent.mkdir(parents=True, exist_ok=True)
    if not (out.is_file() and out.read_text(encoding="utf-8", errors="replace") == body):
        out.write_text(body, encoding="utf-8")
    lines = [f"{name}\teffect_name=particles/smokestack/{name}.vpcf\tlifetime={life:.2f}s speed={speed:g} up, spread={spread:g}, ring {base:g}, "
             f"rate={rate:g}/s max_particles={max_p} size {size0:g}->{size1:g} (radius {start_r:.1f} x{end_scale:.2f}) wind {wx:.1f} {wy:.1f} "
             f"twist {twist:g} roll +-{roll:g} colour {r} {g} {b} alpha {alpha}\t{tex_note}"]
    return True, "ok", lines

def dustmotes_particle_name(kv: dict, half) -> str:
    """particles/dustmotes/<name>.vpcf: the values that shape it, like the steam / smokestack names"""
    g = lambda k, d: _sn(_steam_num(kv, k, d))   # noqa: E731
    try:
        r, gg, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "color", "255 255 255").split()[:3]]
    except ValueError:
        r = gg = b = 255
    return (f"dust_r{g('spawnrate', 40)}_l{g('lifetimemin', 3)}-{g('lifetimemax', 5)}_z{g('sizemin', 10)}-{g('sizemax', 20)}"
            f"_s{g('speedmax', 13)}_d{g('distmax', 1024)}_f{int(_steam_num(kv, 'frozen', 0))}_a{int(_steam_num(kv, 'alpha', 255))}_c{r}-{gg}-{b}"
            f"_b{'-'.join(str(int(round(v))) for v in half)}").lower()


def make_dustmotes_particle(export_dir: Path, name: str, kv: dict, half):
    """Source1 func_dustmotes keyvalues -> particles/dustmotes/<name>.vpcf, following the Source SDK 2013 client code (c_func_dust.cpp,
    supplied by the user) line for line where CS2's particle system can:
      * spawn: SpawnRate a second at random points of the brush (half = its box's half size around the particle's origin; Source1 tests
        the brush itself, so a brush that is not a box spawns in its bounding box here). Frozen: SpawnRate specks at once, which never
        move, fade or die (ClientThink spawns nothing more)
      * life: rand(LifetimeMin, LifetimeMax) seconds; alpha over it sin(2pi t - pi/2) / 2 + 1/2 (0 -> 1 -> 0, peak at half-life), here
        a fade in over the first half and out over the second (C_OP_FadeAndKill)
      * velocity: RandomVector(-SpeedMax, SpeedMax); SimulateParticles then pulls x and y towards the wind (none here: no env_wind in
        CS2) at DUST_ACCEL = 50 units/s2, so x and y stop within SpeedMax / 50 s (13 -> 0.26 s, under 2 units of travel) while z keeps
        its speed: here x and y start at 0 and z is rand(-SpeedMax, SpeedMax)
      * size: DUSTFLAGS_SCALEMOTES (func_dustmotes): m_flSize = rand(SizeMin, SizeMax) / 10000, drawn x the speck's distance from the
        eye, so a speck keeps the same size on screen at any distance (RenderParticle_Color255Size: half width = size). Here the radius is
        rand(SizeMin, SizeMax) / 10000 and the renderer scales it by the camera distance (m_flRadiusScale = PF_TYPE_RENDERER_CAMERA_DISTANCE)
      * DistMax: alpha x (1 - distance / DistMax), not drawn past DistMax: the renderer's m_flAlphaScale remaps the camera distance
        0..DistMax to 1..0 (clamped)
      * colour Color, alpha Alpha; material particle/sparkles ($translucent: alpha blended, unlit), a soft dot when it is not found
    Field and enum names from CS2's particle schema (particles.dll). -> (ok, message, report line)."""
    num = lambda k, d: _steam_num(kv, k, d)   # noqa: E731
    rate = num("spawnrate", 40)
    l0, l1 = sorted((max(0.05, num("lifetimemin", 3)), max(0.05, num("lifetimemax", 5))))
    s0, s1 = sorted((max(0.0, num("sizemin", 10)), max(0.0, num("sizemax", 20))))
    frozen = bool(num("frozen", 0))
    speed = max(0.0, num("speedmax", 13))
    distmax = max(1.0, num("distmax", 1024))
    alpha = max(0, min(255, int(round(num("alpha", 255)))))
    try:
        r, g, b = [max(0, min(255, int(float(x)))) for x in _steam_str(kv, "color", "255 255 255").split()[:3]]
    except ValueError:
        r = g = b = 255
    if rate <= 0:
        return False, "SpawnRate is 0: Source1 drew nothing", ""
    tex_note, additive = "", False
    try:
        vmt, _r = find_in_source1("materials/particle/sparkles.vmt")
        if not vmt:
            raise FileNotFoundError("materials/particle/sparkles.vmt not under SOURCE1_ROOTS")
        data = parse_vmt(Path(vmt))
        if not data.get("basetexture"):
            raise ValueError(f"{vmt} has no $basetexture")
        color_rel, _anim = export_color_texture(export_dir, data["basetexture"], False)
        additive = bool(data.get("additive"))
        tex_note = f"texture from Source1 particle/sparkles ({data['basetexture']}{', additive' if additive else ''})"
    except Exception as ex:
        N = 32
        img = Image.new("RGBA", (N, N))
        px = img.load()
        for y in range(N):
            for x in range(N):
                dd = (((x + .5) / N - .5) ** 2 + ((y + .5) / N - .5) ** 2) ** .5 * 2
                px[x, y] = (255, 255, 255, int(max(0.0, 1 - dd) ** 2.0 * 255 + .5))
        color_rel = "materials/particle/dustmote_soft_color.png"
        (export_dir / color_rel).parent.mkdir(parents=True, exist_ok=True)
        img.save(export_dir / color_rel)
        tex_note = f"generated soft dot ({ex})"
    vtex_rel = os.path.splitext(color_rel)[0] + "_particle.vtex"
    write_simple_vtex(export_dir / vtex_rel, color_rel)
    R = "\t\t\t"

    def rin(name, **ov):
        return [R + f"{name} = "] + _pf_lines(R, ov.pop("ptype", "PF_TYPE_LITERAL"), **ov)
    rend = ["\t\t{", '\t\t\t_class = "C_OP_RenderSprites"']
    if additive:
        rend.append(R + 'm_nOutputBlendMode = "PARTICLE_OUTPUT_BLEND_MODE_ADD"')
    rend += rin("m_flRadiusScale", ptype="PF_TYPE_RENDERER_CAMERA_DISTANCE")
    rend += rin("m_flAlphaScale", ptype="PF_TYPE_RENDERER_CAMERA_DISTANCE", m_nMapType='"PF_MAP_TYPE_REMAP"',
                m_flInput0="0.0", m_flInput1=_kv_f(distmax), m_flOutput0="1.0", m_flOutput1="0.0")
    rend += rin("m_flSelfIllumAmount", m_flLiteralValue="1.0") + rin("m_flDiffuseAmount", m_flLiteralValue="0.0")
    rend += [R + "m_vecTexturesInput =", R + "[", R + "\t{", R + f'\t\tm_hTexture = resource:"{vtex_rel}"', R + "\t},", R + "]", "\t\t},"]
    ind = "\t\t"
    init = [ind + "{", ind + '\t_class = "C_INIT_CreateWithinBox"', ind + "\tm_vecMin = "] + _pvec_literal_lines(ind + "\t", [-v for v in half])
    init += [ind + "\tm_vecMax = "] + _pvec_literal_lines(ind + "\t", list(half)) + [ind + "\tm_nControlPointNumber = 0", ind + "\tm_bLocalSpace = false", ind + "},"]
    if speed > 0 and not frozen:
        init += [ind + "{", ind + '\t_class = "C_INIT_VelocityRandom"', ind + "\tm_LocalCoordinateSystemSpeedMin = "]
        init += _pvec_literal_lines(ind + "\t", (0.0, 0.0, -speed))
        init += [ind + "\tm_LocalCoordinateSystemSpeedMax = "] + _pvec_literal_lines(ind + "\t", (0.0, 0.0, speed)) + [ind + "},"]
    if not frozen:
        init += _init_float_lines(ind, l0, l1, 1)
    init += _init_float_lines(ind, s0 / 10000.0, s1 / 10000.0, 3)
    ops = []
    if not frozen:
        ops = [ind + "{", ind + '\t_class = "C_OP_BasicMovement"', ind + "},",
               ind + "{", ind + '\t_class = "C_OP_FadeAndKill"', ind + "\tm_flStartFadeInTime = 0.0", ind + "\tm_flEndFadeInTime = 0.5",
               ind + "\tm_flStartFadeOutTime = 0.5", ind + "\tm_flEndFadeOutTime = 1.0", ind + "\tm_flStartAlpha = 0.0", ind + "\tm_flEndAlpha = 0.0", ind + "},",
               ind + "{", ind + '\t_class = "C_OP_Decay"', ind + "},"]
        emit = ["\t\t{", '\t\t\t_class = "C_OP_ContinuousEmitter"', f"\t\t\tm_flEmitRate = {rate:.2f}", "\t\t},"]
        max_p = int(rate * l1) + 8
    else:
        emit = ["\t\t{", '\t\t\t_class = "C_OP_InstantaneousEmitter"', "\t\t\tm_nParticlesToEmit = "]
        emit += _pf_lines("\t\t\t", "PF_TYPE_LITERAL", m_flLiteralValue=_kv_f(int(rate))) + ["\t\t},"]
        max_p = int(rate) + 1
    body = VPCF66_HEADER + "\n".join([
        "{", '\t_class = "CParticleSystemDefinition"', "\tm_nBehaviorVersion = 12", f"\tm_nMaxParticles = {max_p}",
        f"\tm_ConstantColor = [ {r}, {g}, {b}, {alpha} ]", f"\tm_flConstantRadius = {s1 / 10000.0:.6f}",
        "\tm_Renderers =", "\t["] + rend + ["\t]", "\tm_Emitters =", "\t["] + emit + ["\t]",
        "\tm_Initializers =", "\t["] + init + ["\t]", "\tm_Operators =", "\t["] + ops + ["\t]", "}"]) + "\n"
    out = export_dir / "particles" / "dustmotes" / f"{name}.vpcf"
    out.parent.mkdir(parents=True, exist_ok=True)
    if not (out.is_file() and out.read_text(encoding="utf-8", errors="replace") == body):
        out.write_text(body, encoding="utf-8")
    return True, "ok", (f"{'frozen: ' + str(int(rate)) + ' specks' if frozen else f'rate {rate:g}/s, life {l0:g}-{l1:g}s'}, size {s0:g}-{s1:g} "
                        f"(/10000 x distance), z speed +-{speed if not frozen else 0:g}, fade out to DistMax {distmax:g}, colour {r} {g} {b} alpha "
                        f"{alpha}, box {' x '.join('%g' % (2 * v) for v in half)}; {tex_note}")


def convert_dustmotes(vmap_paths, vmf_path, export_dir: Path):
    """DUSTMOTES_PARTICLES: func_dustmotes (not in CS2; Valve's importer drops it) -> an info_particle_system at the centre of the .vmf
    brush's box, playing particles/dustmotes/<from its keyvalues>.vpcf (make_dustmotes_particle), with the brush's name; start_active
    from StartDisabled. Outputs sending it TurnOn / TurnOff -> Start / Stop. A brush that is not a box gets its bounding box. Rerun-safe:
    a particle already at that place with a dustmotes effect is updated, not added again. -> log lines"""
    if not vmf_path or not Path(vmf_path).is_file():
        return ["# dust motes: skipped - no .vmf"]
    import numpy as np
    groups = {}
    for b in _vmf_brush_polys(vmf_path, classes=("func_dustmotes",)):
        if b["cls"] != "func_dustmotes":
            continue
        k = b["kv"].get("id") or id(b["kv"])
        lo, hi = np.asarray(b["lo"], float), np.asarray(b["hi"], float)
        if k in groups:
            groups[k] = (groups[k][0], np.minimum(groups[k][1], lo), np.maximum(groups[k][2], hi))
        else:
            groups[k] = (b["kv"], lo, hi)
    if not groups:
        return ["# dust motes: none in the .vmf"]
    out, total = [], 0
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        have = {}
        for e in m.by_class("info_particle_system"):
            if (m.P(e, "effect_name", "") or "").lower().startswith("particles/dustmotes/"):
                have.setdefault(tuple(int(round(v)) for v in m.origin(e)), []).append(e)
        rows, changed, names, used, byname = [], False, set(), set(), {}
        for kv, lo, hi in sorted(groups.values(), key=lambda g_: dustmotes_particle_name(g_[0], [1, 1, 1])):
            c = (lo + hi) / 2
            half = [max(1.0, float(v)) for v in (hi - lo) / 2]
            nm = kv.get("targetname", "") or ""
            pname = dustmotes_particle_name(kv, half)
            ok, msg, note = make_dustmotes_particle(export_dir, pname, kv, half)
            if not ok:
                rows.append(f"NOT_CONVERTED\tfunc_dustmotes {nm or '(unnamed)'} at {' '.join('%g' % round(v) for v in c)}\t{msg}")
                continue
            rel = f"particles/dustmotes/{pname}.vpcf"
            start = "0" if str(kv.get("startdisabled", "0")).strip() == "1" else "1"
            # several dust brushes can share a centre (harero): take the one already playing this effect, else one not yet used
            cands = [x for x in have.get(tuple(int(round(v)) for v in c), []) if x not in used]
            e = next((x for x in cands if (m.P(x, "effect_name", "") or "") == rel), cands[0] if cands else None)
            if e is not None:
                used.add(e)
            if e is None:
                props = {"effect_name": rel, "start_active": start}
                if nm:
                    props["targetname"] = nm
                e = m.new_entity("info_particle_system", [float(v) for v in c], props)
                changed = True
                rows.append(f"CONVERTED\tfunc_dustmotes {nm or '(unnamed)'} at {' '.join('%g' % round(v) for v in c)}\t-> info_particle_system {rel}"
                            f" (start_active {start})\t{note}")
            elif (m.P(e, "effect_name", "") or "") != rel:
                m.setp(e, "effect_name", rel)
                changed = True
                rows.append(f"UPDATED\tinfo_particle_system {nm or '(unnamed)'}\t-> {rel}")
            if nm:
                names.add(nm.lower())
                byname.setdefault(nm.lower(), (kv, c, half, nm))
        dmx = _bundled_vmapedit()[1]
        # AddOutput "Color R G B" (CS:GO: m_Color, networked, so new motes took the colour): CS2 can't recolour a particle, so each colour
        # gets its own copy of the particle (<name>__c<r>_<g>_<b>, start_active 0) and the AddOutput becomes Stop on the others + Start on it
        recol = []
        for s_, cc in list(m.all_conns()):
            tup = m.conn_tuple(cc)
            w = (tup[3] or "").split()
            if tup[2].lower() == "addoutput" and tup[1].lower() in byname and len(w) == 4 and w[0].lower() == "color" \
                    and all(re.fullmatch(r"\d+(?:\.\d+)?", x) for x in w[1:]):
                recol.append((s_, cc, tup, tuple(max(0, min(255, int(float(x)))) for x in w[1:])))
        for nl in {r_[2][1].lower() for r_ in recol}:
            kv, c, half, nm = byname[nl]
            cols = sorted({r_[3] for r_ in recol if r_[2][1].lower() == nl})
            copies = {}
            for col in cols:
                kv2 = dict(kv)
                kv2["color"] = " ".join(str(x) for x in col)
                pn2 = dustmotes_particle_name(kv2, half)
                ok, msg, _note = make_dustmotes_particle(export_dir, pn2, kv2, half)
                if not ok:
                    rows.append(f"NOT_CONVERTED\tfunc_dustmotes {nm} colour {' '.join(map(str, col))}\t{msg}")
                    continue
                cn = f"{nm}__c{col[0]}_{col[1]}_{col[2]}"
                rel2 = f"particles/dustmotes/{pn2}.vpcf"
                ex_ = next((x for x in m.entities() if (m.name(x) or "").lower() == cn.lower()), None)
                if ex_ is None:
                    m.new_entity("info_particle_system", [float(v) for v in c], {"effect_name": rel2, "start_active": "0", "targetname": cn})
                    rows.append(f"COLOUR\t{nm}\tcolour {' '.join(map(str, col))} -> its own particle {cn} ({rel2})")
                elif (m.P(ex_, "effect_name", "") or "") != rel2:
                    m.setp(ex_, "effect_name", rel2)
                changed = True
                copies[col] = cn
            for s_, cc, tup, col in recol:
                if tup[1].lower() != nl or col not in copies:
                    continue
                o, _t, _i, _p, d, times = tup
                others = [nm] + [v for k_, v in copies.items() if k_ != col]
                dmx.set_(cc, b"targetName", dmx.T_STR, copies[col].encode())
                dmx.set_(cc, b"inputName", dmx.T_STR, b"Start")
                dmx.set_(cc, b"overrideParam", dmx.T_STR, b"")
                for on in others:
                    m.add_conn(s_, o, on, "Stop", "", d, times)
                changed = True
                rows.append(f"INPUT\t{nm}\t{o} AddOutput Color {' '.join(map(str, col))} -> {copies[col]} Start, {', '.join(others)} Stop")
        for _s, cc in m.all_conns():
            tup = m.conn_tuple(cc)
            new = {"turnon": "Start", "turnoff": "Stop"}.get(tup[2].lower())
            if tup[1].lower() in names and new:
                dmx.set_(cc, b"inputName", dmx.T_STR, new.encode())
                changed = True
                rows.append(f"INPUT\t{tup[1]}\t{tup[2]} -> {new}")
        if not changed:
            _keep_map(m, vp)
            continue
        try:
            _save_map(m, vp, "dustmotes")
        except OSError as ex:
            out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
            continue
        total += sum(r.startswith("CONVERTED") for r in rows)
        out += [f"# {vn}"] + rows
    out.insert(0, f"# func_dustmotes -> info_particle_system: {total} converted")
    return out


def _angles_forward(ang: str) -> str:
    """Source qangle 'pitch yaw roll' -> world direction of the entity's forward axis, as text."""
    try:
        pitch, yaw = [math.radians(float(x)) for x in str(ang).split()[:2]]
    except ValueError:
        return "?"
    x, y, z = math.cos(pitch) * math.cos(yaw), math.cos(pitch) * math.sin(yaw), -math.sin(pitch)
    names = {(1, 0, 0): "east (+X)", (-1, 0, 0): "west (-X)", (0, 1, 0): "north (+Y)", (0, -1, 0): "south (-Y)",
             (0, 0, 1): "UP (+Z)", (0, 0, -1): "DOWN (-Z)"}
    nm = names.get((round(x), round(y), round(z))) if max(abs(x - round(x)), abs(y - round(y)), abs(z - round(z))) < 0.01 else None
    return f"({x:.2f}, {y:.2f}, {z:.2f})" + (f" = {nm}" if nm else "")

# ---- reading entities from a .vmap (binary DMX "binary 9" as saved by CS2 Hammer, or KeyValues2 text) ----

def read_binary_dmx(d: bytes):
    """Parse a binary DMX file (encoding 'binary 9', e.g. a CS2 .vmap) -> list of elements
    {"type": str, "name": str, "attrs": {name: (basetype, is_array, value)}, "offs": {name: byte offset of the value (arrays: first item)}}.
    Element-reference values are element indexes (-1 = none). The offsets are for patching values in place. Parsed by _DmxDoc.
    The last two results are kept (passes in a row read the same unchanged vmaps), so callers must treat them as read-only.
    Raises ValueError if the layout does not add up (so callers can fall back)."""
    import hashlib
    key = (len(d), hashlib.blake2b(d, digest_size=16).digest())
    if key in _DMX_PARSE_CACHE:
        return _DMX_PARSE_CACHE[key]
    head = d[:80].split(b"\n", 1)[0].decode("latin-1", errors="ignore")
    if "encoding binary 9" not in head:
        raise ValueError(f"unsupported DMX header: {head.strip()[:60]}")
    try:
        doc = _DmxDoc(bytes(d), offsets=True)
    except (struct.error, IndexError, KeyError) as ex:
        raise ValueError(f"binary DMX parse failed: {ex}")
    idx = {id(e): i for i, e in enumerate(doc.els)}

    def conv(bt, v):
        if bt == 1:
            return -1 if v is None else idx[id(v)]
        if bt == 4:
            return bool(v)
        if bt == 5 and not v.isascii():
            return v.encode("utf-8", "surrogateescape").decode("utf-8", "replace")
        if bt == 7:
            return v & 0xFFFFFFFF
        return v
    out = []
    for e in doc.els:
        el = {"type": e.type, "name": e.name, "attrs": {}}
        for name, t, v in e.attrs:
            bt = t - 32 if t >= 32 else t
            if bt in (1, 4, 5, 7):                       # the rest is already in the old reader's form
                v = [conv(bt, x) for x in v] if t >= 32 else conv(bt, v)
            el["attrs"][name] = (bt, t >= 32, v)
        if e.attrs:
            el["offs"] = e.offs
        out.append(el)
    while len(_DMX_PARSE_CACHE) >= 2:                    # the last two maps parsed (a main map and its 3D skybox map)
        _DMX_PARSE_CACHE.pop(next(iter(_DMX_PARSE_CACHE)))
    _DMX_PARSE_CACHE[key] = out
    return out


_DMX_PARSE_CACHE = {}      # read_binary_dmx: (size, content hash) -> elements of the last file parsed
_DMX_DOC_RO = {}           # _dmx_doc_ro: (size, content hash) -> _DmxDoc of the last two maps parsed


def _dmx_doc_ro(data):
    """_DmxDoc(data) for a pass that only READS the map: the reports at the end of a run (missing entities, never enabled, dropped IO)
    read the same unchanged maps one after another, and each parsed them again. Callers must not change the document."""
    import hashlib
    key = (len(data), hashlib.blake2b(data, digest_size=16).digest())
    doc = _DMX_DOC_RO.get(key)
    if doc is None:
        doc = _DmxDoc(data)
        while len(_DMX_DOC_RO) >= 2:                     # the last two maps (a main map and its 3D skybox map)
            _DMX_DOC_RO.pop(next(iter(_DMX_DOC_RO)))
        _DMX_DOC_RO[key] = doc
    return doc

def _fmt_vec(v, nd=1) -> str:
    return " ".join(f"{x:.{nd}f}".rstrip("0").rstrip(".") if nd else str(x) for x in v)

def vmap_entities(path: str):
    """Entities in a .vmap (cached until the file changes) -> see _vmap_entities"""
    try:
        ver = _vmap_version(path)
    except OSError as ex:
        return [], f"cannot read: {ex}"
    return _vmap_entities(path, ver)


@lru_cache(maxsize=8)
def _vmap_entities(path: str, _version=None):
    """Entities in a .vmap -> ([{"cls", "name", "origin", "angles", "props"}], error text or "").
    props = every keyvalue as text. Binary DMX (CS2 Hammer's default) and KeyValues2 text are both read."""
    try:
        data = _vmap_read(path)
    except Exception as ex:
        return [], f"cannot read: {ex}"
    ents = []
    if b"encoding binary" in data[:100]:
        try:
            els = read_binary_dmx(data)
        except ValueError as ex:
            return [], str(ex)
        for e in els:
            if e["type"] != "CMapEntity":
                continue
            ep = e["attrs"].get("entity_properties")
            if not ep or not (0 <= ep[2] < len(els)):
                continue
            props = {k: str(v[2]) for k, v in els[ep[2]]["attrs"].items() if v[0] == 5 and not v[1]}
            ents.append({"cls": props.get("classname", ""), "name": props.get("targetname", ""),
                         "origin": _fmt_vec(e["attrs"]["origin"][2]) if "origin" in e["attrs"] else "?",
                         "angles": _fmt_vec(e["attrs"]["angles"][2]) if "angles" in e["attrs"] else "?",
                         "props": props})
        return ents, ""
    if "keyvalues2" not in data[:200].decode("latin-1", errors="ignore").lower():
        return [], "unrecognised .vmap format"
    stack, found = [{}], []
    for raw in data.decode("utf-8", errors="ignore").splitlines():
        m = _KV2_LINE_RE.match(raw)
        if m:
            stack[-1][m.group(1)] = m.group(3)
            continue
        ln = raw.strip()
        if ln == "{":
            stack.append({})
        elif ln == "}" and len(stack) > 1:
            blk = stack.pop()
            if blk.get("classname"):
                found.append((blk, stack[-1]))
    for blk, parent in found:      # the parent entity block holds origin/angles (read after it was filled)
        ents.append({"cls": blk.get("classname", ""), "name": blk.get("targetname", ""),
                     "origin": blk.get("origin") or parent.get("origin", "?"),
                     "angles": blk.get("angles") or parent.get("angles", "?"), "props": dict(blk)})
    return ents, ""

def _overlay_texture_size(mat: str):
    """Source1 texture size x $decalscale for an overlay material -> (w, h, scale) or None."""
    try:
        base = mat.replace("\\", "/").lower()
        if base.endswith(".vmat"):
            base = base[:-5]
        if not base.startswith("materials/"):
            base = "materials/" + base           # a .vmf side's material ("brick/wall01") is relative to materials/
        vp, _r = find_in_source1(base + ".vmt")
        if not vp:
            return None
        data = parse_vmt(Path(vp))
        vtf = resolve_vtf(data["basetexture"]) if data.get("basetexture") else None
        if not vtf:
            return None
        h = parse_vtf_header(vtf)
        m = re.search(r'"?\$decalscale"?\s+"?([0-9.]+)', data.get("text", ""), flags=re.I)
        return h["width"], h["height"], float(m.group(1)) if m else 1.0
    except Exception:
        return None

def _addon_texture_size(mat: str):
    """Size of the colour texture the converted addon material actually uses (what Hammer draws with) -> (w, h, 1.0) or None."""
    try:
        if not RUN.addon_dir:
            return None
        base = mat.replace("\\", "/").lower()
        vm = Path(RUN.addon_dir) / (base if base.endswith(".vmat") else base + ".vmat")
        if not vm.is_file():
            return None
        vtxt = vm.read_text(errors="ignore")
        mm = re.search(r'"(?:TextureColor|TextureLayer1Color)"\s+"([^"]+)"', vtxt)
        if not mm:
            return None
        # an animation sheet (F_TEXTURE_ANIMATION / F_FLIPBOOK grid, from a Source1 AnimatedTexture): texture coordinates 0..1 cover ONE
        # cell, so a tile is the cell's size, not the sheet's (mg_divine's mclava: a 512 sheet of 128 frames; sized by the sheet, the
        # lava came out 4 x too big and half a tile off)
        g = re.search(r'"(?:g_vAnimationGrid|g_vFlipbookGrid)"\s+"\[\s*(\d+)\s+(\d+)\s*\]"', vtxt)
        gc, gr = (max(1, int(g.group(1))), max(1, int(g.group(2)))) if g else (1, 1)
        tp = Path(RUN.addon_dir) / mm.group(1)
        if not tp.is_file():
            return None
        hdr = tp.read_bytes()[:32]
        if tp.suffix.lower() == ".tga" and len(hdr) >= 18:
            w, h = struct.unpack("<HH", hdr[12:16])
        elif hdr[:8] == b"\x89PNG\r\n\x1a\n":
            w, h = struct.unpack(">II", hdr[16:24])
        else:
            return None
        return (w / gc, h / gr, 1.0) if w > 0 and h > 0 else None
    except Exception:
        return None

def static_overlay_report(vmap_paths, export_dir: Path):
    """CMapStaticOverlay elements (Hammer's decals / Source1 infodecal+info_overlay) are not CMapEntity, so the
    entity checks never see them. -> report lines: one per overlay with origin, material, whether the mesh is still the
    importer's placeholder (a flat 2x2 quad, angles 0, scale 1) or has been edited, the suggested size from the Source1
    texture, and whether the material exists in the addon / CS2."""
    lines, notes, total, n_ph = [], [], 0, 0
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
        except Exception:
            continue
        if b"encoding binary" not in data[:100]:
            notes.append(f"# {os.path.basename(str(vp))}: not a binary .vmap; overlays not listed")
            continue
        try:
            els = read_binary_dmx(data)
        except ValueError as ex:
            notes.append(f"# {os.path.basename(str(vp))}: {ex}")
            continue
        for e in els:
            if e["type"] != "CMapStaticOverlay":
                continue
            a = e["attrs"]
            total += 1
            mats, pos = [], []
            md = a.get("meshData")
            if md and isinstance(md[2], int) and 0 <= md[2] < len(els):
                mesh = els[md[2]]["attrs"]
                mv = mesh.get("materials")
                mats = list(mv[2]) if mv else []
                vd = mesh.get("vertexData")
                if vd and isinstance(vd[2], int) and 0 <= vd[2] < len(els):
                    for si in els[vd[2]]["attrs"].get("streams", (0, 0, []))[2]:
                        if isinstance(si, int) and 0 <= si < len(els) and els[si]["name"].lower().startswith("position"):
                            pos = list(els[si]["attrs"].get("data", (0, 0, []))[2])
            sc = a["scales"][2] if "scales" in a else (1.0, 1.0, 1.0)
            ang = a["angles"][2] if "angles" in a else (0.0, 0.0, 0.0)
            if pos:
                xs, ys = [q[0] for q in pos], [q[1] for q in pos]
                ext = ((max(xs) - min(xs)) * abs(sc[0]), (max(ys) - min(ys)) * abs(sc[1]))
                is_ph = len(pos) == 4 and all(abs(abs(q[0]) - 1) < 1e-3 and abs(abs(q[1]) - 1) < 1e-3 for q in pos)      # the importer's +-1 quad, whatever its scale / angles / depth
            else:
                ext, is_ph = None, False
            tg = a.get("projectionTargets")
            ntg = len(tg[2]) if tg else 0
            for mat in mats or ["?"]:
                where = "?"
                ts = None
                if mat != "?":
                    rel = mat.replace("\\", "/").lower()
                    if os.path.isfile(str(export_dir / (rel + "_c"))) or os.path.isfile(str(export_dir / rel)):
                        where = "in addon"
                    elif cs2_file_exists(rel + "_c"):
                        where = "in CS2"
                    else:
                        where = "MISSING"
                    ts = _overlay_texture_size(mat)
                if is_ph:
                    n_ph += 1
                    status = "PLACEHOLDER"
                elif ext is None:
                    status = "NO MESH"
                elif ts and abs(ext[0] - ts[0] * ts[2]) <= 0.1 * ts[0] * ts[2] and abs(ext[1] - ts[1] * ts[2]) <= 0.1 * ts[1] * ts[2]:
                    status = "OK (size matches texture)"
                else:
                    status = "EDITED"
                sugg = (f"suggest size {ts[0] * ts[2]:g}x{ts[1] * ts[2]:g} -> scales {ts[0] * ts[2] / 2:g} {ts[1] * ts[2] / 2:g} 1 (mesh is +-1)"
                        if ts else "suggest size: Source1 texture not found")
                cur = f"{ext[0]:g}x{ext[1]:g}" if ext else "?"
                lines.append((mat, f"{status}\t{os.path.basename(str(vp))}\t{_fmt_vec(a['origin'][2]) if 'origin' in a else '?'}\t{mat}\t{where}"
                             f"\tsize={cur}\tscales={_fmt_vec(sc)}\tangles={_fmt_vec(ang)}\t{sugg}"
                             f"\tprojectionTargets={ntg}\tprojectionFar={a.get('projectionFar', (0, 0, '?'))[2]}"
                             f"\thidden={a.get('force_hidden', (0, 0, '?'))[2]}"))
    head = [f"# {total} static overlay(s) (CMapStaticOverlay); {n_ph} still the importer's placeholder quad (2x2, angles 0, scale 1)",
            "# To fix one by hand in Hammer: set its Scale to the 'scales' value (the quad is +-1 so scale = size/2) and rotate it with Angles so the quad lies on the surface. Rerun: it flips to OK / EDITED."]
    return head + notes + [t for _m, t in sorted(lines)]      # grouped by material: overlays of one material share a size

@_cache_per_file_version(maxsize=8)
def _vmf_tree(path: str):
    stack, pending = [("root", {}, [])], ""
    with open(path, encoding="utf-8", errors="replace") as f:
        lines_ = f.read().split("\n")      # (not splitlines(): that also splits at \x1c-\x1e, \x85, ...)
    for raw in lines_:
        ln = raw.strip()
        if ln == "{":
            stack.append((pending, {}, []))
        elif ln == "}":
            node = stack.pop()
            stack[-1][2].append(node)
        elif ln.startswith('"'):
            m = re.match(r'"([^"]*)"\s+"(.*)"\s*$', ln)
            if m:
                stack[-1][1][m.group(1).lower()] = m.group(2)
        elif ln:
            pending = ln
    return stack[0]

def _v_sub(a, b): return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
def _v_dot(a, b): return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
def _v_cross(a, b): return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
def _v_norm(a):
    n = math.sqrt(_v_dot(a, a)) or 1.0
    return [x / n for x in a]

def _vmf_solids(root):
    """-> [[(outward unit normal, point on plane, material)]] one list per convex brush"""
    out = []
    def walk(node):
        for ch in node[2]:
            if ch[0] == "solid":
                faces, pts = [], []
                for sd in ch[2]:
                    if sd[0] != "side":
                        continue
                    pl = [[float(x) for x in t.split()] for t in re.findall(r"\(([^)]*)\)", sd[1].get("plane", ""))]
                    if len(pl) != 3:
                        continue
                    n = _v_norm(_v_cross(_v_sub(pl[1], pl[0]), _v_sub(pl[2], pl[0])))
                    faces.append([n, pl[0], _vmf_mat(sd[1].get("material", "").lower())])
                    pts += pl
                if faces and pts:
                    c = [sum(p[k] for p in pts) / len(pts) for k in range(3)]
                    for f in faces:
                        if _v_dot(f[0], _v_sub(f[1], c)) < 0:
                            f[0] = [-x for x in f[0]]
                    out.append([tuple(f) for f in faces])
            elif ch[0] in ("world", "entity"):
                walk(ch)
    walk(root)
    return out

def _surface_under(solids, p, tol=3.0):
    """nearest brush face the point lies on (within tol units) -> (unit normal, point on the face) or None"""
    best = None
    for faces in solids:
        for n, p0, mat in faces:
            if mat.startswith("tools/") and "nodraw" not in mat:
                continue
            d = _v_dot(n, _v_sub(p, p0))
            if abs(d) > tol:
                continue
            q = [p[k] - n[k] * d for k in range(3)]
            if all(_v_dot(n2, _v_sub(q, p2)) <= 1.0 for n2, p2, _m in faces):
                if best is None or abs(d) < best[0]:
                    best = (abs(d), n, q)
    return (best[1], best[2]) if best else None

def _src_angles_from_axes(x, z):
    """Source QAngle (pitch, yaw, roll) whose forward axis is x and up axis is z (both unit, orthogonal)."""
    pitch = math.degrees(math.asin(max(-1.0, min(1.0, -x[2]))))
    yaw = math.degrees(math.atan2(x[1], x[0])) if abs(x[0]) + abs(x[1]) > 1e-6 else 0.0
    cp, sp = math.cos(math.radians(pitch)), math.sin(math.radians(pitch))
    cy, sy = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    best = (9.0, 0.0)
    for r in range(-180, 180):          # solve roll against Source's AngleVectors up vector
        cr, sr = math.cos(math.radians(r)), math.sin(math.radians(r))
        up = [cr * sp * cy + sr * sy, cr * sp * sy - sr * cy, cr * cp]
        err = sum((up[k] - z[k]) ** 2 for k in range(3))
        if err < best[0]:
            best = (err, float(r))
    return pitch, yaw, best[1]

def _overlay_axes(n, decal_yaw):
    """local axes of the overlay quad. CS2 projects along the overlay's local +Z, so Z points INTO the surface (-normal), Y is the
    texture's up, and X = Y x Z is the viewer's LEFT (the corner x signs are flipped when writing so the image is not mirrored).
    Found by testing: Z = +normal made every overlay invisible; turning it 180 degrees showed them mirrored.
    Walls: Y up the wall; floors/ceilings: viewer's right from the decal's yaw."""
    if abs(n[2]) > 0.9:
        a = math.radians(decal_yaw)
        x = [math.cos(a), math.sin(a), 0.0]
        x = _v_norm(_v_sub(x, [n[k] * _v_dot(x, n) for k in range(3)]))
    else:
        x = _v_norm(_v_cross([0.0, 0.0, 1.0], n))
    return [-q for q in x], [-q for q in n]

def _angles_axes(p, y, r):
    """Source AngleVectors: (forward, up) unit vectors for a QAngle in degrees"""
    sp, cp = math.sin(math.radians(p)), math.cos(math.radians(p))
    sy, cy = math.sin(math.radians(y)), math.cos(math.radians(y))
    sr, cr = math.sin(math.radians(r)), math.cos(math.radians(r))
    return [cp * cy, cp * sy, -sp], [cr * sp * cy + sr * sy, cr * sp * sy - sr * cy, cr * cp]

def fix_static_overlays(vmap_paths, vmf_path: str, in_place=False):
    """Rebuild the importer's placeholder overlay quads: size = Source1 texture x $decalscale, orientation = the brush face under
    the matching infodecal in the .vmf (Z = surface normal), origin moved NORMAL_OFFSET above that face. Only same-size
    values are overwritten (vertex positions, origin, angles), in a COPY of the vmap. -> report lines"""
    lines = []
    try:
        tree = _vmf_tree(vmf_path)
    except Exception as ex:
        return [f"# cannot read {vmf_path}: {ex}"]
    solids = _vmf_solids(tree)
    decals = []
    for ent in [c for c in tree[2] if c[0] == "entity"]:
        kv = ent[1]
        if kv.get("classname", "").lower() in ("infodecal", "info_overlay") and kv.get("texture", kv.get("material")):
            o = [float(x) for x in kv.get("origin", "0 0 0").split()[:3]]
            ang = [float(x) for x in kv.get("angles", "0 0 0").split()[:3]]
            decals.append(dict(tex=_vmf_mat((kv.get("texture") or kv.get("material")).lower().replace("\\", "/")), o=o, yaw=ang[1], used=False))
    lines.append(f"# {len(decals)} infodecal/info_overlay in the .vmf, {len(solids)} brushes. CHANGE = this overlay differs from where the .vmf says it should be ('*' marks the values to change); OK = already right.")
    for vp in vmap_paths:
        try:
            data = bytearray(_vmap_read(vp))
            els = read_binary_dmx(bytes(data))
        except Exception as ex:
            lines.append(f"# {os.path.basename(str(vp))}: {ex}")
            continue
        changed = 0
        for e in els:
            if e["type"] != "CMapStaticOverlay" or "offs" not in e:
                continue
            a, offs = e["attrs"], e["offs"]
            md = a.get("meshData")
            mesh = els[md[2]]["attrs"] if md else {}
            mats = mesh.get("materials", (0, 0, []))[2]
            mat = (mats[0] if mats else "").replace("\\", "/").lower()
            _sc = a["scales"][2] if "scales" in a else (1.0, 1.0, 1.0)
            _an = a["angles"][2] if "angles" in a else (0.0, 0.0, 0.0)
            _ps = []
            if mesh.get("vertexData"):
                for si in els[mesh["vertexData"][2]]["attrs"].get("streams", (0, 0, []))[2]:
                    if els[si]["name"].lower().startswith("position"):
                        _ps = els[si]["attrs"]["data"][2]
            if STATIC_OVERLAY_ONLY_PLACEHOLDERS and in_place and not (len(_ps) == 4 and all(abs(abs(q[0]) - 1) < 1e-3 and abs(abs(q[1]) - 1) < 1e-3 for q in _ps)):
                _fn = ""
                if STATIC_OVERLAY_PROJECTION_FAR and in_place and "projectionFar" in offs and "projectionFar" in a \
                        and abs(a["projectionFar"][2] - float(STATIC_OVERLAY_PROJECTION_FAR)) > 1e-3:
                    struct.pack_into("<f", data, offs["projectionFar"], float(STATIC_OVERLAY_PROJECTION_FAR))
                    _fn = f"; projection depth {a['projectionFar'][2]:g} -> {float(STATIC_OVERLAY_PROJECTION_FAR):g}"
                    changed += 1
                lines.append(f"SKIPPED (not the importer's +-1 quad; left as is{_fn})\t{_fmt_vec(a['origin'][2])}\t{mat}\tmesh corners {[tuple(round(c, 2) for c in q) for q in _ps[:4]]}\tscales {_fmt_vec(_sc)}\tangles {_fmt_vec(_an)}\tprojectionFar {a.get('projectionFar', (0, 0, '?'))[2]}")
                continue
            key = mat[len("materials/"):-5] if mat.startswith("materials/") and mat.endswith(".vmat") else mat
            ox, oy, oz = a["origin"][2]
            cand = [d for d in decals if not d["used"] and d["tex"] == key
                    and sum((d["o"][k] - (ox, oy, oz)[k]) ** 2 for k in range(3)) < 40.0 ** 2]    # the importer puts an overlay exactly 16 units off the .vmf decal (and an edited one can move further); the nearest unused decal of the same texture wins
            if not cand:
                lines.append(f"NO VMF MATCH\t{_fmt_vec(a['origin'][2])}\t{mat}")
                continue
            d = min(cand, key=lambda q: sum((q["o"][k] - (ox, oy, oz)[k]) ** 2 for k in range(3)))
            d["used"] = True
            ts = _overlay_texture_size(mat)
            if not ts:
                lines.append(f"NO TEXTURE\t{_fmt_vec(a['origin'][2])}\t{mat}\t(Source1 texture not found; set SOURCE1_ROOTS)")
                continue
            surf = _surface_under(solids, d["o"])
            if not surf:
                lines.append(f"NO SURFACE\t{_fmt_vec(a['origin'][2])}\t{mat}\t(no brush face within 3 units of the decal origin)")
                continue
            n, q = surf
            xax, zax = _overlay_axes(n, d["yaw"])
            pitch, yaw, roll = _src_angles_from_axes(xax, zax)
            pitch, yaw, roll = (round(_q, 1) + 0.0 for _q in (pitch, yaw, roll))      # no '-0.0'
            w, h = ts[0] * ts[2], ts[1] * ts[2]
            neworg = [q[k] + n[k] * STATIC_OVERLAY_NORMAL_OFFSET for k in range(3)]
            vs = mesh.get("vertexData")
            vd_attr = mesh.get("faceVertexData")
            pos_off = None
            if vs:
                for si in els[vs[2]]["attrs"].get("streams", (0, 0, []))[2]:
                    if els[si]["name"].lower().startswith("position"):
                        pos_off = (els[si]["offs"]["data"], els[si]["attrs"]["data"][2])
            if not pos_off or len(pos_off[1]) != 4 or "origin" not in offs or "angles" not in offs:
                lines.append(f"NO MESH\t{_fmt_vec(a['origin'][2])}\t{mat}")
                continue
            cur_ang = a["angles"][2] if "angles" in a else (0.0, 0.0, 0.0)
            cf, cu = _angles_axes(*cur_ang)
            tf, tu = _angles_axes(pitch, yaw, roll)
            pts = pos_off[1]
            cur_w = (max(q[0] for q in pts) - min(q[0] for q in pts)) * abs(a["scales"][2][0] if "scales" in a else 1.0)
            cur_h = (max(q[1] for q in pts) - min(q[1] for q in pts)) * abs(a["scales"][2][1] if "scales" in a else 1.0)
            rot_ok = _v_dot(cf, tf) > 0.999 and _v_dot(cu, tu) > 0.999
            org_ok = sum((a["origin"][2][k] - neworg[k]) ** 2 for k in range(3)) < 1.0
            size_ok = abs(cur_w - w) < 1.0 and abs(cur_h - h) < 1.0
            lines.append(("OK\t" if rot_ok and org_ok and size_ok else "CHANGE\t") + f"{mat}\t"
                         f"origin {_fmt_vec(a['origin'][2])} -> {_fmt_vec(neworg)}{'' if org_ok else ' *'}\t"
                         f"angles {_fmt_vec(cur_ang)} -> {pitch:.1f} {yaw:.1f} {roll:.1f}{'' if rot_ok else ' *'}\t"
                         f"size {cur_w:g}x{cur_h:g} -> {w:g}x{h:g}{'' if size_ok else ' *'} (mesh corners +-{w / 2:g}, +-{h / 2:g}, scale 1 1 1)\t"
                         f"surface normal {_fmt_vec([round(_q, 2) + 0.0 for _q in n], 2)}")
            if not in_place:
                continue
            struct.pack_into("<3f", data, offs["origin"], *neworg)
            struct.pack_into("<3f", data, offs["angles"], pitch, yaw, roll)
            if "scales" in offs:
                struct.pack_into("<3f", data, offs["scales"], 1.0, 1.0, 1.0)
            if STATIC_OVERLAY_PROJECTION_FAR and "projectionFar" in offs:
                struct.pack_into("<f", data, offs["projectionFar"], float(STATIC_OVERLAY_PROJECTION_FAR))
            signs = []
            for i, (px, py, _pz) in enumerate(pos_off[1]):
                sx = 1 if px > 0 else -1
                sy = 1 if py > 0 else -1
                signs.append((sx, sy))
                struct.pack_into("<3f", data, pos_off[0] + 12 * i, sx * w / 2, sy * h / 2, 0.0)
            # texture coordinates: the importer's layout is u = (1 - x)/2, v = (1 + y)/2 per corner; write that (plus the chosen flip) as absolute values
            _flip = STATIC_OVERLAY_TEX_FLIP
            _tc = None
            if vd_attr and mesh.get("edgeVertexIndices") and mesh.get("edgeFaceIndices"):
                for _si in els[mesh["faceVertexData"][2]]["attrs"].get("streams", (0, 0, []))[2]:
                    if els[_si]["name"].lower().startswith("texcoord"):
                        _tc = els[_si]["offs"]["data"]
            if _tc is not None:
                _evi, _efi = mesh["edgeVertexIndices"][2], mesh["edgeFaceIndices"][2]
                for _he, (_vi, _fi) in enumerate(zip(_evi, _efi)):
                    if _fi < 0 or _vi >= len(signs):
                        continue
                    _u, _v = (1 - signs[_vi][0]) / 2, (1 + signs[_vi][1]) / 2
                    if "u" in _flip:
                        _u = 1 - _u
                    if "v" in _flip:
                        _v = 1 - _v
                    struct.pack_into("<2f", data, _tc + 8 * _he, _u, _v)
            changed += 1
            lines.append(f"FIXED\t{mat}\tfind it at current origin {_fmt_vec((ox, oy, oz))}\tset Origin {_fmt_vec(neworg)}\tAngles {pitch:.1f} {yaw:.1f} {roll:.1f}\tScale 1 1 1\tquad corners +-{w / 2:g} x +-{h / 2:g}\ttexture flip '{_flip}'\tsurface normal {_fmt_vec([round(_q, 2) + 0.0 for _q in n], 2)}")
        if changed:
            if in_place:
                bak = _vmap_write(vp, data, "overlayfix")
                lines.append(f"# {changed} overlay(s) patched IN PLACE in {vp}; original saved as {bak}. Reopen the map in Hammer.")
                print(f"  static overlays: patched {changed} in {vp}\n    backup of the original: {bak}")
        elif in_place:
            _msg = (f"# nothing patched in {os.path.basename(str(vp))} (so no backup was made): every overlay is either already right, edited by hand "
                    f"(STATIC_OVERLAY_ONLY_PLACEHOLDERS = {STATIC_OVERLAY_ONLY_PLACEHOLDERS}), or has no matching decal in the .vmf")
            lines.append(_msg)
            print("  static overlays: " + _msg[2:])
    return lines

def _vmf_sides(root):
    """-> [dict(n, d, mat, ua, us, va, vs)] every brush side of the .vmf with its plane and texture mapping"""
    out = []
    def walk(node):
        for ch in node[2]:
            if ch[0] == "solid":
                planes, allpts = [], []
                first = len(out)
                for sd in ch[2]:
                    if sd[0] != "side":
                        continue
                    k = sd[1]
                    pl = [[float(x) for x in t.split()] for t in re.findall(r"\(([^)]*)\)", k.get("plane", ""))]
                    allpts += pl if len(pl) == 3 else []
                    ua = re.match(r"\[([^\]]*)\]\s*(\S+)", k.get("uaxis", ""))
                    va = re.match(r"\[([^\]]*)\]\s*(\S+)", k.get("vaxis", ""))
                    if len(pl) != 3 or not ua or not va:
                        continue
                    try:
                        n = _v_norm(_v_cross(_v_sub(pl[1], pl[0]), _v_sub(pl[2], pl[0])))
                        planes.append((n, _v_dot(n, pl[0])))
                        out.append(dict(n=n, d=_v_dot(n, pl[0]), solid=planes, mat=_vmf_mat(k.get("material", "").lower().replace("\\", "/")).replace(" ", "_"),
                                        us=float(ua.group(2)), vs=float(va.group(2)), disp=any(c[0] == "dispinfo" for c in sd[2]),
                                        ua=[float(x) for x in ua.group(1).split()[:4]], va=[float(x) for x in va.group(1).split()[:4]]))
                    except ValueError:
                        pass
                if allpts:      # make every plane of this brush point outwards, so "inside the brush" can be tested
                    _bb = ([min(q[j] for q in allpts) for j in range(3)], [max(q[j] for q in allpts) for j in range(3)])
                    for _sd in out[first:]:
                        _sd["bb"] = _bb
                    cen = [sum(q[j] for q in allpts) / len(allpts) for j in range(3)]
                    for i, (n_, d_) in enumerate(planes):
                        if _v_dot(n_, cen) - d_ > 0:
                            planes[i] = ([-x for x in n_], -d_)
            elif ch[0] in ("world", "entity"):
                walk(ch)
    walk(root)
    return out

def _solve3(a, b, c):
    """intersection point of three planes (n, d) with n.p = d, or None"""
    cr = _v_cross(b[0], c[0])
    det = _v_dot(a[0], cr)
    if abs(det) < 1e-6:
        return None
    c31, c12 = _v_cross(c[0], a[0]), _v_cross(a[0], b[0])
    return [(a[1] * cr[i] + b[1] * c31[i] + c[1] * c12[i]) / det for i in range(3)]

def _solid_index(sides):
    """.vmf brushes by size: {(dx, dy, dz) rounded to 0.1: [(min corner, [sides of that brush])]}. A copy of a brush that was moved in Hammer keeps its size."""
    import itertools
    groups = {}
    for sd in sides:
        groups.setdefault(id(sd["solid"]), []).append(sd)
    out = {}
    for ss in groups.values():
        pl = ss[0]["solid"]
        if len(pl) < 4 or len(pl) > 24:
            continue
        vs = []
        for a, b, c in itertools.combinations(pl, 3):
            pt = _solve3(a, b, c)
            if pt and all(_v_dot(n, pt) - d <= 0.05 for n, d in pl):
                vs.append(pt)
        if not vs:
            continue
        lo = [min(v[k] for v in vs) for k in range(3)]
        hi = [max(v[k] for v in vs) for k in range(3)]
        out.setdefault(tuple(round(hi[k] - lo[k], 1) for k in range(3)), []).append((lo, ss))
    return out

def _moved_brush_targets(me, fcs, solid_idx):
    """Faces of this mesh that match no .vmf plane in place, but belong to a closed piece of geometry that is the same size as a .vmf brush:
    a copy that was moved in Hammer (texture lock kept the mapping, so shift = .vmf shift - translation.axis / scale). Each face found gets
    a synthetic target {ua, va, us, vs} for the moved position. -> number of faces matched"""
    opp, efi = me["edgeOppositeIndices"][2], me["edgeFaceIndices"][2]
    nf = len(me["faceEdgeIndices"][2])
    nxt = me["edgeNextIndices"][2]
    byface = {fc["fi"]: fc for fc in fcs if fc.get("pts")}
    nb = {}
    for fi, he in ((fc["fi"], me["faceEdgeIndices"][2][fc["fi"]]) for fc in byface.values()):
        h, s_ = he, set()
        for _ in range(64):
            oh = opp[h] if h < len(opp) else -1
            if 0 <= oh < len(efi):
                s_.add(efi[oh])
            h = nxt[h]
            if h == he:
                break
        nb[fi] = s_
    seen, found = set(), 0
    for f0, fc0 in byface.items():
        if f0 in seen or not fc0.get("nomatch"):
            continue
        comp, q = [], [f0]
        seen.add(f0)
        while q:
            f = q.pop()
            comp.append(f)
            for g in nb.get(f, ()):
                if g in byface and g not in seen and 0 <= g < nf:
                    seen.add(g)
                    q.append(g)
        allp = [pt for f in comp for pt in byface[f]["pts"]]
        lo = [min(pt[k] for pt in allp) for k in range(3)]
        hi = [max(pt[k] for pt in allp) for k in range(3)]
        dm = [hi[k] - lo[k] for k in range(3)]
        cands = []
        for dx in (-0.1, 0.0, 0.1):
            for dy in (-0.1, 0.0, 0.1):
                for dz in (-0.1, 0.0, 0.1):
                    cands += solid_idx.get((round(dm[0] + dx, 1), round(dm[1] + dy, 1), round(dm[2] + dz, 1)), [])
        best = None
        for slo, ss in cands:
            T = [lo[k] - slo[k] for k in range(3)]
            good = 0
            for f in comp:
                c_ = byface[f]
                q_ = [[pt[k] - T[k] for k in range(3)] for pt in c_["pts"]]
                if any(sd["mat"] == c_["key"] and abs(abs(_v_dot(sd["n"], c_["n"])) - 1) < 1e-3 and all(abs(_v_dot(sd["n"], x) - sd["d"]) < 0.6 for x in q_) for sd in ss):
                    good += 1
            if best is None or good > best[0]:
                best = (good, T, ss)
        if not best or best[0] < 0.9 * len(comp):
            continue
        T, ss = best[1], best[2]
        for f in comp:
            c_ = byface[f]
            if not c_.get("nomatch"):
                continue
            q_ = [[pt[k] - T[k] for k in range(3)] for pt in c_["pts"]]
            hit = [sd for sd in ss if sd["mat"] == c_["key"] and abs(abs(_v_dot(sd["n"], c_["n"])) - 1) < 1e-3 and all(abs(_v_dot(sd["n"], x) - sd["d"]) < 0.6 for x in q_)]
            if not hit or len({(tuple(sd["ua"]), tuple(sd["va"]), sd["us"], sd["vs"]) for sd in hit}) != 1:
                continue
            sd = hit[0]
            if not sd["us"] or not sd["vs"] or len(sd["ua"]) != 4 or len(sd["va"]) != 4:
                continue
            ua, va = list(sd["ua"]), list(sd["va"])
            ua[3] -= sum(T[k] * ua[k] for k in range(3)) / sd["us"]
            va[3] -= sum(T[k] * va[k] for k in range(3)) / sd["vs"]
            c_["tgt"] = dict(ua=ua, va=va, us=sd["us"], vs=sd["vs"])
            c_["nomatch"] = False
            found += 1
    return found

def _affine_fit2d(src, dst):
    """Least-squares 2D affine map src -> dst: ((a0, a1, a2), (b0, b1, b2)) with u' = a0*u + a1*v + a2, v' = b0*u + b1*v + b2; None if degenerate."""
    n = len(src)
    A = [[sum(s_[i] * s_[j] for s_ in src) for j in range(2)] + [sum(s_[i] for s_ in src)] for i in range(2)]
    A.append([sum(s_[j] for s_ in src) for j in range(2)] + [float(n)])
    out = []
    for k in (0, 1):
        M = [A[i][:] + [sum(d_[k] * s_[i] for s_, d_ in zip(src, dst)) if i < 2 else sum(d_[k] for d_ in dst)] for i in range(3)]
        for i in range(3):
            p = max(range(i, 3), key=lambda r: abs(M[r][i]))
            if abs(M[p][i]) < 1e-12:
                return None
            M[i], M[p] = M[p], M[i]
            for j in range(3):
                if j != i:
                    f_ = M[j][i] / M[i][i]
                    M[j] = [a_ - f_ * b_ for a_, b_ in zip(M[j], M[i])]
        out.append(tuple(M[i][3] / M[i][i] for i in range(3)))
    return tuple(out)


def _face_scales_settle(vmaps, vmf_path, why, passes=3):
    """fix_face_scales again, quietly, until it patches nothing: a face several .vmf brushes could match is left as imported on the first
    pass; once that pass has repaired its scale / shift, the next one can tell which brush it is and restores that mapping. Also run after
    steps that add brush faces later (the water pass), so a single run of the script leaves nothing for the next. -> faces patched"""
    import io as _io, contextlib as _cl
    done, prev, todo = 0, {}, list(vmaps)
    for k in range(passes):
        buf = _io.StringIO()
        _FACE_SCALES_PATCHED.clear()
        with _cl.redirect_stdout(buf):
            fix_face_scales(todo, vmf_path, in_place=True)
        got = dict(_FACE_SCALES_PATCHED)
        if not got:
            break
        done += sum(got.values())
        same = [p_ for p_, n_ in got.items() if prev.get(p_) == n_]
        if same:                                     # the same number again: faces flipping between two mappings, not settling
            print(f"  [CHECK] face scales: {', '.join(os.path.basename(x) for x in same)}: {got[same[0]]} face(s) changed again on pass {k + 2} "
                  f"(they do not settle; see the face_scale_fix log). Stopped there")
            break
        prev = got
        todo = [v for v in vmaps if os.path.abspath(str(v)) in got]      # only the maps that still changed
    if done:
        print(f"  face scales: {done} more face(s) settled {why}")
    return done


def _on_plane(n, d, pts, tol):
    """every point within tol of the plane n.x = d (plain loops: this runs millions of times per map)"""
    a, b, c = n[0], n[1], n[2]
    for q in pts:
        x = a * q[0] + b * q[1] + c * q[2] - d
        if x >= tol or x <= -tol:
            return False
    return True


def _in_solid(solid, pts, tol):
    """every point at most tol outside each plane of a brush [(n, d)]"""
    for n_, d_ in solid:
        a, b, c = n_[0], n_[1], n_[2]
        for q in pts:
            if a * q[0] + b * q[1] + c * q[2] - d_ > tol:
                return False
    return True


_FS_MEMO = {}               # fix_face_scales: {"sides": the .vmf's parsed sides, "m": {(material, face corners): (.vmf sides on its plane, how found)}}
_FACE_SCALES_PATCHED = {}   # abspath -> faces the last fix_face_scales call patched in that map (read by the settle passes; they used to
                            # find it by matching the printed text)


def fix_face_scales(vmap_paths, vmf_path: str, in_place=True):
    """Brush faces whose texture scale the importer got wrong (it does not read the Source1 textures): compare every CMapMesh face
    with the .vmf brush side on the same plane + material. Ratio = vmap scale / .vmf scale per axis; outside FACE_SCALE_BAD_RATIO the
    face is broken: scale := scale / ratio and shift := shift * ratio (the importer multiplies the shift by the same factor it divides
    the scale by). A material whose matched faces all share one broken ratio also gets it applied to its unmatched faces.
    Same-size float values only, patched in place with a backup. -> report lines"""
    lo, hi = FACE_SCALE_BAD_RATIO
    _scale_bad = lambda sc: min(abs(sc[0]), abs(sc[1])) < 0.01 or max(abs(sc[0]), abs(sc[1])) > 8      # noqa: E731  only absurd scales are repaired; deliberate ones (0.125, 2, 4...) stay
    lines = []
    try:
        sides = _vmf_sides_of(str(vmf_path)) if vmf_path else []
    except Exception as ex:
        return [f"# cannot read {vmf_path}: {ex}"]
    if _FS_MEMO.get("sides") is not sides:
        _FS_MEMO.clear()
        _FS_MEMO.update(sides=sides, m={})
    _fs_memo = _FS_MEMO["m"]
    idx = {}           # material -> {floor(plane distance): [sides]}   (a face looks in the neighbouring buckets of +d and -d instead of scanning every side)
    _ts_memo = {}
    def _ts_of(mat_):
        if mat_ not in _ts_memo:
            _ts_memo[mat_] = _overlay_texture_size(mat_)
        return _ts_memo[mat_]
    _modal_scale = {}
    _all_idx = None      # every material's sides by plane, for a face whose own material has none
    _alias_by_base = None      # .vmf material file name -> materials, built on first use
    _par_memo = {}             # (material, axis normal) -> that material's normal buckets within 0.99 of it (most faces share one of 6 normals)
    solid_idx = None   # built on first use: .vmf brushes by size (for copies that were moved in Hammer)
    disp_by_mat = {}   # displacement sides: their faces are the displaced grid, not on the flat base plane, so they cannot be matched by plane
    for sd in sides:
        idx.setdefault(sd["mat"], {}).setdefault(tuple(round(x, 3) for x in sd["n"]), {}).setdefault(math.floor(sd["d"]), []).append(sd)
        if sd.get("disp") and sd.get("bb"):
            disp_by_mat.setdefault(sd["mat"], []).append(sd)
    _disp_polys = []   # the displacement sides' flat base faces (polygon, n, d), read on first use

    def _disp_base_point(cands_, P_):
        """a corner of a displacement face (where the displacement moved it) -> the matching corner of the flat base face it maps from"""
        if not _disp_polys:
            try:
                _disp_polys.extend((x_["P"], x_["n"], x_["d"]) for b_ in _vmf_brush_polys(vmf_path) for x_ in b_["sides"] if x_["disp"] and len(x_["P"]) >= 3)
            except Exception:
                _disp_polys.append(None)
        best_ = None
        for c_ in cands_:
            cn_ = c_["n"]
            for q_ in _disp_polys:
                if q_ is None:
                    continue
                dot_ = sum(q_[1][k] * cn_[k] for k in range(3))   # (the two readers of the .vmf may point a side's normal opposite ways)
                if abs(dot_) < 0.999 or abs(q_[2] - (c_["d"] if dot_ > 0 else -c_["d"])) > 0.5:
                    continue
                mid_ = q_[0].mean(0)
                if not all(c_["bb"][0][k] - 1 <= mid_[k] <= c_["bb"][1][k] + 1 for k in range(3)):
                    continue
                n_, d_ = q_[1], q_[2]
                t_ = sum(P_[k] * n_[k] for k in range(3)) - d_
                Pp_ = [P_[k] - n_[k] * t_ for k in range(3)]          # straight back onto the base plane
                for Q_ in q_[0]:
                    g_ = math.dist(Pp_, Q_)
                    if best_ is None or g_ < best_[0]:
                        edge_ = min(math.dist(q_[0][i_], q_[0][i_ - 1]) for i_ in range(len(q_[0])))
                        best_ = (g_, [float(x) for x in Q_] if g_ < 0.5 * edge_ else Pp_)
        return best_[1] if best_ else P_
    lines.append(f"# {len(sides)} brush sides in {os.path.basename(vmf_path) if vmf_path else '(no .vmf: only the texture coordinates are checked)'}. Columns: action, material, faces, detail. "
                 f"A face is broken when its scale is below 0.01 or above 8 AND vmap scale / vmf scale is outside {lo:g}..{hi:g}.")
    for vp in vmap_paths:
        try:
            data = bytearray(_vmap_read(vp))
            if b"encoding binary" not in bytes(data[:100]):
                continue
            els = read_binary_dmx(bytes(data))
        except Exception as ex:
            lines.append(f"# {os.path.basename(str(vp))}: {ex}")
            continue
        stat = __import__("collections").Counter()
        faces = []      # (mat, scale_off, uoff, voff, sc, u, v, ratio or None)
        subs = []       # displacement meshes: (first face, last face + 1, (file offset, values) of the subdivided surface's texture coordinates)
        for e in els:
            if e["type"] != "CMapMesh":
                continue
            a = e["attrs"]
            md = a.get("meshData")
            if not md or not isinstance(md[2], int):
                continue
            o = a["origin"][2] if "origin" in a else (0.0, 0.0, 0.0)
            ident = all(abs(x) < 1e-4 for x in (a["angles"][2] if "angles" in a else (0, 0, 0))) and \
                all(abs(x - 1) < 1e-4 for x in (a["scales"][2] if "scales" in a else (1, 1, 1)))
            me = els[md[2]]["attrs"]
            mats = me.get("materials", (0, 0, []))[2]
            fd, vd = me.get("faceData"), me.get("vertexData")
            if not fd or not vd or not all(k in me for k in ("faceEdgeIndices", "edgeVertexIndices", "edgeNextIndices", "vertexDataIndices")):
                continue
            st = {els[i]["name"].split(":")[0]: els[i] for i in els[fd[2]]["attrs"].get("streams", (0, 0, []))[2] if isinstance(i, int)}
            if not all(k in st for k in ("textureScale", "textureAxisU", "textureAxisV", "materialindex")):
                continue
            if not all("offs" in st[k] and "data" in st[k]["offs"] for k in ("textureScale", "textureAxisU", "textureAxisV")):
                continue
            pos = None
            for si in els[vd[2]]["attrs"].get("streams", (0, 0, []))[2]:
                if isinstance(si, int) and els[si]["name"].lower().startswith("position"):
                    pos = els[si]["attrs"]["data"][2]
            if not pos:
                continue
            tcs, tgs, nrs = None, None, None
            if me.get("faceVertexData") and "edgeVertexDataIndices" in me:
                for si in els[me["faceVertexData"][2]]["attrs"].get("streams", (0, 0, []))[2]:
                    if isinstance(si, int) and els[si]["name"].lower().startswith("texcoord") and "data" in els[si].get("offs", {}):
                        tcs = (els[si]["offs"]["data"], els[si]["attrs"]["data"][2])
                    elif isinstance(si, int) and els[si]["name"].lower().startswith("tangent") and "data" in els[si].get("offs", {}):
                        tgs = (els[si]["offs"]["data"], els[si]["attrs"]["data"][2])
                    elif isinstance(si, int) and els[si]["name"].lower().startswith("normal"):
                        nrs = els[si]["attrs"]["data"][2]
            evd = me["edgeVertexDataIndices"][2] if tcs else []
            evi, nxt, vdi = me["edgeVertexIndices"][2], me["edgeNextIndices"][2], me["vertexDataIndices"][2]
            scs, us, vs_, mis = (st[k]["attrs"]["data"][2] for k in ("textureScale", "textureAxisU", "textureAxisV", "materialindex"))
            _mesh_start = len(faces)
            _sub = None
            try:
                _sdi = me.get("subdivisionData")
                if _sdi and isinstance(_sdi[2], int):
                    for si in els[_sdi[2]]["attrs"].get("streams", (0, 0, []))[2]:
                        if isinstance(si, int) and els[si]["name"].lower().startswith("texcoord") and "data" in els[si].get("offs", {}):
                            _sub = (els[si]["offs"]["data"], els[si]["attrs"]["data"][2])
            except Exception:
                _sub = None
            _fdi = me["faceDataIndices"][2] if "faceDataIndices" in me else None
            for f, he in enumerate(me["faceEdgeIndices"][2]):
                fd_ = _fdi[f] if _fdi and f < len(_fdi) and 0 <= _fdi[f] else f      # face -> face data row (identity in every vmap seen so far)
                if fd_ >= len(scs) or not (0 <= mis[fd_] < len(mats)):
                    continue
                mat = mats[mis[fd_]].replace("\\", "/").lower()
                ratio, uvv, tgt = None, None, None
                cands0 = []
                pts, n, key, nomatch = None, None, None, False
                if ident:
                    pts, hs, h = [], [], he
                    for _ in range(64):
                        pts.append([pos[vdi[evi[h]]][k] + o[k] for k in range(3)])
                        hs.append(h)
                        h = nxt[h]
                        if h == he:
                            break
                    _nw = [0.0, 0.0, 0.0]
                    for _i in range(len(pts)):
                        _c = _v_cross(pts[_i], pts[(_i + 1) % len(pts)])
                        _nw = [_nw[0] + _c[0], _nw[1] + _c[1], _nw[2] + _c[2]]
                    if _v_dot(_nw, _nw) < 1e-2:          # no area (under 0.05 sq units) (two corners on one spot): invisible, and its scale flipped between two .vmf brushes every run
                        stat["face with no area (left alone)"] += 1
                        continue
                    if tcs and len(pts) >= 3 and all(0 <= evd[x] < len(tcs[1]) for x in hs if x < len(evd)) and max(hs) < len(evd):
                        uvv = [(pts[i], evd[hs[i]]) for i in range(len(pts))]
                    if len(pts) >= 3 and sides:
                        n = _v_norm(_nw)                 # the whole polygon's normal: its first three corners can lie on one line (a point
                                                         # added along an edge), which gave no normal, no match, and the material's ratio
                        # a vertex that is a fraction of a unit off (the importer rounds some brush corners) tilts a triangle's normal by ~0.001,
                        # which moves "plane distance" by several units at map coordinates in the thousands: snap near-axis normals to the axis
                        # and measure the distance at the face centre instead of at one corner
                        for _k in range(3):
                            if abs(n[_k]) > 0.999:
                                n = [(1.0 if n[_k] > 0 else -1.0) if j == _k else 0.0 for j in range(3)]
                                break
                        _c0 = [sum(q[j] for q in pts) / len(pts) for j in range(3)]
                        key = mat[len("materials/"):-5] if mat.startswith("materials/") and mat.endswith(".vmat") else mat
                        if key not in idx:
                            # the material was renamed on its way into the vmap (a different folder, e.g. mytextures/stone-blocks for giza/stone-blocks):
                            # the .vmf's material with the same file name stands in for it, if there is exactly one
                            if _alias_by_base is None:
                                _alias_by_base = {}
                                for _k in idx:
                                    _alias_by_base.setdefault(_k.rsplit("/", 1)[-1], set()).add(_k)
                            _al = _alias_by_base.get(key.rsplit("/", 1)[-1], ())
                            if len(_al) == 1:
                                key = next(iter(_al))
                                stat["material renamed in the vmap, matched to the .vmf material with the same file name"] += 1
                        _bk = idx.get(key, {})
                        # a side matches when the normals agree and every vertex of the face lies on its plane (0.6 units: covers the importer's rounding).
                        # Sides are grouped by their own exact normal and looked up by the face centre's distance along that normal: a small tilt of a
                        # triangle's own normal would move its plane distance by metres at map coordinates in the thousands
                        # the .vmf sides on this face's plane depend only on its corners and material: found once per run (this pass runs up to six
                        # times a run - settle passes, the water pass's faces - and the search was most of its time)
                        _mk = (key, tuple(tuple(q) for q in pts))
                        _mh = _fs_memo.get(_mk)
                        if _mh is not None:
                            cands, _st = list(_mh[0]), _mh[1]
                        else:
                            _st = None
                            cands = []
                            _pk = (key, n[0], n[1], n[2])
                            _par = _par_memo.get(_pk)
                            if _par is None:                 # the buckets whose normal agrees with n (was a scan of every bucket for every face)
                                _par = [(_nk, _bb) for _nk, _bb in _bk.items() if not abs(_v_dot(_nk, n)) <= 0.99]
                                if list(n).count(0.0) == 2:
                                    _par_memo[_pk] = _par
                            for _nk, _bb in _par:
                                _fl = math.floor(_v_dot(_nk, _c0))
                                for b_ in (_fl - 1, _fl, _fl + 1):
                                    for s_ in _bb.get(b_, ()):
                                        if _on_plane(s_["n"], s_["d"], pts, 0.6):
                                            cands.append(s_)
                            if not cands:
                                # a sliver (a triangle a fraction of a unit thick, left over when the importer cut a brush into many pieces) has no usable
                                # normal of its own: a vertex that is 0.1 off tilts it by tens of degrees. Ignore the normal and look for any side of this
                                # material whose plane holds every vertex and whose brush contains the whole face
                                for _nk, _bb in _bk.items():
                                    _fl = math.floor(_v_dot(_nk, _c0))
                                    for b_ in (_fl - 1, _fl, _fl + 1):
                                        for s_ in _bb.get(b_, ()):
                                            if _on_plane(s_["n"], s_["d"], pts, 0.6) and _in_solid(s_["solid"], pts, 0.6):
                                                cands.append(s_)
                                if cands:
                                    _st = "sliver triangle matched by its vertices instead of its own normal"
                            if not cands:
                                # vertices a little further off the plane (the importer rounds some corners of rotated brushes by 1-2 units): same lookup with a
                                # 2.5 unit tolerance, only where the normals agree and the whole face lies inside the brush
                                for _nk, _bb in _par:
                                    _fl = math.floor(_v_dot(_nk, _c0))
                                    for b_ in range(_fl - 3, _fl + 4):
                                        for s_ in _bb.get(b_, ()):
                                            if _on_plane(s_["n"], s_["d"], pts, 2.5) and _in_solid(s_["solid"], pts, 2.5):
                                                cands.append(s_)
                                if cands:
                                    _st = "face a little off its .vmf plane (rounded corners) matched with a 2.5 unit tolerance"
                                if not cands:
                                    # a whole flat face parallel to its .vmf plane but pushed out by up to ~6 units (chamfered / rounded pillars): take only the nearest
                                    # such plane, and only if the face is flat (all vertices at one distance), nearly parallel, and inside the brush
                                    _best = []
                                    for _nk, _bb in _bk.items():
                                        if abs(_v_dot(_nk, n)) <= 0.999:
                                            continue
                                        _fl = math.floor(_v_dot(_nk, _c0))
                                        for b_ in range(_fl - 7, _fl + 8):
                                            for s_ in _bb.get(b_, ()):
                                                _ds = [_v_dot(s_["n"], q) - s_["d"] for q in pts]
                                                if max(_ds) - min(_ds) > 0.6 or max(abs(x) for x in _ds) >= 6.0:
                                                    continue
                                                _tol = max(abs(x) for x in _ds) + 0.6
                                                if _in_solid(s_["solid"], pts, _tol):
                                                    _best.append((max(abs(x) for x in _ds), s_))
                                    if _best:
                                        _m = min(x for x, _ in _best)
                                        cands = [s_ for x, s_ in _best if x <= _m + 0.5]
                                        _st = "flat face pushed off its .vmf plane (up to 6 units) matched to the nearest plane"
                            _fs_memo[_mk] = (list(cands), _st)
                        if _st:
                            stat[_st] += 1
                        cands0 = list(cands)
                        if len(cands) > 1:
                            # brushes that overlap in this plane (adjacent blocks, stacked boxes): keep the one the face actually lies inside
                            cen = [sum(q[j] for q in pts) / len(pts) for j in range(3)]
                            cv = [c for c in cands if _in_solid(c["solid"], pts, 0.6)]      # the whole face inside the brush
                            if cv:
                                cands = cv
                            c0 = [c for c in cands if _in_solid(c["solid"], (cen,), 0.6)]
                            if c0:
                                cands = c0
                        if len(cands) > 1:
                            # several brushes share this plane + material (e.g. crates rotated differently on one floor): keep the sides whose texture
                            # axes are the ones stored on this face, then those whose shift agrees with the stored one modulo 16 (the importer's reduction)
                            c1 = [c for c in cands if len(c["ua"]) == 4 and sum(abs(c["ua"][k] - us[fd_][k]) + abs(c["va"][k] - vs_[fd_][k]) for k in range(3)) < 0.02]
                            if c1:
                                cands = c1
                            if len(cands) > 1:
                                c2 = [c for c in cands if len(c["ua"]) == 4 and all(min((c[ax][3] - cur[3]) % 16.0, 16.0 - (c[ax][3] - cur[3]) % 16.0) < 0.1
                                                                                      for ax, cur in (("ua", us[fd_]), ("va", vs_[fd_])))]
                                if c2:
                                    cands = c2
                            if len(cands) > 1 and uvv:
                                # still several (e.g. neighbouring tiles that differ only in shift): the stored texture coordinates of a face the importer got
                                # right follow exactly one of them
                                _tsz = _ts_of(mat)
                                if _tsz:
                                    def _uverr(c):
                                        e_ = 0.0
                                        for (P_, ti_) in uvv:
                                            nu_ = (sum(P_[k] * c["ua"][k] for k in range(3)) / c["us"] + c["ua"][3]) / _tsz[0]
                                            nv_ = (sum(P_[k] * c["va"][k] for k in range(3)) / c["vs"] + c["va"][3]) / _tsz[1]
                                            du_, dv_ = (tcs[1][ti_][0] - nu_) % 1.0, (tcs[1][ti_][1] - nv_) % 1.0
                                            e_ = max(e_, min(du_, 1 - du_), min(dv_, 1 - dv_))
                                        return e_
                                    c3 = [c for c in cands if c["us"] and c["vs"] and len(c["ua"]) == 4 and len(c["va"]) == 4 and _uverr(c) < 0.004]
                                    if c3:
                                        cands = c3
                        if cands:
                            sd = min(cands, key=lambda c: abs(scs[fd_][0] / c["us"] - 1) + abs(scs[fd_][1] / c["vs"] - 1))      # coplanar sides: take the closest scale
                            if sd["us"] and sd["vs"]:
                                ratio = (scs[fd_][0] / sd["us"], scs[fd_][1] / sd["vs"])
                            # unambiguous: every coplanar side of this material maps the texture identically -> its mapping is the truth for this face.
                            # Shifts that differ by whole texture repeats map it identically too (mg_mario_party's box1_correct and box1_6: one
                            # box twice at one spot, U shifts -256 / 256 on a 512 texture; left as imported, the face kept the importer's V shift)
                            _tsz0 = _ts_of(mat)
                            def _sh_eq(a_, b_, n_):
                                if _tsz0 and _tsz0[n_]:
                                    d_ = (a_ - b_) % _tsz0[n_]
                                    return min(d_, _tsz0[n_] - d_) < 0.01
                                return abs(a_ - b_) < 0.01
                            if len(sd["ua"]) == 4 and len(sd["va"]) == 4 and all(
                                    max(abs(c["ua"][k] - sd["ua"][k]) + abs(c["va"][k] - sd["va"][k]) for k in range(3)) < 0.01
                                    and _sh_eq(c["ua"][3], sd["ua"][3], 0) and _sh_eq(c["va"][3], sd["va"][3], 1)
                                    and abs(c["us"] - sd["us"]) < 1e-4 and abs(c["vs"] - sd["vs"]) < 1e-4 for c in cands):
                                tgt = sd
                        else:
                            # displacement: the face lies over a displacement brush of this material (its base block's footprint, any height)
                            # not only absurd scales: the importer also leaves displacement faces at a plausible-looking but wrong ~1/32 scale
                            _ds = [c for c in disp_by_mat.get(key, [])
                                   if abs(_v_dot(c["n"], n)) > 0.3 and all(
                                       c["bb"][0][j] - (16 if abs(c["n"][j]) < 0.5 else 256) <= _c0[j] <= c["bb"][1][j] + (16 if abs(c["n"][j]) < 0.5 else 256)
                                       for j in range(3))]
                            if len(_ds) > 1:      # several displacements stacked over this spot: the one whose base block is closest in height
                                _gap = lambda c: sum(max(c["bb"][0][j] - _c0[j], _c0[j] - c["bb"][1][j], 0.0) for j in range(3) if abs(c["n"][j]) >= 0.5)   # noqa: E731
                                _g0 = min(_gap(c) for c in _ds)
                                _ds = [c for c in _ds if _gap(c) <= _g0 + 24]
                            if len({(tuple(c["ua"]), tuple(c["va"]), c["us"], c["vs"]) for c in _ds}) == 1:
                                tgt = _ds[0]
                                stat["on a displacement (mapping copied from the displacement's base face)"] += 1
                            else:
                                stat["no .vmf brush on this plane + material"] += 1
                                nomatch = True
                        if cands and not tgt:
                            stat["several .vmf brushes with different mappings overlap this face (left as imported)"] += 1
                if tgt is not None and tgt.get("disp") and uvv and _sub:
                    # Source maps a displacement from its flat base face: each corner's coordinates come from where it sits on the base
                    # face, not from where the displacement moved it (projecting the moved corners skewed the whole surface's texture:
                    # ba_jail_os_gulag_d's cliffs at 9625 -5169 2672 stretched)
                    uvv = [(_disp_base_point([tgt], P_), ti_) for P_, ti_ in uvv]
                faces.append(dict(mat=mat, so=st["textureScale"]["offs"]["data"] + 8 * fd_, uo=st["textureAxisU"]["offs"]["data"] + 16 * fd_,
                                  vo=st["textureAxisV"]["offs"]["data"] + 16 * fd_, sc=scs[fd_], u=us[fd_], v=vs_[fd_], ratio=ratio, tgt=tgt,
                                  uv=uvv, tco=tcs[0] if tcs else None, tcd=tcs[1] if tcs else None, tgs=tgs, nrs=nrs,
                                  fi=f, pts=pts if ident else None, n=n, key=key, nomatch=nomatch,
                                  alts=[(c["us"], c["vs"], c["ua"], c["va"]) for c in cands0 if len(c["ua"]) == 4 and len(c["va"]) == 4]))
            if _sub and ident and tcs and len(faces) > _mesh_start:
                subs.append((_mesh_start, len(faces), _sub, tuple(o)))
            if ident and sides and any(fc_["nomatch"] for fc_ in faces[_mesh_start:]) and all(k_ in me for k_ in ("edgeOppositeIndices", "edgeFaceIndices")):
                if solid_idx is None:
                    solid_idx = _solid_index(sides)
                _nm = _moved_brush_targets(me, faces[_mesh_start:], solid_idx)
                if _nm:
                    stat["on a copy of a .vmf brush that was moved in Hammer (mapping copied, shift corrected for the move)"] += _nm
                    stat["no .vmf brush on this plane + material"] -= _nm
            if ident and sides:
                # a sliver (under 1 unit across) with no .vmf side: nothing to copy, and the importer's scale for it is arbitrary (0.0006, 77...). It cannot
                # be seen, so give it the scale most of this material's .vmf sides use instead of leaving a number that looks broken in Hammer
                for fc_ in faces[_mesh_start:]:
                    if not fc_["nomatch"] or fc_["tgt"] or not fc_["pts"] or fc_["key"] not in idx:
                        continue
                    _p = fc_["pts"]
                    if len(_p) != 3:
                        continue
                    _cr = _v_cross(_v_sub(_p[1], _p[0]), _v_sub(_p[2], _p[0]))
                    _L = max(math.dist(_p[0], _p[1]), math.dist(_p[1], _p[2]), math.dist(_p[0], _p[2]))
                    if not _L or math.sqrt(sum(x * x for x in _cr)) / _L >= 1.0:
                        continue
                    if fc_["key"] not in _modal_scale:
                        _cn = __import__("collections").Counter((round(sd_["us"], 4), round(sd_["vs"], 4)) for _b in idx[fc_["key"]].values() for _l in _b.values() for sd_ in _l
                                                                if sd_["us"] and sd_["vs"] and not sd_.get("disp"))
                        _modal_scale[fc_["key"]] = (_cn.most_common(1)[0][0], list(_cn)) if _cn else None
                    if not _modal_scale[fc_["key"]]:
                        continue
                    _ms, _all = _modal_scale[fc_["key"]]
                    if any(abs(fc_["sc"][0] - a_) < 0.02 * a_ and abs(fc_["sc"][1] - b_) < 0.02 * b_ for a_, b_ in _all):
                        continue
                    fc_["tgt"] = dict(ua=list(fc_["u"]), va=list(fc_["v"]), us=_ms[0], vs=_ms[1])
                    fc_["nomatch"] = False
                    stat["sliver with no .vmf side given the material's usual scale"] += 1
                    stat["no .vmf brush on this plane + material"] -= 1
                # same geometry, different material (a water shader, a swapped texture) and an absurd scale: the .vmf face on this plane still
                # says how the original was mapped, so take its mapping rather than leave a scale like 0.002
                for fc_ in faces[_mesh_start:]:
                    if not fc_["nomatch"] or fc_["tgt"] or not fc_["pts"] or not _scale_bad(fc_["sc"]) or fc_["key"].startswith("tools/"):
                        continue
                    if _all_idx is None:
                        _all_idx = {}
                        for _k in idx:
                            if _k.startswith("tools/"):
                                continue
                            for _nkey, _bb_ in idx[_k].items():
                                for _b, _l in _bb_.items():
                                    _all_idx.setdefault(_nkey, {}).setdefault(_b, []).extend(sd_ for sd_ in _l if not sd_.get("disp"))
                    _pp, _nn = fc_["pts"], fc_["n"]
                    _cc = [sum(q[j] for q in _pp) / len(_pp) for j in range(3)]
                    _hit = []
                    for _tol in (0.6, 2.5):
                        for _nk, _bb_ in _all_idx.items():
                            if abs(_v_dot(_nk, _nn)) <= 0.99:
                                continue
                            _fl = math.floor(_v_dot(_nk, _cc))
                            for b_ in range(_fl - 3, _fl + 4):
                                for sd_ in _bb_.get(b_, ()):
                                    if len(sd_["ua"]) == 4 and len(sd_["va"]) == 4 and sd_["us"] and sd_["vs"] \
                                            and all(abs(_v_dot(sd_["n"], q) - sd_["d"]) < _tol for q in _pp) \
                                            and all(_v_dot(n_, q) - d_ <= _tol for n_, d_ in sd_["solid"] for q in _pp):
                                        _hit.append(sd_)
                        if _hit:
                            break
                    if _hit and len({(tuple(h_["ua"]), tuple(h_["va"]), h_["us"], h_["vs"]) for h_ in _hit}) == 1:
                        fc_["tgt"] = dict(ua=list(_hit[0]["ua"]), va=list(_hit[0]["va"]), us=_hit[0]["us"], vs=_hit[0]["vs"])
                        fc_["nomatch"] = False
                        stat["absurd scale on a face whose .vmf brush has a different material: mapping copied from that brush"] += 1
                        stat["no .vmf brush on this plane + material"] -= 1
        per = {}
        for fc in faces:
            per.setdefault(fc["mat"], []).append(fc)
        fixed = {}      # material -> [fixed by match, fixed by material factor, left alone, texture coordinates rewritten]
        uv_done, no_tex = set(), set()
        for mat, fl in per.items():
            matched = [fc["ratio"] for fc in fl if fc["ratio"]]
            bad = [fc["ratio"] for fc in fl if fc["ratio"] and _scale_bad(fc["sc"]) and not (lo <= fc["ratio"][0] <= hi and lo <= fc["ratio"][1] <= hi)]
            fac = None
            if matched and len(bad) >= 0.8 * len(matched):
                rr = sorted(bad)
                fac = rr[len(rr) // 2]
                if sum(1 for r in bad if abs(r[0] / fac[0] - 1) < 0.02 and abs(r[1] / fac[1] - 1) < 0.02) < 0.8 * len(bad):
                    fac = None
            cnt = fixed.setdefault(mat, [0, 0, 0, 0])
            ts_known = bool(_addon_texture_size(mat) or _overlay_texture_size(mat))
            ts = _addon_texture_size(mat) or _overlay_texture_size(mat)         # (width, height, decalscale): the converted addon texture first (what Hammer draws), then the Source1 one
            if not ts and not any(_scale_bad(fc["sc"]) for fc in fl):
                # no Source1 or addon texture: use the size the stored coordinates imply (what Hammer itself used for this material). Not done for
                # materials with broken scales: their stored coordinates may follow either the old or the corrected numbers, so a size inferred from them is a guess
                tv_ = [__import__("collections").Counter(), __import__("collections").Counter()]
                for fc in fl[:400]:
                    if not fc["uv"]:
                        continue
                    (p0, i0) = fc["uv"][0]
                    for ci, ax in ((0, fc["u"]), (1, fc["v"])):
                        for (p1, i1) in fc["uv"][1:]:
                            dp = sum((p1[k] - p0[k]) * ax[k] for k in range(3)) / fc["sc"][ci]
                            du = fc["tcd"][i1][ci] - fc["tcd"][i0][ci]
                            if abs(dp) > 2.0 and abs(du) > 1e-9:
                                tv_[ci][round(dp / du)] += 1
                                break
                if tv_[0] and tv_[1]:
                    (tu_, nu_), (tw_, nw_) = tv_[0].most_common(1)[0], tv_[1].most_common(1)[0]
                    if tu_ > 0 and tw_ > 0 and nu_ >= 0.6 * sum(tv_[0].values()) and nw_ >= 0.6 * sum(tv_[1].values()):
                        ts = (tu_, tw_, 1.0)
            for fc in fl:
                r = fc["ratio"]
                fix_scale = False
                if r and _scale_bad(fc["sc"]) and not (lo <= r[0] <= hi and lo <= r[1] <= hi):
                    fix_scale = True
                elif r and not (lo <= r[0] <= hi and lo <= r[1] <= hi) and all(
                        any(abs(math.log2(max(x, 1e-9)) - round(math.log2(max(x, 1e-9)))) < 0.06 and abs(round(math.log2(max(x, 1e-9)))) >= 3 for x in (r[0], r[1]))
                        for _ in (0,)) and fc["tgt"] is None:
                    # a scale that is not "absurd" (0.016) but exactly a power of two (8x to 512x) away from the one .vmf brush it sits on, with
                    # nothing in the .vmf to explain it: the importer's divide, not a deliberate change
                    fix_scale = True
                elif not r and fac and _scale_bad(fc["sc"]):
                    r, fix_scale = fac, True
                elif not r and _scale_bad(fc["sc"]):
                    cnt[2] += 1
                if fix_scale and (r[0] <= 0 or r[1] <= 0):
                    fix_scale = False
                sc2, u2, v2 = list(fc["sc"]), list(fc["u"]), list(fc["v"])
                tg = fc["tgt"]
                if len(fc.get("alts") or ()) > 1 and any(
                        abs(fc["sc"][0] - a_[0]) <= 1e-4 * max(1.0, abs(a_[0])) and abs(fc["sc"][1] - a_[1]) <= 1e-4 * max(1.0, abs(a_[1]))
                        and all(abs(fc["u"][k] - a_[2][k]) < 0.01 and abs(fc["v"][k] - a_[3][k]) < 0.01 for k in range(4)) for a_ in fc["alts"]):
                    # several .vmf brushes overlap this face and it already carries one of their mappings exactly: left alone. Picking "the
                    # closest" again made it swap between two of them on every run (mg_divine: a sliver on two brushes, 0.25 x 0.25 and 0.125 x 0.002)
                    fix_scale, tg = False, None
                # a face the turned-texture step (MIRRORED_TEXTURE_FIX) turned to run with its surface: its axes are the .vmf's reversed on
                # purpose, so they are not "restored" (that undid the fix on every run: mg_tomgreens' dodgeball CT platform stayed dark)
                turned_ = bool(tg) and MIRRORED_TEXTURE_FIX and all(abs(fc["u"][k] + tg["ua"][k]) < 0.01 and abs(fc["v"][k] + tg["va"][k]) < 0.01 for k in range(3)) \
                    and abs(fc["sc"][0] - tg["us"]) <= 1e-4 * max(1.0, abs(tg["us"])) and abs(fc["sc"][1] - tg["vs"]) <= 1e-4 * max(1.0, abs(tg["vs"]))
                if turned_:
                    cnt[2] += 0
                elif tg and tg["us"] and tg["vs"] and (abs(fc["sc"][0] - tg["us"]) > 1e-4 * max(1.0, abs(tg["us"])) or abs(fc["sc"][1] - tg["vs"]) > 1e-4 * max(1.0, abs(tg["vs"]))
                                                     or any(abs(fc["u"][k] - tg["ua"][k]) > 0.01 or abs(fc["v"][k] - tg["va"][k]) > 0.01 for k in range(4))):
                    # the importer reduces the shift (to 0..16) and rounds the axes; the .vmf values are the original mapping
                    sc2, u2, v2 = [tg["us"], tg["vs"]], list(tg["ua"]), list(tg["va"])
                    struct.pack_into("<2f", data, fc["so"], *sc2)
                    struct.pack_into("<4f", data, fc["uo"], *u2)
                    struct.pack_into("<4f", data, fc["vo"], *v2)
                    cnt[0] += 1
                    fix_scale = True
                elif fix_scale:
                    sc2 = [fc["sc"][0] / r[0], fc["sc"][1] / r[1]]
                    u2[3], v2[3] = fc["u"][3] * r[0], fc["v"][3] * r[1]
                    struct.pack_into("<2f", data, fc["so"], *sc2)
                    struct.pack_into("<f", data, fc["uo"] + 12, u2[3])
                    struct.pack_into("<f", data, fc["vo"] + 12, v2[3])
                    cnt[0 if fc["ratio"] else 1] += 1
                # stored texture coordinates: Hammer draws these, not the scale/shift numbers (those only matter once a face is edited).
                # Source1 formula (verified on this vmap): u = (P.axisU / scaleU + shiftU) / texture width, P = world position
                if ts and fc["uv"] and not _scale_bad(sc2):
                    wrongs = fix_scale and ts_known      # a size inferred from the stored coordinates is only trusted to repair faces that disagree with their numbers
                    if not wrongs:
                        for (P, ti) in fc["uv"]:           # does every stored coordinate equal the formula (up to whole texture repeats)?
                            nu = (sum(P[k] * u2[k] for k in range(3)) / sc2[0] + u2[3]) / ts[0]
                            nv = (sum(P[k] * v2[k] for k in range(3)) / sc2[1] + v2[3]) / ts[1]
                            du, dv = (fc["tcd"][ti][0] - nu) % 1.0, (fc["tcd"][ti][1] - nv) % 1.0
                            if min(du, 1 - du) > 0.003 or min(dv, 1 - dv) > 0.003:
                                wrongs = True
                                break
                    if wrongs:
                        for (P, ti) in fc["uv"]:
                            if (fc["tco"], ti) in uv_done:
                                continue
                            uv_done.add((fc["tco"], ti))
                            nu = (sum(P[k] * u2[k] for k in range(3)) / sc2[0] + u2[3]) / ts[0]
                            nv = (sum(P[k] * v2[k] for k in range(3)) / sc2[1] + v2[3]) / ts[1]
                            struct.pack_into("<2f", data, fc["tco"] + 8 * ti, nu, nv)
                            fc.setdefault("newtc", {})[ti] = (nu, nv)
                        cnt[3] += 1
                elif fix_scale and not ts:
                    cnt[2] += 0
                    no_tex.add(mat)
        # tangents: Hammer stores one per face corner (the direction of increasing U across the face, w = +-1 handedness) and normal-mapped
        # materials are lit with them. They were left pointing along the OLD texture axis on every face whose coordinates were rewritten.
        # Hammer's rule, checked against 156,000 untouched face corners of the goldeneye vmap (99.0% match): T = the surface direction in which
        # U grows and V stays constant (from the face's positions and texture coordinates), projected perpendicular to the stored normal;
        # w = +1 when cross(normal, T) points the way V grows. A face is only touched when its OLD tangent followed that rule with its OLD
        # coordinates (displacements and other odd faces do not, and are left alone).
        n_tan = n_tan_skip = 0
        def _face_tangents(fc_, tc_of):
            out_ = {}
            P_ = [p_ for (p_, _t) in fc_["uv"]]
            UV_ = [tc_of(t_) for (_p, t_) in fc_["uv"]]
            for i_ in range(1, len(P_) - 1):
                e1_, e2_ = _v_sub(P_[i_], P_[0]), _v_sub(P_[i_ + 1], P_[0])
                du1, dv1, du2, dv2 = UV_[i_][0] - UV_[0][0], UV_[i_][1] - UV_[0][1], UV_[i_ + 1][0] - UV_[0][0], UV_[i_ + 1][1] - UV_[0][1]
                det = du1 * dv2 - du2 * dv1
                if abs(det) < 1e-12:
                    continue
                T_ = [(e1_[k] * dv2 - e2_[k] * dv1) / det for k in range(3)]
                B_ = [(e2_[k] * du1 - e1_[k] * du2) / det for k in range(3)]
                for (_p, t_) in fc_["uv"]:
                    nn_ = fc_["nrs"][t_]
                    ln_ = math.sqrt(_v_dot(nn_, nn_))
                    if ln_ < 1e-9:
                        continue
                    nn_ = [c / ln_ for c in nn_[:3]]
                    d_ = _v_dot(nn_, T_)
                    Tp = [T_[k] - nn_[k] * d_ for k in range(3)]
                    lt_ = math.sqrt(_v_dot(Tp, Tp))
                    if lt_ < 1e-9:
                        continue
                    Tp = [c / lt_ for c in Tp]
                    out_[t_] = (Tp, 1.0 if _v_dot(_v_cross(nn_, Tp), B_) > 0 else -1.0)
                return out_
            return out_
        for fc in faces:
            if not fc.get("newtc") or not fc.get("tgs") or not fc.get("nrs") or not fc["uv"]:
                continue
            try:
                old_ = _face_tangents(fc, lambda t_: fc["tcd"][t_])
                new_ = _face_tangents(fc, lambda t_: fc["newtc"].get(t_, tuple(fc["tcd"][t_][:2])))
                tgo, tgd = fc["tgs"]
                ok_ = bool(old_) and len(old_) == len(fc["uv"]) and len(new_) == len(old_) and all(
                    _v_dot(old_[t_][0], tgd[t_][:3]) > 0.999 and old_[t_][1] == tgd[t_][3] for t_ in old_)
                if not ok_:
                    n_tan_skip += 1
                    continue
                for t_, (T_, w_) in new_.items():
                    struct.pack_into("<4f", data, tgo + 16 * t_, T_[0], T_[1], T_[2], w_)
                n_tan += 1
            except Exception:
                n_tan_skip += 1
        if n_tan:
            stat["tangents recomputed to follow the rewritten texture coordinates"] += n_tan
        if n_tan_skip:
            stat["faces whose old tangent did not follow its coordinates (tangent left as is)"] += n_tan_skip
        # displacements keep their own copy of the texture coordinates for every vertex of the subdivided surface; Hammer draws these, so when the
        # corner coordinates of a base face changed they have to move with them: for each face the old -> new corner mapping is a 2D affine map
        n_sub = 0
        stale_disp = []
        for (_f0, _f1, (_so, _sv), _org) in subs:
            try:
                _fits = []
                for fc_ in faces[_f0:_f1]:
                    if not fc_["uv"] or not fc_.get("newtc"):
                        continue
                    _src = [tuple(fc_["tcd"][ti_][:2]) for (_P, ti_) in fc_["uv"]]
                    _dst = [fc_["newtc"].get(ti_, tuple(fc_["tcd"][ti_][:2])) for (_P, ti_) in fc_["uv"]]
                    if len(_src) < 3 or max(abs(a_[0] - b_[0]) + abs(a_[1] - b_[1]) for a_, b_ in zip(_src, _dst)) < 1e-4:
                        continue
                    _fit = _affine_fit2d(_src, _dst)
                    if _fit:
                        _us, _vs = [q[0] for q in _src], [q[1] for q in _src]
                        _fits.append((_fit, min(_us), max(_us), min(_vs), max(_vs)))
                        # the corners take the same map as the surface table, so they agree with it exactly (the importer laid both out
                        # from the flat base face; corner coordinates worked out from where a displacement moved its corners did not
                        # fit one map, and the surface stretched against its corners)
                        (a0, a1, a2), (b0, b1, b2) = _fit
                        for (_P, ti_), (u_, v_) in zip(fc_["uv"], _src):
                            nu_, nv_ = a0 * u_ + a1 * v_ + a2, b0 * u_ + b1 * v_ + b2
                            if abs(nu_ - fc_["newtc"].get(ti_, (u_, v_))[0]) + abs(nv_ - fc_["newtc"].get(ti_, (u_, v_))[1]) > 1e-6:
                                struct.pack_into("<2f", data, fc_["tco"] + 8 * ti_, nu_, nv_)
                                fc_["newtc"][ti_] = (nu_, nv_)
                for i_, (u_, v_) in enumerate(_sv if _fits else ()):
                    _best = None
                    for (_fit, u0, u1, v0, v1) in _fits:
                        mu_, mv_ = 0.02 * (u1 - u0) + 1e-3, 0.02 * (v1 - v0) + 1e-3
                        if u0 - mu_ <= u_ <= u1 + mu_ and v0 - mv_ <= v_ <= v1 + mv_:
                            _area = (u1 - u0) * (v1 - v0)
                            if _best is None or _area < _best[0]:
                                _best = (_area, _fit)
                    if _best:
                        (a0, a1, a2), (b0, b1, b2) = _best[1]
                        struct.pack_into("<2f", data, _so + 8 * i_, a0 * u_ + a1 * v_ + a2, b0 * u_ + b1 * v_ + b2)
                        n_sub += 1
                # entries that still lie outside every face's corner range were not matched to a face: the table is out of date for this mesh
                _boxes = []
                for fc_ in faces[_f0:_f1]:
                    if fc_["uv"]:
                        _c = [fc_.get("newtc", {}).get(ti_, tuple(fc_["tcd"][ti_][:2])) for (_P, ti_) in fc_["uv"]]
                        _du, _dv = max(q[0] for q in _c) - min(q[0] for q in _c), max(q[1] for q in _c) - min(q[1] for q in _c)
                        _boxes.append((min(q[0] for q in _c) - 0.02 * _du - 1e-3, max(q[0] for q in _c) + 0.02 * _du + 1e-3,
                                       min(q[1] for q in _c) - 0.02 * _dv - 1e-3, max(q[1] for q in _c) + 0.02 * _dv + 1e-3))
                if _boxes:
                    _cur = struct.unpack_from("<%df" % (2 * len(_sv)), data, _so)
                    _out = sum(1 for i_ in range(len(_sv)) if not any(b0 <= _cur[2 * i_] <= b1 and c0 <= _cur[2 * i_ + 1] <= c1 for (b0, b1, c0, c1) in _boxes))
                    if _out > 0.25 * len(_sv):
                        stale_disp.append(_org)
            except Exception as ex_:
                lines.append(f"# displacement texture coordinates not updated for one mesh: {ex_}")
        if n_sub:
            stat["displacement surface texture coordinates moved with their base face"] += n_sub
        if stale_disp:
            lines.append(f"# {len(stale_disp)} displacement mesh(es) still have an out-of-date subdivided-surface texture table (origins): "
                         + "; ".join("%.0f %.0f %.0f" % o_ for o_ in stale_disp))
            print(f"  [NOTE] {len(stale_disp)} displacement mesh(es) look unfinished in Hammer (stale subdivision texture table, usually from a map fixed on an earlier run). "
                  "Select them and nudge one step and back to rebuild it. Origins: " + "; ".join("%.0f %.0f %.0f" % o_ for o_ in stale_disp[:12]))
        if no_tex:
            print("  [NOTE] face scales: no texture size known for " + ", ".join(sorted(no_tex)[:6]) + ": their texture coordinates were NOT rewritten (see the face_scale_fix log)")
        total = sum(c[0] + c[1] + c[3] for c in fixed.values())
        _tg = sum(1 for fc in faces if fc["tgt"])
        lines.append(f"# {os.path.basename(str(vp))}: {len(faces)} brush faces, {_tg} matched to exactly one .vmf mapping" +
                     "".join(f"; {_n} faces: {_k}" for _k, _n in stat.items()))
        print(f"  face scales: {_tg} of {len(faces)} brush faces matched to the .vmf" + "".join(f"; {_n} {_k}" for _k, _n in stat.items()))
        for mat, (a_, b_, c_, d_) in sorted(fixed.items()):
            if a_ or b_ or c_ or d_:
                if a_ or b_ or d_:
                    lines.append(f"FIXED\t{mat}\t{a_ + b_} faces re-scaled ({a_} matched to the .vmf, {b_} by the material's common factor), {d_} faces with texture coordinates rewritten"
                                 + (f"; {c_} out-of-range faces without a .vmf match left alone" if c_ else "")
                                 + ("; no texture size known, so its texture coordinates could NOT be rewritten" if mat in no_tex else ""))
                else:
                    lines.append(f"NOT FIXED\t{mat}\t{c_} faces\tscale out of range (<0.01 or >8) but no .vmf side matches the face")
        if total and in_place:
            bak = _vmap_write(vp, data, "scalefix")
            lines.append(f"# {total} face(s) patched (scale/shift and/or texture coordinates) IN PLACE in {vp}; original saved as {bak}. Reopen the map in Hammer.")
            print(f"  face scales: patched {total} faces in {vp}\n    backup of the original: {bak}")
            _FACE_SCALES_PATCHED[os.path.abspath(str(vp))] = total
        elif total:
            lines.append(f"# {total} face(s) would be fixed (FACE_SCALE_FIX in place is off)")
        else:
            lines.append(f"# {os.path.basename(str(vp))}: no broken face scales found (nothing patched, no backup)")
            print(f"  face scales: no broken face scales in {os.path.basename(str(vp))}")
    return lines

def report_absurd_scale_faces(vmap_paths, vmf_path: str):
    """Every brush face whose texture scale is still out of range (<0.01 or >8) after the repair, with what the Source1 files say about its
    material: the .vmf's scales for that material, the .vmt's $basetexture and texture size. A face whose scale equals one the .vmf
    really uses for that material is legitimate (deliberate stretched scales); the rest are broken, and a material whose .vmf sides all
    share one scale tells you what these faces should be. Needs no extra files. -> report lines (also lists every face's position)."""
    import collections
    lines = []
    try:
        sides = _vmf_sides_of(str(vmf_path)) if vmf_path else []
    except Exception:
        sides = []
    bymat = collections.defaultdict(list)
    for sd in sides:
        bymat[sd["mat"]].append(sd)
    rows = []        # (material, mesh label, centroid, scale, shift)
    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
            if b"encoding binary" not in data[:100]:
                continue
            els = read_binary_dmx(data)
        except Exception:
            continue
        par = {}
        for i, e in enumerate(els):
            ch = e["attrs"].get("children")
            if ch and isinstance(ch[2], list):
                for c in ch[2]:
                    if isinstance(c, int):
                        par[c] = i
        for ei, e in enumerate(els):
            if e["type"] != "CMapMesh":
                continue
            a = e["attrs"]
            md = a.get("meshData")
            if not md or not isinstance(md[2], int):
                continue
            o = a["origin"][2] if "origin" in a else (0.0, 0.0, 0.0)
            me = els[md[2]]["attrs"]
            mats = me.get("materials", (0, 0, []))[2]
            fd, vd = me.get("faceData"), me.get("vertexData")
            if not fd or not vd:
                continue
            st = {els[i]["name"].split(":")[0]: els[i] for i in els[fd[2]]["attrs"].get("streams", (0, 0, []))[2] if isinstance(i, int)}
            if not all(k in st for k in ("textureScale", "textureAxisU", "textureAxisV", "materialindex")):
                continue
            pos = None
            for si in els[vd[2]]["attrs"].get("streams", (0, 0, []))[2]:
                if isinstance(si, int) and els[si]["name"].lower().startswith("position"):
                    pos = els[si]["attrs"]["data"][2]
            if not pos:
                continue
            evi, nxt, vdi = me["edgeVertexIndices"][2], me["edgeNextIndices"][2], me["vertexDataIndices"][2]
            scs, us, vs_, mis = (st[k]["attrs"]["data"][2] for k in ("textureScale", "textureAxisU", "textureAxisV", "materialindex"))
            owner, p_ = "world", par.get(ei)
            while p_ is not None:
                if els[p_]["type"] == "CMapEntity":
                    ep = els[p_]["attrs"].get("entity_properties")
                    cl = els[ep[2]]["attrs"].get("classname", (0, 0, ""))[2] if ep and isinstance(ep[2], int) and ep[2] >= 0 else ""
                    owner = ("entity " + cl) if cl else "entity"
                    break
                p_ = par.get(p_)
            if owner.startswith("entity trigger_"):
                continue                         # triggers are never drawn: their texture scale does not matter
            for f, he in enumerate(me["faceEdgeIndices"][2]):
                if f >= len(scs) or not (0 <= mis[f] < len(mats)):
                    continue
                sc = scs[f]
                if not (min(abs(sc[0]), abs(sc[1])) < 0.01 or max(abs(sc[0]), abs(sc[1])) > 8):
                    continue
                mat = mats[mis[f]].replace("\\", "/").lower()
                if mat.startswith("materials/tools"):
                    continue
                pts, h = [], he
                for _ in range(64):
                    pts.append([pos[vdi[evi[h]]][k] + o[k] for k in range(3)])
                    h = nxt[h]
                    if h == he:
                        break
                cen = [sum(q[j] for q in pts) / len(pts) for j in range(3)]
                key = mat[len("materials/"):-5] if mat.startswith("materials/") and mat.endswith(".vmat") else mat
                rows.append((key, owner, cen, tuple(sc), (us[f][3], vs_[f][3])))
    if not rows:
        return ["# no brush faces with an out-of-range texture scale remain"]
    permat = collections.defaultdict(list)
    for r in rows:
        permat[r[0]].append(r)
    legit_total = 0
    summary, perface = [], []
    for key, rs in sorted(permat.items(), key=lambda kv: -len(kv[1])):
        vsd = bymat.get(key, [])
        vsc = collections.Counter((round(sd["us"], 4), round(sd["vs"], 4)) for sd in vsd)
        info = ""
        try:
            vp_, _r = find_in_source1(key + ".vmt")
            if vp_:
                dd = parse_vmt(Path(vp_))
                vtf = resolve_vtf(dd["basetexture"]) if dd.get("basetexture") else None
                hd = parse_vtf_header(vtf) if vtf else None
                info = f"vmt {os.path.relpath(vp_, SOURCE1_ROOTS[0]) if SOURCE1_ROOTS and str(vp_).startswith(SOURCE1_ROOTS[0]) else vp_}; $basetexture {dd.get('basetexture')}" + (f" ({hd['width']}x{hd['height']})" if hd else "")
            else:
                info = "no .vmt found in the Source1 folders"
        except Exception:
            info = "vmt lookup failed"
        nlegit = 0
        for r in rs:
            legit = any(abs(r[3][0] - a_) <= 0.01 * max(abs(a_), 1e-6) + 1e-4 and abs(r[3][1] - b_) <= 0.01 * max(abs(b_), 1e-6) + 1e-4 for (a_, b_) in vsc)
            nlegit += legit
            perface.append(f"{'SAME AS .VMF' if legit else 'BROKEN'}\t{key}\t{r[1]}\t{r[2][0]:.0f} {r[2][1]:.0f} {r[2][2]:.0f}\t{r[3][0]:.5g} x {r[3][1]:.5g}\tshift {r[4][0]:.1f} {r[4][1]:.1f}")
        legit_total += nlegit
        nbad = len(rs) - nlegit
        dom = vsc.most_common(1)[0] if vsc else None
        if nbad == 0:
            verdict = "all faces use a scale the .vmf also has for this material: legitimate, not broken"
        elif dom and dom[1] >= 0.9 * len(vsd):
            verdict = f"{nbad} broken; every .vmf side of this material uses {dom[0][0]:g} x {dom[0][1]:g}, so that is what they should be"
        elif dom:
            verdict = f"{nbad} broken; the .vmf uses {', '.join(f'{a_:g}x{b_:g} ({n})' for (a_, b_), n in vsc.most_common(3))} for this material (no single answer)"
        else:
            verdict = f"{nbad} broken; material not in the .vmf"
        sample = min((r for r in rs), key=lambda r: min(abs(r[3][0]), abs(r[3][1])))
        summary.append(f"{len(rs)}\t{key}\t{verdict}\tvmap scale e.g. {sample[3][0]:.5g} x {sample[3][1]:.5g}\t{info}")
    lines.append(f"# {len(rows)} brush faces still have a texture scale below 0.01 or above 8 (tools/ materials excluded): {legit_total} equal a scale the .vmf also uses for that material (legitimate), {len(rows) - legit_total} look broken.")
    lines.append("# Per material: faces, material, verdict from the .vmf scales of that material, an example vmap scale, the Source1 .vmt and texture size")
    lines += summary
    lines.append("")
    lines.append("# Every face: verdict, material, owner (world / entity classname), centre x y z, vmap scale, vmap shift")
    lines += perface
    return lines

def find_same_name_elsewhere(missing, per_asset=3):
    """For each missing asset, files with the same name (any folder, any extension) in the Source1 folders and in CS2: a wrong folder or
    extension in the reference is the usual reason something is 'missing'. -> {asset: ['Source1: path', 'CS2: path']}"""
    want = {}
    for a in missing:
        stem = os.path.splitext(os.path.basename(a.lower()))[0]
        if stem:
            want.setdefault(stem, []).append(a)
    found = {a: [] for a in missing}

    def add(stem, label, path):
        for a in want.get(stem, ()):
            if len(found[a]) < per_asset and path.lower() != a.lower() and not any(path in x for x in found[a]):
                found[a].append(f"{label}: {path}")
    try:
        c = cs2_vpk()
        if c.loaded:
            for f in c.files:
                st = os.path.splitext(f.rsplit("/", 1)[-1])[0]
                if st in want:
                    add(st, "CS2", f)
    except Exception:
        pass
    stock = {os.path.normcase(os.path.abspath(str(r_))) for r_ in SOURCE1_STOCK_ROOTS if r_}
    for root in SOURCE1_ROOTS:
        is_stock = os.path.normcase(os.path.abspath(str(root))) in stock
        for rel in _source1_file_list(root, cache=is_stock):
            st = os.path.splitext(rel.rsplit("/", 1)[-1])[0].lower()
            if st in want:
                add(st, "Source1", rel)
    return found


def _source1_file_list(root, cache=False):
    """every file under a Source1 folder's materials / models / sound / sounds / particles, as paths relative to it (walk order).
    cache=True (SOURCE1_STOCK_ROOTS: the extracted game folders, which do not change between runs): the list is kept in
    backups\\source1_file_lists and read back while the folders' top two levels have the same times (a cold walk of the stock folders took
    28 s of a run); delete that folder to rebuild the lists"""
    subs = []
    for sub in ("materials", "models", "sound", "sounds", "particles"):
        try:
            base = find_ci(Path(root), sub)
        except Exception:
            base = None
        if base is not None and Path(base).is_dir():
            subs.append(Path(base))
    stamp, cf = None, None
    if cache:
        try:
            parts = []
            for b_ in subs:
                parts.append(f"{b_.name}:{int(b_.stat().st_mtime)}")
                with os.scandir(b_) as it_:
                    parts += sorted(f"{b_.name}/{d_.name}:{int(d_.stat().st_mtime)}" for d_ in it_ if d_.is_dir())
            import hashlib as _hl
            stamp = f"{len(parts)}:" + _hl.md5("|".join(parts).encode("utf-8", "replace")).hexdigest()
            cf = Path(BACKUP_DIR) / "source1_file_lists" / (_hl.md5(os.path.normcase(os.path.abspath(str(root))).encode("utf-8")).hexdigest()[:16] + ".txt")
            if cf.is_file():
                with open(cf, encoding="utf-8", errors="replace") as f_:
                    head = f_.readline().rstrip("\n")
                    if head == f"{stamp}\t{root}":
                        return [ln.rstrip("\n") for ln in f_]
        except OSError:
            stamp = None
    out = []
    for base in subs:
        for dp, _dn, fn in os.walk(base):
            for f in fn:
                out.append(os.path.relpath(os.path.join(dp, f), root).replace("\\", "/"))
    if stamp is not None and cf is not None:
        try:
            cf.parent.mkdir(parents=True, exist_ok=True)
            cf.write_text(f"{stamp}\t{root}\n" + "".join(x + "\n" for x in out), encoding="utf-8")
        except OSError:
            pass
    return out

# ---- static overlays that sit on brush ENTITIES -> parented translucent quads (CS2 static overlays do not project onto entities) ----

class _DmxEl:
    __slots__ = ("type", "name", "guid", "attrs", "offs")
    def __init__(self, type_, name, guid):
        self.type, self.name, self.guid, self.attrs, self.offs = type_, name, guid, [], None
    def attr(self, name):
        for a_ in self.attrs:
            if a_[0] == name:
                return a_
        return None
    def get(self, name, default=None):
        a_ = self.attr(name)
        return default if a_ is None else a_[2]
    def set(self, name, t, v):
        a_ = self.attr(name)
        if a_:
            a_[1], a_[2] = t, v
        else:
            self.attrs.append([name, t, v])

_DMX_FMT = {2: "<i", 3: "<f", 4: "<B", 7: "<i", 8: "<4B", 9: "<2f", 10: "<3f", 11: "<4f", 12: "<3f", 13: "<4f", 14: "<16f", 15: "<Q", 16: "<B"}
_DMX_ARR = {t: (int(f[1:-1] or 1), f[-1], struct.calcsize(f)) for t, f in _DMX_FMT.items()}   # type -> (values per item, struct letter, item size)

class _DmxDoc:
    """Binary DMX 9 (CS2 .vmap) reader/writer. load()+save() reproduces the original bytes (checked on the jacs / goldeneye /
    tomgreens maps). Element references are objects; new strings are appended to the string table; element order is kept.
    offsets=True also records, per element, the byte offset of each attribute value (e.offs; arrays: the first item)."""
    def __init__(self, data: bytes, offsets=False):
        d = data
        self.head = d[:d.index(b"\n") + 2]
        pos = len(self.head)
        u32 = lambda p_: struct.unpack_from("<I", d, p_)[0]           # noqa: E731
        def cstr(p_):
            e_ = d.index(b"\0", p_)
            return d[p_:e_].decode("utf-8", "surrogateescape"), e_ + 1
        def skip(bt, p_):
            if bt == 5:
                return cstr(p_)[1]
            if bt == 6:
                return p_ + 4 + u32(p_)
            return p_ + struct.calcsize(_DMX_FMT[bt]) if bt != 1 else p_ + 4
        p0 = pos
        npre = u32(pos); pos += 4
        for _ in range(npre):
            na = u32(pos); pos += 4
            for _ in range(na):
                _n, pos = cstr(pos)
                t = d[pos]; pos += 1
                if t >= 32:
                    c = u32(pos); pos += 4
                    for _ in range(c):
                        pos = skip(t - 32, pos)
                else:
                    pos = skip(t, pos)
        self.prefix = d[p0:pos]
        nstr = u32(pos); pos += 4
        self.strings = []
        for _ in range(nstr):
            s_, pos = cstr(pos)
            self.strings.append(s_)
        nel = u32(pos); pos += 4
        self.els = []
        for _ in range(nel):
            ti, ni = struct.unpack_from("<ii", d, pos)
            self.els.append(_DmxEl(self.strings[ti], self.strings[ni] if ni >= 0 else "", d[pos + 8:pos + 24]))
            pos += 24
        for e in self.els:
            na = u32(pos); pos += 4
            for _ in range(na):
                name = self.strings[u32(pos)]; pos += 4
                t = d[pos]; pos += 1
                arr = t >= 32
                bt = t - 32 if arr else t
                def one(p_, inline):
                    if bt == 1:
                        i_ = struct.unpack_from("<i", d, p_)[0]
                        return (self.els[i_] if i_ >= 0 else None), p_ + 4
                    if bt == 5:
                        if inline:
                            return cstr(p_)
                        return self.strings[u32(p_)], p_ + 4
                    if bt == 6:
                        n_ = u32(p_)
                        return d[p_ + 4:p_ + 4 + n_], p_ + 4 + n_
                    f_ = _DMX_FMT[bt]
                    v_ = struct.unpack_from(f_, d, p_)
                    return (v_[0] if len(v_) == 1 else v_), p_ + struct.calcsize(f_)
                if arr:
                    c = u32(pos); pos += 4
                    if offsets:
                        e.offs = e.offs or {}
                        e.offs[name] = pos
                    if bt in _DMX_ARR:                 # fixed-size items: one unpack for the whole array (same values)
                        k_, c_, sz_ = _DMX_ARR[bt]
                        vals = struct.unpack_from("<%d%s" % (c * k_, c_), d, pos)
                        pos += c * sz_
                        v = list(vals) if k_ == 1 else [vals[j_:j_ + k_] for j_ in range(0, c * k_, k_)]
                    else:
                        v = []
                        for _ in range(c):
                            x, pos = one(pos, True)
                            v.append(x)
                else:
                    if offsets:
                        e.offs = e.offs or {}
                        e.offs[name] = pos
                    v, pos = one(pos, False)
                e.attrs.append([name, t, v])
        if pos != len(d):
            raise ValueError(f"DMX parse ended at {pos} of {len(d)} bytes")
        self.root = self.els[0]

    def reachable(self):
        seen, st = set(), [self.root]
        while st:
            e = st.pop()
            if e is None or id(e) in seen:
                continue
            seen.add(id(e))
            for _n, t, v in e.attrs:
                if t == 1:
                    st.append(v)
                elif t == 33:
                    st.extend(v)
        return seen

    def save_bytes(self) -> bytes:
        idx = {id(e): i_ for i_, e in enumerate(self.els)}
        sidx = {s_: i_ for i_, s_ in enumerate(self.strings)}
        strings = list(self.strings)
        def S(s_):
            if s_ not in sidx:
                sidx[s_] = len(strings); strings.append(s_)
            return sidx[s_]
        for e in self.els:
            S(e.type); S(e.name)
            for n_, t, v in e.attrs:
                S(n_)
                if t == 5:
                    S(v)
        def enc(t, v, inline):
            if t & 32:
                if (t - 32) in _DMX_ARR and v:      # fixed-size items: one pack for the whole array (same bytes)
                    k_, c_, _sz = _DMX_ARR[t - 32]
                    try:
                        flat = v if k_ == 1 else [y for x in v for y in x]
                        if len(flat) == len(v) * k_:
                            return struct.pack("<I", len(v)) + struct.pack("<%d%s" % (len(flat), c_), *flat)
                    except (struct.error, TypeError):
                        pass
                return struct.pack("<I", len(v)) + b"".join(enc(t - 32, x, True) for x in v)
            if t == 1:
                return struct.pack("<i", -1 if v is None else idx[id(v)])
            if t == 5:
                return v.encode("utf-8", "surrogateescape") + b"\0" if inline else struct.pack("<I", sidx[v])
            if t == 6:
                return struct.pack("<I", len(v)) + v
            f_ = _DMX_FMT[t]
            return struct.pack(f_, *(v if isinstance(v, (tuple, list)) else (v,)))
        out = bytearray(self.head) + self.prefix + struct.pack("<I", len(strings))
        for s_ in strings:
            out += s_.encode("utf-8", "surrogateescape") + b"\0"
        out += struct.pack("<I", len(self.els))
        for e in self.els:
            out += struct.pack("<ii", sidx[e.type], sidx[e.name]) + e.guid
        for e in self.els:
            out += struct.pack("<I", len(e.attrs))
            for n_, t, v in e.attrs:
                out += struct.pack("<I", sidx[n_]) + bytes([t]) + enc(t, v, False)
        return bytes(out)

def _dmx_clone(e, memo):
    if e is None:
        return None
    if id(e) in memo:
        return memo[id(e)]
    n = _DmxEl(e.type, e.name, bytes(random.getrandbits(8) for _ in range(16)))
    memo[id(e)] = n
    for name, t, v in e.attrs:
        if t == 1:
            v = _dmx_clone(v, memo)
        elif t == 33:
            v = [_dmx_clone(x, memo) for x in v]
        elif isinstance(v, list):
            v = list(v)
        n.attrs.append([name, t, v])
    return n

def _qrot(ang, v):
    """Source/CS2 pitch-yaw-roll rotation of v (roll about X, then pitch about Y, then yaw about Z)."""
    p, y, r = (math.radians(x) for x in ang)
    x, yv, z = v
    cr, sr = math.cos(r), math.sin(r); yv, z = yv * cr - z * sr, yv * sr + z * cr
    cp, sp = math.cos(p), math.sin(p); x, z = x * cp + z * sp, -x * sp + z * cp
    cy, sy = math.cos(y), math.sin(y); x, yv = x * cy - yv * sy, x * sy + yv * cy
    return (x, yv, z)

def _node_world(node, pts, parent_of):
    """node origin/angles/scales applied to local points, then the transforms of the CMapGroup(s) it sits in. Children of a
    brush ENTITY are stored in world space (their own origin is already the world position), so an entity's transform is not applied."""
    def one(nd, ps):
        o, a, s = nd.get("origin") or (0, 0, 0), nd.get("angles") or (0, 0, 0), nd.get("scales") or (1, 1, 1)
        return [tuple(c + o[i] for i, c in enumerate(_qrot(a, (v[0] * s[0], v[1] * s[1], v[2] * s[2])))) for v in ps]
    pts = one(node, pts)
    p = parent_of.get(id(node))
    while p is not None and p.type == "CMapGroup":
        pts = one(p, pts)
        p = parent_of.get(id(p))
    return pts

def _mesh_polys(mesh):
    """-> [(local polygon [(x,y,z)], material path)] for a CMapMesh element."""
    md = mesh.get("meshData")
    if md is None:
        return []
    pos = None
    for s_ in md.get("vertexData").get("streams"):
        if s_.name.startswith("position"):
            pos = s_.get("data")
    mats = md.get("materials") or []
    mi = None
    fd = md.get("faceData")
    if fd is not None:
        for s_ in fd.get("streams"):
            if s_.name.startswith("materialindex"):
                mi = s_.get("data")
    fe, nx, ev, vdi = md.get("faceEdgeIndices"), md.get("edgeNextIndices"), md.get("edgeVertexIndices"), md.get("vertexDataIndices")
    fdi = md.get("faceDataIndices")
    out = []
    if pos is None or fe is None or nx is None or ev is None or vdi is None:
        return out
    for f, he0 in enumerate(fe):
        poly, he = [], he0
        for _ in range(64):
            poly.append(pos[vdi[ev[he]]])
            he = nx[he]
            if he == he0:
                break
        fi = fdi[f] if fdi and f < len(fdi) and fdi[f] >= 0 else f
        m_ = mats[mi[fi]] if mi and 0 <= fi < len(mi) and 0 <= mi[fi] < len(mats) else (mats[0] if mats else "")
        if len(poly) >= 3:
            out.append((poly, str(m_).replace("\\", "/").lower()))
    return out

def _poly_normal(pts):
    nx = ny = nz = 0.0
    for i, p in enumerate(pts):
        q = pts[(i + 1) % len(pts)]
        nx += (p[1] - q[1]) * (p[2] + q[2]); ny += (p[2] - q[2]) * (p[0] + q[0]); nz += (p[0] - q[0]) * (p[1] + q[1])
    l_ = math.sqrt(nx * nx + ny * ny + nz * nz)
    return (nx / l_, ny / l_, nz / l_) if l_ > 1e-9 else None

def _overlap_2d(rect, poly, eps=0.5):
    """rect = (x0, y0, x1, y1), poly = convex [(x, y)] -> True when they overlap by more than eps on every separating axis."""
    axes = [(1.0, 0.0), (0.0, 1.0)]
    for i, p in enumerate(poly):
        q = poly[(i + 1) % len(poly)]
        ex, ey = q[0] - p[0], q[1] - p[1]
        l_ = math.hypot(ex, ey)
        if l_ > 1e-9:
            axes.append((-ey / l_, ex / l_))
    rc = [(rect[0], rect[1]), (rect[2], rect[1]), (rect[2], rect[3]), (rect[0], rect[3])]
    for ax in axes:
        a = [ax[0] * x + ax[1] * y for x, y in rc]
        b = [ax[0] * x + ax[1] * y for x, y in poly]
        if min(max(a), max(b)) - max(min(a), min(b)) <= eps:
            return False
    return True

OVERLAY_ONLY_ATTRS = ("projectionTargets", "renderOrder", "disabledInLowQuality", "useBaseNormals", "projectionFar",
                      "MaterialAdjustmentParamsStruct", "projectOnBackFaces", "backFacingAngle", "projectionMode")

def _vmf_overlay_sources(vmf_path):
    """the .vmf's info_overlay / infodecal entities [dict(cls, mat, o, sides)] and every brush side's plane {side id: (unit normal, d)}"""
    import numpy as np
    if not vmf_path or not Path(vmf_path).is_file():
        return [], {}
    tree = _vmf_tree(str(vmf_path))
    srcs, planes = [], {}

    def walk(node):
        for ch in node[2]:
            if ch[0] == "side":
                pl = [np.array([float(x) for x in t.split()]) for t in re.findall(r"\(([^)]*)\)", ch[1].get("plane", ""))]
                if len(pl) == 3 and ch[1].get("id"):
                    n = _cross3(pl[1] - pl[0], pl[2] - pl[0])
                    ln = float(np.linalg.norm(n))
                    if ln > 1e-9:
                        planes[ch[1]["id"]] = (n / ln, float(n @ pl[0]) / ln)
            elif ch[0] == "entity" and (ch[1].get("classname") or "").lower() in ("info_overlay", "infodecal"):
                kv = ch[1]
                mat = _vmf_mat((kv.get("material") or kv.get("texture") or "").lower().replace("\\", "/"))
                o = [float(x) for x in (kv.get("BasisOrigin") or kv.get("origin") or "0 0 0").split()[:3]]
                srcs.append(dict(cls=kv["classname"].lower(), mat=mat, o=o, sides=(kv.get("sides") or "").split()))
            else:
                walk(ch)
    walk(tree)
    return srcs, planes


def fit_overlay_depths(vmap_paths, vmf_of):
    """STATIC_OVERLAY_FIT_DEPTH: CS2 projects a static overlay onto every world face that faces it within projectionFar of its origin,
    where CS:GO drew it only on the brush sides the info_overlay lists (an infodecal: on the surface it sits on). For each overlay the
    world faces inside its projection volume are found; the ones it belongs on are those on the planes of its .vmf sides (matched by
    material and position), else the nearest layer. When another face lies behind them within the depth, projectionFar is cut to just
    past them (STATIC_OVERLAY_DEPTH_MARGIN); when they lie deeper than the depth, it is raised to reach them. Rerun-safe. -> log lines"""
    import numpy as np
    dmx = _bundled_vmapedit()[1]
    out, tot = [], collections.Counter()
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        ovs = [n for n, _q in m.walk() if m.type(n) == b"CMapStaticOverlay"]
        if not ovs:
            _keep_map(m, vp)
            continue
        srcs, planes = _vmf_overlay_sources((vmf_of or {}).get(vp) or "")
        par = m.parent_of()

        def in_entity(n):
            p = par.get(n)
            while p is not None:
                if m.type(p) == b"CMapStaticOverlay":
                    return True
                if m.type(p) == b"CMapEntity":
                    # the walls the importer merged into a func_water's mesh go back to the world in the water pass (after this one)
                    return m.cls(p) != "func_water"
                p = par.get(p)
            return False
        faces = []                               # world faces an overlay can land on: (polygon, unit normal, d)
        for n, _q in m.walk():
            if m.type(n) != b"CMapMesh" or in_entity(n):
                continue
            for _f, P, _k, mt in _mesh_faces_world(m, n):
                if "/tools/" in mt.lower() or _water_material(mt)[0]:
                    continue
                P = np.asarray(P, float)
                fn = _poly_normal_sum(P)
                ln = float(np.linalg.norm(fn))
                if ln > 1e-9:
                    faces.append((P, fn / ln, float(fn @ P[0]) / ln))
        if not faces:
            _keep_map(m, vp)
            continue
        LO = np.array([f[0].min(0) for f in faces])
        HI = np.array([f[0].max(0) for f in faces])
        free = list(range(len(srcs)))
        rows = []
        for ov in ovs:
            a_far = dmx.geta(m.E[ov], b"projectionFar")
            q = _mesh_faces_world(m, ov)
            if a_far is None or not q:
                continue
            far = float(a_far[2])
            O = np.asarray(m.g(ov, b"origin"), float)
            ang = m.g(ov, b"angles") or [0.0, 0.0, 0.0]
            nd, ex, ey = (np.array(_qrot(ang, v)) for v in ((0, 0, 1), (1, 0, 0), (0, 1, 0)))   # nd: into the surface
            C = np.asarray(q[0][1], float)
            c2 = (C - O) @ np.stack([ex, ey], 1)
            rect = (float(c2[:, 0].min()), float(c2[:, 1].min()), float(c2[:, 0].max()), float(c2[:, 1].max()))
            mats = m.g(m.g(ov, b"meshData"), b"materials") or [b""]
            mat = mats[0].decode("utf-8", "replace").lower().replace("\\", "/")
            mat = mat[len("materials/"):] if mat.startswith("materials/") else mat
            mat = mat[:-5] if mat.endswith(".vmat") else mat
            cand = [i for i in free if srcs[i]["mat"] == mat and float(np.linalg.norm(np.asarray(srcs[i]["o"]) - O)) <= 24.0]
            src = None
            if cand:                             # the .vmf overlay it came from (same material, nearest), each used once
                i_src = min(cand, key=lambda i: float(np.linalg.norm(np.asarray(srcs[i]["o"]) - O)))
                src = srcs[i_src]
                free.remove(i_src)
            reach = max(far, 64.0) + 2.0
            blo = np.minimum((C - nd * reach).min(0), (C + nd * reach).min(0)) - 1.0
            bhi = np.maximum((C - nd * reach).max(0), (C + nd * reach).max(0)) + 1.0
            # world faces in the projection volume, either side of the overlay's plane (the importer's overlays sit on their surface with
            # local Z out of it, the ones rebuilt from infodecals a little above it with Z into it): (nearest, deepest distance under it,
            # normal, d)
            hits = []
            for i in np.where(np.all(HI >= blo, 1) & np.all(LO <= bhi, 1))[0]:
                P, fn, fd = faces[i]
                c = float(fn @ nd)
                if abs(c) < 0.1:                 # faces along the projection are not drawn on
                    continue
                ts = (P - O) @ nd
                tc = ((P[0] - C) @ fn) / c       # where the face's plane lies under each corner of the overlay
                s0, s1 = max(float(ts.min()), float(tc.min())), min(float(ts.max()), float(tc.max()))
                if s0 > s1 + 0.01:
                    continue
                nr = 0.0 if s0 <= 0.0 <= s1 else min(abs(s0), abs(s1))
                if nr > reach or not _overlap_2d(rect, [tuple(x) for x in ((P - O) @ np.stack([ex, ey], 1))]):
                    continue
                hits.append((nr, max(abs(s0), abs(s1)), fn, fd, s0, s1))
            if not hits:
                continue
            if src and src["sides"]:            # CS:GO drew it on these sides only
                sp = [planes[x] for x in src["sides"] if x in planes]
                target = [h for h in hits if any(abs(float(h[2] @ n_)) > 0.999 and abs(h[3] - d_ * (1.0 if float(h[2] @ n_) > 0 else -1.0)) < 0.5
                                                 for n_, d_ in sp)]
                how = "its .vmf sides"
                if not target:                   # its sides are not world faces here (a brush entity's): left alone
                    continue
            else:                                # an infodecal (or an overlay with no sides): the surface it sits on
                flat = [h for h in hits if abs(float(h[2] @ nd)) > 0.7]
                t1 = min((h[0] for h in flat), default=None)
                if t1 is None or t1 > STATIC_OVERLAY_NORMAL_OFFSET + 4.0:
                    continue                     # nothing right at it (CS:GO drew an infodecal only on a surface at it)
                target = [h for h in flat if h[0] <= t1 + 1.0]
                how = "the surface under it"
            shift = 0.0
            top = max(h[5] for h in target)     # how far its surface reaches out along its Z (0: on it; > 0: the overlay is in the wall)
            if STATIC_OVERLAY_SURFACE_GAP > 0 and -0.05 < top <= 2.0:
                # it lies on its surface (or up to 2 units inside it): moved out along its Z so the surface lies that far under
                # it, where CS2 projects (distances shift with it)
                shift = top + float(STATIC_OVERLAY_SURFACE_GAP)
                ti = {id(h) for h in target}

                def moved(h):
                    s0_, s1_ = h[4] - shift, h[5] - shift
                    return (0.0 if s0_ <= 0.0 <= s1_ else min(abs(s0_), abs(s1_)), max(abs(s0_), abs(s1_)), h[2], h[3], s0_, s1_)
                pairs = [(moved(h), id(h) in ti) for h in hits]
                hits = [h for h, _t in pairs]
                target = [h for h, t_ in pairs if t_]
            need = max(h[1] for h in target)
            behind = [h for h in hits if h[0] > need + 0.5 and h[0] <= far + 0.5 and not any(h is x for x in target)]
            if not behind and need <= far and not shift:
                continue
            gap = min((h[0] for h in hits if h[0] > need + 0.05 and not any(h is x for x in target)), default=None)
            new = round(need + (STATIC_OVERLAY_DEPTH_MARGIN if gap is None else min(STATIC_OVERLAY_DEPTH_MARGIN, (gap - need) / 2)), 2)
            if abs(new - far) < 0.01 and not shift:
                continue
            a_far[2] = float(new)
            if shift:
                a_o = dmx.geta(m.E[ov], b"origin")
                a_o[2] = [float(x) for x in (O + nd * shift)]
            tot["changed"] += 1
            rows.append(f"DEPTH\t{mat}\t{' '.join('%g' % round(x, 1) for x in O)}\tprojection depth {far:g} -> {new:g}: on {how} at depth "
                        f"{need:.1f}" + (f"; {len(behind)} face(s) behind it from depth {min(h[0] for h in behind):.1f} were drawn on too" if behind else
                                         ("" if shift and need <= far else "; they lay beyond the old depth")) +
                        (f"; it lay on (or in) that surface (CS2 drew it on part of it only, or not at all): moved {round(shift, 2):g} out along its Z, "
                         f"in front of it" if shift else ""))
        if rows:
            try:
                _save_map(m, vp, "overlay_depth")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            out += [f"# {vn}"] + rows
        else:
            _keep_map(m, vp)
    out.insert(0, f"# static overlay projection depths fitted to the surface CS:GO drew them on: {tot['changed']}")
    return out


def _lz4_block(src: bytes, out_size: int) -> bytes:
    dst = bytearray(); i = 0; n = len(src)
    while i < n:
        tok = src[i]; i += 1
        lit = tok >> 4
        if lit == 15:
            while True:
                b = src[i]; i += 1; lit += b
                if b != 255:
                    break
        dst += src[i:i + lit]; i += lit
        if i >= n:
            break
        off = src[i] | (src[i + 1] << 8); i += 2
        ml = tok & 15
        if ml == 15:
            while True:
                b = src[i]; i += 1; ml += b
                if b != 255:
                    break
        ml += 4
        st = len(dst) - off
        if off >= ml:
            dst += dst[st:st + ml]
        else:
            for k in range(ml):
                dst.append(dst[st + k])
    return bytes(dst[:out_size])

def decode_vtex_c(data: bytes):
    """CS2 compiled texture (.vtex_c) -> PIL RGBA image of mip 0. LZ4 / uncompressed mips; DXT1, DXT5, BC4, BC5, BC7, RGBA8888, BGRA8888.
    Raises ValueError on anything else. Adapted from skink52/cs2mapping create/vtexread.py (MIT), after ValveResourceFormat's Texture.cs."""
    import io
    import numpy as np
    block = {1: 8, 2: 16, 20: 16, 21: 16, 27: 8}
    def mip_size(fmt, w, h):
        if fmt in block:
            return max(1, (w + 3) // 4) * max(1, (h + 3) // 4) * block[fmt]
        if fmt in (4, 28):
            return w * h * 4
        raise ValueError(f"texture format {fmt} not supported")
    _size, _hv, _ver, boff, bcount = struct.unpack("<IHHII", data[:16])
    blocks = {}
    for k in range(bcount):
        p = 8 + boff + k * 12
        t, o, sz = struct.unpack_from("<4sII", data, p)
        blocks[t] = (p + 4 + o, sz)
    off, sz = blocks[b"DATA"]
    w, h, depth, fmt, nmip = struct.unpack_from("<HHHBB", data, off + 20)
    eoff, ecount = struct.unpack_from("<II", data, off + 32)
    comp, method = None, 0
    p = off + 32 + eoff
    for k in range(ecount):
        t, o, _s = struct.unpack_from("<III", data, p + k * 12)
        if t == 4:
            q = p + k * 12 + 4 + o
            method, moff, mips = struct.unpack_from("<III", data, q)
            comp = struct.unpack_from("<%di" % mips, data, q + 4 + moff)
    if method == 2:
        raise ValueError("zstd-compressed mips not supported")
    pos = off + sz
    for j in range(nmip - 1, 0, -1):
        ms = mip_size(fmt, max(1, w >> j), max(1, h >> j)) * max(1, depth)
        if comp is not None:
            ms = min(ms, comp[j])
        pos += ms
    full = mip_size(fmt, w, h)
    raw = _lz4_block(data[pos:pos + comp[0]], full) if comp is not None and comp[0] < full else data[pos:pos + full]
    if fmt in (4, 28):
        a = np.frombuffer(raw, np.uint8).reshape(h, w, 4)
        if fmt == 28:
            a = a[..., [2, 1, 0, 3]]
        return Image.fromarray(a.copy(), "RGBA")
    fourcc = {1: b"DXT1", 2: b"DXT5"}.get(fmt, b"DX10")
    hdr = struct.pack("<4sI6I44x", b"DDS ", 124, 0x1 | 0x2 | 0x4 | 0x1000 | 0x80000, h, w, len(raw), 0, 1)
    pf = struct.pack("<II4s5I", 32, 0x4, fourcc, 0, 0, 0, 0, 0)
    out = hdr + pf + struct.pack("<5I", 0x1000, 0, 0, 0, 0)
    if fourcc == b"DX10":
        out += struct.pack("<5I", {20: 98, 21: 83, 27: 80}[fmt], 3, 0, 1, 0)
    return Image.open(io.BytesIO(out + raw)).convert("RGBA")

def _cs2_overlay_textures(mat: str):
    """Overlay material shipped with CS2 (not in the addon): the compiled .vmat_c lists the textures it uses as plain strings
    (external reference table). -> (color .vtex, translucency .vtex or None, [every .vtex found]) or None when CS2 / the material
    cannot be read. Paths come back without '_c'."""
    try:
        v = cs2_vpk()
        if not v.loaded:
            return None
        base = mat.replace("\\", "/").lower()
        data = v.read((base if base.endswith(".vmat") else base + ".vmat") + "_c")
        if not data:
            return None
        found = []
        for m_ in re.finditer(rb"materials/[a-z0-9_\-./]+?\.vtex(?:_c)?(?![a-z0-9_])", data, flags=re.I):
            p_ = m_.group(0).decode("latin-1").lower()
            p_ = p_[:-2] if p_.endswith("_c") else p_
            if p_ not in found:
                found.append(p_)
        col = next((p_ for p_ in found if "_color" in os.path.basename(p_)), None)
        tr = next((p_ for p_ in found if "_trans" in os.path.basename(p_)), None)
        return (col, tr, found) if col else None
    except Exception:
        return None

def _backup_subdir(vp):
    """the folder (under BACKUP_DIR) for a vmap's backups: the map's path below the addon's maps folder, so maps with the same name in
    different folders (maps/prefabs/<map>/x.vmap, a main map and a prefab of the same name) never share one. Main maps: BACKUP_DIR itself."""
    parts = Path(os.path.abspath(str(vp))).parts[:-1]
    k = max((i for i, x in enumerate(parts) if x.lower() == "maps"), default=None)
    sub = parts[k + 1:] if k is not None else ()
    return os.path.join(BACKUP_DIR, *sub) if sub else BACKUP_DIR


def _backup_vmap_name(vp, kind):
    """the path a vmap is backed up to before its first change of the run (nothing is written here). The first copy ever made of a map is
    kept as <map>.original.vmap (never pruned); each run that changes it also gets <map>.<time>.before_<kind>.vmap (kind = the first pass
    that changed it), of which the newest BACKUP_KEEP are kept. Maps below maps/ (prefabs) are backed up in the same sub-folders."""
    stem = os.path.splitext(os.path.basename(str(vp)))[0]
    t = time.time()
    return os.path.join(_backup_subdir(vp), f"{stem}.{time.strftime('%Y%m%d-%H%M%S', time.localtime(t))}{int(t * 1000) % 1000:03d}.before_{kind}.vmap")


def _backup_vmap_copy(vp, dst):
    """copy vp to dst (a _backup_vmap_name path), keep <map>.original.vmap and prune to the newest BACKUP_KEEP"""
    bdir = os.path.dirname(dst)
    os.makedirs(bdir, exist_ok=True)
    stem = os.path.splitext(os.path.basename(str(vp)))[0]
    orig = os.path.join(bdir, stem + ".original.vmap")
    if not os.path.exists(orig):
        shutil.copy2(str(vp), orig)
    shutil.copy2(str(vp), dst)
    old = sorted(f for f in os.listdir(bdir) if f.startswith(stem + ".") and ".before_" in f and f.endswith(".vmap")
                 and re.fullmatch(r"\d{8}-\d{9}", f[len(stem) + 1:].split(".")[0]))
    for f in old[:-BACKUP_KEEP] if BACKUP_KEEP > 0 else []:
        try:
            os.remove(os.path.join(bdir, f))
        except OSError:
            pass
    return dst


def _atomic_write(path, data: bytes):
    """write a file so it is either the old or the new contents, never half of one: a temp file next to it, flushed to disk, then renamed
    over it. OSError propagates (on Windows the rename fails while Hammer holds the file)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    try:
        with open(tmp, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except OSError:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


# ---- .vmap store. Every pass reads and writes the maps through these, not the files: a changed map is kept in memory (as the bytes the
# file would hold) and written to disk once, by _flush_vmaps at the end of the run, with one backup per map per run. A pass that is
# interrupted part-way leaves the last saved version, as before.
_VMAPS = {}         # _npath -> {"path", "data": bytes of the version not on disk yet (None = disk is current), "gen", "kinds", "bak"}
_VMAP_BACKUPS = {}  # _npath -> this run's backup of the map (named at its first change, copied by _flush_vmaps just before the map is written)
_VMAP_BACKUP_PENDING = set()   # _npath of maps whose backup is named but not copied yet
_AFTER_FLUSH = []   # (file, {_npath of the maps it depends on}, backup copy) - prefab files to delete once the maps that placed them are written
_VMAP_GEN = [0]     # version counter for in-memory versions (global, so a version token is never reused for another content)
_MAP_CACHE = collections.OrderedDict()     # _npath -> (version, vmapedit.Map, file size) of maps passes handed back, oldest first (MAP_CACHE_MB)


def _vmap_version(vp):
    """a token that changes whenever the map changes, in memory this run or on disk (OSError if neither has it)"""
    e = _VMAPS.get(_npath(vp))
    if e is not None and e["data"] is not None:
        return ("mem", e["gen"])
    st = os.stat(str(vp))
    return st.st_mtime_ns, st.st_size


def _vmap_read(vp) -> bytes:
    """the current contents of a .vmap: this run's unsaved version if a pass changed it, else the file"""
    e = _VMAPS.get(_npath(vp))
    if e is not None and e["data"] is not None:
        return e["data"]
    return Path(vp).read_bytes()


def _vmap_write(vp, data, kind):
    """a pass's new contents for a .vmap -> the path of this run's backup of it ("" for a new file). Kept in memory until _flush_vmaps.
    The first change of the run checks the file can be written (OSError while Hammer holds it, as a direct write did) and backs it up.
    A map that does not exist yet (the 3D skybox split's) is written straight away."""
    key = _npath(vp)
    data = bytes(data)
    _MAP_CACHE.pop(key, None)
    if not os.path.exists(str(vp)):
        _atomic_write(vp, data)
        _VMAPS.pop(key, None)
        return ""
    e = _VMAPS.get(key)
    if e is None or e["data"] is None:
        with open(str(vp), "r+b"):          # can it be written? (Hammer holds the file open while the map is loaded)
            pass
        if key not in _VMAP_BACKUPS:            # named now (the first pass that changed it), copied when the map is written
            _VMAP_BACKUPS[key] = _backup_vmap_name(vp, kind)
            _VMAP_BACKUP_PENDING.add(key)
        if e is None:
            e = _VMAPS[key] = {"path": str(vp), "data": None, "gen": 0, "kinds": []}
    e["data"] = data
    _VMAP_GEN[0] += 1
    e["gen"] = _VMAP_GEN[0]
    if kind not in e["kinds"]:
        e["kinds"].append(kind)
    return _VMAP_BACKUPS[key]


def _vmap_forget(vp):
    """a .vmap moved or deleted by a pass: drop what the store holds for it"""
    key = _npath(vp)
    _VMAPS.pop(key, None)
    _MAP_CACHE.pop(key, None)


def _flush_vmaps():
    """write every map changed this run to disk (atomically) -> log lines. A map that cannot be written is reported, not lost silently:
    its file is left as it was before the run."""
    lines = []
    written, failed = set(), set()
    for key, e in list(_VMAPS.items()):
        if e["data"] is None:
            continue
        p, gen = e["path"], e["gen"]
        try:
            disk = Path(p).read_bytes()
            same = len(disk) == len(e["data"]) and (disk == e["data"] or _vmap_signature(disk) == _vmap_signature(e["data"]))
        except Exception:
            same = False
        if same:
            # the passes rebuilt what was already there (the lighting rebuild's lights, with new ids): nothing to write or back up
            lines.append(f"UNCHANGED\t{p}\tchanged by: {', '.join(e['kinds'])}, but the result is the map already on disk (only Hammer ids "
                         "differ): not written, no backup made")
            e["data"] = None
            e["kinds"] = []
            _VMAP_BACKUP_PENDING.discard(key)
            _VMAP_BACKUPS.pop(key, None)
            hit = _MAP_CACHE.get(key)
            if hit and hit[0] == ("mem", gen):
                _MAP_CACHE.pop(key, None)         # it holds the new ids; the file keeps the old ones
            written.add(key)
            continue
        if FAST_SAVE:
            try:                                     # the parse check every save used to make, once per map
                _bundled_vmapedit()[1].loads(e["data"])
            except Exception as ex:
                lines.append(f"NOT_SAVED\t{p}\tthe new version does not read back ({ex}); the file is as it was before this run")
                print(f"  [ERROR] {p}: the new version does not read back ({ex}); not saved, the file is as it was before this run")
                failed.add(key)
                continue
        if key in _VMAP_BACKUP_PENDING:
            try:
                _backup_vmap_copy(p, _VMAP_BACKUPS[key])
                _VMAP_BACKUP_PENDING.discard(key)
            except OSError as ex:
                lines.append(f"NOT_SAVED\t{p}\tcould not back it up ({ex}): not written, changes by: {', '.join(e['kinds'])} are LOST; "
                             "the file is as it was before this run")
                print(f"  [ERROR] could not back up {p} ({ex}): not saved, this run's changes to it are lost")
                failed.add(key)
                continue
        try:
            _atomic_write(p, e["data"])
        except OSError as ex:
            lines.append(f"NOT_SAVED\t{p}\t{ex}\tchanges by: {', '.join(e['kinds'])} are LOST; the file is as it was before this run. Close Hammer and rerun.")
            print(f"  [ERROR] could not save {p} ({ex}): this run's changes to it are lost; close Hammer and rerun")
            failed.add(key)
            continue
        written.add(key)
        e["data"] = None
        hit = _MAP_CACHE.get(key)
        if hit and hit[0] == ("mem", gen):          # the cached copy is the version just written: still good
            _MAP_CACHE[key] = (_vmap_version(p), hit[1], hit[2])
        lines.append(f"SAVED\t{p}\tchanged by: {', '.join(e['kinds'])}\tbackup: {_VMAP_BACKUPS.get(key, '')}")
        e["kinds"] = []
    # prefab files collapsed into their maps: deleted only now that those maps are on disk (deleting them at once left the map on disk
    # placing prefabs that were gone whenever its save failed, e.g. Hammer had opened it during the run)
    for f, deps, dst in list(_AFTER_FLUSH):
        bad = sorted(d for d in deps if d in failed or (d in _VMAPS and _VMAPS[d]["data"] is not None))
        if bad:
            lines.append(f"KEPT_FILE\t{f}\tnot deleted: {', '.join(os.path.basename(b) for b in bad)}, which places it, could not be saved")
            print(f"  [WARNING] prefab {f} kept: the map that places it could not be saved")
            _AFTER_FLUSH.remove((f, deps, dst))
            continue
        try:
            os.remove(f)
            _vmap_forget(f)
            d_ = Path(f).parent
            while d_.name.lower() != "maps" and d_.is_dir() and not any(d_.iterdir()):
                d_.rmdir()
                d_ = d_.parent
            lines.append(f"DELETED_FILE\t{f}\tcollapsed into its map (a copy is in {dst})")
        except OSError as ex:
            lines.append(f"KEPT_FILE\t{f}\tcould not be deleted ({ex}); its contents are already in the map: delete it by hand")
        _AFTER_FLUSH.remove((f, deps, dst))
    return lines


_SIG_SKIP = (b"nodeID", b"referenceID", b"randomSeed")


def _vmap_signature(data: bytes) -> bytes:
    """a digest of a .vmap's content that leaves out what a pass makes anew when it rebuilds the same thing: element GUIDs, the elements'
    order in the file and Hammer's nodeID / referenceID / randomSeed. Elements are numbered in the order they are reached from the root,
    so two versions with the same signature hold the same nodes, keyvalues, connections and mesh data in the same order."""
    import hashlib
    dmx = _bundled_vmapedit()[1]
    doc = dmx.loads(data)
    E = doc.elements
    h = hashlib.blake2b(digest_size=32)
    out = bytearray(doc.header)
    for attrs in doc.prefix:
        out += struct.pack("<i", len(attrs))
        for name, t, v in attrs:
            out += name + b"\0"
            dmx._w_attr(out, t, v, None, True)
    h.update(out)
    canon = {0: 0} if E else {}
    queue = [0] if E else []
    qi = 0
    while qi < len(queue):
        el = E[queue[qi]]
        qi += 1
        out = bytearray(el["type"] + b"\0" + el["name"] + b"\0")
        for name, t, v in el["attrs"]:
            if name in _SIG_SKIP:
                continue
            out += name + b"\0"
            if t == dmx.T_ELEM or t == dmx.ARR + dmx.T_ELEM:
                ids = []
                for x in (v if t > dmx.ARR else [v]):
                    if isinstance(x, tuple):             # a reference by GUID string
                        ids.append(-2)
                        out += x[1] + b"\0"
                    elif isinstance(x, int) and x >= 0:
                        if x not in canon:
                            canon[x] = len(canon)
                            queue.append(x)
                        ids.append(canon[x])
                    else:
                        ids.append(-1)
                out.append(t)
                out += struct.pack("<%di" % len(ids), *ids)
            else:
                dmx._w_attr(out, t, v, None, True)
        h.update(struct.pack("<i", len(out)))
        h.update(out)
    return h.digest()


def _new_map(vp):
    """a fresh vmapedit.Map of the current version of vp (not shared with the cache)"""
    vmapedit, _dmx = _bundled_vmapedit()
    return vmapedit.Map(os.path.abspath(str(vp)), data=_vmap_read(vp))


def _open_map(vp):
    """vmapedit.Map of vp. Reuses the copy the previous pass handed back (_keep_map / _save_map) when the map has not changed since;
    otherwise loads the current version. Hand it back with _keep_map only if this pass changed nothing."""
    key = _npath(vp)
    hit = _MAP_CACHE.pop(key, None)
    if hit and hit[0] == _vmap_version(vp):
        return hit[1]
    return _new_map(vp)


def _cache_map(vp, m):
    """keep a parsed map for the next pass. Parsed maps take ~10x their file size in memory: the most recent ones are kept while they
    fit in MAP_CACHE_MB (the last one always), so a main map and its 3D skybox map are not re-read by every pass in turn"""
    key = _npath(vp)
    e = _VMAPS.get(key)
    size = len(e["data"]) if e is not None and e["data"] is not None else os.path.getsize(str(vp))
    _MAP_CACHE.pop(key, None)
    _MAP_CACHE[key] = (_vmap_version(vp), m, size)
    while len(_MAP_CACHE) > 1 and sum(x[2] for x in _MAP_CACHE.values()) * 10 > MAP_CACHE_MB * 1e6:
        _MAP_CACHE.popitem(last=False)


def _keep_map(m, vp):
    """hand an UNCHANGED map back for the next pass"""
    _cache_map(vp, m)


def _save_map(m, vp, kind):
    """store m as the new version of vp -> this run's backup path. OSError (Hammer holds the file) propagates. The saved bytes are re-read
    at once (the check Map.save made, and the 32-bit floats the file holds) and that copy is handed to the next pass."""
    vmapedit, dmx = _bundled_vmapedit()
    out = dmx.dumps(m.doc)
    # FAST_SAVE: the next pass gets this same parsed map instead of a fresh parse of the bytes (the re-parse was ~2/3 of each save;
    # 35 saves were ~50 s of a mg_hellz run). The bytes are still made here (failed passes fall back to them) and checked once at flush.
    fresh = m if FAST_SAVE else vmapedit.Map(os.path.abspath(str(vp)), data=out)
    bak = _vmap_write(vp, out, kind)
    _cache_map(vp, fresh)
    return bak


def _game_dir(export_dir: Path):
    """the addon's game folder (content\\csgo_addons\\x -> game\\csgo_addons\\x), or None when export_dir is not under a content folder"""
    parts = [x.lower() for x in export_dir.parts]
    if "content" not in parts:
        return None
    k = len(parts) - 1 - parts[::-1].index("content")
    return Path(*export_dir.parts[:k], "game", *export_dir.parts[k + 1:])


def _safe_write(path: Path, data: bytes):
    """Write a file in the addon; skip when it already holds exactly this; retry briefly (Hammer / the resource compiler can hold a
    freshly written content file open). -> None on success, else a reason string."""
    last = None
    for _attempt in range(6):
        try:
            if path.is_file() and path.read_bytes() == data:
                return None
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            return None
        except OSError as ex:
            last = ex
            time.sleep(0.4)
    return f"cannot write {path} ({last}); Hammer or another program probably has it open - close Hammer and rerun"

def _build_quad_material(mat: str, export_dir: Path):
    """Quad material for one overlay material (done once per material per run). -> (quad vmat path, colour ref, translucency ref or None,
    (w, h, 1.0) or None, log note) or a string saying why not."""
    vm = export_dir / (mat if mat.endswith(".vmat") else mat + ".vmat")
    txt = vm.read_text(errors="ignore") if vm.is_file() else ""
    mc = re.search(r'"TextureColor"\s+"([^"]+)"', txt)
    mt = re.search(r'"TextureTranslucency"\s+"([^"]+)"', txt)
    src_note, ts = "", _addon_texture_size(mat)
    qb = (mat[:-5] if mat.endswith(".vmat") else mat) + "_quad"
    if mc:
        col_ref, tr_ref = mc.group(1), (mt.group(1) if mt else None)
    else:
        # CS2's own overlay material: its textures are compiled .vtex_c in the VPK, and a vmat cannot point at those directly (Hammer
        # shows the error material), so the colour texture is decoded to a TGA + an alpha mask TGA in the addon, the same way the
        # Source1 materials are done.
        cs = _cs2_overlay_textures(mat)
        if not cs:
            return ("the overlay material is not in the addon folder and CS2's own copy could not be read (CS2 VPK not loaded, "
                    "material not in it, or no texture references in it): no texture to build the quad material from")
        try:
            vt = cs2_vpk().read(cs[0] + "_c")
            if not vt:
                raise ValueError(f"{cs[0]}_c is not in the indexed CS2 files")
            im = decode_vtex_c(vt)
        except Exception as ex:
            return f"CS2's colour texture {cs[0]} could not be decoded ({ex})"
        import io
        col_ref = qb + "_color.tga"
        b_ = io.BytesIO(); im.convert("RGB").save(b_, "TGA")
        err = _safe_write(export_dir / col_ref, b_.getvalue())
        tr_ref = None
        if not err and im.getchannel(3).getextrema()[0] < 255:
            tr_ref = qb + "_trans.tga"
            b_ = io.BytesIO(); im.getchannel(3).convert("RGB").save(b_, "TGA")
            err = _safe_write(export_dir / tr_ref, b_.getvalue())
        if err:
            return err
        ts = (im.size[0], im.size[1], 1.0)
        src_note = f"; CS2 texture {cs[0]} ({im.size[0]}x{im.size[1]}) decoded to {col_ref}" + (f" + {tr_ref}" if tr_ref else " (fully opaque, no mask)")
    qmat = qb + ".vmat"
    err = _safe_write(export_dir / qmat, ("\n".join(['"Layer0"', "{", '    "Shader" "csgo_vertexlitgeneric.vfx"', f'    "TextureColor" "{col_ref}"']
                                                  + ([f'    "TextureTranslucency" "{tr_ref}"'] if tr_ref else [])
                                                  + ['    "F_TRANSLUCENT" "1"', '    "F_RENDER_BACKFACES" "1"', "}"]) + "\n").encode("utf-8"))
    if err:
        return err
    return qmat, col_ref, tr_ref, ts, src_note

def convert_entity_overlays(vmap_paths, export_dir: Path):
    """CS2 static overlays do not project onto entities (func_breakable, doors, ...). For each CMapStaticOverlay whose projection
    volume reaches a face of exactly one brush entity (and no world brush face), the overlay is replaced by a translucent quad
    (CMapMesh, same position/angles/size/uv, laid QUAD_OFFSET above that face) parented to the entity, so it moves with it.
    Overlays that also touch world brushes, touch two entities, lie on slanted faces or whose material is not in the addon stay overlays.
    Re-running is safe: converted overlays no longer exist as overlays."""
    lines, total, mat_cache = [], 0, {}
    for vp in vmap_paths:
        try:
            raw = _vmap_read(vp)
            if b"encoding binary" not in raw[:100]:
                lines.append(f"# {os.path.basename(str(vp))}: not a binary .vmap; skipped")
                continue
            doc = _DmxDoc(raw)
        except Exception as ex:
            lines.append(f"# {os.path.basename(str(vp))}: cannot read ({ex}); skipped")
            continue
        els = doc.els
        parent_of = {}
        for e in els:
            if e.type in ("CMapEntity", "CMapGroup", "CMapWorld"):
                for c in e.get("children") or []:
                    parent_of[id(c)] = e
        ovs = [e for e in els if e.type == "CMapStaticOverlay" and id(e) in parent_of]
        if not ovs:
            continue
        meshes = []        # (mesh element, owning entity or None, world polygons [(pts, material)], aabb)
        for e in els:
            if e.type != "CMapMesh" or id(e) not in parent_of:
                continue
            owner = parent_of[id(e)]
            # a func_water's faces are not an entity's: the importer merges world brushes into one (the water pass puts them back in the world),
            # so its other faces count as world faces, and no quad goes on a water surface
            pr_ = owner.get("entity_properties") if owner.type == "CMapEntity" else None
            wat = pr_ is not None and any(a_[0] == "classname" and a_[1] == 5 and str(a_[2]).lower() == "func_water" for a_ in pr_.attrs)
            polys = []
            for loc, mat in _mesh_polys(e):
                if mat.startswith("materials/tools/") or (wat and _water_material(mat)[0]):
                    continue
                polys.append((_node_world(e, loc, parent_of), mat))
            if not polys:
                continue
            allp = [p for pl, _m in polys for p in pl]
            bb = ([min(p[i] for p in allp) for i in range(3)], [max(p[i] for p in allp) for i in range(3)])
            meshes.append((e, owner if owner.type == "CMapEntity" and not wat else None, polys, bb))
        next_id = max((e.get("nodeID") or 0) for e in els if e.attr("nodeID")) + 1
        made, notes = [], []
        for ov in ovs:
            md = ov.get("meshData")
            mats = (md.get("materials") or []) if md is not None else []
            mat = str(mats[0]).replace("\\", "/").lower() if mats else ""
            vloc = None
            for s_ in md.get("vertexData").get("streams"):
                if s_.name.startswith("position"):
                    vloc = s_.get("data")
            if not vloc or len(vloc) != 4:
                continue
            ang = ov.get("angles") or (0, 0, 0)
            ex_, ey_, n_ = _qrot(ang, (1, 0, 0)), _qrot(ang, (0, 1, 0)), _qrot(ang, (0, 0, 1))
            O = ov.get("origin")
            pts_w = _node_world(ov, list(vloc), parent_of)
            loc2 = [(sum((p[i] - O[i]) * ex_[i] for i in range(3)), sum((p[i] - O[i]) * ey_[i] for i in range(3))) for p in pts_w]
            rect = (min(p[0] for p in loc2), min(p[1] for p in loc2), max(p[0] for p in loc2), max(p[1] for p in loc2))
            far = ov.get("projectionFar")
            far = 64.0 if far is None else far
            lo = [min(min(p[i] for p in pts_w), O[i]) - far - 1 for i in range(3)]
            hi = [max(max(p[i] for p in pts_w), O[i]) + far + 1 for i in range(3)]
            hits_e, hits_w, slanted = [], [], 0
            for m_, own, polys, bb in meshes:
                if any(bb[1][i] < lo[i] or bb[0][i] > hi[i] for i in range(3)):
                    continue
                for pl, _pmat in polys:
                    fn = _poly_normal(pl)
                    if fn is None:
                        continue
                    t = sum((pl[0][i] - O[i]) * n_[i] for i in range(3))
                    if t < -0.5 or t > far + 0.5:
                        continue
                    pl2 = [(sum((p[i] - O[i]) * ex_[i] for i in range(3)), sum((p[i] - O[i]) * ey_[i] for i in range(3))) for p in pl]
                    if not _overlap_2d(rect, pl2):
                        continue
                    d_ = sum(fn[i] * n_[i] for i in range(3))
                    if d_ > -0.99:
                        if d_ > -0.7:         # back faces / perpendicular faces are not projected on
                            continue
                        slanted += 1
                        continue
                    (hits_e if own is not None else hits_w).append((t, own, pl2, m_))
            nid = ov.get("nodeID")
            where = "origin %.1f %.1f %.1f" % tuple(O)
            if not hits_e and not slanted:
                continue
            if not hits_e:
                notes.append(f"LEFT\tnode {nid}\t{mat}\t{where}\tonly slanted entity face(s) under it ({slanted}); the quad would not lie flat")
                continue
            if hits_w:
                notes.append(f"LEFT\tnode {nid}\t{mat}\t{where}\ttouches {len(hits_w)} world brush face(s) as well as an entity: a quad would cover only part of it")
                continue
            hits_e.sort(key=lambda h: h[0])
            best = hits_e[0]
            if any(h[1] is not best[1] and h[0] - best[0] <= 0.5 for h in hits_e):
                notes.append(f"LEFT\tnode {nid}\t{mat}\t{where}\ttouches faces of two different entities at the same depth")
                continue
            ent = best[1]
            pr = ent.get("entity_properties")
            props = {a_[0]: a_[2] for a_ in pr.attrs if a_[1] == 5} if pr is not None else {}
            who = f"{props.get('classname', '?')} '{props.get('targetname', '')}'"
            qm_ = mat_cache.get(mat)
            if qm_ is None:
                qm_ = mat_cache[mat] = _build_quad_material(mat, Path(export_dir))
            if isinstance(qm_, str):
                notes.append(f"LEFT\tnode {nid}\t{mat}\t{where}\ton {who}; {qm_}")
                continue
            qmat, _col_ref, tr_ref, ts, src_note = qm_
            tw, th = (ts[0], ts[1]) if ts else (256.0, 256.0)
            # texcoords per vertex of the overlay's single face -> axes / scale / shift in the mesh's local space
            tc = None
            for s_ in md.get("faceVertexData").get("streams"):
                if s_.name.startswith("texcoord"):
                    tc = s_.get("data")
            fe, nx, evx, vdi, evd = md.get("faceEdgeIndices"), md.get("edgeNextIndices"), md.get("edgeVertexIndices"), md.get("vertexDataIndices"), md.get("edgeVertexDataIndices")
            vt, he = {}, fe[0]
            for _ in range(4):
                vt[vdi[evx[he]]] = tc[evd[he]]
                he = nx[he]
            ok_uv = len(vt) == 4 and all(k in vt for k in range(4))
            axes = None
            if ok_uv:
                x0, y0, x1, y1, x3, y3 = vloc[0][0], vloc[0][1], vloc[1][0], vloc[1][1], vloc[3][0], vloc[3][1]
                det = (x1 - x0) * (y3 - y0) - (y1 - y0) * (x3 - x0)
                if abs(det) > 1e-6:
                    sol = []
                    for k in (0, 1):
                        du, dv = vt[1][k] - vt[0][k], vt[3][k] - vt[0][k]
                        gx = (du * (y3 - y0) - (y1 - y0) * dv) / det
                        gy = ((x1 - x0) * dv - du * (x3 - x0)) / det
                        c = vt[0][k] - gx * x0 - gy * y0
                        err = max(abs(gx * v[0] + gy * v[1] + c - vt[i_][k]) for i_, v in enumerate(vloc))
                        gl = math.hypot(gx, gy)
                        if err > 1e-3 or gl < 1e-9:
                            sol = None
                            break
                        tex = tw if k == 0 else th
                        sol.append(((gx / gl, gy / gl, 0.0, c * tex), 1.0 / (gl * tex)))
                    axes = sol
            q = _dmx_clone(ov, {})
            q.type = "CMapMesh"
            q.attrs = [a_ for a_ in q.attrs if a_[0] not in OVERLAY_ONLY_ATTRS]
            q.set("nodeID", 2, next_id); next_id += 1
            q.set("referenceID", 15, random.getrandbits(64))
            q.set("randomSeed", 2, random.getrandbits(31))
            t_face = best[0]
            q.set("origin", 10, tuple(float(O[i] + n_[i] * (t_face - OVERLAY_QUAD_OFFSET)) for i in range(3)))
            qm = q.get("meshData")
            qm.set("materials", 37, [qmat])
            if axes:
                for s_ in qm.get("faceData").get("streams"):
                    if s_.name.startswith("textureScale"):
                        s_.set("data", s_.attr("data")[1], [(axes[0][1], axes[1][1])])
                    elif s_.name.startswith("textureAxisU"):
                        s_.set("data", s_.attr("data")[1], [axes[0][0]])
                    elif s_.name.startswith("textureAxisV"):
                        s_.set("data", s_.attr("data")[1], [axes[1][0]])
            doc.els.append(q)
            made.append((ov, q, ent))
            notes.append(f"CONVERTED\tnode {nid} -> {q.get('nodeID')}\t{mat}\t{where}\tquad on {who}, {t_face - OVERLAY_QUAD_OFFSET:.2f} units from the overlay plane"
                         + ("" if ts else "; texture size unknown (256 assumed for the uv axes)") + ("" if axes else "; uv axes left as the overlay's")
                         + ("" if tr_ref else "; no translucency mask for this decal") + src_note)
        if made:
            for ov, q, ent in made:
                par = parent_of[id(ov)]
                par.attr("children")[2] = [c for c in par.get("children") if c is not ov]
                ent.attr("children")[2] = list(ent.get("children") or []) + [q]
            # new sub-elements of the quads must be in the element list too; dropped overlays' private sub-elements are removed
            seen_ids = {id(e) for e in doc.els}
            st = [q for _o, q, _e in made]
            while st:
                e = st.pop()
                for _n, t, v in e.attrs:
                    for x in ([v] if t == 1 else v if t == 33 else []):
                        if x is not None and id(x) not in seen_ids:
                            seen_ids.add(id(x)); doc.els.append(x); st.append(x)
            after = doc.reachable()
            dead = set()
            for ov, _q, _e in made:
                st = [ov]
                while st:
                    e = st.pop()
                    if id(e) in dead or id(e) in after:
                        continue
                    dead.add(id(e))
                    for _n, t, v in e.attrs:
                        for x in ([v] if t == 1 else v if t == 33 else []):
                            if x is not None:
                                st.append(x)
            doc.els = [e for e in doc.els if id(e) not in dead]
            data = doc.save_bytes()
            try:
                chk = read_binary_dmx(data)
                _left = sum(1 for e in chk if e["type"] == "CMapStaticOverlay")
                if _left != len(ovs) - len(made):
                    raise ValueError(f"{_left} static overlays left, expected {len(ovs) - len(made)}")
            except Exception as ex:
                notes.append(f"# {os.path.basename(str(vp))}: the edited file failed its re-read check ({ex}); NOT written")
                made = []
            if made:
                try:
                    bak = _vmap_write(vp, data, "overlayquads")
                except OSError as ex:
                    notes.append(f"# {os.path.basename(str(vp))}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                    print(f"  [WARN] overlay quads: could not write {vp} ({ex}); close Hammer and rerun")
                    made = []
            if made:
                notes.append(f"# {len(made)} overlay(s) converted to parented quads in {vp}; original saved as {bak}. Reopen the map in Hammer.")
                print(f"  overlay quads: converted {len(made)} of {len(ovs)} static overlays in {os.path.basename(str(vp))} (backup {bak})")
                total += len(made)
        if notes:
            lines.append(f"# {os.path.basename(str(vp))}: {len(ovs)} static overlay(s); LEFT = stays a static overlay (reason given)")
            lines += notes
    return [f"# {total} static overlay(s) converted to quads parented to brush entities (CS2 static overlays do not project onto entities)"] + lines


# ---- report: entity outputs (IO connections) that are in the .vmf but not in the .vmap. READ-ONLY: nothing is changed ----

_IO_SPECIAL = ("!activator", "!caller", "!self", "!player", "!picker", "!pvsplayer", "!enemy", "!target")
_IO_RESTORE = ("!self", "!activator", "!caller")      # dropped outputs to these targets are put back (RESTORE_SELF_IO): CS2 supports them


def _restore_io(vp, restore):
    """[(vmap owner record, (output, target, input, param, delay, times))] -> put the outputs back on those owners.
    -> (restored conn tuples, log lines). Owners are found by class, name and origin."""
    vn = os.path.basename(str(vp))
    try:
        m = _open_map(vp)
    except Exception as ex:
        return [], [f"# {vn}: cannot open to restore outputs ({ex})"]
    by = {}
    for e in m.entities():
        by.setdefault((m.cls(e).lower(), m.name(e).lower()), []).append(e)
    done, rows = [], []
    for rec, (o, t, i, p, d, n) in restore:
        cands = [e for e in by.get((rec["cls"], rec["name"].lower()), []) if max(abs(a - b) for a, b in zip(m.origin(e), rec["origin"])) < 0.01]
        if ADDOUTPUT_OUTPUTS_GATED and (i or "").lower() == "addoutput" and _ao_output_fields(p):
            # an AddOutput adding an output: left out only when gate_addoutput_outputs already made it the Enable of a gate (<target>__ao<N>
            # firing that output). One the importer dropped (mg_mario_party's relay: OnUser1 !self AddOutput "OnTrigger Cannon:Trigger::0:1",
            # the re-arming of the pirate cannon) has no gate yet: it goes back, and the gate pass after this one converts it
            _o, _it, _ii, _ip, _id, _in = _ao_output_fields(p)
            _tn = (rec["name"] if t.lower() == "!self" else t).lower()
            _it2 = (_tn if _it.lower() in ("!self", "!caller") else _it).lower()
            gated = False
            for (gc, gn), ges in by.items():
                if gc != "logic_relay" or not gn.startswith(_tn + "__ao"):
                    continue
                for ge in ges:
                    if (m.P(ge, "csgo_addoutput", "") or "") == p:
                        gated = True                   # the gate made from this AddOutput (its output may have been converted since)
                    elif not m.P(ge, "csgo_addoutput", "") and any(m.conn_tuple(cc)[0].lower() == "ontrigger" and m.conn_tuple(cc)[1].lower() == _it2
                                                                    and m.conn_tuple(cc)[1].lower() != "!self" for cc in m.conns(ge)) \
                            and _ii.lower() == "addoutput":
                        gated = True                   # an earlier version's gate (no record of its AddOutput) whose AddOutput was converted since
                    for cc in m.conns(ge):
                        ct = m.conn_tuple(cc)
                        if ct[0].lower() == "ontrigger" and ct[1].lower() == _it2 and ct[2].lower() == _ii.lower() and ct[3] == _ip \
                                and abs(ct[4] - round(_id, 3)) < 1e-3:
                            gated = True
            if gated:
                continue
        if len(cands) != 1:
            continue
        m.add_conn(cands[0], o, t, i, p, d, n)
        done.append((o, t, i, p, d, n))
        rows.append(f"RESTORED\t{rec['cls']} '{rec['name'] or '(unnamed)'}'\t{o}\t-> {t}\t{i}\t{p!r}\tdelay {d:g}\ttimes {n}")
    if not done:
        _keep_map(m, vp)
        return [], []
    try:
        bak = _save_map(m, vp, "io_restore")
    except OSError as ex:
        print(f"  [WARN] dropped IO: {vn} could not be saved ({ex}); close it in Hammer and run again")
        return [], [f"# {vn}: outputs NOT restored ({ex})"]
    print(f"  [IO RESTORE] {vn}: {len(done)} output(s) to !self / !activator / !caller put back; original saved as {os.path.basename(str(bak))}")
    return done, rows

def _vmf_entities_io(path: str):
    """-> the .vmf's entities (see _vmf_entities_io_parse); fresh dicts per call (the reports mark them as they match), the parse is cached"""
    return [dict(e) for e in _vmf_entities_io_parse(path)]


@_cache_per_file_version(maxsize=8)
def _vmf_entities_io_parse(path: str):
    """-> [{"cls","name","origin" (tuple or None),"bbox" ((lo),(hi)) or None,"conns":[(output,target,input,param,delay,times)]}]
    Keeps repeated output names (a plain dict would collapse them). Connection values are 'target,input,param,delay,times' with ','
    or ESC (0x1b) between the fields."""
    ents, depth, cur, sect, pending = [], 0, None, None, ""
    with open(path, encoding="utf-8", errors="replace") as f:
        lines_ = f.read().split("\n")      # (not splitlines(): that also splits at \x1c-\x1e, \x85, ...)
    for raw in lines_:
        ln = raw.strip()
        if ln == "{":
            depth += 1
            if depth == 1 and pending == "entity":
                cur = {"cls": "", "name": "", "origin": None, "pts": [], "conns": []}
            elif cur is not None and depth == 2:
                sect = pending
            continue
        if ln == "}":
            if cur is not None and depth == 2:
                sect = None
            if depth == 1 and cur is not None:
                pts = cur.pop("pts")
                cur["bbox"] = ([min(p[i] for p in pts) for i in range(3)], [max(p[i] for p in pts) for i in range(3)]) if pts else None
                ents.append(cur)
                cur = None
            depth -= 1
            continue
        if ln.startswith('"'):
            m = re.match(r'"([^"]*)"\s+"(.*)"\s*$', ln)
            if not m or cur is None:
                continue
            k, v = m.group(1), m.group(2)
            if depth == 1:
                kl = k.lower()
                if kl == "classname":
                    cur["cls"] = v.lower()
                elif kl == "targetname":
                    cur["name"] = v
                elif kl == "origin":
                    try:
                        cur["origin"] = tuple(float(x) for x in v.split()[:3])
                    except ValueError:
                        pass
            elif depth == 2 and sect == "connections":
                esc = "\x1b" in v
                f = v.split("\x1b") if esc else v.split(",")
                if len(f) >= 5:
                    try:
                        cur["conns"].append((k, f[0], f[1], f[2] if esc else ",".join(f[2:-2]), float(f[-2]), int(float(f[-1]))))
                    except ValueError:
                        pass
            elif depth == 3 and sect == "solid" and k.lower() == "plane":
                for t in re.findall(r"\(([^)]*)\)", v):
                    try:
                        cur["pts"].append(tuple(float(x) for x in t.split()))
                    except ValueError:
                        pass
            continue
        if ln:
            pending = ln
    return ents

def _vmap_entities_io(path: str):
    doc = _dmx_doc_ro(_vmap_read(path))
    parent_of = {}
    for e in doc.els:
        if e.type in ("CMapEntity", "CMapGroup", "CMapWorld"):
            for c in e.get("children") or []:
                parent_of[id(c)] = e
    out = []
    for e in doc.els:
        if e.type != "CMapEntity":
            continue
        pr = e.get("entity_properties")
        props = {a_[0]: a_[2] for a_ in pr.attrs if a_[1] == 5} if pr is not None else {}
        pts = []
        for k in e.get("children") or []:
            if k.type == "CMapMesh":
                for loc, _m in _mesh_polys(k):
                    pts += _node_world(k, loc, parent_of)
        bbox = ([min(p[i] for p in pts) for i in range(3)], [max(p[i] for p in pts) for i in range(3)]) if pts else None
        conns = []
        for c in e.get("connectionsData") or []:
            _par = c.get("overrideParam") or ""
            conns.append((c.get("outputName") or "", c.get("targetName") or "", c.get("inputName") or "", "" if _par.strip().lower() == "(null)" else _par,
                          float(c.get("delay") or 0.0), int(c.get("timesToFire") if c.get("timesToFire") is not None else -1)))
        cls, name = (props.get("classname") or "").lower(), props.get("targetname") or ""
        ccl = (props.get("csgo_class") or "").lower()
        if ccl == "trigger_push":
            # a push made a trigger_multiple (TRIGGER_PUSH_SCRIPT): compared with the .vmf as the trigger_push it was, under its old name
            cls, name = "trigger_push", re.sub(r"(^trigger_push)?__tp\d+$", "", name)
        elif ccl == "trigger_softbarrier":       # SOFT_BARRIERS: a trigger_multiple; an unnamed one was named trigger_softbarrier__sb<N>
            cls, name = ccl, re.sub(r"^trigger_softbarrier__sb\d+$", "", name)
        elif ccl in ("trigger_teleport", "game_player_equip", "player_weaponstrip", "game_round_end", "func_physbox_multiplayer", "game_score"):
            cls = ccl                            # CSGO_TELEPORTS trigger_multiple / EQUIP_SCRIPT point_script or info_target: the entity it was
        elif ccl == "equip_stub":                # EQUIP_SCRIPT's stand-in: an unnamed spawn equip is itself the stand-in; a named one is new
            cls = "game_player_equip" if not name else "equip_stub"
        elif cls == "filter_activator_attribute_int":
            cls = "filter_activator_name"          # a name filter the script rebuilt on an attribute (CS:GO had no attribute filter)
        elif cls == "func_clip_interaction_layer" and props.get("csgo_classname"):
            cls = props["csgo_classname"].lower()  # ENTITY_PLAYERCLIP_LAYER: a player clip entity, compared as the class it was
        out.append({"cls": cls, "name": name, "origin": tuple(e.get("origin") or (0, 0, 0)), "bbox": bbox, "conns": conns, "used": False,
                    "model": (props.get("model") or "").replace("\\", "/").lower(), "ao": props.get("csgo_addoutput") or ""})
    return out

def _without_vmf_skybox(vents, vmf_path, ments):
    """the .vmf entities minus those in its 3D skybox, when this vmap has a skybox_reference (the skybox is its own map now)"""
    if not any(x["cls"] == "skybox_reference" for x in ments):
        return vents
    sky = _vmf_sky_region(vmf_path)
    if not sky:
        return vents

    def inside(v):
        p = v["origin"] if v.get("origin") and not v.get("bbox") else ([(a + b) / 2 for a, b in zip(*v["bbox"])] if v.get("bbox") else None)
        return p is not None and all(sky[0][k] - 1 <= p[k] <= sky[1][k] + 1 for k in range(3))
    return [v for v in vents if not inside(v)]


# REPORT_NEVER_ENABLED: (class test, "starts off" test on the .vmf keyvalues -> reason or None, inputs that turn it on). Source1 FGD
# meanings; the first rule whose class test matches is used, and the StartDisabled rule applies to every other class
def _sf(kv):
    try:
        return int(float(kv.get("spawnflags") or 0))
    except ValueError:
        return 0


_NEVER_ENABLED_RULES = [
    (lambda c: c in ("env_smokestack", "env_steam"), lambda kv: "InitialState 0 (off)" if str(kv.get("initialstate", "0")).strip() == "0" else None,
     ("turnon", "toggle")),
    (lambda c: c in ("light", "light_spot"),      # (vbsp only makes named lights switchable; an unnamed one is baked on whatever its flag)
     lambda kv: "named and Initially dark (spawnflags 1)" if kv.get("targetname") and _sf(kv) & 1 else None, ("turnon", "toggle")),
    (lambda c: c == "point_spotlight", lambda kv: "Start On flag (spawnflags 1) not set" if not _sf(kv) & 1 else None, ("lighton", "lighttoggle")),
    (lambda c: c in ("env_sprite", "env_glow", "env_sprite_oriented"),      # (an unnamed sprite always starts on)
     lambda kv: "named and Start On flag (spawnflags 1) not set" if kv.get("targetname") and not _sf(kv) & 1 else None,
     ("showsprite", "togglesprite")),
    (lambda c: c in ("env_beam", "env_laser"), lambda kv: "named and Start On flag (spawnflags 1) not set" if kv.get("targetname") and not _sf(kv) & 1 else None, ("turnon", "toggle", "strikeonce")),
    (lambda c: c == "env_fire", lambda kv: "Start On flag (spawnflags 4) not set" if not _sf(kv) & 4 else None, ("startfire", "enable")),
    (lambda c: c == "env_spark", lambda kv: "Start ON flag (spawnflags 64) not set" if not _sf(kv) & 64 else None,
     ("startspark", "togglespark", "sparkonce")),
    (lambda c: c == "info_particle_system", lambda kv: "Start Active 0" if str(kv.get("start_active", "0")).strip() == "0" else None, ("start",)),
    (lambda c: c == "ambient_generic", lambda kv: "Start Silent flag (spawnflags 16)" if _sf(kv) & 16 else None,
     ("playsound", "togglesound", "fadein")),
    (lambda c: c == "func_wall_toggle", lambda kv: "Starts Invisible flag (spawnflags 1)" if _sf(kv) & 1 else None, ("toggle",)),
    (lambda c: True, lambda kv: "StartDisabled 1" if str(kv.get("startdisabled", "0")).strip() == "1" else None, ("enable", "toggle", "turnon")),
]


def report_vscripts(vmap_paths, vmf_path: str):
    """REPORT_VSCRIPTS: CS2 has no VScript (Squirrel), so nothing a .nut did happens there; nothing is converted, this only lists it, from
    the .vmf (what CS:GO had): every entity with a vscripts keyvalue, and every output whose input runs script (RunScriptFile /
    RunScriptCode / CallScriptFunction / RunScriptInput-less script inputs), with whether each script file is in SOURCE1_ROOTS
    (scripts/vscripts/). -> log lines"""
    if not vmf_path or not Path(vmf_path).is_file():
        return ["# no .vmf: VScript use cannot be listed"]
    text = Path(vmf_path).read_text(encoding="latin-1", errors="replace")
    blocks = re.findall(r'\nentity\s*\n\{(.*?)\n\}(?=\s*\n)', text, re.S)
    rows, files = [], {}

    def found(name):
        n = name.strip().replace("\\", "/").lstrip("/")
        if not n:
            return None
        key = n.lower()
        if key not in files:
            cands = [n] if os.path.splitext(n)[1] else [n + ".nut", n + ".gnut", n]
            files[key] = any(find_in_source1("scripts/vscripts/" + c)[0] for c in cands)
        return files[key]
    n_ent = n_out = 0
    for b in blocks:
        kv = dict(re.findall(r'^\t"([^"]+)" "([^"]*)"', b, re.M))
        kl = {k.lower(): v for k, v in kv.items()}
        who = f"{kl.get('classname', '?')} {kl.get('targetname') or '(unnamed)'} at {kl.get('origin', '?')}"
        vs = (kl.get("vscripts") or "").strip()
        if vs:
            n_ent += 1
            st = [f"{s} ({'found' if found(s) else 'NOT FOUND'})" for s in vs.split()]
            rows.append(f"VSCRIPTS\t{who}\t{', '.join(st)}" + (f"\tthink function {kl['thinkfunction']}" if kl.get("thinkfunction") else ""))
        conn = re.search(r'\n\t*connections\s*\n\t*\{(.*?)\n\t*\}', b, re.S)
        for o, v in (re.findall(r'^\s*"([^"]+)" "([^"]*)"', conn.group(1), re.M) if conn else []):
            parts = v.split("\x1b") if "\x1b" in v else v.split(",")
            if len(parts) < 2:
                continue
            tg, inp, prm = parts[0], parts[1], (parts[2] if len(parts) > 2 else "")
            il = inp.lower()
            if il not in ("runscriptfile", "runscriptcode", "callscriptfunction", "callprivatescriptfunction", "callplayerscriptfunction"):
                continue
            n_out += 1
            extra = ""
            if il == "runscriptfile" and prm.strip():
                extra = f"\t{prm} ({'found' if found(prm) else 'NOT FOUND'})"
            rows.append(f"OUTPUT\t{who}\t{o} -> {tg} {inp} {prm!r}\tdelay {parts[3] if len(parts) > 3 else '0'}{extra}")
    if not rows:
        return ["# no VScript in this map"]
    head = [f"# VScript (CS2 has none: nothing below runs, nothing was converted): {n_ent} entit(ies) with vscripts, {n_out} script output(s), "
            f"{len(files)} script file(s) ({sum(1 for x in files.values() if not x)} not found in SOURCE1_ROOTS scripts/vscripts/)"]
    head += [f"#   {k}: {'found' if v else 'NOT FOUND'}" for k, v in sorted(files.items())]
    return head + rows


def report_never_enabled(vmap_paths, vmf_path: str):
    """REPORT_NEVER_ENABLED: see the setting. From the .vmf (what CS:GO had); the vmaps are only read for the BAKED ON rows (a disabled CS2
    light at the light's position). An output turns an entity on when its input is one of the rule's and its target is the entity's name,
    a name* wildcard matching it or its class name. Outputs to !activator / !caller / !player,
    AddOutput and vscripts can reach things this cannot see: they are counted in the header. -> log lines"""
    if not vmf_path or not Path(vmf_path).is_file():
        return ["# no .vmf: entities that are never turned on cannot be listed"]
    ents = parse_vmf_file(vmf_path)
    on_targets = collections.defaultdict(set)      # input -> targets (lower case) that get it
    unknown, addout, scripts = collections.Counter(), 0, 0
    for ve in ents:
        kv = ve["kv"]
        if (kv.get("vscripts") or "").strip():
            scripts += 1
        for _o, tgt, inp in ve["conns"]:
            t_, i_ = (tgt or "").strip().lower(), (inp or "").strip().lower()
            if i_ == "addoutput":
                addout += 1
            if t_.startswith("!") and t_ != "!self":
                unknown[i_] += 1
            on_targets[i_].add(t_)
    dark = []                                      # CS2 lights with Enabled 0 (for the BAKED ON rows)
    for vp in vmap_paths or ():
        try:
            doc = _dmx_doc_ro(_vmap_read(vp))
        except Exception:
            continue
        for e in doc.els:
            pr = e.get("entity_properties") if e.type == "CMapEntity" else None
            if pr is not None:
                props = {a_[0]: a_[2] for a_ in pr.attrs if a_[1] == 5}
                if (props.get("classname") or "").startswith("light_") and str(props.get("enabled", "1")).strip() == "0":
                    dark.append(tuple(e.get("origin") or (0, 0, 0)))
    rows, total, baked = [], 0, 0
    for ve in ents:
        kv = ve["kv"]
        cls = (kv.get("classname") or "").lower()
        if cls == "worldspawn":
            continue
        if cls in ("light", "light_spot") and _sf(kv) & 1 and not (kv.get("targetname") or "").strip():
            o = [fnum(v) for v in str(kv.get("origin") or "").split()]
            if len(o) == 3 and any(math.dist(o, d) < 2 for d in dark):
                baked += 1
                rows.append(f"BAKED ON\t{cls} (unnamed) at {' '.join(str(round(v)) for v in o)}\tInitially dark (spawnflags 1) but unnamed: vbsp only "
                            f"makes named lights switchable, so CS:GO baked it on. The CS2 light here has Enabled 0, so it never lights (not rebuilt this run: "
                            f"the lighting rebuild turns it on)")
            continue
        rule = next(r for r in _NEVER_ENABLED_RULES if r[0](cls))
        why = rule[1](kv)
        if not why:
            continue
        name = (kv.get("targetname") or "").strip().lower()
        own = {(i or "").strip().lower() for _o, t, i in ve["conns"] if (t or "").strip().lower() == "!self"}

        def reached(i_):
            for t_ in on_targets.get(i_, ()):
                if not t_:
                    continue
                if (name and (t_ == name or (t_.endswith("*") and name.startswith(t_[:-1])))) or t_ == cls:
                    return True
            return i_ in own
        if any(reached(i_) for i_ in rule[2]):
            continue
        total += 1
        where = " ".join(str(round(fnum(v))) for v in str(kv.get("origin") or "").split()) or "(brush entity)"
        rows.append(f"NEVER\t{cls} {kv.get('targetname') or '(unnamed)'} at {where}\t{why}; nothing in the map sends it "
                    f"{' / '.join(rule[2])}" + ("" if name else " (it has no name, so nothing can)"))
    out = [f"# entities that start off and that no output turns on (in CS:GO they never showed / worked either): {total}"]
    if baked:
        out.append(f"# BAKED ON: unnamed 'Initially dark' lights that were lit in CS:GO but are off in the CS2 map: {baked}")
    if unknown or addout or scripts:
        out.append(f"#   not seen by this check: {sum(unknown.values())} output(s) to !activator / !caller / !player, {addout} AddOutput input(s), "
                   f"{scripts} entit(ies) with vscripts")
    return out + sorted(rows)


def report_dropped_io(vmap_paths, vmf_path: str, restore_self=False):
    """Compare every entity output in the .vmf with the .vmap's. -> report lines. Changes nothing, except with restore_self: outputs the
    importer dropped whose target is !self / !activator / !caller (e.g. a button's OnPressed !self Lock) are put back (backup before_io_restore).
    Owners are matched by name (+ classname), unnamed ones by classname and position / brush bounds. A dropped output is flagged by
    whether its target still exists in the vmap, so outputs of removed / replaced logic (an edited map) are told apart from ones the
    importer lost."""
    import fnmatch
    from collections import Counter
    if not vmf_path or not Path(vmf_path).is_file():
        return ["# no .vmf: dropped outputs cannot be listed"]
    vents = all_vents = [e for e in _vmf_entities_io(vmf_path) if e["conns"]]
    nconn = sum(len(e["conns"]) for e in vents)
    lines = [f"# outputs (IO) in the .vmf that are not in the .vmap. {len(vents)} .vmf entities with outputs, {nconn} outputs. Only RESTORED rows (outputs to !self / !activator / !caller, RESTORE_SELF_IO) were changed.",
             "# OWNER = the entity that fires the output; TARGET = what it fires at. Matching is by name (+classname), or for unnamed owners by classname and position / brush bounds.",
             "# TARGET EXISTS: an entity with that name (or a matching wildcard / classname) is in the vmap, so the output is probably a real loss.",
             "# TARGET GONE: nothing in the vmap has that name, so the logic was most likely removed or replaced when the map was edited.",
             "# TARGET SPECIAL: !activator / !self / ... resolved at run time.  OWNER NOT FOUND: no vmap entity matches the owner, so its outputs cannot be compared (listed once, no judgement).", ""]
    for vp in vmap_paths:
        try:
            ments = _vmap_entities_io(vp)
        except Exception as ex:
            lines.append(f"# {os.path.basename(str(vp))}: cannot read ({ex})")
            continue
        vents = _without_vmf_skybox(all_vents, vmf_path, ments)
        names = {}
        for m in ments:
            if m["name"]:
                names.setdefault(m["name"].lower(), []).append(m)
        all_names, all_cls = set(names), {m["cls"] for m in ments}
        equips = {m["name"].lower() for m in ments if m["cls"] == "game_player_equip" and m["name"]}
        psys = {m["name"].lower() for m in ments if m["cls"] in ("info_particle_system", "env_particle_glow") and m["name"]}
        zl = {}                                  # hurt_zone label -> name: heal trigger_hurts renamed hurt_..._z<label> (HEAL_TRIGGERS_TO_SCRIPT)
        for m in ments:
            lab = _hz_label_of(m["name"])
            if lab:
                zl.setdefault(lab.lower(), m["name"].lower())

        gates = {}                               # ADDOUTPUT_OUTPUTS_GATED gates: target (lower) -> [(gate name, its AddOutput, targets it fires)]
        for m in ments:
            mm_ = re.match(r"^(.*)__ao\d+$", m["name"] or "")
            if m["cls"] == "logic_relay" and mm_:
                gates.setdefault(mm_.group(1).lower(), []).append(
                    (m["name"].lower(), m["ao"], {t.lower() for o, t, i, p, d, n in m["conns"] if o.lower() == "ontrigger" and t.lower() != "!self"}))

        def ao_gated(owner, owner_conns, o, t, p):
            """the AddOutput <p> that <owner> sent to <t> on <o> became a gate: one recording that AddOutput, or (gates made before
            they recorded it) a gate of <t> that the owner enables on <o> and that fires at the target of the added output"""
            tn = (owner if t.lower() == "!self" else t).lower()
            f = _ao_output_fields(p)
            if not f:
                return False
            it = (tn if f[1].lower() in ("!self", "!caller") else f[1]).lower()
            en = {ct.lower() for co, ct, ci, _cp, _cd, _cn in owner_conns if co.lower() == o and ci.lower() == "enable"}
            return any(ao == p or (not ao and gn in en and it in fires) for gn, ao, fires in gates.get(tn, ()))

        pushed = {}                              # props renamed push_<mass>_<name> (PROP_MASS_RENAME): old name -> new name
        for m in ments:
            if m["name"] and _PROP_NAME_HAS_MASS_RE.match(m["name"]):
                rest = _PROP_NAME_HAS_MASS_RE.sub("", m["name"])
                pushed.setdefault(rest.lower(), m["name"].lower())
                wt = re.match(r"^w\d+(?:\.\d+)?x\d+(?:\.\d+)?x\d+(?:\.\d+)?a?_(.+)$", rest, re.I)   # PHYSBOX_WEIGHT_AUTO's tag
                if wt:
                    pushed.setdefault(wt.group(1).lower(), m["name"].lower())

        def canon(x):                            # a .vmf name as the vmap now has it
            xl = (x or "").lower()
            if xl and xl not in names:
                return pushed.get(xl) or zl.get(("z" + re.sub(r"[^A-Za-z0-9]", "", x)).lower(), xl)
            return xl

        def norm_in(t, i):                       # inputs the script renames: Use on equips, TurnOn / TurnOff on converted env_steam
            tl, il = t.lower(), i.lower()
            if il == "use" and tl in equips:
                return "triggerforactivatedplayer"
            if tl in psys and il in ("turnon", "turnoff", "showsprite", "hidesprite", "startspark_", "stopspark_", "sparkonce_"):
                return "start" if il in ("turnon", "showsprite", "startspark", "sparkonce") else "stop"
            if tl in psys and il == "destroyimmediately":     # LASERS_TESLAS: TurnOff / Stop on a laser -> DestroyImmediately
                return "stop"
            return il
        def target_status(t):
            tl = t.lower()
            if tl in _IO_SPECIAL:
                return "TARGET SPECIAL"
            if tl in all_names or tl in all_cls:
                return "TARGET EXISTS"
            if any(c in tl for c in "*?") and (any(fnmatch.fnmatchcase(n, tl) for n in all_names) or any(fnmatch.fnmatchcase(c, tl) for c in all_cls)):
                return "TARGET EXISTS"
            return "TARGET GONE"
        def dist(v, m):
            if v["bbox"] and m["bbox"]:
                cv = [(v["bbox"][0][i] + v["bbox"][1][i]) / 2 for i in range(3)]
                cm = [(m["bbox"][0][i] + m["bbox"][1][i]) / 2 for i in range(3)]
                sz = max(abs((v["bbox"][1][i] - v["bbox"][0][i]) - (m["bbox"][1][i] - m["bbox"][0][i])) for i in range(3))
                return math.dist(cv, cm) + (1e6 if sz > 4.0 else 0.0)
            if v["origin"] and not v["bbox"] and not m["bbox"]:
                return math.dist(v["origin"], m["origin"])
            return 1e9
        dropped, notfound, matched, restore = [], [], 0, []
        for v in vents:
            cand = [m for m in ments if m["cls"] == v["cls"] and not m["used"]]
            if v["name"]:
                cand = [m for m in cand if m["name"].lower() == canon(v["name"])]
            else:
                cand = [m for m in cand if not m["name"]]
            best = min(cand, key=lambda m: dist(v, m), default=None)
            if best is None or (not v["name"] and dist(v, best) > (3.0 if v["bbox"] else 1.0)):
                notfound.append(v)
                continue
            best["used"] = True
            matched += 1
            miss = Counter((o.lower(), canon(t), norm_in(t, i), p, round(d, 3), n) for o, t, i, p, d, n in v["conns"])
            miss.subtract(Counter((o.lower(), t.lower(), norm_in(t, i), p, round(d, 3), n) for o, t, i, p, d, n in best["conns"]))
            # an AddOutput "targetname X" that ADDOUTPUT_FIX made an AddAttribute / RemoveAttribute (same output, target, delay, times) is there,
            # not dropped: put back, it was a second, dead output to !activator, and a rerun listed all of them as left to fix by hand
            attr = Counter((o.lower(), t.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() in ("addattribute", "removeattribute"))
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] == "addoutput" and k_[3].replace(":", " ").lower().split()[:1] == ["targetname"]]:
                ak = (key[0], key[1], key[4], key[5])
                take = min(miss[key], max(attr[ak], 0))
                miss[key] -= take
                attr[ak] -= take
            # likewise ADDOUTPUT_KEY_INPUTS: health X -> SetHealth X, renderamt X -> Alpha X, origin X Y Z -> Teleport of <target>__to_<X>_<Y>_<Z>;
            # rendermode was taken out on purpose; and ADDOUTPUT_FIX's speed X -> SetSpeed X
            if ADDOUTPUT_KEY_INPUTS:
                have_k = Counter((o.lower(), t.lower(), i.lower(), p, round(d, 3), n) for o, t, i, p, d, n in best["conns"])
                have_pv = Counter((o.lower(), p, round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() == "runscriptinput")
                for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] == "addoutput"]:
                    w = key[3].replace(":", " ").split()
                    k0 = w[0].lower() if w else ""
                    if k0 == "rendermode" and len(w) == 2:
                        miss[key] = 0
                        continue
                    if k0 in ("health", "renderamt") and len(w) == 2:
                        twin = (key[0], key[1], {"health": "sethealth", "renderamt": "alpha"}[k0], w[1], key[4], key[5])
                    elif k0 == "speed" and len(w) == 2:      # ADDOUTPUT_FIX: speed X on a door / func_conveyor -> SetSpeed X
                        twin = (key[0], key[1], "setspeed", w[1], key[4], key[5])
                    elif k0 in ("basevelocity", "gravity", "origin") and len(w) == (2 if k0 == "gravity" else 4) and key[1] == "!activator":
                        try:                     # ADDOUTPUT_VELOCITY_SCRIPT: -> RunScriptInput BaseVel_ / Gravity_ on the velocity point_script (any name)
                            pv_in = _velocity_input(k0, w[1:])
                        except ValueError:
                            continue
                        pv_k = (key[0], pv_in, key[4], key[5])
                        take = min(miss[key], max(have_pv[pv_k], 0))
                        miss[key] -= take
                        have_pv[pv_k] -= take
                        continue
                    elif k0 == "origin" and len(w) == 4 and not key[1].startswith("!"):
                        try:
                            tag = "_".join(("%g" % float(x)).replace("-", "n").replace(".", "p") for x in w[1:])
                        except ValueError:
                            continue
                        twin = (key[0], f"{key[1]}__to_{tag}".lower(), "teleport", "", key[4], key[5])
                    else:
                        continue
                    take = min(miss[key], max(have_k[twin], 0))
                    miss[key] -= take
                    have_k[twin] -= take
            # ADDOUTPUT_FIX teleports: AddOutput target X / SetRemoteDestination X on <T> -> Teleport of the point_teleport <T>__to_<X>
            have_tp = Counter((o.lower(), t.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() == "teleport")
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in ("addoutput", "setremotedestination")]:
                w = key[3].replace(":", " ").split()
                if key[2] == "addoutput":
                    if len(w) < 2 or w[0].lower() != "target":
                        continue
                    x = w[1]
                elif w:
                    x = w[0]
                else:
                    continue
                tk = (key[0], f"{key[1]}__to_{x}".lower(), key[4], key[5])
                take = min(miss[key], max(have_tp[tk], 0))
                miss[key] -= take
                have_tp[tk] -= take
            # EQUIP_SCRIPT: Use / TriggerFor* / Strip* on an equip or weaponstrip -> RunScriptInput eq_<N>... on the same name
            have_eq = Counter((o.lower(), t.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() == "runscriptinput" and p.startswith("eq_"))
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in ("use", "triggerforactivatedplayer", "triggerforallplayers", "strip", "stripweaponsandsuit")]:
                ek = (key[0], key[1], key[4], key[5])
                take = min(miss[key], max(have_eq[ek], 0))
                miss[key] -= take
                have_eq[ek] -= take
            # GAME_SCORE_TO_SCRIPT: ApplyScore / AddScoreTerrorist / AddScoreCT -> RunScriptInput Score_ / TeamScore_ / TeamT_ / TeamCT_ on the same target
            have_gs = Counter((o.lower(), t.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"]
                              if i.lower() == "runscriptinput" and _SCORE_INPUT_NAME_RE.match(p))
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in ("applyscore", "addscoreterrorist", "addscorect")]:
                gk = (key[0], key[1], key[4], key[5])
                take = min(miss[key], max(have_gs[gk], 0))
                miss[key] -= take
                have_gs[gk] -= take
            # speedmod: ModifySpeed X -> RunScriptInput Speed_<X> on the speedmod point_script (any target name)
            have_sm = Counter((o.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() == "runscriptinput" and p.startswith("Speed_"))
            # LOGIC_CASE_NUMERIC_FIX: InValue to <case> -> SetValueCompare to the logic_compares <case>__is<value> (one or more per output)
            have_lc = Counter((o.lower(), t.lower().split("__is")[0], round(d, 3), n) for o, t, i, p, d, n in best["conns"]
                              if i.lower() == "setvaluecompare" and "__is" in t.lower())
            # SCREEN_OVERLAYS: StartOverlays / StopOverlays / SwitchOverlay to <name> -> RunScriptInput so_<g>_... to screen_overlay
            have_so = Counter((o.lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"] if i.lower() == "runscriptinput" and p.startswith("so_"))
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in ("startoverlays", "stopoverlays", "switchoverlay")]:
                sk = (key[0], key[4], key[5])
                take = min(miss[key], max(have_so[sk], 0))
                miss[key] -= take
                have_so[sk] -= take
            # GAME_ROUND_END_TO_SCRIPT: EndRound_<X> to <name> -> RunScriptInput RoundEnd_<X>_<delay> to the same name
            have_re = Counter((o.lower(), t.lower(), p.split("_")[1].lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"]
                              if i.lower() == "runscriptinput" and p.startswith("RoundEnd_"))
            _rek = {"endround_terroristswin": "t", "endround_counterterroristswin": "ct", "endround_draw": "draw"}
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in _rek]:
                pk = (key[0], key[1], _rek[key[2]], key[4], key[5])
                take = min(miss[key], max(have_re[pk], 0))
                miss[key] -= take
                have_re[pk] -= take
            # MAKER_SPAWN_SCRIPT: ForceSpawn to <maker> -> RunScriptInput ms_<maker> on the maker_spawn point_script
            have_ms = Counter((o.lower(), p[3:].lower(), round(d, 3), n) for o, t, i, p, d, n in best["conns"]
                              if i.lower() == "runscriptinput" and p.startswith("ms_"))
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] == "forcespawn"]:
                mk = (key[0], key[1], key[4], key[5])
                take = min(miss[key], max(have_ms[mk], 0))
                miss[key] -= take
                have_ms[mk] -= take
            # keyvalue AddOutputs the script sends as an input instead (ADDOUTPUT_KEY_INPUTS, the pirate cannon's angles, dustmotes' Color):
            # the owner fires that input on the same output and delay at the target, or at one of its copies / helpers (<target>__...)
            _kv_in = {"angles": ("setlocalangles", "setabsangles"), "health": ("sethealth",), "renderamt": ("alpha",), "origin": ("teleport",),
                      "color": ("start", "stop"), "maxspeed": ("setspeed",)}
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] == "addoutput" and not _ao_output_fields(k_[3])]:
                kv0 = (key[3].split() or [""])[0].lower()
                if kv0 in _kv_in and any(co.lower() == key[0] and ci.lower() in _kv_in[kv0] and abs(round(cd, 3) - key[4]) < 1e-3
                                         and (ct.lower() == key[1] or ct.lower().startswith(key[1] + "__") or ct.lower().startswith(key[1] + "_"))
                                         for co, ct, ci, _cp, cd, _cn in best["conns"]):
                    miss[key] = 0
            # the rest of the conversions that keep the output: the same input with a parameter the script changed (func_rotating SetSpeed as
            # a fraction of its max speed), or the owner now fires the same output at a helper the script made for that target
            # (<target>__<...>: a laser / tesla / spotlight's on-off and colour branches, a door's __door, a teleport's __to_...)
            for key in [k_ for k_, c in miss.items() if c > 0]:
                o_, t_, i_, _p, d_, n_ = key
                if not t_ or t_.startswith("!"):
                    continue
                if any(co.lower() == o_ and abs(round(cd, 3) - d_) <= 0.011 and cn == n_
                       and ((ct.lower() == t_ and (ci.lower() == i_ or (i_ in ("start", "startforward", "startbackward") and ci.lower() == "setspeed")))
                            or ct.lower().startswith(t_ + "__"))
                       for co, ct, ci, _cp, cd, cn in best["conns"]):
                    miss[key] = 0
            # ADDOUTPUT_OUTPUTS_GATED: an AddOutput adding an output is now the Enable of a gate logic_relay <target>__ao<N> firing that output
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] == "addoutput" and _ao_output_fields(k_[3])]:
                if ao_gated(best["name"], best["conns"], key[0], key[1], key[3]):
                    miss[key] = 0
            for key in [k_ for k_, c in miss.items() if c > 0 and k_[2] in ("modifyspeed", "invalue")]:
                pool_, pk = (have_sm, (key[0], key[4], key[5])) if key[2] == "modifyspeed" else (have_lc, (key[0], key[1], key[4], key[5]))
                take = min(miss[key], max(pool_[pk], 0) if key[2] == "modifyspeed" else (miss[key] if pool_[pk] > 0 else 0))
                miss[key] -= take
                if key[2] == "modifyspeed":
                    pool_[pk] -= take
            for (o, t, i, p, d, n), c in miss.items():
                for _ in range(max(c, 0)):
                    dropped.append((v, o, t, i, p, d, n))
                    if restore_self and t in _IO_RESTORE:
                        _orig = next((x for x in v["conns"] if (x[0].lower(), x[1].lower(), x[2].lower(), x[3], round(x[4], 3), x[5]) == (o, t, norm_in(t, i), p, round(d, 3), n)), None)
                        if _orig:
                            restore.append((best, _orig))
        if restore:
            done_r, rows_r = _restore_io(vp, restore)
            if done_r:
                left = Counter((o.lower(), t.lower(), i.lower(), p, round(d, 3), n) for o, t, i, p, d, n in done_r)
                keep = []
                for r in dropped:
                    k = (r[1], r[2], r[3], r[4], round(r[5], 3), r[6])
                    if left[k] > 0:
                        left[k] -= 1
                    else:
                        keep.append(r)
                dropped = keep
            lines += rows_r
        # a console "play <sound>" sent through point_clientcommand / point_servercommand: CS:GO played it to that one client (or the
        # listen host); CS2's command entities don't run it and a map has no way to play a sound to one player (KNOWN LIMITS in the header)
        snd_cmd = lambda i, p: i.lower() == "command" and (p or "").strip().lower().split(" ", 1)[0] in ("play", "playvol", "playgamesound", "playflush")
        stats = Counter("CLIENT_SOUND" if snd_cmd(_i, _p) else target_status(t) for _v, _o, t, _i, _p, _d, _n in dropped)
        lines.append(f"# {os.path.basename(str(vp))}: owners matched {matched} of {len(vents)}; outputs dropped from matched owners: {len(dropped)} "
                     f"({stats['TARGET EXISTS']} target exists, {stats['TARGET GONE']} target gone, {stats['TARGET SPECIAL']} special, "
                     f"{stats['CLIENT_SOUND']} client sounds); owners not found {len(notfound)} ({sum(len(v['conns']) for v in notfound)} outputs not compared). "
                     f"Outputs the script converted (gates, script inputs, helpers) are not counted")
        n_snd = sum(1 for _v, _o, _t, i, p, _d, _n in dropped if snd_cmd(i, p))
        if n_snd:
            lines.append(f"# CLIENT_SOUND: {n_snd} output(s) playing a sound through a console command: not portable to CS2 (listed below, left out)")
        by = Counter((o, i) for _v, o, _t, i, _p, _d, _n in dropped if target_status(_t) == "TARGET EXISTS" and not snd_cmd(i, _p))
        if by:
            lines.append("# probable losses by output -> input (target still exists): " + ", ".join(f"{o}->{i} x{c}" for (o, i), c in by.most_common(12)))
        order = {"TARGET EXISTS": 0, "TARGET SPECIAL": 1, "TARGET GONE": 2}
        for v, o, t, i, p, d, n in sorted(dropped, key=lambda r: (order[target_status(r[2])], r[0]["cls"], r[0]["name"].lower(), r[1])):
            who = f"{v['cls']} '{v['name']}'" if v["name"] else f"{v['cls']} (unnamed, {' '.join(str(round(x)) for x in (v['origin'] or [(a + b) / 2 for a, b in zip(*v['bbox'])]))})"
            lines.append(f"{'CLIENT_SOUND' if snd_cmd(i, p) else target_status(t)}\t{who}\t{o}\t-> {t}\t{i}\t{p!r}\tdelay {d:g}\ttimes {n}")
        for v in notfound[:400]:
            who = f"{v['cls']} '{v['name']}'" if v["name"] else f"{v['cls']} (unnamed, {' '.join(str(round(x)) for x in (v['origin'] or [(a + b) / 2 for a, b in zip(*v['bbox'])]))})"
            lines.append(f"OWNER NOT FOUND\t{who}\t{len(v['conns'])} output(s): " + "; ".join(sorted({f"{o}->{t}.{i}" for o, t, i, _p, _d, _n in v['conns']}))[:200])
        lines.append("")
    return lines


# .vmf class -> classes it can have in the vmap (importer conversions)
def _box_covers_2axes(box, boxes):
    """boxes (all inside box, 1 unit slack) together span box on at least two of the three axes: what is left of a brush entity whose
    hidden faces were not kept (a func_illusionary floor panel: its top face only)"""
    lo, hi = box
    return sum(1 for k in range(3) if abs(min(b[0][k] for b in boxes) - lo[k]) <= 1 and abs(max(b[1][k] for b in boxes) - hi[k]) <= 1) >= 2 \
        and all(lo[k] - 1 <= b[0][k] and b[1][k] <= hi[k] + 1 for b in boxes for k in range(3))


_ENT_ALIAS = {"light": ("light_omni2",), "light_spot": ("light_barn",), "func_physbox_multiplayer": ("func_physbox",), "func_illusionary": ("func_brush",),
              "func_wall": ("func_brush",), "func_wall_toggle": ("func_brush",), "env_sprite": ("info_particle_system", "env_particle_glow"),
              "env_sprite_oriented": ("info_particle_system", "env_particle_glow"), "env_glow": ("info_particle_system", "env_particle_glow"),
              "env_steam": ("info_particle_system",), "env_steamjet": ("info_particle_system",),  "env_spritetrail": ("info_particle_system", "env_spritetrail"), "env_smokestack": ("info_particle_system",),
              "func_breakable_surf": ("func_breakable", "func_shatterglass"), "trigger_gravity": ("trigger_gravity", "trigger_multiple"),
              "func_monitor": ("func_brush",), "trigger_once": ("trigger_once", "trigger_multiple"), 
              "weapon_p228": ("weapon_p250",), "weapon_usp": ("weapon_usp_silencer",), "weapon_mp5navy": ("weapon_mp5sd",), "weapon_scout": ("weapon_ssg08",),
              "weapon_m3": ("weapon_nova",), "weapon_sg550": ("weapon_scar20",), "weapon_sg552": ("weapon_sg556",), "weapon_tmp": ("weapon_mp9",),
              "weapon_galil": ("weapon_galilar",), "weapon_p2000": ("weapon_hkp2000",), "light_dynamic": ("light_barn", "light_omni2"), "color_correction": ("post_processing_volume",),
              # what this script's own passes turn entities into (they were listed MISSING after their own conversion)
              "env_beam": ("info_particle_system",), "env_laser": ("info_particle_system",), "point_tesla": ("info_particle_system",),
              "env_spark": ("info_particle_system",), "func_dustmotes": ("info_particle_system",), "player_weaponstrip": ("game_player_equip",), "game_score": ("point_script",), "trigger_softbarrier": ("trigger_multiple",),
              "filter_activator_name": ("filter_activator_attribute_int",), "func_water_analog": ("func_water",),
              "prop_physics": ("prop_dynamic",), "prop_physics_override": ("prop_dynamic",),
              "prop_physics_multiplayer": ("prop_dynamic",)}
# classes the importer folds into the world or never makes an entity of (counted, not listed)
_ENT_EXPECTED = {"worldspawn", "func_detail", "func_ladder", "info_overlay", "infodecal", "env_cubemap", "info_node", "info_node_hint", "info_node_air",
                 "func_areaportal", "func_areaportalwindow", "func_occluder", "func_viscluster", "info_lighting", "env_fog_controller", "shadow_control",
                 "env_tonemap_controller", "sky_camera", "env_sun", "water_lod_control", "func_precipitation", "point_spotlight",
                 "env_lightglow", "fog_volume", "info_null", "func_vehicleclip", "info_overlay_transition", "env_detail_controller", "vgui_screen",
                 "player_speedmod"}     # player_speedmod: removed on purpose (SPEEDMOD_TO_SCRIPT; its outputs go to speedmod.js)


def report_missing_entities(vmap_paths, vmf_path: str):
    """Every .vmf entity with no counterpart in the .vmap -> report lines. Changes nothing.
    Named entities are matched by name (a push_<mass>_ prefix from PROP_MASS_RENAME is ignored), unnamed ones by position (point entities) or
    brush bounds. A leftover .vmf entity with an unused vmap entity of the same class and the same brush size / name elsewhere is listed as MOVED."""
    if not vmf_path or not Path(vmf_path).is_file():
        return ["# no .vmf: missing entities cannot be listed"]
    from collections import Counter
    all_vents = _vmf_entities_io(vmf_path)
    lines = []
    for vp in vmap_paths:
        try:
            ments = _vmap_entities_io(vp)
        except Exception as ex:
            lines.append(f"# {os.path.basename(str(vp))}: cannot read ({ex})")
            continue
        vents = _without_vmf_skybox(all_vents, vmf_path, ments)
        def nm(x):
            return _PROP_NAME_HAS_MASS_RE.sub("", x["name"]).lower()
        def centre(x):
            return tuple((a + b) / 2 for a, b in zip(*x["bbox"])) if x["bbox"] else tuple(x["origin"] or (0, 0, 0))
        def size(x):
            return tuple(b - a for a, b in zip(*x["bbox"])) if x["bbox"] else None
        bycls = {}
        for x in ments:
            x["used"] = False
            bycls.setdefault(x["cls"], []).append(x)
        expected, left = Counter(), []
        todo = [v for v in vents if v["cls"]]
        for v in todo:
            if v["cls"] in _ENT_EXPECTED:
                expected[v["cls"]] += 1
                v["hit"] = True
                continue
            v["hit"] = False
            pool = [x for c in (v["cls"],) + _ENT_ALIAS.get(v["cls"], ()) for x in bycls.get(c, []) if not x["used"]]
            if v["name"]:
                cand = [x for x in pool if nm(x) == v["name"].lower()]
                best = min(cand, key=lambda x: math.dist(centre(v), centre(x)), default=None)
            else:
                # an unnamed .vmf entity: whatever sits in the same place with the same size (preferring one still unnamed). Something the
                # converter named since (a hurt_ / vel_ zone) is the same entity: it used to lose to any unnamed one further away and was listed MISSING
                tol = 4.0 if v["bbox"] else 2.0
                sv = size(v)
                near = [x for x in pool if math.dist(centre(v), centre(x)) <= tol
                        and not (sv and size(x) and max(abs(a - b) for a, b in zip(sv, size(x))) > 4.0)]
                best = min(near, key=lambda x: (bool(nm(x)), math.dist(centre(v), centre(x))), default=None)
                if best is None and v["bbox"]:
                    # the brush entity with only its drawn faces (a func_illusionary's nodraw sides are not kept): inside the .vmf box and as
                    # wide on two axes
                    flat = [x for x in pool if x["bbox"] and _box_covers_2axes(v["bbox"], [x["bbox"]])]
                    best = min(flat, key=lambda x: (bool(nm(x)), math.dist(centre(v), centre(x))), default=None)
            if best is not None:
                best["used"] = True
                v["hit"] = True
            else:
                left.append(v)
        moved, changed, edit = [], [], []
        def iou(a, b):
            inter = 1.0
            for i in range(3):
                lo, hi = max(a[0][i], b[0][i]), min(a[1][i], b[1][i])
                if hi < lo - 1:
                    return 0.0
                inter *= max(hi - lo, 1.0)
            va = math.prod(max(a[1][i] - a[0][i], 1.0) for i in range(3))
            vb = math.prod(max(b[1][i] - b[0][i], 1.0) for i in range(3))
            return inter / (va + vb - inter)
        for v in left:
            pool = [x for c in (v["cls"],) + _ENT_ALIAS.get(v["cls"], ()) for x in bycls.get(c, []) if not x["used"]]
            sv = size(v)
            # same class, same brush size and name, somewhere else -> moved
            cand = [x for x in pool if nm(x) == v["name"].lower() and (not sv or (size(x) and max(abs(a - b) for a, b in zip(sv, size(x))) <= 1.0))]
            if not v["name"] and sv:
                cand = [x for x in pool if not nm(x) and size(x) and max(abs(a - b) for a, b in zip(sv, size(x))) <= 1.0]
            best = min(cand, key=lambda x: math.dist(centre(v), centre(x)), default=None)
            if best is not None and (v["name"] or math.dist(centre(v), centre(best)) <= 2048):
                best["used"] = True
                moved.append((v, best))
                continue
            edit.append(v)
        # edited in place, closest pairs first: a brush entity of any class mostly over the same box, or a point entity of the class within 128 units
        pairs = []
        for v in edit:
            if v["bbox"]:
                pairs += [(-iou(v["bbox"], x["bbox"]), id(v), v, x) for xs in bycls.values() for x in xs if not x["used"] and x["bbox"] and iou(v["bbox"], x["bbox"]) >= 0.25]
            else:
                pool = [x for c in (v["cls"],) + _ENT_ALIAS.get(v["cls"], ()) for x in bycls.get(c, []) if not x["used"] and not x["bbox"]]
                pairs += [(math.dist(centre(v), centre(x)) / 1e4, id(v), v, x) for x in pool if math.dist(centre(v), centre(x)) <= 128]
        done = set()
        for _r, _i, v, x in sorted(pairs, key=lambda r: (r[0], r[1])):
            if id(v) in done or x["used"]:
                continue
            x["used"] = True
            done.add(id(v))
            changed.append((v, x))
        missing = [v for v in edit if id(v) not in done]
        # a brush entity whose brushes are world geometry now (DISPLAY_BRUSH_TO_WORLD, or merged into the world by hand) is not missing
        in_world = []
        if any(v["bbox"] for v in missing):
            try:
                mw = _open_map(vp)
                wpar = mw.parent_of()
                wb = []
                for n_, _p in mw.walk():
                    if mw.type(n_) != b"CMapMesh":
                        continue
                    q_ = wpar.get(n_)
                    while q_ is not None and mw.type(q_) != b"CMapEntity":
                        q_ = wpar.get(q_)
                    if q_ is None:
                        b_ = mw.bounds(n_)
                        if b_:
                            wb.append(b_)
                _keep_map(mw, vp)
            except Exception:
                wb = []
            for v in [v for v in missing if v["bbox"]]:
                lo_, hi_ = v["bbox"]
                inside = [b_ for b_ in wb if all(lo_[k] - 1 <= b_[0][k] and b_[1][k] <= hi_[k] + 1 for k in range(3))]
                if inside and _box_covers_2axes(v["bbox"], inside):      # (only its drawn faces became world: as wide on two axes)
                    in_world.append(v)
            missing = [v for v in missing if v not in in_world]
        def who(v):
            return f"{v['cls']}\t{v['name'] or '(unnamed)'}\t{' '.join(str(round(c)) for c in centre(v))}"
        lines.append(f"# {os.path.basename(str(vp))}: {len(todo)} .vmf entities; {len(missing)} missing, {len(moved)} moved, {len(changed)} edited, "
                     f"{len(in_world)} now world geometry; "
                     f"{sum(expected.values())} of classes the importer folds into the world or never keeps (not listed)")
        mc = Counter(v["cls"] for v in missing)
        if mc:
            lines.append("# missing by class: " + ", ".join(f"{c} x{n}" for c, n in mc.most_common()))
        if expected:
            lines.append("# not listed (expected): " + ", ".join(f"{c} x{n}" for c, n in expected.most_common()))
        # many copies of one name (192 x z14nadea), or many unnamed of one class (80 smoke grenades): one line with the area they span
        groups = {}
        for v in missing:
            groups.setdefault((v["cls"], v["name"].lower()), []).append(v)
        for (_c, _n), vs in sorted(groups.items()):
            if _n or len(vs) > 6:
                cs = [centre(v) for v in vs]
                area = "" if len(vs) == 1 else "\t(x%d, within %s .. %s)" % (len(vs), " ".join(str(round(min(c[i] for c in cs))) for i in range(3)),
                                                                            " ".join(str(round(max(c[i] for c in cs))) for i in range(3)))
                lines.append(f"MISSING\t{who(vs[0]) if len(vs) == 1 else vs[0]['cls'] + chr(9) + (vs[0]['name'] or '(unnamed)') + chr(9)}{area}"
                             + (f"\t{sum(len(v['conns']) for v in vs)} output(s)" if any(v["conns"] for v in vs) else ""))
            else:
                for v in vs:
                    lines.append(f"MISSING\t{who(v)}" + (f"\t{len(v['conns'])} output(s)" if v["conns"] else ""))
        for v, x in sorted(changed, key=lambda r: (r[0]["cls"], r[0]["name"])):
            sv, sx = size(v), size(x)
            what = [f"now {x['cls']}"] if x["cls"] != v["cls"] else []
            if (x["name"] or "") != (v["name"] or ""):
                what.append(f"name {v['name'] or '(none)'} -> {x['name'] or '(none)'}")
            if sv and sx and max(abs(a - b) for a, b in zip(sv, sx)) > 1.0:
                what.append("size " + " ".join(str(round(a)) for a in sv) + " -> " + " ".join(str(round(a)) for a in sx))
            if math.dist(centre(v), centre(x)) > 2:
                what.append("centre -> " + " ".join(str(round(c)) for c in centre(x)))
            lines.append(f"EDITED\t{who(v)}\t{', '.join(what) or 'changed'} (probably the same entity edited in Hammer)")
        for v, x in sorted(moved, key=lambda r: (r[0]["cls"], r[0]["name"])):
            lines.append(f"MOVED\t{who(v)}\t-> {' '.join(str(round(c)) for c in centre(x))}"
                         + ("\tby WEAPON_PROP_ALIGN: CS2's weapon model, moved so the gun is where CS:GO drew it (weapon_props log)"
                            if WEAPON_PROP_ALIGN and x.get("model", "").startswith("weapons/models/") else ""))
        for v in sorted(in_world, key=lambda r: (r["cls"], r["name"])):
            lines.append(f"IN_WORLD\t{who(v)}\tits brushes are world meshes now (display-brush conversion, or merged into the world in Hammer); not missing")
        lines.append("")
    lines.insert(0, "# .vmf entities with no counterpart in the .vmap (deleted in Hammer, dropped by the importer, or changed beyond matching). Nothing was changed.\n"
                    "# Named ones are matched by name (+ the classes the importer converts to, e.g. light -> light_omni2, env_sprite -> info_particle_system),\n"
                    "# unnamed ones by position / brush bounds. MOVED = same class, name and brush size somewhere else. EDITED = something now fills the same space\n"
                    "# (a brush entity over mostly the same box, or a point entity of the class within 128 units) but its class, name or size changed.\n"
                    "# IN_WORLD = a brush entity whose exact box is filled by world meshes now (DISPLAY_BRUSH_TO_WORLD turns plain display brushes into world).")
    return lines


def _map_family(vp):
    """the name of the map a .vmap belongs to: its own name; <map> for a 3D skybox map <map>_skybox.vmap and for the importer's
    prefabs in maps/prefabs/<map>/"""
    p = Path(str(vp))
    parts = [x.lower() for x in p.parts[:-1]]
    if "prefabs" in parts:
        k = len(parts) - 1 - parts[::-1].index("prefabs")
        if k + 1 < len(parts):
            return p.parts[k + 1]
    return p.stem[:-len("_skybox")] if p.stem.lower().endswith("_skybox") else p.stem


def match_vmfs(vmap_paths, primary=None):
    """Each map's decompiled Source1 .vmf, matched by NAME (case-insensitive): <name>.vmf for <name>.vmap; a 3D skybox map
    <name>_skybox.vmap and the prefabs in maps/prefabs/<name>/ use <name>.vmf. Looked for in <Source1 root>/maps (and <root>/*/maps,
    roots in SOURCE1_ROOTS order), a maps folder next to this script, the script's folder and the vmap's own folder.
    STATIC_OVERLAY_VMF (any name) is used for the map VMAP_PATH names, or for the only map in the run when VMAP_PATH is a folder.
    -> ({vmap path: .vmf path or ""}, note lines)"""
    import glob
    cands = []
    for root in SOURCE1_ROOTS:
        for pat in ("maps/*.vmf", "*/maps/*.vmf"):
            cands += sorted(glob.glob(os.path.join(root, pat)))
    for d in [os.path.join(SCRIPT_DIR, "maps"), SCRIPT_DIR] + sorted({os.path.dirname(str(v)) for v in vmap_paths}):
        cands += sorted(glob.glob(os.path.join(d, "*.vmf")))
    by_name = {}
    for c in cands:
        by_name.setdefault(Path(c).stem.lower(), c)          # the first one found wins
    out, notes = {}, []
    for vp in vmap_paths:
        fam = _map_family(vp).lower()
        in_prefabs = any(x.lower() == "prefabs" for x in Path(str(vp)).parts[:-1])
        out[vp] = (by_name.get(fam) if in_prefabs else by_name.get(Path(str(vp)).stem.lower()) or by_name.get(fam)) or ""
    if STATIC_OVERLAY_VMF:
        fams = {_map_family(v).lower() for v in vmap_paths}
        target = _map_family(primary).lower() if primary else (next(iter(fams)) if len(fams) == 1 else None)
        if not os.path.isfile(STATIC_OVERLAY_VMF):
            notes.append(f"[WARN] STATIC_OVERLAY_VMF not found: {STATIC_OVERLAY_VMF} (check the drive letter / spelling; use r\"C:\\...\\file.vmf\")")
        elif target is None:
            notes.append(f"[WARN] STATIC_OVERLAY_VMF ignored: this run has {len(fams)} maps ({', '.join(sorted(fams))}), so each gets the .vmf of its "
                         "own name. Set VMAP_PATH to the one map STATIC_OVERLAY_VMF belongs to.")
        else:
            for vp in vmap_paths:
                if _map_family(vp).lower() == target:
                    out[vp] = STATIC_OVERLAY_VMF
    return out, notes


def group_by_vmf(vmap_paths, vmf_of, need_vmf=True):
    """[(vmf, [vmaps])] in first-seen order; maps without a .vmf are left out when need_vmf, else grouped under \"\""""
    groups = {}
    for vp in vmap_paths:
        v = vmf_of.get(vp, "")
        if v or not need_vmf:
            groups.setdefault(v, []).append(vp)
    return list(groups.items())


def find_env_steam(vmap_paths):
    """env_steam / env_steamjet entities, plus info_particle_system entities that carry the Source1 steam keys
    (Speed, JetLength...), in the .vmap files ->
    [(vmap name, targetname, origin, angles, keyvalues dict, classname, current effect_name)], notes."""
    found, notes = [], []
    for vp in vmap_paths:
        ents, err = vmap_entities(str(vp))
        if err:
            notes.append(f"# {os.path.basename(str(vp))}: entities could not be read ({err}); "
                         f"add env_steam keyvalues to STEAM_EFFECTS by hand")
            continue
        for e in ents:
            cls = e["cls"].lower()
            low = {k.lower() for k in e["props"]}
            if cls in ("env_steam", "env_steamjet") or (cls == "info_particle_system" and {"speed", "jetlength"} <= low):
                found.append((os.path.basename(str(vp)), e["name"], e["origin"], e["angles"], dict(e["props"]),
                              cls, e["props"].get("effect_name", "")))
    return found, notes

# ======================================================================== ENTITY SOUND CHECK

SOUND_KEY_HINTS = ("sound", "noise", "message", "snd")
_KV2_LINE_RE = re.compile(r'^\s*"([^"]*)"\s+"([^"]*)"\s+"((?:[^"\\]|\\.)*)"\s*$')

def _event_names_in_file(export_dir: Path) -> set:
    f = export_dir / "soundevents" / "soundevents_addon.vsndevts"
    try:
        txt = f.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return set()
    txt = re.sub(r"//[^\n]*", "", txt)
    return set(re.findall(r'^\s*"([^"]+)"\s*=', txt, flags=re.M))

_DOOR_SOUND_DEFAULTS = {     # Source SDK 2013 doors.cpp CBaseDoor::Precache (UTIL_ValidateSoundName: an empty or "0" key gets the default).
    # startclosesound / closesound have no default: an empty one plays noise1 / noise2 (StartMovingSound / DoorHitBottom)
    "func_door": {"noise1": "DoorSound.DefaultMove", "noise2": "DoorSound.DefaultArrive", "locked_sound": "DoorSound.DefaultLocked",
                  "unlocked_sound": "DoorSound.Null"},
    "func_door_rotating": {"noise1": "RotDoorSound.DefaultMove", "noise2": "RotDoorSound.DefaultArrive", "locked_sound": "RotDoorSound.DefaultLocked",
                           "unlocked_sound": "DoorSound.Null"},
}


def add_door_default_sounds(vmap_paths, vmf_path):
    """DOOR_DEFAULT_SOUNDS: give func_door / func_door_rotating the sounds CS:GO played for them. A key that is empty in the vmap gets the
    .vmf door's own value when it had one (the importer can drop noise1 / noise2), else CS:GO's default soundscript name. Rerun-safe: a key
    with any value is never touched. -> log lines"""
    vdoors = []
    if vmf_path:
        try:
            for ve in parse_vmf_file(vmf_path):
                kv = ve["kv"]
                if kv.get("classname", "").lower() in _DOOR_SOUND_DEFAULTS:
                    try:
                        o = tuple(float(x) for x in kv.get("origin", "").split()[:3])
                    except ValueError:
                        o = None
                    vdoors.append((kv["classname"].lower(), (kv.get("targetname") or "").lower(), o, kv))
        except OSError:
            pass
    out, total, stats = [], 0, {}
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        rows = []
        for e in m.by_class(*_DOOR_SOUND_DEFAULTS):
            cls, nm, o = m.cls(e).lower(), m.name(e), m.origin(e)
            try:
                if int(float(m.P(e, "spawnflags", "0") or 0)) & 4096:      # SF_DOOR_SILENT: CS:GO played nothing for it
                    continue
            except ValueError:
                pass
            src = [d for d in vdoors if d[0] == cls and d[2] and all(abs(d[2][k] - o[k]) < 1.0 for k in range(3))]
            if not src and nm:
                src = [d for d in vdoors if d[0] == cls and d[1] == nm.lower()]
            vkv = src[0][3] if len(src) == 1 else {}
            for key, default in _DOOR_SOUND_DEFAULTS[cls].items():
                cur = (m.P(e, key, "") or "").strip()
                if cur not in ("", "0"):
                    continue
                own = (vkv.get(key) or "").strip()
                val = own if own not in ("", "0") else default
                m.setp(e, key, val)
                why = "the .vmf door's own sound (dropped by the importer)" if val == own else "CS:GO's default for an empty key"
                stats[(val, why)] = stats.get((val, why), 0) + 1
                rows.append(f"SET\t{cls} {nm or '(unnamed)'} at {' '.join('%g' % round(x) for x in o)}\t{key} = {val}\t{why}")
        if rows:
            try:
                bak = _save_map(m, vp, "door_sounds")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            print(f"  [DOOR SOUNDS] {vn}: {len(rows)} door sound key(s) set; original saved as {os.path.basename(bak)}")
            total += len(rows)
            out += [f"# {vn}"] + rows
        else:
            _keep_map(m, vp)
    out.insert(0, f"# door sounds: {total} key(s) set" + ("".join(f"; {n} x {v} ({w})" for (v, w), n in sorted(stats.items())) if stats else "")
               + ". The soundevents come from the soundscript step (<prefix>_soundscripts.txt says whether each name was found in CS:GO's scripts or CS2 has it)")
    return out


_BUTTON_CLASSES = ("func_button", "func_rot_button", "momentary_rot_button")
# CS:GO key (a number) -> CS2 key (a sound name). Source SDK buttons.cpp MakeButtonSound: N -> soundscript "Buttons.snd<N>" for sounds,
# locked_sound and unlocked_sound alike; 0 played nothing (Buttons.snd0 is null.wav).
_BUTTON_SOUND_KEYS = (("sounds", "use_sound"), ("locked_sound", "locked_sound"), ("unlocked_sound", "unlocked_sound"))


def add_button_sounds(vmap_paths, vmf_path):
    """BUTTON_SOUNDS: CS:GO buttons named their sounds by number (sounds / locked_sound / unlocked_sound = N -> soundscript Buttons.sndN);
    CS2's use_sound / locked_sound / unlocked_sound take a sound name. The numbers come from the .vmf button at the same origin (the
    importer drops "sounds"), else from the vmap key when it still holds a number. A key that already holds a name is never touched,
    so reruns change nothing. -> log lines"""
    vbtn = []
    if vmf_path:
        try:
            for ve in parse_vmf_file(vmf_path):
                kv = ve["kv"]
                if kv.get("classname", "").lower() in _BUTTON_CLASSES:
                    try:
                        o = tuple(float(x) for x in kv.get("origin", "").split()[:3])
                    except ValueError:
                        o = None
                    vbtn.append((kv["classname"].lower(), (kv.get("targetname") or "").lower(), o, kv))
        except OSError:
            pass
    index = load_soundscripts()
    out, total, stats, unknown = [], 0, collections.Counter(), set()
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        rows, cleared = [], 0
        for e in m.by_class(*_BUTTON_CLASSES):
            cls, nm, o = m.cls(e).lower(), m.name(e), m.origin(e)
            who = f"{cls} {nm or '(unnamed)'} at {' '.join('%g' % round(x) for x in o)}"
            src = [d for d in vbtn if d[0] == cls and d[2] and len(d[2]) == 3 and all(abs(d[2][k] - o[k]) < 1.0 for k in range(3))]
            if len(src) != 1 and nm:
                src = [d for d in vbtn if d[0] == cls and d[1] == nm.lower()]
            vkv = src[0][3] if len(src) == 1 else {}
            for old_key, new_key in _BUTTON_SOUND_KEYS:
                cur = (m.P(e, new_key, "") or "").strip()
                if cur and not re.fullmatch(r"-?\d+", cur):
                    continue                                     # already a sound name (this script's earlier run, or set by hand)
                raw = (vkv.get(old_key) or "").strip() if vkv else ""
                where = "the .vmf button"
                if not re.fullmatch(r"-?\d+(\.\d*)?", raw):
                    raw, where = cur, "the number left in the vmap"
                if not raw:
                    continue
                n = int(float(raw))
                val = f"Buttons.snd{n}" if n > 0 else ""
                if val == cur:
                    continue
                m.setp(e, new_key, val)
                stats[val or "(none: a 0 cleared)"] += 1
                if val and index and val.lower() not in index:
                    unknown.add(val)
                if val:              # a 0 (CS:GO: none) only cleared: counted in the summary, no row each
                    rows.append(f"SET\t{who}\t{new_key} = {val}\tCS:GO {old_key} {n} (from {where})")
                else:
                    cleared += 1
            if vkv:
                for k in ("locked_sentence", "unlocked_sentence"):
                    v = (vkv.get(k) or "").strip()
                    if v not in ("", "0"):
                        rows.append(f"SENTENCE\t{who}\t{k} {v}: HL2 sentence groups; CS2 has no sentences, left out")
        if rows or cleared:
            if cleared:
                rows.append(f"CLEARED\t{cleared} key(s)\tCS:GO's 0 (no sound) left as the number 0 by the importer -> empty")
            try:
                bak = _save_map(m, vp, "button_sounds")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            n_set = sum(r.startswith("SET") for r in rows) + cleared
            print(f"  [BUTTON SOUNDS] {vn}: {n_set} button sound key(s) set; original saved as {os.path.basename(bak)}")
            total += n_set
            out += [f"# {vn}"] + rows
        else:
            _keep_map(m, vp)
    out.insert(0, f"# button sounds: {total} key(s) set" + "".join(f"; {n} x {v}" for v, n in sorted(stats.items()))
               + ". The soundevents come from the soundscript step (<prefix>_soundscripts.txt says whether each Buttons.sndN was found in CS:GO's scripts or CS2 has it)"
               + (f". NOT IN THE SOUNDSCRIPTS FOUND: {', '.join(sorted(unknown))}" if unknown else ""))
    return out


def _sb_planes(sides, pushdir):
    """CTriggerSoftBarrier::SetupFrontAndBackPlanes on .vmf brush sides (world space, outward normals): the push direction is pushdir
    (pitch yaw roll) as a forward vector; front = the first side whose outward normal has the largest positive dot with it, back = the
    first with the most negative (not equal to the front's) -> ((n, d) front, (n, d) back) outward normal and offset, or None when
    either is missing (CS:GO removed the trigger then)"""
    import numpy as np
    try:
        pit, yaw = (float(x) for x in (pushdir or "0 0 0").split()[:2])
    except ValueError:
        pit, yaw = 0.0, 0.0
    cp, sp, cy, sy = math.cos(math.radians(pit)), math.sin(math.radians(pit)), math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    dvec = np.array([cp * cy, cp * sy, -sp])
    fdot = bdot = 0.0
    front = back = None
    for n, d in sides:
        dt = float(np.dot(n, dvec))
        if dt > fdot:
            fdot, front = dt, (n, d)
            continue
        if dt < bdot and dt != fdot:
            bdot, back = dt, (n, d)
    return (front, back) if front is not None and back is not None else None


def convert_soft_barriers(vmap_paths, vmf_path):
    """SOFT_BARRIERS: trigger_softbarrier (gone in CS2) -> trigger_multiple (same brush, flags, filter, outputs; csgo_class
    trigger_softbarrier) with its front and back planes in sb_front / sb_back ("nx ny nz d", outward normal), for softbarrier.js (copied by
    add_map_scripts). Planes from the .vmf brush at the same origin, by CS:GO's rule. Unnamed ones are named trigger_softbarrier__sb<N>.
    Rerun-safe: converted ones are matched again and get the same keys. -> log lines"""
    out, total = [], 0
    if not vmf_path:
        return ["# soft barriers: no .vmf, nothing done (the planes come from its brushes)"]
    vb = collections.defaultdict(list)
    for b in _vmf_brush_polys(vmf_path, classes=("trigger_softbarrier",)):
        if b["cls"] == "trigger_softbarrier":
            vb[id(b["kv"])].append(b)
    vents = []
    for brushes in vb.values():
        kv = brushes[0]["kv"]
        try:
            o = tuple(float(x) for x in (kv.get("origin") or "").split()[:3])
        except ValueError:
            o = ()
        sides = [(sd["n"], float(sd["d"])) for b in brushes for sd in b["sides"] if len(sd["P"])]   # faces with area (the model's planes)
        vents.append((o, kv, sides))
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        rows, changed = [], False
        names = {(m.name(x) or "").lower() for x in m.entities()}
        for e in m.entities():
            cls = m.cls(e)
            if not (cls == "trigger_softbarrier" or (cls == "trigger_multiple" and (m.P(e, "csgo_class", "") or "").lower() == "trigger_softbarrier")):
                continue
            o = m.origin(e)
            who = f"{m.name(e) or '(unnamed)'} at {' '.join('%g' % round(x) for x in o)}"
            src = [v for v in vents if len(v[0]) == 3 and all(abs(v[0][k] - o[k]) < 1.0 for k in range(3))]
            if len(src) != 1:
                rows.append(f"SKIPPED\t{who}\t{'no' if not src else len(src)} trigger_softbarrier in the .vmf at its origin: left as it was")
                continue
            pl = _sb_planes(src[0][2], m.P(e, "pushdir", "") or src[0][1].get("pushdir", "0 0 0"))
            if pl is None:
                rows.append(f"SKIPPED\t{who}\tno front or back face for its push direction: CS:GO removed it at spawn; left as it was")
                continue
            fmt = lambda nd: " ".join("%.6g" % (0.0 if abs(x) < 1e-9 else x) for x in (*nd[0], nd[1]))
            want = {"classname": "trigger_multiple", "csgo_class": "trigger_softbarrier", "sb_front": fmt(pl[0]), "sb_back": fmt(pl[1])}
            if (m.P(e, "wait", "") or "") == "":
                want["wait"] = "1"
            if not m.name(e):
                k = 1
                while f"trigger_softbarrier__sb{k}" in names:
                    k += 1
                want["targetname"] = f"trigger_softbarrier__sb{k}"
                names.add(want["targetname"])
            todo = {k: v for k, v in want.items() if (m.P(e, k, "") or "") != v}
            if todo:
                for k, v in todo.items():
                    m.setp(e, k, v)
                changed = True
                total += 1
                rows.append(f"SET\t{m.name(e)} at {' '.join('%g' % round(x) for x in o)}\tpushdir {m.P(e, 'pushdir', '')}: front {want['sb_front']}, "
                            f"back {want['sb_back']}" + (" (named)" if "targetname" in todo else "") + (" (now a trigger_multiple)" if cls != "trigger_multiple" else ""))
        sbn = {(m.name(x) or "").lower() for x in m.entities() if (m.P(x, "csgo_class", "") or "").lower() == "trigger_softbarrier"} - {""}
        for src_, cc in m.all_conns():
            t = m.conn_tuple(cc)
            il, w = t[2].lower(), t[3].replace(":", " ").split()
            if t[1].lower() in sbn and (il == "setpushdirection" or (il == "addoutput" and w[:1] and w[0].lower() == "pushdir")):
                rows.append(f"DIRECTION_LOST\t{t[1]}\t{m.cls(src_)} {m.name(src_) or '(unnamed)'} {t[0]} -> {t[2]} {t[3]}: softbarrier.js keeps the "
                            "push direction it was converted with (change pushdir in Hammer and rerun)")
        if changed:
            try:
                bak = _save_map(m, vp, "soft_barriers")
            except OSError as ex:
                out.append(f"# {vn}: could not write the map ({ex}); nothing was changed in it. Close Hammer and rerun.")
                continue
            print(f"  [SOFT BARRIERS] {vn}: {sum(r.startswith('SET') for r in rows)} soft barrier(s) converted / updated; original saved as {os.path.basename(bak)}")
        else:
            _keep_map(m, vp)
        if rows:
            out += [f"# {vn}"] + rows
    out.insert(0, f"# soft barriers: {total} converted / updated this run (trigger_multiple + softbarrier.js)")
    return out


def fix_sound_entities(vmap_paths, sound_events: dict, export_dir: Path):
    """Sound keyvalues that still hold a sound file path (ambient_generic message = sounds/x/y.vsnd, ...) -> the soundevent made for
    that file. CS2 plays soundevents only: a .vsnd path in ambient_generic is silent. Same matching as check_sound_entities.
    Rerun-safe (a value that already is an event name is left alone). Backup as before_sound_entities."""
    events = _event_names_in_file(export_dir) | set(sound_events)
    events_l = {e.lower() for e in events}
    by_vsnd = {}
    for name, v in sound_events.items():
        for f in (v[0] if isinstance(v, tuple) else [v]):
            by_vsnd.setdefault(f.lower(), name)
    out, total = [], 0
    for vp in vmap_paths:
        vn = os.path.basename(str(vp))
        try:
            m = _open_map(vp)
        except Exception as ex:
            out.append(f"# {vn}: cannot read ({ex})")
            continue
        rows = []
        for e in m.entities():
            attrs = m.props(e).get("attrs") or []
            for a in attrs:
                if len(a) < 3 or not isinstance(a[2], bytes):
                    continue
                k = a[0].decode("utf-8", "replace") if isinstance(a[0], bytes) else str(a[0])
                kl = k.lower()
                val = a[2].decode("utf-8", "replace")
                if kl in ("classname", "targetname") or not val.strip():
                    continue
                v = val.strip().replace("\\", "/")
                vl = v.lstrip(_WAVE_PREFIX_CHARS).lower()
                base, ext = os.path.splitext(vl)
                if ext not in (".vsnd", ".wav", ".mp3") or vl in events_l:
                    continue
                if not any(h in kl for h in SOUND_KEY_HINTS) and m.cls(e) != "ambient_generic":
                    continue
                key = (base if base.startswith("sounds/") else "sounds/" + base.removeprefix("sound/")) + ".vsnd"
                ev = by_vsnd.get(key)
                if not ev:
                    rows.append(f"NO_EVENT\t{m.cls(e)} {m.name(e) or '(unnamed)'}\t{k}\t{val}\tno soundevent was made for this file (left as is; it will be silent)")
                    continue
                m.setp(e, k, ev)
                rows.append(f"CHANGED\t{m.cls(e)} {m.name(e) or '(unnamed)'}\t{k}\t{val}\t-> {ev}")
        done = sum(r.startswith("CHANGED") for r in rows)
        if not done:
            _keep_map(m, vp)
            if rows:
                out += [f"# {vn}"] + rows
            continue
        try:
            bak = _save_map(m, vp, "sound_entities")
        except OSError as ex:
            out += [f"# {vn}: NOT SAVED ({ex}); close it in Hammer and run again"] + rows
            print(f"  [WARN] sound entities: {vn} could not be saved ({ex}); close it in Hammer and run again")
            continue
        total += done
        print(f"  [SOUND ENTITIES] {vn}: {done} sound path(s) replaced by their soundevent; original saved as {os.path.basename(str(bak))}")
        out += [f"# {vn}  (backup {bak})"] + rows
    return total, ["# sound keyvalues that held a sound file path -> the soundevent made for it (CS2 ambient_generic plays soundevents only)"] + out


def check_sound_entities(vmap_paths, sound_events: dict, export_dir: Path):
    """For every entity key in the (text keyvalues2) .vmap whose value looks like a sound, say whether it already
    names a soundevent. Binary .vmap files only get a token-level report (no entity context)."""
    events = _event_names_in_file(export_dir) | set(sound_events)
    events_l = {e.lower(): e for e in events}
    by_vsnd = {}
    for name, v in sound_events.items():
        for f in (v[0] if isinstance(v, tuple) else [v]):
            by_vsnd.setdefault(f.lower(), name)
    lines, counts = [], {"OK": 0, "CHANGE": 0, "UNKNOWN": 0}

    def judge(val: str):
        v = val.strip().replace("\\", "/")
        vl = v.lstrip(_WAVE_PREFIX_CHARS).lower()
        if vl in events_l:
            return "OK", ""
        base, ext = os.path.splitext(vl)
        if ext in (".vsnd", ".wav", ".mp3"):
            key = (base if base.startswith("sounds/") else "sounds/" + base.removeprefix("sound/")) + ".vsnd"
            if key in by_vsnd:
                return "CHANGE", by_vsnd[key]
            return "UNKNOWN", "sound path without a matching soundevent"
        return None, ""

    for vp in vmap_paths:
        try:
            data = _vmap_read(vp)
        except Exception:
            continue
        head = data[:200].decode("latin-1", errors="ignore").lower()
        _ents, _err = vmap_entities(str(vp))
        if not _err and _ents:
            for _e in _ents:
                for k, val in _e["props"].items():
                    kl = k.lower()
                    if kl in ("classname", "targetname") or not val:
                        continue
                    if not any(h in kl for h in SOUND_KEY_HINTS) and not val.lower().endswith((".vsnd", ".wav", ".mp3")):
                        continue
                    st, sug = judge(val)
                    if st:
                        counts[st] += 1
                        lines.append(f"{st}\t{os.path.basename(str(vp))}\t{_e['cls']}\t{_e['name']}\t{k}\t{val}\t{sug}")
            continue
        if "keyvalues2" not in head:
            lines.append(f"# {vp}: binary .vmap, no entity context; token-level check only")
            toks = {m.group(0).decode("ascii", errors="ignore") for m in
                    re.finditer(rb'[A-Za-z0-9_\-./\\]{3,}', data)}
            for t in sorted(toks):
                st, sug = judge(t)
                if st:
                    counts[st] += 1
                    lines.append(f"{st}\t{os.path.basename(str(vp))}\t-\t-\t-\t{t}\t{sug}")
            continue
        text = data.decode("utf-8", errors="ignore")
        stack = [{}]
        for raw in text.splitlines():
            ln = raw.strip()
            m = _KV2_LINE_RE.match(raw)
            if m:
                stack[-1][m.group(1).lower()] = m.group(3)
                continue
            if ln == "{":
                stack.append({})
                continue
            if ln == "}" and len(stack) > 1:
                blk = stack.pop()
                cls = blk.get("classname")
                if cls:
                    for k, val in blk.items():
                        if k in ("classname", "targetname") or not val:
                            continue
                        if not any(h in k for h in SOUND_KEY_HINTS) and not val.lower().endswith((".vsnd", ".wav", ".mp3")):
                            continue
                        st, sug = judge(val)
                        if st:
                            counts[st] += 1
                            lines.append(f"{st}\t{os.path.basename(str(vp))}\t{cls}\t{blk.get('targetname', '')}\t{k}\t{val}\t{sug}")
    head = ["# OK = value already is a soundevent name | CHANGE = value is a sound path, use the event named in the last column | "
            "UNKNOWN = sound path with no matching event",
            f"# OK {counts['OK']}   CHANGE {counts['CHANGE']}   UNKNOWN {counts['UNKNOWN']}"]
    return head + lines

# ======================================================================== ASSET RESOLUTION

# ======================================================================== MODEL IMPORT (cs_mdl_import.exe)

DMX_PATH_RE = PATH_RE_TEXT

@_cache_per_file_version(maxsize=200_000)
def parse_vmdl_dependencies(vmdl_path: str):
    deps = set()
    try:
        text = Path(vmdl_path).read_text(encoding="utf-8", errors="ignore")
        deps.update(re.findall(r'filename\s*=\s*["\']?([^"\']+\.dmx)["\']?', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.dmx)"', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.(?:vmat|vtex|vtex_c|tga|png|jpg|jpeg))"', text, flags=re.IGNORECASE))
        deps.update(re.findall(r'"([^"]+\.(?:vmdl|vmdl_c))"', text, flags=re.IGNORECASE))
    except Exception:
        pass
    return frozenset(d for d in (normalize_dep_must_be_rooted(x) for x in deps) if d)

@_cache_per_file_version(maxsize=200_000)
def extract_nul_tokens(path: str) -> tuple:
    try:
        data = Path(path).read_bytes()
    except Exception:
        return tuple()
    out = []
    for seg in data.split(b"\x00"):
        if 2 <= len(seg) <= 8192:
            s = seg.decode("utf-8", errors="ignore").strip()
            if s:
                out.append(s)
    return tuple(out)

@_cache_per_file_version(maxsize=200_000)
def parse_dmx_deps_nul(dmx_path: str):
    """(rooted dependency paths, bare *.vmat names with no folder)"""
    rooted, orphans = set(), set()
    for tok in extract_nul_tokens(dmx_path):
        for m in DMX_PATH_RE.findall(tok):
            t = m.strip().strip('"').strip("'").replace("\\", "/").lstrip("/")
            if "/" in t:
                nr = normalize_dep_must_be_rooted(t)
                if nr:
                    rooted.add(nr)
            elif t.lower().endswith(".vmat"):
                orphans.add(t)
    return frozenset(rooted), frozenset(orphans)

def _mdl_parts(rel: str):
    return [p for p in rel.replace("\\", "/").split("/") if p]

def _mdl_path(root: Path, rel: str) -> Path:
    return root.joinpath(*_mdl_parts(rel))

def mdl_sidecar_problems(source1_root: Path, mdl_rel: str):
    mdl = _mdl_path(source1_root, mdl_rel)
    problems = []
    if not mdl.is_file():
        problems.append(".mdl")
    if not mdl.with_name(mdl.stem + ".vvd").is_file():
        problems.append(".vvd")
    if not any(mdl.with_name(mdl.stem + s).is_file() for s in MDL_VTX_SUFFIXES):
        problems.append(".vtx")
    return problems

def _mdl_checksum_problems(source1_root: Path, mdl_rel: str):
    """a model whose .vvd or the .vtx cs_mdl_import reads (the first of MDL_VTX_SUFFIXES) was saved with another version of its .mdl (their
    checksums differ): the importer stops with "Invalid VTX file checksum" and crashes. -> list of problems ([] = fine or unreadable)"""
    import struct as _st
    mdl = _mdl_path(source1_root, mdl_rel)

    def at(path, off):
        try:
            with open(path, "rb") as f_:
                f_.seek(off)
                b_ = f_.read(4)
            return _st.unpack("<i", b_)[0] if len(b_) == 4 else None
        except OSError:
            return None
    want = at(mdl, 8)
    if want is None:
        return []
    out = []
    vvd = at(mdl.with_name(mdl.stem + ".vvd"), 8)
    if vvd is not None and vvd != want:
        out.append(f".vvd belongs to another version of the .mdl (checksum {vvd}, the .mdl's {want})")
    vtx = next((mdl.with_name(mdl.stem + x) for x in MDL_VTX_SUFFIXES if mdl.with_name(mdl.stem + x).is_file()), None)
    if vtx is not None:
        c_ = at(vtx, 16)
        if c_ is not None and c_ != want:
            out.append(f"{vtx.name[len(mdl.stem):]} belongs to another version of the .mdl (checksum {c_}, the .mdl's {want})")
    return out


def _mdl_other_source(mdl_rel: str, not_root):
    """another Source1 folder (SOURCE1_ROOTS order) with a complete copy of the model whose files match each other -> root or None"""
    for r_ in SOURCE1_ROOTS:
        if not r_ or os.path.normcase(os.path.abspath(str(r_))) == os.path.normcase(os.path.abspath(str(not_root))):
            continue
        try:
            if _mdl_path(Path(r_), mdl_rel).is_file() and not mdl_sidecar_problems(Path(r_), mdl_rel) and not _mdl_checksum_problems(Path(r_), mdl_rel):
                return str(r_)
        except OSError:
            continue
    return None


def _mdl_stamp(source1_root: Path, mdl_rel: str):
    """size + time of a model's Source1 files (MDL_REMEMBER_FAILURES: a failure is remembered for exactly these files)"""
    mdl = _mdl_path(source1_root, mdl_rel)
    out = []
    for x in [".mdl", ".vvd"] + list(MDL_VTX_SUFFIXES):
        q = mdl.with_name(mdl.stem + x)
        try:
            st_ = q.stat()
            out.append(f"{x}:{st_.st_size}:{int(st_.st_mtime)}")
        except OSError:
            pass
    return " ".join(out + [f"script:{MDL_FIX_REV}"])


def _mdl_failures_path():
    return Path(BACKUP_DIR) / "model_import_failures.txt"


def _mdl_failures_load():
    """MDL_REMEMBER_FAILURES -> {(model, source folder) lower case: (file stamp, reason)}"""
    out = {}
    try:
        for ln in _mdl_failures_path().read_text(encoding="utf-8", errors="replace").splitlines():
            p_ = ln.split("\t")
            if len(p_) >= 4 and not ln.startswith("#"):
                out[(p_[0].lower(), p_[1].lower())] = (p_[2], p_[3])
    except OSError:
        pass
    return out


def _mdl_failures_save(mem):
    try:
        Path(BACKUP_DIR).mkdir(parents=True, exist_ok=True)
        lines = ["# models whose import failed (MDL_REMEMBER_FAILURES): not tried again while their Source1 files are unchanged. Delete a line "
                 "(or this file) to try one again. Columns: model, Source1 folder, files, reason"]
        lines += [f"{k[0]}\t{k[1]}\t{v[0]}\t{v[1]}" for k, v in sorted(mem.items())]
        _mdl_failures_path().write_text("\n".join(lines) + "\n", encoding="utf-8")
    except OSError:
        pass


def mdl_output_footprint(export_dir: Path, mdl_rel: str):
    """(output .vmdl, output _refs dir) for a Source1 model path like 'models/props/crate.mdl'."""
    parts = _mdl_parts(mdl_rel)
    stem = parts[-1].rsplit(".", 1)[0]
    d = export_dir.joinpath(*parts[:-1])
    return d / f"{stem}.vmdl", d / f"{stem}_refs"

def _newest_mtime(path: Path) -> float:
    if not path.exists():
        return -1.0
    if path.is_file():
        try:
            return path.stat().st_mtime
        except Exception:
            return -1.0
    newest = -1.0
    for f in path.rglob("*"):
        try:
            if f.is_file():
                newest = max(newest, f.stat().st_mtime)
        except Exception:
            continue
    return newest

def _count_recent(path: Path, t_ref: float) -> int:
    if not path.exists():
        return 0
    if path.is_file():
        try:
            return 1 if path.stat().st_mtime >= t_ref else 0
        except Exception:
            return 0
    n = 0
    for f in path.rglob("*"):
        try:
            if f.is_file() and f.stat().st_mtime >= t_ref:
                n += 1
        except Exception:
            continue
    return n

def mdl_success_detect(export_dir: Path, mdl_rel: str, t0: float):
    """Success = the .vmdl was written after the start time (refs-only output is partial)."""
    t_ref = t0 - MDL_MTIME_TOLERANCE
    vmdl, refs = mdl_output_footprint(export_dir, mdl_rel)
    refs_n = _count_recent(refs, t_ref)
    if _count_recent(vmdl, t_ref) > 0:
        return True, f"vmdl written ({refs_n} ref files updated)"
    if refs_n:
        return False, f"partial output: {refs_n} ref files but no .vmdl"
    return False, "no model-scoped outputs updated"

def _recent_minidumps(source1_root: Path, t_ref: float) -> int:
    n = 0
    for base in (source1_root, source1_root / "models", Path.cwd()):
        if not base.exists():
            continue
        for mdmp in base.glob("cs_mdl_import_*_accessviolation.mdmp"):
            try:
                if mdmp.stat().st_mtime >= t_ref:
                    n += 1
                mdmp.unlink()
            except Exception:
                pass
    return n

def _kill_tree(proc) -> None:
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(proc.pid)], capture_output=True, timeout=15)
        else:
            proc.kill()
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    try:
        proc.wait(timeout=10)
    except Exception:
        pass

def _import_attempt(source1_root: Path, mdl_rel: str, export_dir: Path, list_path: Path, stdout_log: Path):
    """One importer run -> (success, stalled, return_code, message)."""
    rel_win = "\\".join(_mdl_parts(mdl_rel))
    list_path.write_text(rel_win + "\n", encoding="utf-8", errors="ignore")
    args = [CS_MDL_IMPORT_EXE, "-nop4", "-game", IMPORT_GAME, "-r",
            "-i", str(source1_root), "-o", str(export_dir), "-l", str(list_path), "-v"]
    vmdl, refs = mdl_output_footprint(export_dir, mdl_rel)
    t0 = time.time()

    with stdout_log.open("a", encoding="utf-8", errors="ignore") as log:
        log.write("\n" + "=" * 78 + f"\n[IMPORT] {rel_win}\n[CMD] {' '.join(args)}\n")
        log.flush()
        try:
            proc = subprocess.Popen(
                args, cwd=str(source1_root), stdout=log, stderr=subprocess.STDOUT,
                creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0)
        except Exception as e:
            return False, False, -1, f"failed to start: {e}"

        stalled, reason = False, ""
        last_activity, last_sig = time.time(), None
        try:
            while proc.poll() is None:
                time.sleep(MDL_POLL_SECONDS)
                now = time.time()
                try:
                    size = stdout_log.stat().st_size
                except Exception:
                    size = -1
                sig = (size, _newest_mtime(vmdl), _newest_mtime(refs))
                if sig != last_sig:
                    last_sig, last_activity = sig, now
                if now - last_activity >= MDL_MAX_IDLE_SECONDS:
                    reason = f"no activity for {MDL_MAX_IDLE_SECONDS}s"
                elif now - t0 >= MDL_MAX_RUNTIME_SECONDS:
                    reason = f"exceeded {MDL_MAX_RUNTIME_SECONDS}s"
                if reason:
                    stalled = True
                    _kill_tree(proc)
                    log.write(f"[STALL] Killed ({reason}): {rel_win}\n")
                    log.flush()
                    break
        except KeyboardInterrupt:
            _kill_tree(proc)
            raise
        rc = proc.returncode if proc.returncode is not None else -999
        log.flush()

    crashed = _recent_minidumps(source1_root, t0 - MDL_MTIME_TOLERANCE)
    note = " [crash dump found]" if crashed else ""
    if stalled:
        return False, True, rc, f"stalled ({reason}){note}"
    ok, msg = mdl_success_detect(export_dir, mdl_rel, t0)
    return ok, False, rc, msg + note

# ---- MDL_INCLUDE_TRIM: Source1 .mdl sequence tables
_SEQ_SIZE, _ANIM_SIZE = 212, 100
_SEQ_REL = (0, 4, 8, 28, 60, 64, 152, 156, 160, 168, 172, 180)      # mstudioseqdesc_t fields that are offsets from the struct
_ANIM_REL = (0, 4, 24, 64, 76, 80, 92)                              # mstudioanimdesc_t ones (animindex 56 separately: only in block 0)


def _mdl_cstr(b, o):
    e = b.find(b"\0", o)
    return bytes(b[o:e]).decode("latin-1")


def mdl_read(b):
    """the parts of a Source1 .mdl (IDST, version 44-49) this script edits -> dict, or None when it is not one.
    seqs: [dict(name, activity, weight, anims [local animation indices], layers [local sequence indices], next)]; includes: [path]"""
    if len(b) < 408 or b[:4] != b"IDST":
        return None
    ver = struct.unpack_from("<i", b, 4)[0]
    if not 44 <= ver <= 49:
        return None
    na, ai, ns, si = struct.unpack_from("<iiii", b, 180)
    ni, ii = struct.unpack_from("<ii", b, 336)
    nblk = struct.unpack_from("<i", b, 352)[0]
    if not (0 <= na < 100000 and 0 <= ns < 100000 and 0 <= ni < 64) or ai + na * _ANIM_SIZE > len(b) or si + ns * _SEQ_SIZE > len(b):
        return None
    seqs = []
    for i in range(ns):
        o = si + i * _SEQ_SIZE
        lab, act = struct.unpack_from("<ii", b, o + 4)
        g0, g1 = struct.unpack_from("<ii", b, o + 68)
        aio = struct.unpack_from("<i", b, o + 60)[0]
        nlay, layo = struct.unpack_from("<ii", b, o + 148)
        seqs.append(dict(name=_mdl_cstr(b, o + lab), activity=_mdl_cstr(b, o + act) if act else "", weight=struct.unpack_from("<i", b, o + 20)[0],
                         anims=list(struct.unpack_from("<%dh" % (g0 * g1), b, o + aio)) if aio and g0 * g1 > 0 else [],
                         layers=[struct.unpack_from("<h", b, o + layo + k * 24)[0] for k in range(nlay)] if layo else [],
                         next=struct.unpack_from("<i", b, o + 136)[0]))
    incs = []
    for i in range(ni):
        o = ii + i * 8
        incs.append(_mdl_cstr(b, o + struct.unpack_from("<i", b, o + 4)[0]).replace("\\", "/"))
    return dict(version=ver, checksum=struct.unpack_from("<i", b, 8)[0], seqs=seqs, includes=incs, nanim=na, animblocks=nblk,
                _ai=ai, _si=si, _ii=ii)


def mdl_keep_sequences(b, names):
    """a copy of a .mdl with only the sequences named (lower case), the sequences those layer on or lead to, and the animations they
    use: the kept sequence and animation records move to the front of their tables (every offset in them corrected for the move), the
    table counts shrink, nothing else in the file moves. -> (bytes, [kept sequence names]) or (None, why)"""
    d = mdl_read(b)
    if d is None:
        return None, "not a Source1 .mdl of version 44-49"
    seqs = d["seqs"]
    keep = {i for i, s in enumerate(seqs) if s["name"].lower() in names}
    todo = list(keep)
    while todo:
        s = seqs[todo.pop()]
        for j in s["layers"] + ([s["next"]] if s["next"] > 0 else []):
            if 0 <= j < len(seqs) and j not in keep:
                keep.add(j)
                todo.append(j)
    keep = sorted(keep)
    anims = sorted({a for i in keep for a in seqs[i]["anims"] if 0 <= a < d["nanim"]})
    out = bytearray(b)
    ver, ai, si = d["version"], d["_ai"], d["_si"]
    amap, smap = {a: k for k, a in enumerate(anims)}, {s: k for k, s in enumerate(keep)}
    # animation records
    for new, old in enumerate(anims):
        src, dst = ai + old * _ANIM_SIZE, ai + new * _ANIM_SIZE
        rec = bytearray(b[src:src + _ANIM_SIZE])
        delta = src - dst
        block, nfr = struct.unpack_from("<i", rec, 52)[0], struct.unpack_from("<i", rec, 16)[0]
        sec_o, sec_fr = struct.unpack_from("<ii", rec, 80)
        if ver >= 46 and sec_o and sec_fr > 0:           # each section's data offset is from the record too
            for k in range(nfr // sec_fr + 2):
                so = src + sec_o + k * 8
                blk, off = struct.unpack_from("<ii", b, so)
                if blk == 0:                             # mstudioanimsections_t { animblock, animindex }: the offset is the second
                    struct.pack_into("<i", out, so + 4, off + delta)     # (was written over animblock: cs_mdl_import crashed, poketrainer_red)
        rel = _ANIM_REL + ((56,) if block == 0 else ()) + ((28,) if ver >= 49 else ())
        for f in rel:
            if f in (76, 80, 92) and ver < 46:
                continue
            v = struct.unpack_from("<i", rec, f)[0]
            if v or f == 0:
                struct.pack_into("<i", rec, f, v + delta)
        out[dst:dst + _ANIM_SIZE] = rec
    # sequence records
    done = set()
    for new, old in enumerate(keep):
        src, dst = si + old * _SEQ_SIZE, si + new * _SEQ_SIZE
        rec = bytearray(b[src:src + _SEQ_SIZE])
        delta = src - dst
        g0, g1 = struct.unpack_from("<ii", rec, 68)
        aio = struct.unpack_from("<i", rec, 60)[0]
        if aio and src + aio not in done:               # its animation index grid (shared grids renumbered once)
            done.add(src + aio)
            for k in range(g0 * g1):
                a = struct.unpack_from("<h", b, src + aio + 2 * k)[0]
                struct.pack_into("<h", out, src + aio + 2 * k, amap.get(a, 0))
        nlay, layo = struct.unpack_from("<ii", rec, 148)
        if layo and src + layo not in done:
            done.add(src + layo)
            for k in range(nlay):
                j = struct.unpack_from("<h", b, src + layo + 24 * k)[0]
                struct.pack_into("<h", out, src + layo + 24 * k, smap.get(j, 0))
        nx = struct.unpack_from("<i", rec, 136)[0]
        struct.pack_into("<i", rec, 136, smap.get(nx, 0) if nx > 0 else nx)
        for f in _SEQ_REL + ((184,) if ver >= 49 else ()):
            v = struct.unpack_from("<i", rec, f)[0]
            if v or f == 0:
                struct.pack_into("<i", rec, f, v + delta)
        out[dst:dst + _SEQ_SIZE] = rec
    struct.pack_into("<i", out, 180, len(anims))
    struct.pack_into("<i", out, 188, len(keep))
    return bytes(out), [seqs[i]["name"] for i in keep]


def mdl_set_includes(b, paths):
    """a copy of a .mdl whose $includemodel list is paths (no more than it had): the new names are appended to the file -> bytes"""
    d = mdl_read(b)
    out = bytearray(b)
    for k, p in enumerate(paths[:len(d["includes"])]):
        o = d["_ii"] + k * 8
        struct.pack_into("<i", out, o + 4, len(out) - o)
        out += p.replace("/", "\\").encode("latin-1") + b"\0"
    while len(out) % 4:
        out += b"\0"
    struct.pack_into("<i", out, 336, min(len(paths), len(d["includes"])))
    struct.pack_into("<i", out, 76, len(out))
    return bytes(out)


def _mdl_seq_names(path):
    """mdl_read of a file -> dict or None"""
    try:
        return mdl_read(Path(path).read_bytes())
    except OSError:
        return None


def _s1_file(rel, first_root=None):
    """a Source1 file by its game path: in first_root when it has it, else in the Source1 folders in order -> Path or None"""
    if first_root is not None:
        q = find_ci(Path(first_root), rel)
        if q is not None and q.is_file():
            return q
    q, _r = find_in_source1(rel)
    return Path(q) if q else None


_NPC_MODEL_CLASSES = ("monster_generic", "npc_furniture", "monster_furniture")


def vmf_model_sequences(vmf_paths):
    """the sequences the maps play on each model -> {model path (.mdl, lower case): set of sequence names in lower case, plus "@act_idle"
    for a model on a monster_generic (it plays its idle activity)}. From the .vmf entities (those in hidden groups too): DefaultAnim, and
    the SetAnimation / SetDefaultAnimation parameters of outputs aimed at an entity with that model."""
    out = collections.defaultdict(set)
    for vmf in sorted({str(v) for v in vmf_paths if v}):
        try:
            ents = parse_vmf_file(vmf)
            with open(vmf, encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError:
            continue
        by_name = collections.defaultdict(set)
        for ve in ents:
            kv = ve["kv"]
            mdl = (kv.get("model") or "").replace("\\", "/").lower()
            if not mdl.endswith(".mdl"):
                continue
            out[mdl]                                 # (a model with no animation asked for still gets a row)
            v = (kv.get("defaultanim") or "").strip().lower()
            if v:
                out[mdl].add(v)
            if (kv.get("classname") or "").lower() in _NPC_MODEL_CLASSES:
                out[mdl].add("@act_idle")
            if kv.get("targetname"):
                by_name[kv["targetname"].lower()].add(mdl)
        for tgt, par in re.findall(r'"[^"\n]*"\s+"([^",\x1b\n]*)[,\x1b](?:SetAnimation|SetDefaultAnimation|SetAnimationNoReset)[,\x1b]([^",\x1b\n]*)[,\x1b]', text, re.I):
            tgt, par = tgt.strip().lower(), par.strip().lower()
            if not par:
                continue
            for nm, mdls in by_name.items():
                if nm == tgt or (tgt.endswith("*") and nm.startswith(tgt[:-1])):
                    for mdl in mdls:
                        out[mdl].add(par)
    return out


def mdl_activity_sequence(mdl_rel, activity):
    """the sequence a Source1 model plays for an activity ("ACT_IDLE"): its own, else the heaviest one in its shared animation files
    -> its name, or "" (model not found, or no such sequence)"""
    q, q_root = find_in_source1(mdl_rel)
    d = _mdl_seq_names(q) if q else None
    if d is None:
        return ""
    act = activity.upper()
    for s_ in d["seqs"]:
        if s_["activity"].upper() == act:
            return s_["name"]
    best = None
    for ip in d["includes"]:
        di = _mdl_include_files(ip, q_root)[1]       # (a shared file whose .ani is missing or does not fit is not imported)
        for s_ in (di["seqs"] if di else ()):
            if s_["activity"].upper() == act and (best is None or s_["weight"] > best[0]):
                best = (s_["weight"], s_["name"])
    return best[1] if best else ""


def _mdl_ani_fits(blob, ani_path):
    """whether a .ani file is the one a .mdl was built with: the .mdl's block table says where each block of animation data lies in it,
    so the file must be as long as the last block's end (a .ani of another build of the model is shorter or longer: mg maps pack a
    version 48 male_shared.mdl while CS:GO's own male_shared.ani belongs to its version 49 one) -> (fits, why not)"""
    nblk, blko = struct.unpack_from("<ii", blob, 352)
    if nblk <= 1:
        return True, ""
    end = max(struct.unpack_from("<ii", blob, blko + 8 * k)[1] for k in range(nblk))
    try:
        size = Path(ani_path).stat().st_size
        with open(ani_path, "rb") as f:
            head = f.read(8)
    except OSError as ex:
        return False, str(ex)
    if head[:4] != b"IDAG":
        return False, "not a .ani file"
    if not end <= size <= end + 4096:
        return False, (f"{size} bytes (version {struct.unpack_from('<i', head, 4)[0]}), but the .mdl (version {struct.unpack_from('<i', blob, 4)[0]}) "
                       f"expects its animation data to end at byte {end}: built from another version of the model")
    return True, ""


def _mdl_include_files(ip, source1_root):
    """the files of a shared animation model: its .mdl and, when its animation data is in a .ani, the .ani that fits it. The Source1
    folders are tried in order (the model's own first) until one has a .mdl with a fitting .ani, which may come from another folder.
    -> (mdl path, parsed, .ani path or None, .ani game path, "") or (None, None, None, "", why)"""
    roots, why = [], ""
    for r in [str(source1_root)] + [str(x) for x in SOURCE1_ROOTS]:
        if r.lower() not in [x.lower() for x in roots]:
            roots.append(r)
    seen_any = False
    for r in roots:
        q = find_ci(Path(r), ip)
        if q is None or not q.is_file():
            continue
        seen_any = True
        try:
            blob = q.read_bytes()
        except OSError as ex:
            why = why or f"{ip}: {ex}"
            continue
        di = mdl_read(blob)
        if di is None:
            why = why or f"{ip} in {r}: not a Source1 .mdl of version 44-49"
            continue
        if di["animblocks"] <= 0:
            return q, di, None, "", ""
        ani = _mdl_cstr(blob, struct.unpack_from("<i", blob, 348)[0]).replace("\\", "/")
        tried = False
        for r2 in roots:
            for cand in (ani, os.path.splitext(ip)[0] + ".ani"):
                qa = find_ci(Path(r2), cand)
                if qa is not None and qa.is_file():
                    tried = True
                    ok, bad = _mdl_ani_fits(blob, qa)
                    if ok:
                        return q, di, qa, ani, ""
                    why = why or f"{ani} in {r2} does not fit {ip} in {r}: {bad}"
                    break
        if not tried:
            why = why or f"{ani} (the animation data of {os.path.basename(ip)}) is in no Source1 folder"
    return None, None, None, "", why or (f"{ip} is in no Source1 folder" if not seen_any else f"{ip}: no usable copy")


def _mdl_trim_memo(work_dir):
    import json
    try:
        return json.loads((Path(work_dir) / "done.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def mdl_trim_stale(work_dir, mdl_rel, wanted):
    """whether a model already in the addon was imported (MDL_INCLUDE_TRIM) without a sequence the map now plays on it"""
    had = _mdl_trim_memo(work_dir).get(mdl_rel.replace("\\", "/").lower())
    return had is not None and not set(wanted) <= set(had)


def mdl_trimmed_source(source1_root, mdl_rel, wanted, mdl_mats, work_dir):
    """MDL_INCLUDE_TRIM: see the setting. Builds, below work_dir, a stand-in Source1 folder for cs_mdl_import holding a copy of the model
    whose $includemodel list names trimmed copies of its shared animation files (only the wanted sequences those hold; none wanted from a
    file: it is not included), the model's .vvd / .vtx / .phy / .ani, the shared files' .ani, its .vmt files and gameinfo.txt.
    -> (stand-in folder, note for the log), or (None, "") for a model to import as it is (no shared files, or small ones)"""
    import json
    import zlib
    rel = mdl_rel.replace("\\", "/")
    src = find_ci(Path(source1_root), rel)
    if src is None:
        return None, ""
    try:
        data = src.read_bytes()
    except OSError:
        return None, ""
    d = mdl_read(data)
    if d is None or not d["includes"]:
        return None, ""
    incs, lost, gone, other = [], [], [], []
    for ip in d["includes"]:
        q, di, qa, ani, why = _mdl_include_files(ip, source1_root)
        if di is None:
            gone.append(why)
        else:
            incs.append((ip, q, di, qa, ani))
            own_q = find_ci(Path(source1_root), ip)
            if own_q is not None and own_q.is_file() and own_q != q:
                other.append(f"{os.path.basename(ip)} from {q.parent} (the copy in {own_q.parent} has no .ani that fits it)")
    if sum(len(di["seqs"]) for _ip, _q, di, _qa, _an in incs) <= MDL_INCLUDE_TRIM_MIN and not lost and not gone:
        return None, ""
    own = {s_["name"].lower() for s_ in d["seqs"]}
    want = {w for w in wanted if not w.startswith("@")}
    for w in wanted:
        if w.startswith("@"):                        # an activity: the model's own sequence for it, else the heaviest one in a shared file
            act = w[1:].upper()
            if any(s_["activity"].upper() == act for s_ in d["seqs"]):
                continue
            cands = [(-(s_["weight"]), k, s_["name"].lower()) for k, (_ip, _q, di, _qa, _an) in enumerate(incs) for s_ in di["seqs"] if s_["activity"].upper() == act]
            if cands:
                want.add(min(cands)[2])
    want -= own
    root = Path(work_dir) / ("%08x" % (zlib.crc32(str(source1_root).lower().encode("utf-8")) & 0xffffffff))
    tag = "%08x" % (zlib.crc32((rel.lower() + "|" + ",".join(sorted(want))).encode("utf-8")) & 0xffffffff)
    new_incs, kept_all, found = [], [], set()

    def put(rel_out, blob=None, copy_from=None):
        dst = root / rel_out
        dst.parent.mkdir(parents=True, exist_ok=True)
        if blob is not None:
            dst.write_bytes(blob)
        else:
            shutil.copyfile(str(copy_from), str(dst))
    for ip, q, di, qa, ani in incs:
        names = want & {s_["name"].lower() for s_ in di["seqs"]}
        if not names:
            continue
        blob = q.read_bytes()
        nb, kept = mdl_keep_sequences(blob, names)
        if nb is None:
            lost.append(f"{ip} ({kept})")
            continue
        found |= names
        out_rel = f"models/_trim/{tag}/{os.path.basename(ip)}"
        put(out_rel, blob=nb)
        new_incs.append(out_rel)
        kept_all += kept
        if qa is not None:                           # its animation data is in a .ani file, named in the header
            put(ani, copy_from=qa)
    put(rel, blob=mdl_set_includes(data, new_incs))
    stem = src.name[:-4].lower()
    try:
        for q in src.parent.iterdir():               # the model's other files (.vvd, .vtx, .phy, .ani)
            low = q.name.lower()
            if q.is_file() and low != src.name.lower() and low.startswith(stem + ".") and low[len(stem):] in (".vvd", ".phy", ".ani") + tuple(MDL_VTX_SUFFIXES):
                put(rel.rsplit("/", 1)[0] + "/" + q.name, copy_from=q)
    except OSError:
        pass
    for vmat in mdl_mats or ():                      # cs_mdl_import looks its materials up below the folder it is given
        vmt = os.path.splitext(vmat)[0] + ".vmt"
        q = _s1_file(vmt, source1_root)
        if q is not None:
            put(vmt, copy_from=q)
    gi = find_ci(Path(source1_root), "gameinfo.txt")
    if gi is not None and gi.is_file():
        put("gameinfo.txt", copy_from=gi)
    memo = _mdl_trim_memo(work_dir)
    memo[rel.lower()] = sorted(set(wanted))
    try:
        (Path(work_dir) / "done.json").write_text(json.dumps(memo, indent=1, sort_keys=True), encoding="utf-8")
    except OSError:
        pass
    n_inc = sum(len(di["seqs"]) for _ip, _q, di, _qa, _an in incs)
    note = (f"MDL_INCLUDE_TRIM: its shared animation files ({', '.join(os.path.basename(x) for x in d['includes'])}: {n_inc} sequences) "
            + (f"cut down to the {len(kept_all)} the map plays on it ({', '.join(kept_all)})" if kept_all else
               f"could not be used (the model's own {len(d['seqs'])} sequence(s) are kept)" if not incs else
               f"left out: the map plays none of their sequences on it (the model's own {len(d['seqs'])} sequence(s) are kept)"))
    miss = sorted(want - found)
    if miss:
        note += f"; NOT FOUND in the model or its shared files: {', '.join(miss)}"
    if lost:
        note += f"; could not be read: {', '.join(lost)}"
    if other:
        note += f"; used {'; '.join(other)}"
    if gone:
        note += f"; LEFT OUT (its sequences are not imported): {'; '.join(gone)}"
    return root, note


def import_models_batch(source1_root: Path, mdl_rels, export_dir: Path, list_path: Path, stdout_log: Path):
    """One cs_mdl_import run for many models (MDL_BATCH) -> {mdl_rel: (ok, message)}. A model it did not write a .vmdl for is left for
    import_model (one at a time, with retries)."""
    mdl_rels = list(mdl_rels)
    list_path.write_text("".join("\\".join(_mdl_parts(r)) + "\n" for r in mdl_rels), encoding="utf-8", errors="ignore")
    args = [CS_MDL_IMPORT_EXE, "-nop4", "-game", IMPORT_GAME, "-r",
            "-i", str(source1_root), "-o", str(export_dir), "-l", str(list_path), "-v"]
    t0 = time.time()
    cap = MDL_MAX_RUNTIME_SECONDS + 60 * len(mdl_rels)
    with stdout_log.open("a", encoding="utf-8", errors="ignore") as log:
        log.write("\n" + "=" * 78 + f"\n[IMPORT BATCH] {len(mdl_rels)} model(s)\n[CMD] {' '.join(args)}\n")
        log.flush()
        try:
            proc = subprocess.Popen(args, cwd=str(source1_root), stdout=log, stderr=subprocess.STDOUT,
                                    creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0)
        except Exception as e:
            return {r: (False, f"failed to start: {e}") for r in mdl_rels}
        last_activity, last_size, reason = time.time(), None, ""
        try:
            while proc.poll() is None:
                time.sleep(0.25)
                now = time.time()
                try:
                    size = stdout_log.stat().st_size
                except Exception:
                    size = -1
                if size != last_size:
                    last_size, last_activity = size, now
                if now - last_activity >= MDL_MAX_IDLE_SECONDS:
                    reason = f"no output for {MDL_MAX_IDLE_SECONDS}s"
                elif now - t0 >= cap:
                    reason = f"exceeded {cap}s"
                if reason:
                    _kill_tree(proc)
                    log.write(f"[STALL] Killed batch ({reason})\n")
                    break
        except KeyboardInterrupt:
            _kill_tree(proc)
            raise
    _recent_minidumps(source1_root, t0 - MDL_MTIME_TOLERANCE)
    out = {}
    for r in mdl_rels:
        ok, msg = mdl_success_detect(export_dir, r, t0)
        out[r] = (ok, "batch: " + msg)
    return out


def import_model(source1_root: Path, mdl_rel: str, export_dir: Path, list_path: Path, stdout_log: Path):
    """Run cs_mdl_import.exe on one model with retries -> (ok, message)."""
    last = ""
    for attempt in range(1, MDL_MAX_RETRIES + 1):
        ok, stalled, rc, msg = _import_attempt(source1_root, mdl_rel, export_dir, list_path, stdout_log)
        if ok:
            return True, msg
        last = f"attempt {attempt}: rc={rc} | {msg}"
        if stalled:
            break
        time.sleep(0.3)
    return False, last

# ======================================================================== ASSET RESOLUTION

@lru_cache(maxsize=500_000)
def find_asset(asset_rel_path: str):
    """-> (kind, found_path, extra). Order: already in CS2 -> Source1 roots."""
    asset = normalize_candidate(asset_rel_path)
    ext = os.path.splitext(asset)[1].lower()

    # 0. a sound file path: CS:GO's own wave first, as the soundscripts do (SOUND_PREFER_CS2_FILES: some CS2 entries are stubs with no
    # audio). Found in CS2 only, it is verified below and still gets a soundevent (main loop): an entity can only play an event
    if ext == ".vsnd" and not SOUND_PREFER_CS2_FILES:
        rest = os.path.splitext(asset)[0]
        rest = rest[len("sounds/"):] if rest.startswith("sounds/") else rest
        for sub in ("sound/", "sounds/"):
            for e in (".wav", ".mp3"):
                p, r = find_in_source1(sub + rest + e)
                if p:
                    return ("source1_sound", p, r)

    # 1. already shipped with CS2 (a vmat that compiles to the error shader does not count: port it from Source1 if possible)
    if ext == ".vmat" and USE_CS2_VPK and cs2_vmat_is_stub(asset):
        if find_in_source1(os.path.splitext(asset)[0] + ".vmt")[0]:
            RUN.stub_cs2_vmats.add(asset)
        else:
            RUN.stub_cs2_vmats.add(asset + "  (no Source1 .vmt found to port from)")
            return ("cs2_verify", "cs2:" + asset + "_c", None)
    elif cs2_file_exists(asset):
        return ("cs2_verify", "cs2:" + asset, None)
    if ext in COMPILED_EXTS and ext != ".vmat" and cs2_file_exists(asset + "_c"):
        return ("cs2_verify", "cs2:" + asset + "_c", None)
    if ext == ".vmat" and asset not in RUN.stub_cs2_vmats and cs2_file_exists(asset + "_c") and not any(x.startswith(asset + " ") for x in RUN.stub_cs2_vmats):
        return ("cs2_verify", "cs2:" + asset + "_c", None)
    if ext in IMAGE_EXTS and cs2_compiled_texture_exists(asset):
        return ("cs2_verify", "cs2:" + asset, None)

    # 2. Source1 roots
    base_no_ext = os.path.splitext(asset)[0]
    if ext in (".vmat", ".vmt"):
        p, r = find_in_source1(base_no_ext + ".vmt")
        if p:
            return ("source1_vmt", p, r)
    elif ext == ".vtex":
        p, r = find_in_source1(base_no_ext + ".vtf")
        if p:
            return ("source1_vtex", p, r)
    elif ext == ".vtf":
        p, r = find_in_source1(asset)
        if p:
            return ("source1_vtf", p, r)
    elif ext == ".vmdl":
        p, r = find_in_source1(base_no_ext + ".mdl")
        if p:
            return ("source1_model", p, r)
    elif ext in IMAGE_EXTS:
        p, r = find_in_source1(asset)
        if p:
            return ("source1_raw", p, r)
    elif ext == ".vsnd":
        # CS2 map references 'sounds/x.vsnd'; source is 'sounds/x.wav|mp3', which the CS2 resource
        # compiler turns into x.vsnd_c. Source1 keeps them in 'sound/x.wav|mp3'.
        rest = base_no_ext[len("sounds/"):] if base_no_ext.startswith("sounds/") else base_no_ext
        for sub in ("sound/", "sounds/"):
            for e in (".wav", ".mp3"):
                p, r = find_in_source1(sub + rest + e)
                if p:
                    return ("source1_sound", p, r)
    elif ext in (".wav", ".mp3"):
        p, r = find_in_source1(asset)
        if not p and asset.startswith("sounds/"):
            p, r = find_in_source1("sound/" + asset[len("sounds/"):])
        if p:
            return ("source1_sound", p, r)
    return (None, None, None)

# ======================================================================== MAIN

# VERSION HISTORY (newest first; the current version is SCRIPT_VERSION)
#   2026-11-15b RENDER_TARGET_BLACK: a render-target material (dev/dev_tvmonitornonoise: a camera / monitor screen; CS2 has no render targets) is pointed at CS2's black material and logged as obsolete
#   2026-11-15a AddOutput keyvalues CS2 cannot read ('AddOutput fired with bad string'): health -> SetHealth, renderamt -> Alpha, origin -> Teleport of a point_teleport at that place, rendermode taken out (ADDOUTPUT_KEY_INPUTS; the dropped-IO check counts them as present). PHYS_TRIGGER_WAKE: a sleeping func_physbox / prop_physics inside a physics trigger is woken when the trigger is enabled (mg_divine's creeper). SELFILLUM_MASKS: $selfillum gets a self-illumination mask (LightmappedGeneric on csgo_complex; mg_divine's lava drew red and see-through). Brush entity copies: matching tolerance 0.25 (the importer shifts the copies' corners up to ~0.2: mg_divine's func_wall_toggle copies stayed)
#   2026-11-14e MDL_INCLUDE_TRIM checks that a shared animation file's .ani fits its .mdl (the .mdl says where the data ends) and looks through the Source1 folders for a .mdl / .ani pair that does; a shared file with no fitting .ani is left out and logged instead of being handed to cs_mdl_import (ba_jail_os_gulag_d packs version 48 male_*.mdl, CS:GO's own male_*.ani belong to its version 49 ones)
#   2026-11-14d MDL_INCLUDE_TRIM: player / hostage models (any model whose $includemodel files hold more than MDL_INCLUDE_TRIM_MIN sequences) are imported from a temporary copy that includes only the sequences the map plays on them (DefaultAnim, SetAnimation outputs, a monster_generic's idle), so cs_mdl_import no longer converts cs_player_shared.mdl's 723 sequences per model; MDL_SKIP_PREFIXES then skips nothing. MONSTER_GENERIC_FIX: monster_generic -> prop_dynamic with the model's idle sequence (a sleeping one that nothing wakes starts disabled, as a sleeping NPC is not drawn)
#   2026-11-14c MISSING_BLACK_FIX also covers imported models: a mesh material named black that exists nowhere (a full path, or the bare name cs_mdl_import leaves when it finds no .vmt) is remapped to CS2's black material in the model's .vmdl, so the model compiles; a remap an earlier run pointed at the missing material is corrected
#   2026-11-14b MISSING_BLACK_FIX: a material named black that exists nowhere (mg_hellz: halflife/black, not packed with the map and in no Source1 folder) is pointed at CS2's black material (materials/dev/black_simple.vmat, checked in CS2 on the run) in the map and in the passes that match the map to the .vmf. Source1 has no fallback folder for a missing material: CS:GO simply drew it plain black, CS2 draws a flashing checkerboard
#   2026-11-14a WEAPON_PROP_ALIGN: a prop given CS2's weapon model is moved so the gun is drawn where CS:GO's was. Same origin, but the two models draw their gun at different distances from it (AWP: CS:GO 20.9 in front / 3.5 above, CS2 15.8 / 8.2), and the distance differs for every weapon and for a held and a _dropped CS:GO model. Both models are measured on the run (CS:GO .mdl first-sequence box from the Source1 folders, CS2 .vmdl_c mesh bounds from the VPK, read with the bundled kv3bin decoder); an axis where CS2's box holds loose parts (shotgun shells) is lined up on the grip bone. The .vmf says where each prop started, so reruns and maps swapped by an earlier version end up the same. Converted water: the screen-space reflection settings are CS2's own (overpasswater: thickness 2, step 0.2, jitter 0.05) instead of the shader defaults
#   2026-11-13b converted water (WATER_CONVERT): CS2's wave textures are unpacked from the one compiled texture that holds both (the normal and the height; the script waited for a second compiled texture CS2 does not have, so the water was a flat sheet with no waves), how that texture holds them is read off the texture and logged; Water Fog Strength stops at the Material Editor's maximum of 80 (WATER_FOG_STRENGTH_MAX: de_aztec's water was written as 150); the material text is written the way the Material Editor saves it
#   2026-11-13a trigger_push.js: pushes sharing a name AND an origin get a name of their own (the script found a push by name and origin: mg_hellz's ring corner wedges got each other's direction and box, and one stopped pushing); func_physbox masses go to the script by name, and a push no longer doubles a physics object's first tick and takes it back after (capped speeds left mg_hellz's cannon ball crawling) but stops at CS:GO's 2000 units/s. 3D skybox: the skybox map's sky_camera is made to compile (the importer's Editor only flag kept the skybox from being drawn). ENV_SUN_IN_SKY: the .vmf's env_sun (not in CS2) is painted into the ported sky
#   2026-11-11e speed, same output (mg_hellz: 87 s -> 72 s; the map, the addon files and the logs are byte for byte the same): the large-face split looked through every entity for every mesh (now one table); the stationary-light pass reuses the world grid the probe pass rasterised; the probe tiles and the vis cells are grouped without np.unique over every voxel; the crack pass tests each face against the .vmf sides near its mesh, not all of them; the origin-duplicate pass finds the entities near a mesh in one comparison; the three reports at the end (missing entities, never enabled, dropped IO) share one parse of each map
#   2026-11-11d ADDOUTPUT_FIX on a map an older version converted: the AddOutput targetname outputs versions before 11b put back beside their AddAttribute / RemoveAttribute are removed (a filter already made an attribute filter still counts as watching its name), so a rerun ends with the same outputs as a fresh run. Cleanup: the fire pass no longer looks for an older version's info_target fire zones
#   2026-11-11c reruns: an unnamed env_fire that starts on and an unnamed env_spark that starts on no longer get another flame / spark particle on every run (what an earlier run made for them was looked up by name, and they have none; it is now found by its place and parent; the burn trigger of FIRE_HURT_MODE trigger too). Cleanup: the fire pass no longer turns a fire zone an older version made as an info_target into an info_particle_system (never needed on a fresh import)
#   2026-11-11b reruns: a second run of the same map no longer adds anything - the face restore skips strips under 0.05 units wide (float residue of the import's faces, 0.0002 - 0.03 wide; one was added as a hair of a face on every rerun), the dropped-IO check counts an AddOutput targetname that ADDOUTPUT_FIX made an AddAttribute / RemoveAttribute as there (it put the dead AddOutput back, and a rerun listed all of them as left to fix by hand), and the static-prop check reads the map's scripts without their comments (push_mass.js names EnableMotion only in its notes: once copied into the addon, every Motion Disabled prop was UNCERTAIN and renamed on a rerun). A face with skewed .vmf texture axes gets its tangent with its coordinates (the face-scale pass rewrote it first on every run, so one tangent differed after a rerun). logic_case: no CHECK row for a case that is not a whole number (logic_case compares text)
#   2026-11-11a renames keep shared names working: when an entity renamed for a script (heal trigger_hurts for hurt_zone.js, weapon zones, fire zones) shares its name with others (two heal pads both named heal, a func_brush named the same), the outputs aimed at that name are copied for the new name instead of moved, and a point_template slot naming it gets the new name too; before, only the first renamed entity still received them (CS:GO sent them to all)
